-- Carga los 601 ejercicios del catálogo (RepDB). Idempotente: se puede correr de nuevo.
insert into public.ejercicios (id, nombre, descripcion, grupo, categoria, nivel, equipo, peso_corporal, musculos, musculos_secundarios, met, imagen, imagen_final, instrucciones, consejos)
select e->>0, e->>1, e->>2, e->>3, e->>4, e->>5, e->>6, (e->>7)::boolean,
  array(select jsonb_array_elements_text(e->8)), array(select jsonb_array_elements_text(e->9)),
  (e->>10)::numeric, e->>11, e->>12,
  array(select jsonb_array_elements_text(e->13)), array(select jsonb_array_elements_text(e->14))
from jsonb_array_elements($j$[["jackknife-sit-up","Abdominal navaja","Un crunch de cuerpo completo realizado desde el suelo, levantando las piernas y el torso simultáneamente para tocar las manos con los pies.","Core","Fuerza","Intermedio","Sin equipo",true,["Recto abdominal"],["Flexores de cadera","Oblicuos"],5.0,"jackknife-sit-up-start.webp","jackknife-sit-up-peak.webp",["Acuéstate boca arriba en el suelo con los brazos extendidos por encima de la cabeza y las piernas estiradas.","Levanta simultáneamente el torso y las piernas rectas del suelo.","Lleva las manos hacia los pies mientras estos suben — encuéntralos sobre las caderas.","Baja el torso y las piernas de vuelta al suelo con control.","Repite el número recomendado de repeticiones."],["Brazos y piernas se mueven a la misma velocidad — evita hacer trampa levantando primero las piernas.","Si la zona lumbar se arquea al bajar, reduce la velocidad y no toques completamente el suelo."]],["sit-ups","Abdominales","Un ejercicio abdominal clásico con rango de movimiento completo.","Pierna","Fuerza","Principiante","Sin equipo",true,["Flexores de cadera","Recto abdominal"],["Oblicuos"],5.0,"sit-ups-start.webp","sit-ups-peak.webp",["Acuéstate boca arriba con las rodillas flexionadas y los pies anclados.","Cruza los brazos sobre el pecho o coloca las manos detrás de la cabeza.","Siéntate completamente hasta que el torso quede erguido.","Baja con control.","Repite."],["No tires del cuello con las manos al subir.","Exhala mientras subes para mantener el abdomen activo.","Si notas tirantez lumbar, reduce el rango de movimiento."]],["machine-seated-crunch","Abdominales en Máquina Sentado","Un ejercicio de aislamiento abdominal en una máquina sentada que flexiona la columna contra resistencia.","Core","Fuerza","Principiante","Máquina de abdominales",false,["Recto abdominal"],["Oblicuos","Transverso abdominal"],5.0,"machine-seated-crunch-start.webp","machine-seated-crunch-peak.webp",["Siéntate en la máquina de abdominales y sujeta las manijas.","Coloca la almohadilla de pecho contra tu torso.","Contrae el abdomen para flexionar el torso hacia adelante y abajo.","Contrae al final del recorrido.","Vuelve a la posición inicial con control.","Repite el número de repeticiones deseado."],["Inicia el movimiento con el abdomen, no con los brazos.","Exhala mientras flexionas el torso.","Evita el impulso balanceando el cuerpo."]],["side-lying-hip-abduction","Abducción de Cadera Acostado de Lado","Un ejercicio de aislamiento con peso corporal que trabaja el glúteo medio y los abductores de cadera.","Pierna","Fuerza","Principiante","Sin equipo",true,["Abductores","Glúteo medio"],[],3.5,"side-lying-hip-abduction-start.webp","side-lying-hip-abduction-peak.webp",["Acuéstate de lado con las piernas apiladas.","Mantén la pierna inferior ligeramente flexionada.","Eleva la pierna superior hacia el techo.","Baja con control.","Repite de ambos lados."],["Mantén las caderas apiladas durante todo el ejercicio.","Evita inclinar la pelvis."]],["side-lying-hip-abduction-hold","Abducción de Cadera Acostado de Lado Isométrica","La parte alta de la elevación lateral de pierna mantenida en el tiempo: tumbado de lado con la pierna superior elevada y ligeramente por detrás del cuerpo, cargando el glúteo medio de forma isométrica.","Pierna","Fuerza","Principiante","Sin equipo",true,["Abductores","Glúteo medio"],[],3.5,"side-lying-hip-abduction-hold-main.webp",null,["Túmbate de lado con las piernas estiradas y apiladas, apoyando la cabeza sobre el brazo inferior.","Aprieta el tronco para que el torso quede cuadrado y no ruede hacia atrás.","Eleva la pierna superior unos 30 o 45 grados, con los dedos del pie apuntando al frente.","Mantén la pierna ahí durante el tiempo indicado, respirando con normalidad.","Baja la pierna de forma controlada y repite del otro lado."],["Girar los dedos hacia el techo pasa el trabajo al flexor de la cadera; mantenlos mirando al frente.","Lleva la pierna algo por detrás de la línea del cuerpo para enfatizar el glúteo medio.","Apoya la mano superior en el suelo por delante si el equilibrio es lo que te limita."]],["banded-seated-hip-abduction","Abducción de Cadera Sentado con Banda","Este ejercicio de aislamiento trabaja el glúteo medio y mayor al rotar externamente las caderas contra la resistencia de una banda mientras estás sentado.","Pierna","Fuerza","Principiante","Banda circular",false,["Glúteo medio"],["Glúteo mayor"],5.0,"banded-seated-hip-abduction-start.webp","banded-seated-hip-abduction-peak.webp",["Siéntate en un banco o silla con una banda elástica alrededor de tus rodillas.","Mantén los pies apoyados en el suelo, separados al ancho de tus caderas, y conserva una postura erguida.","Empuja tus rodillas hacia afuera contra la banda, activando tus glúteos.","Sostén la contracción máxima brevemente, luego regresa lentamente tus rodillas a la posición inicial.","Controla el movimiento a lo largo de todo el rango de movimiento."],["Concéntrate en apretar tus glúteos para iniciar el movimiento.","Evita inclinarte hacia atrás o usar el impulso; mantén tu torso estable.","Elige una resistencia de banda que permita un movimiento controlado.","Mantén la tensión en la banda incluso en la posición inicial."]],["banded-standing-hip-abduction","Abducción de Cadera de Pie con Banda","Este ejercicio de aislamiento trabaja el glúteo medio y mayor, mejorando la estabilidad y fuerza de la cadera al abducir la pierna contra la resistencia de la banda.","Pierna","Fuerza","Principiante","Banda circular",false,["Glúteo medio"],["Glúteo mayor"],5.0,"banded-standing-hip-abduction-start.webp","banded-standing-hip-abduction-peak.webp",["Coloca una banda elástica alrededor de tus tobillos o justo encima de tus rodillas.","Ponte de pie con una ligera flexión de rodillas y activa tu core.","Transfiere tu peso a una pierna, manteniendo el torso estable.","Abduce lentamente la pierna libre hacia un lado, sintiendo la contracción del glúteo.","Controla el movimiento mientras regresas la pierna a la posición inicial.","Completa todas las repeticiones por lado antes de cambiar."],["Mantén tu torso erguido y evita inclinarte hacia un lado.","Concéntrate en un movimiento controlado, no en el impulso.","Asegúrate de que la banda mantenga la tensión durante todo el rango de movimiento.","Inicia el movimiento desde tu cadera, no desde tu pie."]],["hip-abduction","Abducción de Cadera en Máquina","Un ejercicio en máquina que trabaja los músculos de la cadera externa.","Pierna","Fuerza","Principiante","Máquina de abductores",false,["Glúteo medio"],["Abductores"],5.0,"hip-abduction-start.webp","hip-abduction-peak.webp",["Siéntate en la máquina de abducción de cadera con los apoyos contra la parte externa de los muslos.","Empuja las piernas hacia afuera contra la resistencia.","Mantén brevemente en el punto más amplio.","Vuelve a la posición inicial de forma controlada.","Repite."],["Mantén la espalda apoyada en el respaldo de la máquina.","Abre las piernas sin impulso, con un ritmo controlado.","Resiste la vuelta al centro en lugar de soltar el peso de golpe."]],["side-lying-hip-adduction","Aducción de Cadera Acostado de Lado","Un ejercicio de aducción tumbado de lado que eleva la pierna inferior contra la gravedad para trabajar la cadera con el propio peso.","Pierna","Fuerza","Intermedio","Sin equipo",true,["Aductores"],[],3.5,"side-lying-hip-adduction-start.webp","side-lying-hip-adduction-peak.webp",["Acuéstate de lado con la pierna inferior recta.","Flexiona la pierna superior y coloca su pie plano frente al muslo inferior.","Apoya la cabeza con el brazo inferior.","Eleva la pierna inferior hacia el techo.","Baja la pierna con control.","Completa las repeticiones de un lado y luego cambia."],["Mueve solo la pierna; la cadera y el torso quedan quietos.","Sube la pierna sin impulso y baja despacio.","Alinea hombros, cadera y pies antes de empezar a moverte."]],["side-lying-hip-adduction-hold","Aducción de Cadera Acostado de Lado Isométrica","La parte alta de la elevación de cara interna del muslo mantenida en el tiempo: tumbado de lado con la pierna superior cruzada por delante y la pierna inferior separada del suelo por los aductores.","Pierna","Fuerza","Intermedio","Sin equipo",true,["Aductores"],[],3.5,"side-lying-hip-adduction-hold-main.webp",null,["Túmbate de lado con la pierna inferior estirada y la superior cruzada por encima, con el pie apoyado en el suelo.","Apoya la cabeza sobre el brazo inferior y mantén las caderas apiladas en vertical.","Eleva la pierna inferior todo lo que puedas con la rodilla estirada y los dedos del pie al frente.","Mantén esa posición elevada durante el tiempo indicado sin rodar la cadera hacia atrás.","Baja la pierna de forma controlada y repite del otro lado."],["El recorrido es corto: unos pocos centímetros con la pelvis quieta valen más que un balanceo amplio.","Mantén la pierna elevada en línea con el torso en lugar de dejar que se vaya hacia delante.","Presiona ligeramente el pie superior contra el suelo si necesitas estabilizar la posición."]],["banded-standing-hip-adduction","Aducción de Cadera de Pie con Banda","Una aducción de cadera de pie con banda elástica, aislando los aductores del muslo interno.","Pierna","Fuerza","Principiante","Banda circular",false,["Aductores"],[],5.0,"banded-standing-hip-adduction-start.webp","banded-standing-hip-adduction-peak.webp",["Ancla una banda elástica a un poste firme a la altura del tobillo.","Pasa el bucle por la pierna que trabaja, orientada hacia el anclaje.","Aléjate algunos pasos para que la banda quede tensa.","Lleva la pierna que trabaja cruzando el cuerpo hacia la otra pierna.","Regresa lentamente. Completa las repeticiones por lado y cambia."],["Mantén la pierna de apoyo ligeramente flexionada para estabilidad.","Mueve solo la pierna que trabaja — el torso permanece quieto.","Controla la fase excéntrica para un estiramiento completo del aductor."]],["hip-adduction","Aducción de cadera","Un ejercicio en máquina apretando las piernas una contra otra frente a la resistencia, aislando y fortaleciendo los aductores de la cara interna del muslo.","Pierna","Fuerza","Intermedio","Máquina de aductores",false,["Aductores"],[],5.0,"hip-adduction-start.webp","hip-adduction-peak.webp",["Siéntate en la máquina de aducción de cadera con la espalda contra el respaldo.","Coloca las piernas contra las almohadillas con la máquina ajustada a un estiramiento cómodo.","Aprieta las piernas hasta que las almohadillas se junten en el centro.","Mantén brevemente la contracción en la posición completamente cerrada.","Deja que las piernas se abran de vuelta con control hasta el inicio.","Repite el número deseado de repeticiones."],["Elige una apertura inicial que estire sin forzar la ingle.","Recorre todo el rango a una velocidad uniforme y controlada.","No dejes que la placa de peso golpee al abrir las piernas."]],["plate-pinch","Agarre de Discos","Un ejercicio clásico para el agarre: pellizca dos discos con la cara lisa hacia afuera y mantenlos durante un tiempo determinado, cargando los flexores del pulgar y los dedos en trabajo isométrico sostenido.","Antebrazo","Fuerza","Intermedio","Discos",false,["Flexores del antebrazo"],["Trapecio"],5.0,"plate-pinch-start.webp","plate-pinch-peak.webp",["Coloca dos discos en el suelo uno al lado del otro con las caras lisas hacia afuera.","Baja en sentadilla, agarra ambos discos juntos entre los dedos y el pulgar de una mano — sin agarraderas, solo pellizca.","Levántate y sostén los discos al costado durante el tiempo deseado, manteniendo el brazo recto.","Devuélvelos al suelo con control.","Repite con la otra mano."],["Empieza con dos discos de 5 kg / 10 lb y ve aumentando.","La magnesia en las manos marca una gran diferencia; con las manos sudadas el agarre falla rápido."]],["banded-clamshell","Almeja con Banda","Una abducción de cadera tipo almeja con una banda circular por encima de las rodillas, que aísla el glúteo medio.","Pierna","Fuerza","Principiante","Banda circular",false,["Glúteo medio"],["Glúteo mayor"],5.0,"banded-clamshell-start.webp","banded-clamshell-peak.webp",["Túmbate de lado con las caderas y rodillas flexionadas a unos 45 grados y los pies juntos uno sobre otro.","Coloca una banda circular alrededor de ambas piernas por encima de las rodillas.","Mantén los pies pegados y la pelvis estable; no rotes hacia atrás durante el movimiento.","Abre la rodilla de arriba contra la banda, como una almeja al abrirse, hasta notar que el glúteo se activa.","Haz una breve pausa arriba y baja de forma controlada hasta la posición inicial.","Completa todas las repeticiones de un lado y luego cambia."],["La pelvis se queda fija; en cuanto rotas hacia atrás, el glúteo deja de trabajar.","Un tempo lento y controlado vale más que una banda dura.","Si te da un calambre en el lateral de la cadera, acorta la serie."]],["clamshells","Almejas","Un ejercicio de abducción de cadera, realizado tumbado de lado, que activa el glúteo medio sin material adicional.","Pierna","Fuerza","Intermedio","Sin equipo",true,["Abductores","Glúteo medio"],["Glúteo mayor"],5.0,"clamshells-start.webp","clamshells-peak.webp",["Túmbate de lado con las rodillas dobladas y apiladas una sobre la otra.","Mantén los pies juntos y las caderas alineadas.","Abre la rodilla superior hacia el techo sin rotar las caderas.","Aprieta el glúteo externo en la posición superior.","Baja de forma controlada. Completa las repeticiones de un lado y luego cambia."],["Sube la rodilla solo hasta donde la pelvis no se mueva.","Hazlo lento y controlado para notar bien el glúteo medio.","Exhala al abrir la rodilla y mantén el abdomen activo."]],["clamshells-hold","Almejas Isométricas","La posición final de la almeja mantenida en el tiempo: tumbado de lado con las rodillas flexionadas y apiladas, la rodilla superior se abre y la pelvis se mantiene firme, de modo que el glúteo medio trabaja de forma isométrica en lugar de por repeticiones.","Pierna","Fuerza","Intermedio","Sin equipo",true,["Abductores","Glúteo medio"],["Glúteo mayor"],5.0,"clamshells-hold-main.webp",null,["Túmbate de lado con las caderas y las rodillas flexionadas unos 45 y 90 grados, los talones juntos y las rodillas apiladas.","Alinea los hombros y las caderas en vertical y aprieta el tronco para que la pelvis no ruede hacia atrás.","Abre la rodilla superior todo lo que puedas sin que la pelvis rote, manteniendo los talones en contacto.","Mantén esa posición abierta durante el tiempo indicado, respirando con normalidad.","Baja la rodilla de forma controlada y repite del otro lado."],["Detén la apertura donde la pelvis empieza a rodar hacia atrás; el recorrido es menor de lo que la mayoría espera.","Mantén los talones presionados entre sí para que el movimiento se quede en la cadera y no en el tobillo.","Añade una banda circular por encima de las rodillas solo cuando la pelvis se mantenga completamente quieta."]],["incline-dumbbell-fly","Apertura con mancuernas en banco inclinado","Un ejercicio de aislamiento en banco inclinado que abre las mancuernas en un arco amplio, estirando y trabajando el pecho superior.","Pecho","Fuerza","Intermedio","Mancuernas",false,["Pectoral mayor"],["Deltoides anterior","Bíceps braquial"],5.0,"incline-dumbbell-fly-start.webp","incline-dumbbell-fly-peak.webp",["Acuéstate en un banco inclinado con mancuernas sobre el pecho.","Sube las mancuernas con las palmas enfrentadas.","Mantén una ligera flexión en los codos durante todo el movimiento.","Baja las mancuernas en un arco amplio hasta sentir el estiramiento del pecho.","Aprieta el pecho para juntar las mancuernas de nuevo.","Repite el número deseado de repeticiones."],["Mantén una ligera flexión fija en los codos en todo momento.","Baja solo hasta donde permita un estiramiento cómodo del pecho.","Aprieta el pecho para volver a juntar las mancuernas."]],["rear-delt-fly","Apertura de Deltoides Posterior","Un movimiento de aislamiento que trabaja los deltoides posteriores y la parte superior de la espalda.","Hombro","Fuerza","Principiante","Mancuernas",false,["Deltoides posterior","Romboides"],["Trapecio"],5.0,"rear-delt-fly-start.webp","rear-delt-fly-peak.webp",["Sostén las mancuernas e inclínate hacia adelante desde las caderas.","Con una ligera flexión en los codos, eleva las mancuernas hacia los lados.","Aprieta las escápulas en la parte superior.","Baja con control.","Repite."],["Elige un peso ligero para no usar impulso.","Mantén la espalda recta mientras estás inclinado hacia delante.","Lidera el movimiento con los codos, no con las manos."]],["cable-fly","Aperturas con Cable","Un ejercicio de aislamiento para el pecho con resistencia de cable para tensión constante.","Pecho","Fuerza","Intermedio","Polea",false,["Pectoral mayor"],["Deltoides anterior"],5.0,"cable-fly-start.webp","cable-fly-peak.webp",["Colócate entre dos columnas de cable con los agarres enganchados a las poleas altas.","Con una ligera flexión en los codos, abre los brazos hacia los lados.","Junta las manos frente al pecho en un movimiento de abrazo.","Vuelve lentamente a la posición inicial.","Repite."],["Mantén el ángulo de los codos constante para no convertirlo en un press.","Aprieta el pecho un segundo cuando las manos se encuentren.","No adelantes los hombros cuando los brazos están abiertos."]],["db-fly","Aperturas con Mancuernas","Un ejercicio de aislamiento que estira y contrae el pectoral a través de un amplio arco de movimiento.","Pecho","Fuerza","Principiante","Mancuernas",false,["Pectoral mayor"],["Deltoides anterior"],5.0,"db-fly-start.webp","db-fly-peak.webp",["Túmbate en un banco con las mancuernas sobre el pecho y las palmas mirándose entre sí.","Con una ligera flexión de codos, baja las mancuernas hacia los lados.","Regresa a la posición inicial apretando el pecho.","Repite."],["Mantén una flexión constante en los codos durante todo el ejercicio.","No bajes demasiado las mancuernas."]],["decline-db-fly","Aperturas con Mancuernas en Banco Declinado","Un movimiento de apertura en banco declinado para enfatizar el pecho inferior.","Pecho","Fuerza","Intermedio","Mancuernas",false,["Pectoral mayor"],["Deltoides anterior"],5.0,"decline-db-fly-start.webp","decline-db-fly-peak.webp",["Túmbate en un banco declinado sosteniendo mancuernas sobre el pecho.","Con una ligera flexión de codos, baja las mancuernas ampliamente hacia los lados.","Aprieta el pecho para subirlas de nuevo.","Repite."],["No extiendas completamente los codos.","Concéntrate en el estiramiento en la posición inferior."]],["machine-chest-fly","Aperturas en Máquina","Un ejercicio de aislamiento de pecho realizado en una máquina que junta las palancas en un arco frente al cuerpo.","Pecho","Fuerza","Principiante","Máquina de aperturas",false,["Pectoral mayor"],["Deltoides anterior","Serrato anterior"],5.0,"machine-chest-fly-start.webp","machine-chest-fly-peak.webp",["Siéntate en la máquina de aperturas y ajusta el asiento para que las palancas queden a la altura del pecho.","Sujeta las palancas con una ligera flexión de codos.","Junta las palancas frente al pecho en un arco suave.","Contrae el pectoral en el punto de máxima contracción.","Vuelve con control a la posición inicial sin dejar caer el peso.","Repite el número de repeticiones deseado."],["Mantén una flexión de codo ligera y constante durante todo el movimiento.","Enfócate en contraer el pecho en lugar de empujar con los brazos.","Controla el regreso en vez de dejar caer la pila de pesas."]],["snatch","Arrancada","Un levantamiento olímpico que tira de la barra desde el suelo hasta encima de la cabeza en un solo movimiento, recibida en una sentadilla por encima de la cabeza.","Cuerpo completo","Halterofilia","Intermedio","Barra",false,["Glúteo mayor","Cuádriceps","Trapecio"],["Erectores espinales","Isquiotibiales","Deltoides lateral"],8.0,"snatch-start.webp","snatch-peak.webp",["Párate con los pies al ancho de las caderas y agarra la barra con un agarre ancho.","Inclínate hacia abajo manteniendo la espalda plana y el pecho arriba.","Extiende explosivamente caderas, rodillas y tobillos para impulsar la barra hacia arriba.","Colócate debajo de la barra en una sentadilla por encima de la cabeza.","Levántate con la barra bloqueada por encima de la cabeza.","Devuelve la barra al suelo y repite."],["Mantén la barra cerca del cuerpo mientras sube.","Extiende completamente las caderas antes de tirar por debajo de la barra.","Bloquea los brazos y estabiliza antes de ponerte de pie."]],["back-lever","Back lever","Un isométrico gimnástico avanzado: colgado de una barra, el cuerpo se mantiene horizontal y boca abajo en línea recta, exigiendo tensión de todo el cuerpo a través de dorsales, core y cadena posterior.","Cuerpo completo","Fuerza","Avanzado","Barra de dominadas",false,["Erectores espinales","Dorsal ancho"],["Deltoides anterior","Glúteo mayor","Recto abdominal"],6.0,"back-lever-main.webp",null,["Cuélgate de una barra con agarre prono y rota hacia atrás a través de los brazos hasta quedar invertido.","Baja el cuerpo hacia delante y abajo hasta que quede horizontal, con la cara hacia el suelo.","Mantén los brazos rectos y todo el cuerpo en una línea rígida de la cabeza a los pies.","Aprieta el core y los glúteos para que la cadera y los hombros no se hundan.","Mantén la posición el tiempo deseado y rota de nuevo hacia arriba de forma controlada."],["Progresa con variantes agrupadas y a una pierna antes de intentar el lever completo con el cuerpo recto.","Deprime y retrae las escápulas para proteger los hombros.","Mantente rígido: cualquier flexión o arqueo colapsa la postura."]],["half-kneeling-hip-flexor-rock","Balanceo de Flexor de Cadera en Media Rodilla","La versión dinámica del estiramiento de flexor de cadera de rodillas: desde media rodilla las caderas se balancean hacia el estiramiento y vuelven, repetido en lugar de mantenido.","Pierna","Estiramiento","Principiante","Sin equipo",true,["Flexores de cadera"],["Glúteo mayor","Cuádriceps"],5.0,"half-kneeling-hip-flexor-rock-start.webp","half-kneeling-hip-flexor-rock-peak.webp",["Apóyate sobre una rodilla con el otro pie plano en el suelo por delante.","Mete ligeramente el coxis y aprieta el tronco para que la zona lumbar quede neutra.","Balancea las caderas hacia delante hasta notar el alargamiento en la parte frontal del muslo trasero.","Vuelve de forma controlada y repite con ritmo.","Cambia de lado y repite el mismo número de veces."],["Mantén el movimiento en las caderas; si la zona lumbar se arquea, acorta el recorrido.","Aprieta el glúteo de la pierna arrodillada durante el balanceo hacia delante.","Acolcha la rodilla de apoyo con una esterilla doblada si el suelo es duro."]],["stationary-bike","Bicicleta Estática","Un ejercicio cardiovascular sentado que mueve un volante de inercia mediante un pedaleo continuo, trabajando las piernas sin impacto sobre las articulaciones.","Pierna","Cardio","Principiante","Bicicleta estática",false,["Cuádriceps"],["Gemelos","Glúteo mayor","Isquiotibiales","Sóleo"],8.0,"stationary-bike-main.webp",null,["Ajusta la altura del sillín para que la rodilla quede ligeramente flexionada en el punto más bajo del pedaleo, siéntate y apoya la parte anterior de los pies en los pedales.","Sujeta el manillar con un agarre relajado y siéntate erguido, con la espalda neutra y los hombros bajos.","Empuja un pedal hacia abajo y hacia delante mientras el otro sube, manteniendo el esfuerzo en las piernas en lugar de tirar del manillar.","Sigue pedaleando en un círculo suave y regular a una cadencia constante, respirando al ritmo del pedaleo.","Ajusta la resistencia para sostener el esfuerzo que buscas y continúa durante el tiempo o la distancia deseados."],["Ajusta el sillín antes de empezar: demasiado bajo castiga las rodillas y demasiado alto hace que la cadera bascule de lado a lado en cada pedalada.","Empuja con las piernas y mantén el tren superior quieto — agarrarte y tirar del manillar solo añade tensión en el cuello y los hombros.","Sube la resistencia en lugar de girar los pedales sueltos y rápidos; un volante ligero a cadencia alta se siente duro en los pulmones pero aporta poco a las piernas."]],["air-bike","Bicicleta de Aire","Un ejercicio de cuerpo completo en bicicleta de aire que combina el empuje y la tracción de los brazos con el pedaleo continuo.","Cuerpo completo","Cardio","Intermedio","Bicicleta de aire",false,["Isquiotibiales","Cuádriceps"],["Glúteo mayor","Dorsal ancho","Pectoral mayor","Recto abdominal"],8.0,"air-bike-main.webp",null,["Siéntate en la bicicleta de aire y sujeta los manillares móviles.","Coloca los pies en los pedales y contrae el core.","Empuja y jala los manillares mientras pedaleas a un ritmo constante.","Impulsa con brazos y piernas para mantener la potencia.","Continúa durante la duración o distancia deseada."],["Mantén las rodillas alineadas con los pedales al pedalear.","Evita encorvar la espalda cuando aumente la fatiga.","Respira de forma rítmica para sostener la potencia."]],["bird-dog","Bird-Dog","Un ejercicio de estabilidad del core que extiende el brazo y la pierna opuestos para trabajar los erectores espinales y el core profundo.","Espalda","Fuerza","Principiante","Sin equipo",true,["Erectores espinales","Transverso abdominal"],["Glúteo mayor"],5.0,"bird-dog-start.webp","bird-dog-peak.webp",["Comienza a cuatro patas con la columna en posición neutra.","Extiende el brazo derecho hacia adelante y la pierna izquierda hacia atrás simultáneamente.","Aguanta un momento, luego vuelve.","Repite en el otro lado.","Alterna."],["Muévete lentamente y con control.","Mantén las caderas niveladas en todo momento."]],["bird-dog-hold","Bird-Dog Isométrico","Un ejercicio isométrico de core a cuatro patas que extiende un brazo y la pierna contraria manteniendo la columna estable.","Espalda","Fuerza","Intermedio","Sin equipo",true,["Erectores espinales","Recto abdominal"],["Glúteo mayor","Oblicuos","Deltoides posterior"],3.5,"bird-dog-hold-main.webp",null,["Comienza a cuatro patas con las manos bajo los hombros y las rodillas bajo las caderas.","Extiende un brazo hacia adelante y la pierna opuesta hacia atrás.","Mantén el core apretado y el cuerpo nivelado.","Aguanta la posición sin rotar el torso.","Mantén el tiempo indicado. Completa en un lado, luego cambia."],["Imagina que llevas un vaso de agua sobre la zona lumbar.","Evita que la cadera rote al extender la pierna.","Empuja el suelo con la mano de apoyo para estabilizar el hombro."]],["good-morning","Buenos Días","Un movimiento de bisagra de cadera con barra en la espalda para el desarrollo de la cadena posterior.","Espalda","Fuerza","Intermedio","Barra",false,["Erectores espinales","Glúteo mayor","Isquiotibiales"],[],6.0,"good-morning-start.webp","good-morning-peak.webp",["De pie con una barra sobre la parte superior de la espalda.","Realiza una bisagra de cadera empujando las caderas hacia atrás mientras mantienes la espalda plana.","Baja el torso hasta que quede casi paralelo al suelo.","Impulsa las caderas hacia adelante para volver a la posición erguida.","Repite."],["Mantén una ligera flexión de rodillas durante todo el movimiento.","Empieza con la barra vacía hasta dominar la bisagra de cadera.","Si la espalda se redondea, reduce el rango de movimiento."]],["banded-good-morning","Buenos Días con Banda","Un hip-hinge con banda elástica sobre la espalda alta, que trabaja isquiotibiales y glúteos.","Pierna","Fuerza","Principiante","Banda circular",false,["Glúteo mayor","Isquiotibiales"],["Erectores espinales"],6.0,"banded-good-morning-start.webp","banded-good-morning-peak.webp",["Pisa una banda elástica con ambos pies y pásala por la nuca.","Coloca los pies a la anchura de las caderas, ligera flexión de rodillas.","Flexiona desde la cadera empujándola atrás, espalda recta.","Baja hasta sentir el estiramiento en los isquiotibiales.","Empuja las caderas adelante para volver a la posición inicial."],["Mueve desde la cadera, no desde la zona lumbar.","Pecho arriba y espalda recta.","Usa una banda lo bastante ligera para permitir el rango completo."]],["bodyweight-good-morning","Buenos Días con Peso Corporal","Una bisagra de cadera con el propio peso corporal que fortalece los erectores espinales y los isquiotibiales.","Espalda","Fuerza","Principiante","Sin equipo",true,["Erectores espinales","Isquiotibiales"],["Glúteo mayor"],5.0,"bodyweight-good-morning-start.webp","bodyweight-good-morning-peak.webp",["Colócate de pie con los pies separados al ancho de las caderas y las manos detrás de la cabeza.","Mantén una ligera flexión en las rodillas y contrae el core.","Bisagra en las caderas y baja el torso hasta quedar casi paralelo al suelo.","Impulsa las caderas hacia adelante para volver a la posición erguida.","Repite el número deseado de repeticiones."],["Empuja la cadera hacia atrás como si cerraras un cajón.","Mantén la espalda recta durante toda la bajada.","Detén el descenso si notas que la zona lumbar se redondea."]],["smith-machine-good-morning","Buenos Días en Máquina Smith","Una bisagra de cadera con la barra de la máquina Smith apoyada sobre la espalda alta, inclinándote hacia delante desde las caderas contra una trayectoria fija para cargar isquiotibiales y erectores espinales.","Espalda","Fuerza","Principiante","Máquina Smith",false,["Erectores espinales","Isquiotibiales"],["Glúteo mayor"],6.0,"smith-machine-good-morning-start.webp","smith-machine-good-morning-peak.webp",["Coloca la barra a la altura de la espalda alta, métete debajo y apóyala sobre los trapecios; desengánchala con los pies al ancho de las caderas.","Flexiona ligeramente las rodillas y déjalas así: esto es una bisagra, no una sentadilla.","Empuja las caderas rectas hacia atrás y deja que el torso se incline hacia delante, con la espalda plana y la cabeza en línea con la columna.","Detente cuando sientas un estiramiento fuerte en los isquiotibiales, con el torso cerca de la paralela al suelo.","Lleva las caderas hacia delante para volver a erguirte, aprieta los glúteos arriba y repite las repeticiones deseadas."],["Usa mucho menos peso del que usarías en una sentadilla. Abajo, la barra queda muy lejos de tus caderas, y ese brazo de palanca, no el número en la barra, es lo que cuesta el ejercicio.","Caderas atrás, no pecho abajo. Si el torso baja sin que las caderas retrocedan, estás flexionando la columna en lugar de hacer bisagra en la cadera.","Termina el recorrido donde tu espalda empezaría a redondearse. En un buenos días la profundidad la marcan tus isquiotibiales, y la máquina te llevará encantada más allá de ese punto."]],["burpees","Burpees","Un ejercicio de acondicionamiento de cuerpo completo que combina sentadilla, plank, flexión y salto.","Cuerpo completo","Cardio","Intermedio","Sin equipo",true,["Glúteo mayor","Pectoral mayor","Cuádriceps"],["Deltoides anterior","Recto abdominal","Tríceps braquial"],8.0,"burpees-main.webp",null,["Mantente en pie con los pies a la anchura de los hombros.","Baja en sentadilla y apoya las manos en el suelo delante de ti.","Salta o lleva los pies atrás a la posición de plank y haz una flexión.","Salta o lleva los pies adelante hasta las manos.","Levántate y salta explosivamente con los brazos arriba."],["Mantén la espalda recta en el plank — no dejes caer las caderas.","Aterriza suavemente del salto.","Escálalo dando pasos atrás en lugar de saltar."]],["walking","Caminar","Marcha natural sobre terreno llano, manteniendo siempre un pie en contacto con el suelo, lo que la convierte en la forma de menor impacto de acumular trabajo aeróbico.","Cuerpo completo","Cardio","Principiante","Sin equipo",true,["Gemelos","Cuádriceps"],["Glúteo mayor","Isquiotibiales","Flexores de cadera","Sóleo"],3.5,"walking-main.webp",null,["Ponte erguido, con el peso sobre la parte media de los pies y los hombros relajados, sin llevarlos hacia atrás.","Da un paso al frente y apoya primero el talón, luego rueda sobre el pie y empuja con la almohadilla y los dedos.","Mantén al menos un pie en el suelo en todo momento — en cuanto ambos se despegan estás corriendo, no caminando.","Deja que los brazos oscilen con naturalidad desde el hombro, brazo contrario a pierna contraria, con los codos ligeramente flexionados.","Mira al frente en lugar de a los pies y respira con un ritmo constante y sostenible.","Continúa el tiempo o la distancia deseados, eligiendo un ritmo al que todavía podrías mantener una conversación."],["El ritmo lo es todo aquí. Un paseo y una caminata enérgica son estímulos distintos, así que elige uno a propósito en vez de dejarte llevar.","Alarga el empuje por detrás en lugar de estirar más hacia delante: la zancada larga te hace aterrizar con la pierna recta y frena cada paso.","Es el único trabajo de acondicionamiento que puedes hacer a diario sin necesitar recuperarte de él, y por eso merece la pena programarlo en vez de dejarlo al azar."]],["banded-lateral-walk","Caminata Lateral con Banda","Un desplazamiento lateral a pasos con una banda circular por encima de las rodillas o en los tobillos, que activa el glúteo medio.","Pierna","Fuerza","Principiante","Banda circular",false,["Glúteo medio"],["Glúteo mayor","Cuádriceps"],6.0,"banded-lateral-walk-start.webp","banded-lateral-walk-peak.webp",["Coloca una banda circular alrededor de las piernas por encima de las rodillas (o en los tobillos para una versión más difícil).","Ponte en cuarto de sentadilla: pies a la anchura de los hombros, caderas atrás, pecho alto y rodillas alineadas con los pies.","Da un paso lateral con un pie directamente hacia el lado contra la tensión de la banda.","Acerca el pie de atrás hacia el de delante manteniendo la tensión de la banda en todo momento; no dejes que los pies se junten de golpe.","Sigue dando pasos laterales en una dirección durante las repeticiones o la distancia indicada y luego invierte.","Permanece abajo todo el rato; no te incorpores entre paso y paso."],["Mantén las puntas de los pies hacia el frente; no dejes que el pie de delante se abra.","Las caderas se quedan niveladas; no te balancees de lado a lado al caminar.","Si las rodillas se van hacia dentro, la banda es demasiado dura; usa una más suave."]],["banded-sumo-walk","Caminata Sumo con Banda","Una caminata en posición sumo con banda sobre las rodillas, que trabaja el glúteo medio y mayor.","Pierna","Fuerza","Principiante","Banda circular",false,["Glúteo mayor","Glúteo medio"],["Cuádriceps"],6.0,"banded-sumo-walk-start.webp","banded-sumo-walk-peak.webp",["Coloca una banda elástica justo sobre las rodillas.","Baja a una media sentadilla con los pies más anchos que los hombros.","Avanza un paso al frente en posición ancha, mantén tensión en la banda.","Sigue avanzando alternando los pies por la distancia indicada.","Permanece bajo — no te incorpores entre pasos."],["Mantén tensión en la banda durante toda la serie.","Quédate en media sentadilla — no te levantes entre pasos.","Da pasos cortos y controlados con las puntas ligeramente afuera."]],["dumbbell-farmers-walk","Caminata del Granjero con Mancuernas","Este ejercicio de cuerpo completo implica caminar sosteniendo mancuernas pesadas, desarrollando eficazmente la fuerza de agarre, la estabilidad del core y la resistencia muscular general.","Cuerpo completo","Fuerza","Principiante","Mancuernas",false,["Flexores del antebrazo","Trapecio"],["Glúteo mayor","Oblicuos","Cuádriceps","Recto abdominal"],5.5,"dumbbell-farmers-walk-main.webp",null,["Párate erguido con una mancuerna en cada mano, los brazos extendidos a los lados.","Retrae tus escápulas y activa tu core, manteniendo una columna vertebral neutra.","Camina lenta y deliberadamente por una distancia o duración establecida, dando pasos cortos y controlados.","Mantén el pecho erguido y evita inclinarte hacia un lado mientras caminas.","Concéntrate en mantener una postura fuerte y estable durante todo el movimiento."],["Usa las mancuernas más pesadas que puedas controlar sin comprometer la forma.","Respira profunda y rítmicamente para mantener la tensión del core.","Imagina que estás equilibrando un vaso de agua sobre tu cabeza."]],["bear-crawl","Caminata del Oso","Un gateo en cuadrupedia sobre manos y puntas de los pies con las rodillas suspendidas justo por encima del suelo, que desarrolla la estabilidad del hombro y el control del core al desplazarse hacia adelante.","Cuerpo completo","Fuerza","Principiante","Sin equipo",true,["Deltoides anterior","Recto abdominal"],["Oblicuos","Cuádriceps","Tríceps braquial"],5.0,"bear-crawl-start.webp","bear-crawl-peak.webp",["Empieza en cuadrupedia con las manos bajo los hombros y las rodillas bajo las caderas.","Apoya las puntas de los pies y eleva las rodillas unos centímetros del suelo.","Con la espalda plana y las caderas bajas, avanza juntos la mano derecha y el pie izquierdo.","Luego mueve la mano izquierda y el pie derecho, gateando hacia adelante con ritmo controlado.","Mantén el core firme y evita que las caderas se balanceen de lado a lado."],["Mueve juntos la mano y el pie opuestos, como un gateo exagerado.","Mantén las rodillas bajas y las caderas niveladas: que no suban ni se balanceen."]],["incline-treadmill-walk","Caminata en Cinta Inclinada","Una caminata cuesta arriba sostenida sobre una cinta inclinada, manteniendo siempre un pie en contacto con la banda para que glúteos e isquiotibiales trabajen duro casi sin impacto.","Cuerpo completo","Cardio","Principiante","Cinta de correr",false,["Glúteo mayor","Cuádriceps"],["Gemelos","Isquiotibiales","Sóleo"],8.0,"incline-treadmill-walk-main.webp",null,["Arranca la banda a velocidad de caminata lenta, súbete y luego eleva la inclinación hasta la pendiente que buscas.","Camina con una zancada larga y deliberada, rodando del talón a la punta y empujando la banda hacia atrás en cada paso.","Mantente erguido e inclínate hacia la cuesta desde los tobillos, sin doblarte hacia delante por la cintura.","Mantén al menos un pie sobre la banda en todo momento — camina la cuesta, no la trotes.","Deja que los brazos se balanceen con naturalidad o apóyalos suavemente en los raíles para equilibrarte, sin descargar el peso en ellos.","Sostén la pendiente durante el tiempo deseado, luego bájala y camina en llano unos minutos para terminar."],["Elige una velocidad a la que todavía puedas caminar. En cuanto necesites una fase de vuelo para seguir el ritmo, baja la velocidad o la inclinación — es una caminata, no una carrera.","Colgar el peso del cuerpo de los pasamanos elimina casi todo el trabajo que la cuesta está ahí para generar; tócalos solo para equilibrarte.","Es la pendiente pronunciada la que traslada el esfuerzo del cuádriceps a glúteos e isquiotibiales, así que sube la inclinación antes que la velocidad."]],["hang-clean","Cargada desde Colgante","Una variante de la cargada que comienza con la barra a la altura de los muslos, entrenando la triple extensión explosiva y una recepción rápida.","Cuerpo completo","Halterofilia","Intermedio","Barra",false,["Glúteo mayor","Cuádriceps","Trapecio"],["Deltoides anterior","Erectores espinales","Isquiotibiales"],8.0,"hang-clean-start.webp","hang-clean-peak.webp",["De pie, sujeta la barra con agarre a la anchura de los hombros a la altura de los muslos.","Realiza una bisagra de cadera para bajar la barra justo por encima de las rodillas.","Extiende caderas, rodillas y tobillos de forma explosiva.","Encoge los hombros y tira de la barra hacia arriba.","Recibe la barra sobre los deltoides frontales en un cuarto de sentadilla.","Ponte erguido y luego vuelve a la posición de colgante."],["Flexiona las caderas hasta justo por encima de las rodillas antes de explotar hacia arriba.","Encoge los hombros y tira de la barra cerca del cuerpo.","Recibe la barra sobre los hombros en un cuarto de sentadilla."]],["treadmill-running","Carrera en Cinta","Una carrera realizada sobre una cinta motorizada, que permite sostener un ritmo y una distancia bajo techo controlando la superficie y la pendiente.","Cuerpo completo","Cardio","Principiante","Cinta de correr",false,["Gemelos","Cuádriceps"],["Glúteo mayor","Isquiotibiales","Flexores de cadera","Sóleo"],8.0,"treadmill-running-main.webp",null,["Súbete a la cinta con un pie sobre cada raíl lateral, arranca la banda a velocidad de caminata y pisa cuando ya esté en movimiento.","Sube progresivamente hasta tu ritmo de carrera, apoyando el pie bajo la cadera en lugar de estirar la zancada hacia delante.","Corre erguido con los hombros relajados, los codos flexionados unos noventa grados y los brazos balanceándose adelante y atrás, no cruzando el cuerpo.","Mira al frente y mantente en el centro de la banda en lugar de dejarte llevar hacia el rodillo trasero.","Sostén el ritmo durante el tiempo o la distancia deseados, luego baja la velocidad y camina unos minutos antes de bajarte."],["Engancha la llave de seguridad a la cinturilla — es lo único que detiene la banda si pierdes el pie.","No te agarres a los pasamanos mientras corres. Apoyarte en ellos acorta la zancada, tuerce la postura y oculta cuánto estás trabajando de verdad.","Una pendiente del uno o dos por ciento acerca la carrera en cinta a la carrera al aire libre, donde además hay que vencer la resistencia del aire."]],["clean","Clean","Un levantamiento olímpico en el que tiras de la barra de forma explosiva desde el suelo hasta la posición de rack frontal sobre los hombros.","Cuerpo completo","Halterofilia","Intermedio","Barra",false,["Glúteo mayor","Cuádriceps"],["Deltoides anterior","Erectores espinales","Isquiotibiales","Trapecio"],8.0,"clean-start.webp","clean-peak.webp",["Colócate sobre una barra cargada con los pies a la anchura de las caderas.","Agarra la barra justo por fuera de las rodillas con un agarre prono.","Empuja de forma explosiva con las piernas y extiende las caderas.","Métete bajo la barra y recíbela sobre los deltoides anteriores.","Ponte completamente erguido para completar el levantamiento."],["Mantén la barra cerca del cuerpo mientras sube.","Completa el empuje de piernas antes de tirar por debajo de la barra.","Recibe con los codos altos para que la barra descanse en los hombros."]],["clean-and-jerk","Clean and Jerk","Un levantamiento olímpico en dos partes: cargas la barra hasta los hombros y luego la impulsas por encima de la cabeza en posición de tijera.","Cuerpo completo","Halterofilia","Intermedio","Barra",false,["Deltoides anterior","Glúteo mayor","Cuádriceps"],["Erectores espinales","Trapecio","Tríceps braquial"],8.0,"clean-and-jerk-start.webp","clean-and-jerk-peak.webp",["Lleva la barra cargada desde el suelo hasta los hombros como en un clean.","Ponte completamente erguido con la barra apoyada en los deltoides anteriores.","Flexiona ligeramente las rodillas y lanza la barra sobre la cabeza de forma explosiva.","Separa las piernas para recibir la barra con los brazos extendidos.","Recupera la posición juntando los pies."],["Ponte de pie por completo y recoloca tu posición antes de iniciar el envión.","Impulsa la barra con las piernas, no solo con los brazos.","Bloquea los brazos mientras los pies aterrizan en la tijera."]],["double-kettlebell-clean-and-press","Clean and press con doble kettlebell","Un ejercicio de fuerza de cuerpo completo que sube dos kettlebells desde el suelo hasta la posición de rack en los hombros y luego las presiona por encima de la cabeza hasta la extensión completa en una secuencia continua.","Hombro","Fuerza","Avanzado","Kettlebell",false,["Deltoides anterior","Deltoides lateral"],["Glúteo mayor","Cuádriceps","Recto abdominal","Trapecio","Tríceps braquial"],8.0,"double-kettlebell-clean-and-press-start.webp","double-kettlebell-clean-and-press-peak.webp",["Colócate con dos kettlebells en el suelo entre los pies, separados a la anchura de las caderas, y flexiona las caderas para agarrar un asa con cada mano.","Empuja con las piernas y extiende las caderas de forma explosiva para tirar de ambas kettlebells hacia arriba; luego rota los codos por debajo y recibe las pesas en la posición de rack, al frente de los hombros.","Activa el core y presiona ambas kettlebells por encima de la cabeza hasta bloquear los brazos por completo.","Baja las kettlebells de vuelta a la posición de rack y después al suelo de forma controlada.","Repite las repeticiones deseadas."],["Mantén las kettlebells cerca del cuerpo durante el clean y pasa las manos alrededor y a través de las asas al recibirlas, para que las pesas se asienten sobre los antebrazos en lugar de golpearlos.","Inicia la presión con un breve impulso de piernas y caderas (dip-drive) y termina con los hombros; mantén el core firme para no inclinarte hacia atrás bajo la carga.","En el bloqueo mantén las muñecas rectas y las kettlebells alineadas sobre los codos y los hombros, con la cabeza en posición neutra entre las pesas."]],["double-kettlebell-clean","Clean con Dos Pesas Rusas","Un jalón de cadera explosivo que lleva dos pesas rusas simultáneamente hasta los hombros en posición de rack, base para los press y jerk con doble pesa rusa.","Pierna","Fuerza","Avanzado","Kettlebell",false,["Glúteo mayor","Isquiotibiales"],["Deltoides anterior","Erectores espinales","Flexores del antebrazo","Trapecio"],8.0,"double-kettlebell-clean-start.webp","double-kettlebell-clean-peak.webp",["Ponte de pie con dos pesas rusas en el suelo entre tus pies, con las asas ligeramente giradas hacia adentro.","Inclínate desde las caderas, agarra las asas y envía las pesas rusas hacia atrás entre las piernas.","Extiende las caderas de forma explosiva para impulsar las pesas rusas hacia arriba a lo largo del cuerpo.","Cuando lleguen a la altura del pecho, mete las manos por las asas para recibirlas en la posición de rack sobre los hombros.","Baja de vuelta a la posición colgante inclinándote desde las caderas y guiando las pesas entre las piernas.","Repite el número de repeticiones recomendado."],["Mete las manos por las asas — no dejes que las pesas se vuelquen y golpeen las muñecas.","El impulso viene de las caderas; los brazos solo guían el trayecto."]],["cocoons","Cocoons","Un ejercicio abdominal dinámico que combina un encogimiento de rodillas con un crunch desde una posición extendida boca arriba.","Core","Fuerza","Intermedio","Sin equipo",true,["Recto abdominal"],["Flexores de cadera","Oblicuos"],5.0,"cocoons-start.webp","cocoons-peak.webp",["Túmbate boca arriba con los brazos extendidos sobre la cabeza; manos y pies ligeramente elevados.","Lleva las rodillas al pecho y balancea los brazos hacia adelante en un crunch simultáneamente.","Intenta tocar las espinillas con las manos en el punto máximo.","Extiende brazos y piernas de forma controlada sin tocar el suelo.","Repite el movimiento durante las repeticiones indicadas."],["Las manos y los pies no tocan el suelo entre repeticiones.","Exhala con fuerza al llegar al punto máximo."]],["dead-hang","Colgado Pasivo","Una suspensión estática en barra de dominadas que fortalece el agarre y la musculatura de antebrazos y espalda.","Antebrazo","Fuerza","Intermedio","Barra de dominadas",false,["Flexores del antebrazo"],["Dorsal ancho","Recto abdominal","Trapecio"],4.5,"dead-hang-main.webp",null,["Agarra la barra de dominadas con las palmas mirando hacia afuera, a la anchura de los hombros.","Cuélgate con los brazos completamente extendidos y los pies sin tocar el suelo.","Relaja los hombros y deja que el cuerpo cuelgue.","Mantén el core ligeramente activo.","Aguanta el tiempo deseado."],["Empieza con tiempos cortos y auméntalos de forma gradual.","Respira tranquilo y evita tensar el cuello.","Baja con control en lugar de soltarte de golpe."]],["running","Correr","Carrera al aire libre, con una fase de vuelo en cada zancada en la que ningún pie toca el suelo — el impacto y el esfuerzo que la separan de caminar.","Cuerpo completo","Cardio","Principiante","Sin equipo",true,["Gemelos","Cuádriceps"],["Glúteo mayor","Isquiotibiales","Flexores de cadera","Sóleo"],8.0,"running-main.webp",null,["Empieza con un trote suave y sube hasta tu ritmo durante los primeros minutos, en lugar de salir directamente a la velocidad objetivo.","Apoya el pie bajo la cadera, no por delante del cuerpo, y mantén el contacto con el suelo corto y silencioso.","Corre erguido desde la cadera, con una ligera inclinación desde los tobillos y sin doblarte por la cintura.","Flexiona los codos unos noventa grados y lleva los brazos adelante y atrás, sin cruzarlos sobre el pecho.","Respira con ritmo y mantén sueltos los hombros, la mandíbula y las manos.","Sostén el ritmo el tiempo o la distancia deseados, luego trota y camina unos minutos para terminar."],["Aumenta el volumen semanal poco a poco. Casi toda lesión al correr viene de sumar kilómetros más rápido de lo que se adaptan tendones y huesos, no de una sola tirada dura.","La mayor parte de tus carreras debe ser lo bastante suave como para poder hablar. Correr cada sesión a un ritmo medio-fuerte es la vía más rápida al estancamiento.","Si notas que pisas con estruendo, acorta la zancada y deja subir la cadencia — buscar un paso más largo pone el freno en cada apoyo."]],["cross-body-crunch","Crunch Cruzado","Un crunch de oblicuos en el suelo que acerca el codo y la rodilla opuestos entre sí, trabajando los oblicuos y el recto abdominal juntos.","Core","Fuerza","Principiante","Sin equipo",true,["Oblicuos"],["Recto abdominal"],3.5,"cross-body-crunch-start.webp","cross-body-crunch-peak.webp",["Túmbate boca arriba en el suelo con las rodillas dobladas y las manos ligeramente detrás de las orejas.","Contrae y rota llevando el codo derecho hacia la rodilla izquierda mientras la rodilla sube.","Regresa a la posición inicial de forma controlada.","Repite del otro lado, alternando en cada repetición."],["Gira desde la caja torácica, no desde los brazos; los codos siguen a los hombros.","La zona lumbar permanece en el suelo durante todo el ejercicio."]],["decline-crunch","Crunch Declinado","Un crunch realizado en banco declinado, aumentando el rango de movimiento y la resistencia sobre los abdominales.","Core","Fuerza","Intermedio","Sin equipo",true,["Recto abdominal"],["Flexores de cadera","Oblicuos"],3.5,"decline-crunch-start.webp","decline-crunch-peak.webp",["Asegura los pies en la parte superior del banco declinado.","Recuéstate con las manos cruzadas sobre el pecho o detrás de la cabeza.","Sube contrayendo la columna hacia las rodillas.","Aprieta el abdomen en la posición superior.","Baja de forma controlada y repite."],["Enrolla la columna en lugar de tirar del cuello.","Exhala al subir y aprieta los abdominales arriba.","Baja despacio en lugar de dejarte caer sobre el banco."]],["cable-crunch","Crunch con Cable","Un encogimiento abdominal de rodillas en polea alta con cuerda, que permite añadir carga progresiva al trabajo del recto abdominal.","Core","Fuerza","Intermedio","Polea",false,["Recto abdominal"],["Oblicuos","Transverso abdominal"],5.0,"cable-crunch-start.webp","cable-crunch-peak.webp",["Arrodíllate frente a una máquina de cable con el accesorio de cuerda en la parte superior.","Sujeta la cuerda cerca de la frente con los codos flexionados.","Baja flexionando la columna y llevando los codos hacia los muslos.","Aprieta fuerte los abdominales en la parte inferior.","Vuelve a la posición inicial y repite."],["Flexiona la columna en lugar de tirar con los brazos.","Evita sentarte hacia atrás con la cadera en cada repetición.","Exhala con fuerza al bajar para contraer mejor el abdomen."]],["bicycle-crunch","Crunch de Bicicleta","Una variación dinámica del crunch que trabaja tanto el recto abdominal como los oblicuos.","Core","Fuerza","Principiante","Sin equipo",true,["Oblicuos","Recto abdominal"],["Flexores de cadera"],5.0,"bicycle-crunch-start.webp","bicycle-crunch-peak.webp",["Acuéstate boca arriba con las manos detrás de la cabeza y las piernas elevadas.","Acerca una rodilla al pecho mientras rotas el torso para encontrarla con el codo opuesto.","Extiende esa pierna mientras traes la otra rodilla hacia adentro.","Continúa alternando en un movimiento de pedaleo.","Repite."],["No tires del cuello con las manos.","Lleva el hombro hacia la rodilla, no solo el codo.","Mantén la zona lumbar apoyada en el suelo."]],["weighted-wall-crunch","Crunch en Pared con Peso","Una variante del crunch con las piernas apartadas del movimiento —los pies apoyados contra una pared o un cajón, o simplemente las piernas en alto— para que la cadera no ayude y trabajen los abdominales.","Core","Fuerza","Intermedio","Discos",false,["Recto abdominal"],["Oblicuos"],5.0,"weighted-wall-crunch-start.webp","weighted-wall-crunch-peak.webp",["Túmbate boca arriba y coloca las piernas de modo que la cadera no pueda ayudar: apoya los pies contra una pared o un cajón, o mantén las piernas en alto con las rodillas flexionadas.","Sujeta un peso contra el pecho con ambas manos: un disco, una mancuerna o una pesa rusa sirven igual.","Haz el crunch hacia arriba, despegando los omóplatos del suelo.","Baja de forma controlada.","Repite."],["Apoya los pies en la pared con las rodillas a 90 grados.","Sujeta el disco sobre el pecho durante todo el ejercicio.","Despega los omóplatos del suelo sin tirar del cuello."]],["crunches","Crunches","Un ejercicio abdominal básico enfocado en el recto abdominal.","Core","Fuerza","Principiante","Sin equipo",true,["Recto abdominal"],["Oblicuos"],3.5,"crunches-start.webp","crunches-peak.webp",["Túmbate boca arriba con las rodillas dobladas y las manos detrás de la cabeza.","Enrolla el tronco superior hacia las rodillas levantando los omóplatos del suelo.","Aprieta el abdomen en la posición superior.","Baja con control.","Repite."],["No tires del cuello con las manos al subir.","Exhala al subir y mantén la zona lumbar pegada al suelo.","Piensa en acercar las costillas a la pelvis, no en sentarte."]],["reverse-crunches","Crunches Inversos","Un ejercicio de core en el suelo que enrolla la cadera hacia el pecho para trabajar la parte baja del abdomen.","Core","Fuerza","Intermedio","Sin equipo",true,["Recto abdominal"],["Flexores de cadera","Oblicuos","Transverso abdominal"],3.5,"reverse-crunches-start.webp","reverse-crunches-peak.webp",["Túmbate boca arriba con los brazos a los lados.","Eleva las piernas con las rodillas flexionadas a 90 grados.","Despega las caderas del suelo contrayendo el abdomen inferior.","Lleva las rodillas hacia el pecho.","Baja las caderas con control.","Repite el número deseado de repeticiones."],["Despega la cadera con el abdomen, no con impulso de las piernas.","Exhala al subir para activar mejor el abdomen.","Presiona los brazos contra el suelo para mayor estabilidad."]],["ring-dead-hang","Cuelgue Estático en Anillas","Un cuelgue pasivo en anillas de gimnasia. El agarre de rotación libre recluta más estabilizadores en las manos, los antebrazos y la cintura escapular que una barra fija.","Antebrazo","Fuerza","Intermedio","Anillas",false,["Flexores del antebrazo"],["Dorsal ancho","Recto abdominal","Trapecio"],4.5,"ring-dead-hang-main.webp",null,["Agarra un par de anillas de gimnasia con agarre neutro, palmas enfrentadas entre sí.","Cuélgate con los brazos completamente extendidos y los pies fuera del suelo.","Deja que las anillas giren naturalmente; no luches contra el agarre.","Mantén los hombros activos (sin encogerlos hacia las orejas) y el core ligeramente apretado.","Mantén la posición durante el tiempo deseado."],["Empieza con series cortas y aumenta el tiempo de forma progresiva.","Agarra fuerte con toda la mano, no solo con los dedos.","Baja apoyando los pies con control, no te sueltes de golpe."]],["battle-ropes","Cuerdas de Batalla","Un ejercicio de acondicionamiento de alta intensidad con cuerdas gruesas, trabaja espalda alta, hombros y agarre.","Cuerpo completo","Cardio","Intermedio","Cuerda de batalla",false,["Deltoides anterior","Deltoides lateral","Dorsal ancho"],["Flexores del antebrazo","Cuádriceps","Recto abdominal","Trapecio"],10.3,"battle-ropes-main.webp",null,["Ancla las cuerdas a un punto fijo y agarra un extremo en cada mano.","Da unos pasos atrás para que las cuerdas tengan tensión moderada.","Baja a una media sentadilla con los pies a la anchura de los hombros.","Mueve cada brazo arriba y abajo rápidamente generando ondas en las cuerdas.","Continúa durante el intervalo de trabajo indicado."],["Permanece en media sentadilla todo el intervalo.","Genera fuerza desde piernas y caderas, no solo desde los brazos.","Mantén las ondas constantes y compactas."]],["spider-curl","Curl Araña","Un curl tumbado boca abajo en banco inclinado con los brazos colgando verticales, aislando el bíceps en un rango estricto.","Bíceps","Fuerza","Intermedio","Mancuernas",false,["Bíceps braquial"],["Braquial anterior"],5.0,"spider-curl-start.webp","spider-curl-peak.webp",["Túmbate boca abajo en un banco inclinado con los brazos colgando rectos hacia abajo.","Sostén una mancuerna en cada mano con agarre supino.","Mantén los brazos superiores verticales mientras curleas los pesos hacia arriba.","Aprieta fuerte los bíceps en la parte superior.","Baja las mancuernas de forma controlada hasta la extensión completa.","Repite el número de repeticiones deseado."],["Mantén el pecho pegado al respaldo durante toda la serie.","Aprieta arriba sin dejar que los codos se desplacen hacia atrás.","Usa el rango completo: el estiramiento abajo es la mitad del beneficio."]],["strict-curl","Curl Estricto","Un curl de pie realizado sin ningún impulso corporal — el torso permanece quieto y los codos se mantienen fijos, de modo que el bíceps hace todo el trabajo.","Bíceps","Fuerza","Intermedio","Mancuernas",false,["Bíceps braquial"],["Braquial anterior","Flexores del antebrazo"],5.0,"strict-curl-start.webp","strict-curl-peak.webp",["Ponte de pie con una mancuerna en cada mano, los brazos a los costados y las palmas hacia adelante.","Fija los codos a los costados y contrae el core para que el torso no pueda balancearse.","Flexiona ambas mancuernas hacia arriba moviendo solo los codos.","Bájalas de forma controlada hasta que los brazos queden rectos.","Repite las repeticiones deseadas."],["Ponerte de pie con la espalda contra una pared o poste es una buena autoevaluación — si los hombros o las caderas se separan de ella, estás usando impulso.","Evita que los codos se adelanten; los brazos superiores deben permanecer verticales durante todo el movimiento.","Baja más lento de lo que subes — la versión estricta vive en el descenso."]],["reverse-curl","Curl Inverso","Un curl con barra en agarre prono que trabaja el braquial y los extensores del antebrazo.","Bíceps","Fuerza","Principiante","Barra",false,["Braquial anterior","Extensores del antebrazo"],["Bíceps braquial"],5.0,"reverse-curl-start.webp","reverse-curl-peak.webp",["Párate y sostén la barra con agarre prono.","Sube la barra hacia los hombros.","Baja con control.","Repite."],["Mantén las muñecas rectas.","Realiza el movimiento en un rango completo de movimiento."]],["ez-bar-reverse-curl","Curl Inverso con Barra Z","Un curl inverso con barra Z que trabaja el braquial y los extensores del antebrazo con un agarre cómodo.","Bíceps","Fuerza","Principiante","Barra Z",false,["Braquial anterior","Extensores del antebrazo"],["Bíceps braquial"],5.0,"ez-bar-reverse-curl-start.webp","ez-bar-reverse-curl-peak.webp",["Sujeta una barra Z con agarre prono.","Sube la barra hacia tus hombros.","Baja de forma controlada.","Repite."],["Mantén los codos cerca del torso.","La barra Z reduce la tensión en las muñecas."]],["db-reverse-curl","Curl Inverso con Mancuernas","Una variación del curl con agarre prono que trabaja el braquial y los extensores del antebrazo.","Bíceps","Fuerza","Principiante","Mancuernas",false,["Braquial anterior","Extensores del antebrazo"],["Bíceps braquial"],5.0,"db-reverse-curl-start.webp","db-reverse-curl-peak.webp",["Sujeta las mancuernas con agarre prono a los costados.","Súbelas hasta la altura de los hombros.","Baja de forma controlada.","Repite."],["Mantén las muñecas neutras durante todo el ejercicio.","El movimiento controlado es clave."]],["cross-body-hammer-curl","Curl Martillo Cruzado","Un curl con agarre neutro que lleva la mancuerna cruzando el cuerpo hacia el hombro opuesto, enfatizando el braquial y los antebrazos.","Bíceps","Fuerza","Intermedio","Mancuernas",false,["Braquial anterior","Braquiorradial"],["Bíceps braquial","Flexores del antebrazo"],5.0,"cross-body-hammer-curl-start.webp","cross-body-hammer-curl-peak.webp",["De pie, sujeta una mancuerna en cada mano con agarre neutro.","Sube una mancuerna cruzando el cuerpo hacia el hombro opuesto.","Mantén el codo fijo a tu costado.","Baja de forma controlada y repite del otro lado.","Continúa alternando el número de repeticiones deseado."],["Mantén el codo pegado al costado durante todo el curl.","Evita balancear el torso para levantar el peso.","Baja con control en lugar de dejar caer la mancuerna."]],["preacher-hammer-curl","Curl Martillo en Banco Scott","Un curl de bíceps en banco Scott con agarre neutro tipo martillo que enfatiza el braquial y los antebrazos.","Bíceps","Fuerza","Intermedio","Mancuernas",false,["Braquial anterior","Braquiorradial"],["Bíceps braquial"],5.0,"preacher-hammer-curl-start.webp","preacher-hammer-curl-peak.webp",["Siéntate en un banco Scott con una mancuerna en cada mano.","Apoya los brazos superiores en la almohadilla con las palmas enfrentadas.","Flexiona las mancuernas hacia arriba manteniendo las muñecas neutras.","Contrae el bíceps en la parte alta del movimiento.","Baja las mancuernas con control.","Repite el número de repeticiones deseado."],["Mantén los brazos superiores apoyados en la almohadilla.","Evita bloquear completamente los codos en la parte baja.","Controla la bajada en lugar de dejar caer el peso."]],["nordic-hamstring-curl","Curl Nórdico de Isquiotibiales","Un ejercicio de flexión de rodilla bajando el torso hacia delante desde una posición arrodillada, trabajando los isquiotibiales de forma excéntrica.","Pierna","Fuerza","Avanzado","Banco GHD",false,["Isquiotibiales"],["Gemelos","Glúteo mayor"],5.0,"nordic-hamstring-curl-start.webp","nordic-hamstring-curl-peak.webp",["Arrodíllate sobre una colchoneta con los tobillos anclados bajo un soporte fijo.","Mantén el torso erguido y las caderas extendidas.","Baja el cuerpo hacia adelante lentamente resistiendo con los isquiotibiales.","Amortigua la caída con las manos justo antes de tocar el suelo.","Empuja con las manos para volver y tírate hacia la posición inicial.","Repite el número de repeticiones deseado."],["Baja tan despacio como sea posible: la fase excéntrica es el objetivo.","Mantén las caderas extendidas; no te dobles por la cintura.","Frénate con las manos y empuja ligeramente mientras ganas fuerza."]],["barbell-preacher-curl","Curl Predicador con Barra","Este ejercicio de aislamiento trabaja el bíceps braquial y el braquial al fijar los brazos en un banco predicador, minimizando el impulso y maximizando la tensión muscular.","Bíceps","Fuerza","Intermedio","Barra",false,["Bíceps braquial"],["Braquial anterior"],5.0,"barbell-preacher-curl-start.webp","barbell-preacher-curl-peak.webp",["Siéntate en un banco predicador con el pecho contra la almohadilla, sujetando una barra con agarre supino al ancho de los hombros.","Apoya firmemente tus brazos en la almohadilla, asegurándote de que tus codos estén ligeramente flexionados al inicio.","Sube la barra contrayendo tus bíceps, manteniendo tus brazos inmóviles sobre la almohadilla.","Aprieta los bíceps en la parte superior del movimiento, enfocándote en la contracción máxima.","Baja lentamente la barra a la posición inicial, controlando la fase excéntrica.","Extiende completamente tus brazos en la parte inferior para lograr un estiramiento completo en los bíceps."],["Mantén una tensión constante en los bíceps durante todo el rango de movimiento.","Evita levantar los codos de la almohadilla; esto indica que estás usando demasiado peso o impulso.","Concéntrate en una fase excéntrica (bajada) controlada para maximizar el daño muscular y el crecimiento.","Mantén tus muñecas rectas y alineadas con tus antebrazos para prevenir tensiones."]],["zottman-curl","Curl Zottman","Un curl con mancuernas de pie que sube con agarre supinado, gira las palmas hacia abajo en la parte superior y desciende en pronación para combinar el trabajo del bíceps con una fase excéntrica centrada en los antebrazos.","Bíceps","Fuerza","Intermedio","Mancuernas",false,["Bíceps braquial"],["Braquial anterior","Braquiorradial","Extensores del antebrazo"],5.0,"zottman-curl-start.webp","zottman-curl-peak.webp",["Colócate de pie con los pies aproximadamente al ancho de las caderas, los brazos extendidos a los lados y una mancuerna en cada mano con las palmas hacia delante.","Mantén los brazos junto a las costillas y lleva ambas mancuernas hacia los hombros sin balancear el torso.","En la parte superior, conserva los codos flexionados y gira los antebrazos hasta que las palmas miren hacia abajo.","Baja lentamente las mancuernas con el agarre pronado hasta extender los brazos.","Vuelve a girar las palmas hacia delante en la parte inferior y repite las repeticiones deseadas."],["Usa menos peso que en un curl con mancuernas convencional; la bajada con las palmas hacia abajo suele ser la parte limitante.","Gira desde los antebrazos y mantén las muñecas rectas en lugar de doblarlas alrededor de las empuñaduras.","Mantén los codos cerca de las costillas y evita convertir el curl en un balanceo de hombros."]],["barbell-curl","Curl con Barra","Un ejercicio clásico de aislamiento de bíceps que usa la barra para una carga máxima.","Bíceps","Fuerza","Principiante","Barra",false,["Bíceps braquial"],["Braquial anterior","Flexores del antebrazo"],5.0,"barbell-curl-start.webp","barbell-curl-peak.webp",["Párate sosteniendo una barra con agarre supino a la anchura de los hombros.","Sube la barra hacia los hombros.","Aprieta en la parte superior, luego baja de forma controlada.","Repite."],["Evita balancear el torso.","Mantén los codos pegados a los costados."]],["ez-bar-curl","Curl con Barra Z","Un ejercicio de aislamiento para el bíceps con barra Z, que reduce la tensión en las muñecas en comparación con una barra recta.","Bíceps","Fuerza","Principiante","Barra Z",false,["Bíceps braquial"],["Braquial anterior","Braquiorradial"],5.0,"ez-bar-curl-start.webp","ez-bar-curl-peak.webp",["Ponte de pie sujetando la barra Z con agarre supino en las partes anguladas.","Sube la barra hacia los hombros manteniendo los codos fijos.","Aprieta en la parte superior y luego baja de forma controlada.","Repite."],["Usa el agarre interior o exterior para variar el énfasis.","Mantén las muñecas en posición neutra en los agarres angulados."]],["close-grip-ez-bar-curl","Curl con Barra Z y Agarre Cerrado","Un curl de bíceps con barra Z y manos juntas, que carga más la cabeza larga del bíceps.","Bíceps","Fuerza","Principiante","Barra Z",false,["Bíceps braquial"],["Braquial anterior"],5.0,"close-grip-ez-bar-curl-start.webp","close-grip-ez-bar-curl-peak.webp",["Sujeta una barra Z con las manos en las curvas internas, palmas arriba.","Mantén los codos pegados al cuerpo.","Sube la barra hasta los hombros contrayendo el bíceps.","Baja con control hasta el estiramiento completo.","Repite el número de repeticiones indicado."],["Mantén los codos pegados — no dejes que se vayan adelante.","Contrae fuerte arriba.","Evita balancear el torso para tomar impulso."]],["cable-curl","Curl con Cable","Un curl de bíceps con resistencia de cable para tensión constante.","Bíceps","Fuerza","Principiante","Polea",false,["Bíceps braquial"],["Braquial anterior"],5.0,"cable-curl-start.webp","cable-curl-peak.webp",["Colócate de pie frente a una polea baja con una barra recta o barra Z.","Agarra la barra con agarre supino y los codos pegados a los costados.","Sube la barra hacia los hombros.","Baja de forma controlada.","Repite."],["Evita que los codos se adelanten al subir la barra.","No balancees el torso para ayudarte con el peso.","Aleja un poco el cuerpo de la polea para mantener la tensión."]],["cheat-curl","Curl con Impulso","Un curl de bíceps que emplea un ligero impulso de cadera para iniciar la subida y enfatiza una bajada lenta y controlada.","Bíceps","Fuerza","Intermedio","Barra",false,["Bíceps braquial"],["Braquial anterior","Braquiorradial","Erectores espinales"],5.0,"cheat-curl-start.webp","cheat-curl-peak.webp",["Colócate de pie sujetando el peso a la altura de los muslos con agarre supino.","Usa un ligero impulso de cadera para iniciar el curl.","Sube el peso hacia los hombros de forma explosiva.","Baja el peso lentamente de forma controlada por todo el rango de movimiento.","Repite el número deseado de repeticiones."],["Evita convertir el ejercicio en un balanceo de todo el cuerpo.","Si no puedes controlar la bajada, reduce la carga.","Mantén el abdomen firme para proteger la zona lumbar."]],["seated-dumbbell-curl","Curl con Mancuernas Sentado","Un curl de bíceps sentado con mancuernas, donde la posición sentada y erguida elimina el impulso para una técnica más estricta.","Bíceps","Fuerza","Principiante","Mancuernas",false,["Bíceps braquial"],["Braquial anterior","Braquiorradial"],5.0,"seated-dumbbell-curl-start.webp","seated-dumbbell-curl-peak.webp",["Siéntate en un banco con una mancuerna en cada mano.","Deja los brazos colgando a los lados con las palmas hacia adelante.","Sube ambas mancuernas hacia los hombros flexionando los bíceps.","Aprieta en la parte superior del movimiento.","Baja las mancuernas con control.","Repite el número deseado de repeticiones."],["Mantén los codos pegados a los costados en todo momento.","Evita inclinarte hacia atrás para ayudar a levantar el peso.","Estira los brazos por completo al final de cada repetición."]],["incline-db-curl","Curl con mancuernas en banco inclinado","Un curl de bíceps en banco inclinado para un mayor estiramiento de la cabeza larga.","Bíceps","Fuerza","Intermedio","Mancuernas",false,["Bíceps braquial"],["Braquial anterior"],5.0,"incline-db-curl-start.webp","incline-db-curl-peak.webp",["Siéntate en un banco inclinado a 45 grados con mancuernas a los lados.","Deja que los brazos cuelguen rectos con las palmas hacia adelante.","Sube las mancuernas hacia los hombros.","Baja con control hasta la extensión completa.","Repite."],["Mantén los hombros y la espalda apoyados en el banco.","No adelantes los hombros al subir las mancuernas.","Aprovecha el estiramiento abajo con una bajada lenta."]],["close-grip-barbell-curl","Curl de Barra con Agarre Cerrado","Un curl de barra de pie con agarre estrecho que enfatiza la cabeza larga del bíceps y el braquial.","Bíceps","Fuerza","Principiante","Barra",false,["Bíceps braquial"],["Braquial anterior","Braquiorradial"],5.0,"close-grip-barbell-curl-start.webp","close-grip-barbell-curl-peak.webp",["De pie, sujeta la barra con un agarre supino con las manos más juntas que la anchura de los hombros.","Comienza con la barra a la altura de los muslos, brazos extendidos y codos pegados a los costados.","Sube la barra hasta los hombros flexionando los codos.","Aprieta los bíceps en la parte superior y luego baja de forma controlada.","Repite el número de repeticiones recomendado."],["Mantén los codos pegados a los costados; no dejes que se desplacen hacia adelante.","Si el agarre estrecho molesta las muñecas, usa una barra Z."]],["trx-bicep-curl","Curl de Bíceps TRX","Este ejercicio utiliza un entrenador de suspensión para aislar y fortalecer los músculos bíceps braquial y braquial, desarrollando fuerza e hipertrofia en la parte superior del brazo.","Bíceps","Fuerza","Principiante","Entrenador de suspensión (TRX)",false,["Bíceps braquial"],["Braquial anterior","Braquiorradial"],5.0,"trx-bicep-curl-start.webp","trx-bicep-curl-peak.webp",["Ajusta las correas del entrenador de suspensión a una longitud media.","Párate frente al punto de anclaje, sujeta las asas con un agarre supino e inclínate hacia atrás hasta que tus brazos estén completamente extendidos.","Mantén tu cuerpo recto y el core activado, jala tu pecho hacia tus manos doblando los codos.","Contrae tus bíceps en la parte superior del movimiento.","Extiende lentamente tus brazos de regreso a la posición inicial, controlando el descenso.","Mantén la tensión durante toda la serie."],["Ajusta el ángulo de tu cuerpo para aumentar o disminuir la dificultad; inclinarte más hacia atrás lo hace más difícil.","Mantén los codos altos y fijos para aislar los bíceps de manera efectiva.","Evita balancear tu cuerpo o usar el impulso; concéntrate en una contracción controlada.","Asegura un rango completo de movimiento, desde la extensión total hasta una fuerte contracción máxima."]],["double-kettlebell-bicep-curl","Curl de Bíceps con Dos Pesas Rusas","Un curl de bíceps de pie con una pesa rusa en cada mano, sujeta por el asa. La masa descentrada en la parte inferior de la pesa añade un ligero reto de agarre y estabilidad.","Bíceps","Fuerza","Principiante","Kettlebell",false,["Bíceps braquial"],["Braquial anterior","Flexores del antebrazo"],5.0,"double-kettlebell-bicep-curl-start.webp","double-kettlebell-bicep-curl-peak.webp",["Ponte de pie sujetando una pesa rusa en cada mano por el asa, con las palmas mirando hacia adelante.","Mantén los codos pegados a los costados y las pesas colgando a lo largo de los brazos.","Sube ambas pesas rusas hacia los hombros flexionando los codos.","Aprieta los bíceps en la parte superior, luego baja de forma controlada hasta la posición inicial.","Repite el número de repeticiones recomendado."],["No dejes que las pesas oscilen — controla la fase excéntrica.","Los codos permanecen pegados a los costados; sin flexión de hombros.","Agarra con fuerza durante todo el movimiento; la pesa tiende a extender la muñeca."]],["bicep-curl","Curl de Bíceps con Mancuernas","Un ejercicio de aislamiento que trabaja los bíceps.","Bíceps","Fuerza","Principiante","Mancuernas",false,["Bíceps braquial"],["Braquial anterior","Flexores del antebrazo"],5.0,"bicep-curl-start.webp","bicep-curl-peak.webp",["Párate sosteniendo mancuernas a los lados, palmas hacia adelante.","Sube las mancuernas hacia los hombros.","Aprieta en la parte superior, luego baja de forma controlada.","Repite."],["Mantén los codos pegados a los costados.","Evita balancear las mancuernas."]],["one-arm-kettlebell-bicep-curl","Curl de Bíceps con Pesa Rusa a Un Brazo","Un curl de bíceps unilateral con pesa rusa que entrena cada brazo por separado e implica con fuerza el antebrazo.","Bíceps","Fuerza","Intermedio","Kettlebell",false,["Bíceps braquial"],["Braquial anterior","Flexores del antebrazo"],5.0,"one-arm-kettlebell-bicep-curl-start.webp","one-arm-kettlebell-bicep-curl-peak.webp",["De pie, sostén una pesa rusa en una mano.","Mantén el codo pegado al costado.","Sube la pesa rusa hacia el hombro flexionando el bíceps.","Aprieta en la parte superior del movimiento.","Baja la pesa rusa con control.","Completa las repeticiones de un lado y luego cambia."],["Mantén la muñeca recta aunque la pesa tire de ella.","Evita balancear el torso para ayudarte a subir el peso.","Empieza siempre por tu lado más débil."]],["machine-bicep-curl","Curl de Bíceps en Máquina","Un curl de bíceps en máquina para el entrenamiento aislado de brazos.","Bíceps","Fuerza","Principiante","Máquina de curl de bíceps",false,["Bíceps braquial"],["Braquial anterior"],5.0,"machine-bicep-curl-start.webp","machine-bicep-curl-peak.webp",["Siéntate en la máquina y ajusta el rodillo a la longitud de tus brazos.","Agarra las manijas con agarre en supinación.","Lleva las manijas hacia los hombros.","Baja con control.","Repite."],["Mantén los codos apoyados en la almohadilla en todo momento.","Evita encoger los hombros al subir las asas.","Baja hasta casi extender los brazos sin perder la tensión."]],["concentration-curl","Curl de Concentración","Un curl de aislamiento realizado sentado para la máxima contracción del bíceps.","Bíceps","Fuerza","Principiante","Mancuernas",false,["Bíceps braquial"],["Braquial anterior"],5.0,"concentration-curl-start.webp","concentration-curl-peak.webp",["Siéntate en un banco con las piernas separadas y sujeta una mancuerna en una mano.","Apoya el codo en la cara interna del muslo.","Sube la mancuerna hacia el hombro.","Baja con control.","Repite en ambos lados."],["No balancees el torso para ayudarte a subir.","Gira ligeramente la muñeca hacia fuera para contraer más el bíceps.","Trabaja ambos brazos por igual, empezando por el más débil."]],["trx-hamstring-curl","Curl de Isquiotibiales con TRX","Este ejercicio de aislamiento utiliza un entrenador de suspensión para trabajar los isquiotibiales, glúteos y pantorrillas al flexionar los talones hacia los glúteos.","Pierna","Fuerza","Intermedio","Entrenador de suspensión (TRX)",false,["Isquiotibiales"],["Gemelos","Glúteo mayor"],5.0,"trx-hamstring-curl-start.webp","trx-hamstring-curl-peak.webp",["Acuéstate boca arriba con los talones en los soportes del entrenador de suspensión, rodillas flexionadas a 90 grados.","Levanta tus caderas del suelo, creando una línea recta desde las rodillas hasta los hombros.","Extiende tus piernas hacia adelante, manteniendo las caderas elevadas y la tensión en el core.","Tira de tus talones hacia tus glúteos, contrayendo los isquiotibiales con fuerza.","Controla el movimiento, evitando que las caderas caigan durante toda la serie."],["Mantén tu core contraído para evitar que tus caderas se hundan.","Concéntrate en una fuerte contracción de los isquiotibiales en el punto máximo del curl.","Controla la fase excéntrica extendiendo lentamente tus piernas."]],["hammer-curl","Curl de Martillo con Mancuernas","Una variación del curl de bíceps con agarre neutro que trabaja el braquiorradial.","Bíceps","Fuerza","Principiante","Mancuernas",false,["Bíceps braquial","Braquial anterior"],["Flexores del antebrazo"],5.0,"hammer-curl-start.webp","hammer-curl-peak.webp",["De pie, sujeta las mancuernas a los lados con las palmas enfrentadas.","Sube las mancuernas manteniendo las palmas hacia adentro.","Aprieta en la parte alta y baja de forma controlada.","Repite."],["Mantén los codos pegados al torso durante todo el recorrido.","Evita balancear el cuerpo para impulsar las mancuernas.","Las muñecas van firmes y neutras durante todo el curl."]],["cable-hammer-curl","Curl de Martillo en Cable","Un curl en cable con cuerda y agarre neutro que trabaja el braquial y braquiorradial con tensión constante.","Bíceps","Fuerza","Intermedio","Polea",false,["Bíceps braquial","Braquial anterior","Braquiorradial"],["Flexores del antebrazo"],5.0,"cable-hammer-curl-start.webp","cable-hammer-curl-peak.webp",["Engancha una cuerda a la polea baja y párate frente a la máquina.","Agarra la cuerda con agarre neutro, palmas enfrentadas.","Sube la cuerda hacia los hombros manteniendo los codos fijos a los lados.","Aprieta arriba, luego baja lentamente hasta la extensión completa.","Repite el número de repeticiones deseado."],["Mantén los codos inmóviles durante todo el movimiento.","Separa ligeramente los extremos de la cuerda arriba para mayor contracción.","Evita balancear el torso."]],["kettlebell-reverse-wrist-curl","Curl de Muñeca Inverso con Kettlebell","Un curl de muñeca inverso unilateral con kettlebell, que entrena los extensores del antebrazo.","Antebrazo","Fuerza","Principiante","Kettlebell",false,["Extensores del antebrazo"],[],5.0,"kettlebell-reverse-wrist-curl-start.webp","kettlebell-reverse-wrist-curl-peak.webp",["Siéntate en un banco con el antebrazo sobre el muslo, palma hacia abajo.","Sujeta una kettlebell por el asa, muñeca fuera de la rodilla.","Deja caer la muñeca, bajando la kettlebell.","Levanta el dorso de la mano extendiendo la muñeca.","Baja con control. Repeticiones por lado."],["Usa una kettlebell muy ligera — los extensores se fatigan rápido.","Mueve solo la muñeca.","Sujeta el asa, no la bola."]],["db-reverse-wrist-curl","Curl de Muñeca Inverso con Mancuerna","Un curl de muñeca con mancuerna y palma hacia abajo, que entrena los extensores del antebrazo.","Antebrazo","Fuerza","Principiante","Mancuernas",false,["Extensores del antebrazo"],[],5.0,"db-reverse-wrist-curl-start.webp","db-reverse-wrist-curl-peak.webp",["Siéntate en un banco con el antebrazo sobre el muslo, palma hacia abajo.","Sujeta una mancuerna con la muñeca fuera de la rodilla.","Deja caer la muñeca, bajando la mancuerna.","Levanta el dorso de la mano hacia el techo extendiendo la muñeca.","Baja con control. Repeticiones por lado."],["Usa una carga mucho más ligera que en el curl de muñeca normal.","Mueve solo la muñeca.","Contrae la parte posterior del antebrazo arriba."]],["barbell-wrist-curl","Curl de Muñeca con Barra","Un curl de muñeca con barra que aísla los flexores del antebrazo para fuerza de agarre y tamaño.","Antebrazo","Fuerza","Principiante","Barra",false,["Flexores del antebrazo"],[],5.0,"barbell-wrist-curl-start.webp","barbell-wrist-curl-peak.webp",["Siéntate en un banco con los antebrazos sobre los muslos, palmas hacia arriba.","Sujeta una barra con las manos a la anchura de los hombros, muñecas fuera de las rodillas.","Deja que la barra ruede hasta las puntas de los dedos.","Sube la barra flexionando las muñecas.","Baja con control."],["Mueve solo la muñeca — los antebrazos permanecen quietos.","Rueda la barra a las puntas de los dedos para el rango completo.","Usa un agarre sin pulgar si te resulta más cómodo."]],["ez-bar-wrist-curl","Curl de Muñeca con Barra Z","Un curl de muñeca con barra Z, más amigable con las muñecas que la barra recta.","Antebrazo","Fuerza","Principiante","Barra Z",false,["Flexores del antebrazo"],[],5.0,"ez-bar-wrist-curl-start.webp","ez-bar-wrist-curl-peak.webp",["Siéntate en un banco con los antebrazos sobre los muslos, palmas hacia arriba.","Sujeta una barra Z por las curvas internas a la anchura de los hombros.","Deja que la barra ruede hasta las puntas de los dedos.","Sube la barra flexionando las muñecas.","Baja con control."],["El ángulo de la barra Z es más amable con las muñecas.","Mueve solo la muñeca — los antebrazos permanecen quietos.","Rueda la barra a las puntas de los dedos para el rango completo."]],["cable-wrist-curl","Curl de Muñeca con Cable","Un curl de muñeca en polea baja, con los antebrazos apoyados en un banco, que fortalece los flexores del antebrazo.","Antebrazo","Fuerza","Intermedio","Polea",false,["Flexores del antebrazo"],[],5.0,"cable-wrist-curl-start.webp","cable-wrist-curl-peak.webp",["Engancha una barra recta a la polea baja.","Arrodíllate o siéntate con los antebrazos sobre un banco, palmas hacia arriba.","Deja que las muñecas se flexionen sobre el borde del banco.","Sube la barra flexionando las muñecas.","Baja de forma controlada y repite."],["Mueve solo las muñecas, sin levantar los antebrazos del banco.","Usa cargas moderadas para no castigar las muñecas.","Sube y baja despacio, sin rebotes en el estiramiento."]],["kettlebell-wrist-curl","Curl de Muñeca con Kettlebell","Un curl de muñeca unilateral con kettlebell — el peso descentrado añade un reto extra al agarre.","Antebrazo","Fuerza","Principiante","Kettlebell",false,["Flexores del antebrazo"],[],5.0,"kettlebell-wrist-curl-start.webp","kettlebell-wrist-curl-peak.webp",["Siéntate en un banco con el antebrazo sobre el muslo, palma hacia arriba.","Sujeta una kettlebell por el asa, muñeca fuera de la rodilla.","Deja que la kettlebell rote hacia las puntas de los dedos.","Súbela flexionando la muñeca, controlando el peso descentrado.","Baja con control. Repeticiones por lado."],["Sujeta el asa, no la bola, para que el peso descentrado cargue el agarre.","Mueve solo la muñeca.","Usa una carga más ligera que con una mancuerna."]],["dumbbell-wrist-curl","Curl de Muñeca con Mancuerna","Un curl de muñeca con mancuerna que aísla los flexores del antebrazo y trabaja ambos brazos por separado.","Antebrazo","Fuerza","Principiante","Mancuernas",false,["Flexores del antebrazo"],["Braquiorradial"],5.0,"dumbbell-wrist-curl-start.webp","dumbbell-wrist-curl-peak.webp",["Siéntate en un banco con el antebrazo sobre el muslo, palma hacia arriba.","Sujeta una mancuerna con la muñeca fuera de la rodilla.","Deja que la mancuerna ruede hasta las puntas de los dedos.","Sube la mancuerna flexionando la muñeca.","Baja con control. Repeticiones por lado."],["Mueve solo la muñeca — el antebrazo permanece quieto.","Rueda la mancuerna a las puntas de los dedos para el rango completo.","Entrena ambos brazos con la misma carga y repeticiones."]],["wrist-curl","Curl de Muñeca con Mancuernas Bilateral","Un curl de muñeca con mancuernas realizado con ambos brazos a la vez, que aísla los flexores del antebrazo para un entrenamiento eficiente.","Antebrazo","Fuerza","Principiante","Mancuernas",false,["Flexores del antebrazo"],["Braquiorradial"],5.0,"wrist-curl-start.webp","wrist-curl-peak.webp",["Siéntate en un banco sujetando una mancuerna en cada mano, con los antebrazos apoyados sobre los muslos, palmas hacia arriba.","Deja que ambas mancuernas rueden hacia las puntas de los dedos.","Flexiona las muñecas para levantar ambas mancuernas.","Aprieta arriba y baja con control.","Repite el número deseado de repeticiones."],["Mantén los antebrazos apoyados en los muslos durante todo el movimiento — solo se mueven las muñecas.","Usa una carga por mano más ligera que en la versión unilateral, ya que ambos lados trabajan a la vez."]],["single-leg-lying-leg-curl","Curl de Pierna Tumbado a Una Pierna","Un curl femoral tumbado a una pierna en máquina, que aísla los isquiotibiales de cada lado por separado.","Pierna","Fuerza","Intermedio","Máquina de curl femoral",false,["Isquiotibiales"],["Gemelos"],5.0,"single-leg-lying-leg-curl-start.webp","single-leg-lying-leg-curl-peak.webp",["Acuéstate boca abajo en la máquina de curl de piernas tumbado.","Coloca un tobillo bajo el apoyo y deja el otro pie fuera de la máquina.","Flexiona la pierna de trabajo llevando el talón hacia el glúteo.","Aprieta los isquiotibiales en la parte superior.","Baja la pierna con control.","Completa las repeticiones de un lado y luego cambia."],["Mantén la cadera pegada al apoyo durante todo el recorrido.","Usa un peso que te permita subir y bajar sin tirones.","Empieza por la pierna más débil y repite igual con la otra."]],["banded-standing-curl","Curl de Pierna de Pie con Banda","Un curl femoral de pie con una banda elástica alrededor del tobillo, útil para viajes o como finalizador con poca carga para isquiotibiales.","Pierna","Fuerza","Principiante","Banda circular",false,["Isquiotibiales"],["Gemelos"],5.0,"banded-standing-curl-start.webp","banded-standing-curl-peak.webp",["Coloca una banda elástica alrededor de un tobillo y ancla el otro extremo bajo el pie de apoyo o en un punto fijo delante de ti.","Mantente erguido, sujétate a algo si necesitas equilibrio, con ligera flexión en la pierna de apoyo.","Sube el talón con la banda hacia el glúteo, manteniendo el muslo quieto.","Contrae el isquiotibial arriba, luego baja con control hasta el estiramiento completo.","Completa todas las repeticiones de un lado y cambia de pierna."],["Mantén el muslo quieto — solo se mueve la parte inferior de la pierna.","Evita balancear la cadera para tomar impulso.","Usa una banda más ligera si no puedes controlar el descenso."]],["seated-leg-curl","Curl de Piernas Sentado","Un ejercicio de aislamiento de isquiotibiales en máquina en posición sentada, con tensión constante y menor implicación de los flexores de cadera respecto a la variante tumbada.","Pierna","Fuerza","Principiante","Máquina de curl femoral",false,["Isquiotibiales"],["Gemelos"],5.0,"seated-leg-curl-start.webp","seated-leg-curl-peak.webp",["Ajusta el respaldo y el cojín de tobillo para que las rodillas queden alineadas con el pivote de la máquina.","Siéntate erguido, coloca la parte posterior de los tobillos sobre el cojín y sujeta las asas.","Flexiona las piernas hacia abajo y atrás bajo el asiento hasta donde la máquina lo permita.","Pausa en la contracción máxima, luego vuelve lentamente a la posición inicial.","Repite el número de repeticiones deseado."],["Mantén la espalda firmemente apoyada en el respaldo durante todo el movimiento.","Flexiona ligeramente los pies hacia las espinillas en la contracción máxima para mayor activación de los isquios.","Controla la fase excéntrica — no dejes que el peso jale las piernas de vuelta rápidamente."]],["leg-curl","Curl de Piernas Tumbado","Un ejercicio de aislamiento para los isquiotibiales usando la máquina de curl de piernas.","Pierna","Fuerza","Principiante","Máquina de curl femoral",false,["Isquiotibiales"],["Gemelos"],5.0,"leg-curl-start.webp","leg-curl-peak.webp",["Túmbate boca abajo en la máquina de curl de piernas con los tobillos bajo el rodillo.","Lleva los talones hacia los glúteos.","Aprieta los isquiotibiales en la parte superior.","Baja con control.","Repite."],["Mantén las caderas pegadas al banco durante todo el recorrido.","Evita arquear la zona lumbar al subir los talones.","Elige un peso que permita un recorrido completo y controlado."]],["ball-leg-curl","Curl de Piernas con Pelota de Estabilidad","Un curl de isquiotibiales con el propio peso usando una pelota de estabilidad, rodando los talones hacia los glúteos mientras se eleva la cadera.","Pierna","Fuerza","Intermedio","Pelota de estabilidad",false,["Isquiotibiales"],["Gemelos","Glúteo mayor"],5.0,"ball-leg-curl-start.webp","ball-leg-curl-peak.webp",["Acuéstate boca arriba en el suelo con los talones y la parte inferior de las pantorrillas sobre la pelota de estabilidad y los brazos estirados para hacer equilibrio.","Presiona con los talones para elevar las caderas formando una línea recta desde los hombros hasta los tobillos.","Manteniendo las caderas arriba, flexiona las rodillas para rodar la pelota hacia los glúteos.","Extiende las piernas de vuelta de forma controlada sin bajar las caderas.","Completa todas las repeticiones, luego baja las caderas y sepárate de la pelota."],["Las caderas permanecen arriba durante toda la serie: es una combinación de puente y curl.","Empieza con ambos pies; progresa a una sola pierna cuando se vuelva fácil."]],["kettlebell-concentration-curl","Curl de concentración con kettlebell","Un ejercicio de aislamiento de bíceps a una mano, sentado: el codo se apoya contra la cara interna del muslo mientras se curla una kettlebell, manteniendo el brazo quieto para que el bíceps haga todo el trabajo.","Bíceps","Fuerza","Principiante","Kettlebell",false,["Bíceps braquial"],["Braquial anterior"],5.0,"kettlebell-concentration-curl-start.webp","kettlebell-concentration-curl-peak.webp",["Siéntate en un banco con los pies bien separados, sujetando una kettlebell con una mano.","Apoya la parte posterior del brazo contra la cara interna del muslo y deja colgar la kettlebell.","Curla la kettlebell hacia el hombro, manteniendo el codo fijo contra la pierna.","Contrae el bíceps arriba y luego baja despacio y de forma controlada.","Termina todas las repeticiones de un lado y cambia de brazo."],["Mantén el brazo fijo y quieto: solo el antebrazo se mueve.","Rota ligeramente la muñeca al curlar para una contracción máxima más fuerte.","Usa un peso más ligero que en un curl normal: aquí importa más la técnica estricta."]],["preacher-curl","Curl en Banco Scott","Una variación del curl que usa un banco Scott para aislar el bíceps.","Bíceps","Fuerza","Principiante","Barra Z",false,["Bíceps braquial"],["Braquial anterior"],5.0,"preacher-curl-start.webp","preacher-curl-peak.webp",["Siéntate en el banco Scott con los brazos apoyados en el pad.","Sostén una barra Z con agarre supinado.","Sube la barra hacia los hombros.","Baja con control hasta que los brazos queden casi extendidos.","Repite."],["Evita los rebotes en la parte baja del recorrido.","Mantén las muñecas neutras sobre la barra EZ.","Sube la barra sin impulso de hombros ni espalda."]],["machine-preacher-curl","Curl en Máquina de Predicador","Un curl de bíceps en máquina de predicador que fija los codos sobre el almohadillado y ofrece una curva de fuerza guiada.","Bíceps","Fuerza","Principiante","Máquina de predicador",false,["Bíceps braquial"],["Braquial anterior"],5.0,"machine-preacher-curl-start.webp","machine-preacher-curl-peak.webp",["Siéntate y ajusta el asiento para que las axilas queden en la parte superior del almohadillado.","Coloca los brazos sobre el soporte y sujeta las asas.","Comienza con los brazos ligeramente flexionados, sin bloquear los codos.","Flexiona los codos hacia arriba y aprieta en la posición máxima.","Baja lentamente hasta la posición inicial y repite."],["No separes los codos del almohadillado.","Para justo antes de la extensión completa para proteger los tendones del codo."]],["kettlebell-hammer-curl","Curl martillo con pesa rusa","Un curl con agarre neutro sosteniendo el asa de una pesa rusa de modo que la campana cuelgue junto a la muñeca. La masa descentrada y el agarre neutro trabajan principalmente el braquial y el braquiorradial.","Bíceps","Fuerza","Principiante","Kettlebell",false,["Bíceps braquial","Braquial anterior"],["Braquiorradial"],5.0,"kettlebell-hammer-curl-start.webp","kettlebell-hammer-curl-peak.webp",["Párate sosteniendo una pesa rusa en una mano, agarrando el asa en posición neutra (palma hacia el cuerpo).","La campana descansa sobre o junto al antebrazo.","Mantén el codo pegado al costado y sube la campana hacia el hombro.","Aprieta en la parte superior y baja con control.","Completa todas las repeticiones en un lado y luego cambia."],["Controla la masa descentrada — la campana tiende a rotar en la parte inferior del recorrido.","El codo se mantiene quieto; solo el antebrazo se mueve.","Carga ligera — esto trabaja el braquial, no el volumen máximo del bíceps."]],["incline-hammer-curl","Curl martillo en banco inclinado","Un curl martillo realizado en banco inclinado para mayor estiramiento y activación de la cabeza larga del bíceps.","Bíceps","Fuerza","Intermedio","Mancuernas",false,["Bíceps braquial","Braquial anterior"],["Flexores del antebrazo"],5.0,"incline-hammer-curl-start.webp","incline-hammer-curl-peak.webp",["Siéntate en un banco inclinado con mancuernas en agarre neutro.","Deja que los brazos cuelguen rectos.","Sube las mancuernas en un movimiento de martillo.","Baja lentamente.","Repite."],["La inclinación proporciona un mayor estiramiento.","Evita balancear el cuerpo."]],["single-arm-hammer-curl","Curl martillo unilateral","Un curl unilateral con mancuerna y agarre neutro que mantiene el codo de trabajo junto al torso mientras el braquial y el braquiorradial flexionan el codo.","Bíceps","Fuerza","Intermedio","Mancuernas",false,["Braquial anterior","Braquiorradial"],["Bíceps braquial","Flexores del antebrazo"],5.0,"single-arm-hammer-curl-start.webp","single-arm-hammer-curl-peak.webp",["Colócate con los pies al ancho de las caderas y sostén una mancuerna al costado con la palma hacia dentro.","Activa el tronco y mantén el brazo de trabajo junto a las costillas mientras cuelga extendido.","Lleva la mancuerna hacia el hombro sin girar la palma ni balancear el torso.","Aprieta los flexores del codo arriba y baja la mancuerna de forma controlada hasta extender el brazo.","Completa las repeticiones de un lado y después cambia de brazo."],["Deja que el lado más débil marque el peso y las repeticiones para que ambos lados reciban el mismo trabajo.","Mantén la muñeca neutra y el hombro quieto; el movimiento debe venir del codo.","Controla la bajada en lugar de dejar caer la mancuerna desde arriba."]],["dead-bug","Dead Bug","Un ejercicio de core en decúbito supino que coordina la extensión de extremidades opuestas para entrenar la estabilidad del core profundo.","Core","Fuerza","Principiante","Sin equipo",true,["Recto abdominal","Transverso abdominal"],["Flexores de cadera"],5.0,"dead-bug-start.webp","dead-bug-peak.webp",["Túmbate boca arriba con los brazos extendidos hacia el techo y las rodillas a 90 grados.","Baja el brazo derecho y la pierna izquierda hacia el suelo manteniendo la zona lumbar presionada contra el suelo.","Regresa a la posición inicial.","Repite del otro lado.","Alterna."],["Presiona la zona lumbar contra el suelo en todo momento.","Muévete despacio."]],["dead-bug-hold","Dead Bug Isométrico","La posición extendida del dead bug mantenida en el tiempo: tumbado boca arriba con un brazo por encima de la cabeza y la pierna contraria estirada justo por encima del suelo, con la zona lumbar pegada al suelo.","Core","Fuerza","Principiante","Sin equipo",true,["Recto abdominal","Transverso abdominal"],["Flexores de cadera"],5.0,"dead-bug-hold-main.webp",null,["Túmbate boca arriba con los brazos apuntando al techo y las caderas y rodillas flexionadas a 90 grados.","Presiona la zona lumbar contra el suelo y mantenla ahí durante toda la serie.","Extiende un brazo por encima de la cabeza y estira la pierna contraria hasta que ambos queden suspendidos justo sobre el suelo.","Mantén esa posición extendida durante el tiempo indicado, sin que las costillas se abran ni la espalda se arquee.","Vuelve al inicio y repite con el otro brazo y la otra pierna."],["Si la zona lumbar se despega del suelo, mantén la pierna más alta en lugar de buscar el suelo.","Exhala despacio durante el mantenimiento; aguantar la respiración es lo que suele romper la tensión del tronco.","Mantén el brazo extendido junto a la oreja, no abierto hacia el lado."]],["double-kettlebell-dead-clean","Dead Clean con Dos Pesas Rusas","Un clean con dos pesas rusas desde el suelo que desarrolla potencia de cadera llevando ambas pesas a la posición de rack.","Cuerpo completo","Halterofilia","Intermedio","Kettlebell",false,["Glúteo mayor","Isquiotibiales"],["Erectores espinales","Flexores del antebrazo","Cuádriceps","Trapecio"],8.0,"double-kettlebell-dead-clean-start.webp","double-kettlebell-dead-clean-peak.webp",["Coloca dos pesas rusas en el suelo entre tus pies.","Inclínate y agarra ambas asas.","Empuja de forma explosiva con las piernas y las caderas.","Tira de las pesas rusas hacia arriba y gíralas hasta la posición de rack.","Bájalas de vuelta al suelo y repite."],["Genera la fuerza con las caderas, no con los brazos.","Mantén las pesas cerca del cuerpo durante la subida.","Recibe en el rack con suavidad, sin golpear los antebrazos."]],["double-kettlebell-dead-split-snatch","Dead Split Snatch con Dos Pesas Rusas","Un snatch con dos pesas rusas desde el suelo que se recibe en posición de tijera con los brazos bloqueados arriba.","Cuerpo completo","Halterofilia","Intermedio","Kettlebell",false,["Deltoides anterior","Glúteo mayor"],["Erectores espinales","Isquiotibiales","Cuádriceps","Trapecio"],8.0,"double-kettlebell-dead-split-snatch-start.webp","double-kettlebell-dead-split-snatch-peak.webp",["Coloca dos pesas rusas en el suelo entre tus pies.","Inclínate y agarra ambas asas con firmeza.","Tira de las pesas rusas por encima de la cabeza de forma explosiva en un solo movimiento.","Cae en postura dividida para recibirlas con los brazos bloqueados.","Recupera la posición juntando los pies."],["Practica la tijera sin peso hasta dominar la recepción.","Recibe con los codos completamente bloqueados.","Mantén el torso erguido al entrar en la tijera."]],["pull-up","Dominada","Un ejercicio compuesto con el peso corporal que trabaja el dorsal ancho y el bíceps.","Espalda","Fuerza","Intermedio","Barra de dominadas",false,["Dorsal ancho"],["Bíceps braquial","Deltoides posterior","Romboides"],6.0,"pull-up-start.webp","pull-up-peak.webp",["Cuélgate de una barra con agarre prono, ligeramente más ancho que el ancho de los hombros.","Súbete hasta que la barbilla quede por encima de la barra.","Baja con control hasta el cuelgue completo.","Repite."],["Evita balancearte o usar impulso.","Activa el dorsal ancho jalando los codos hacia abajo."]],["weighted-pull-up","Dominada Lastrada","Una dominada con carga añadida — normalmente un disco colgado de un cinturón de lastre entre las piernas — para mantener el ejercicio en un rango de fuerza cuando las dominadas con el propio peso ya resultan fáciles.","Espalda","Fuerza","Avanzado","Barra de dominadas",false,["Dorsal ancho"],["Bíceps braquial","Deltoides posterior","Romboides","Trapecio"],6.0,"weighted-pull-up-start.webp","weighted-pull-up-peak.webp",["Cuelga un disco del cinturón de lastre y ajústalo a la cintura de modo que el peso quede suelto entre las piernas; también puedes sujetar la carga entre los pies.","Agarra la barra en pronación algo más abierto que la anchura de los hombros y cuélgate con los brazos estirados y las piernas juntas.","Tira de los codos hacia abajo y hacia atrás llevando el pecho hacia la barra hasta que la barbilla la supere.","Baja de forma controlada hasta la suspensión completa, mantén la tensión en los dorsales y deja que el peso se estabilice antes de la siguiente repetición.","Repite el número de repeticiones deseado."],["Añade peso solo cuando hagas dominadas limpias con el propio peso en todo el recorrido: saltos de 2,5 a 5 kg son suficientes, porque la carga se suma a tu propio peso corporal.","Mantén las piernas juntas y el core apretado para que el disco colgante no empiece a balancearse; un peso que oscila convierte la repetición en un kipping.","No recortes la parte baja: vuelve a la suspensión completa en cada repetición y termina la serie cuando la barbilla deje de superar la barra, en lugar de forzar repeticiones parciales."]],["pause-pull-up","Dominada con Pausa","Una variante de dominada que añade una breve pausa isométrica en la parte superior del movimiento, con la barbilla sobre la barra, antes de bajar de nuevo.","Espalda","Fuerza","Avanzado","Barra de dominadas",false,["Dorsal ancho"],["Bíceps braquial","Deltoides posterior","Romboides","Trapecio"],6.0,"pause-pull-up-start.webp","pause-pull-up-peak.webp",["Cuélgate de una barra de dominadas con agarre prono, brazos completamente extendidos.","Tira de tu cuerpo hacia arriba hasta que la barbilla supere la barra.","Haz una pausa y mantén esa posición superior un momento.","Baja con control de vuelta a la posición de colgado completo.","Repite el número deseado de repeticiones."],["La pausa elimina el impulso, así que el tirón es más difícil que en una dominada normal -- espera menos repeticiones.","Mantén los hombros activos durante la pausa en lugar de relajarte colgando de la barra.","Baja despacio en vez de caer directamente a la siguiente repetición."]],["behind-the-neck-pull-ups","Dominada tras nuca","Una dominada con agarre ancho en la que se tira lo suficientemente alto como para que la barra pase por detrás de la cabeza en lugar de por debajo de la barbilla, lo que obliga a los hombros a llegar al final de su rotación externa.","Espalda","Fuerza","Avanzado","Barra de dominadas",false,["Dorsal ancho"],["Bíceps braquial","Deltoides posterior","Romboides","Trapecio"],6.0,"behind-the-neck-pull-ups-start.webp","behind-the-neck-pull-ups-peak.webp",["Sujeta la barra de dominadas en pronación, con las manos más separadas que los hombros, y cuélgate con los brazos extendidos y las piernas juntas.","Mantén el torso vertical en lugar de inclinarte hacia atrás y tira de los codos hacia abajo y hacia los lados.","Sigue tirando hasta que la barra pase por detrás de la cabeza y la nuca quede a su altura, sin que la barra llegue a tocarte el cuello.","Baja de forma controlada hasta la suspensión completa, manteniendo la cabeza quieta en lugar de dejar que se desplace hacia adelante.","Repite el número de repeticiones deseado."],["Esta variante está desaconsejada de forma generalizada. Terminar por detrás de la cabeza carga el hombro en el final de su rotación externa, donde la articulación tiene menos capacidad de protegerse, y cualquier contacto entre la barra y el cuello transmite esa carga a la columna cervical.","Una dominada normal o con agarre ancho trabaja los mismos músculos en el mismo rango de movimiento del hombro: nada en el desarrollo de la espalda exige que la barra pase por detrás de la cabeza, así que no hay ningún beneficio que compense el riesgo.","Si aun así la haces, detente bastante antes de que la barra toque el cuello, y descártala por completo si no tienes movilidad de hombro completa y sin dolor por encima de la cabeza o si tienes antecedentes de problemas de hombro o cuello."]],["archer-pull-ups","Dominadas Arquero","Una dominada unilateral desplazando el cuerpo hacia una mano mientras el otro brazo permanece estirado, desarrollando fuerza de tracción a un brazo.","Espalda","Fuerza","Avanzado","Barra de dominadas",false,["Dorsal ancho"],["Bíceps braquial","Flexores del antebrazo","Deltoides posterior","Romboides"],6.0,"archer-pull-ups-start.webp","archer-pull-ups-peak.webp",["Agarra la barra más ancha que la anchura de los hombros con las palmas mirando hacia afuera.","Tírate hacia arriba desplazando el cuerpo hacia una mano.","Mantén el brazo opuesto extendido como soporte.","Bájate de forma controlada hasta quedar colgado.","Alterna lados en cada repetición o completa las repeticiones de un lado primero."],["Mantén el brazo estirado completamente extendido y úsalo solo como guía.","Lleva la barbilla hacia la mano que trabaja, no directamente hacia arriba.","Domina las dominadas con agarre ancho antes de progresar a las arqueras."]],["assisted-pull-ups","Dominadas Asistidas","Una dominada en máquina asistida que contrarresta parte del peso corporal, pensada para construir la fuerza de espalda necesaria para dominadas estrictas.","Espalda","Fuerza","Principiante","Máquina de dominadas asistidas",false,["Dorsal ancho"],["Bíceps braquial","Flexores del antebrazo","Deltoides posterior","Romboides"],6.0,"assisted-pull-ups-start.webp","assisted-pull-ups-peak.webp",["Coloca las rodillas en el pad de la máquina de dominadas asistidas.","Agarra la barra con las palmas mirando hacia afuera, ligeramente más ancho que los hombros.","Tira del pecho hacia la barra impulsando los codos hacia abajo.","Bájate de forma controlada hasta quedar colgado con los brazos extendidos.","Repite el número de repeticiones deseado."],["Inicia el movimiento bajando los omóplatos antes de doblar los codos.","Evita balancearte para no restar trabajo a la espalda.","Ajusta el contrapeso para completar todas las repeticiones con buena técnica."]],["band-assisted-pull-ups","Dominadas Asistidas con Banda","Una dominada con banda elástica enganchada a la barra que reduce el peso corporal a vencer en cada repetición.","Espalda","Fuerza","Principiante","Banda elástica",false,["Dorsal ancho"],["Bíceps braquial","Flexores del antebrazo","Deltoides posterior","Romboides"],6.0,"band-assisted-pull-ups-start.webp","band-assisted-pull-ups-peak.webp",["Engancha una banda elástica en la barra de dominadas e introduce un pie en ella.","Agarra la barra con las palmas mirando hacia afuera, a la anchura de los hombros.","Tira del pecho hacia la barra impulsando los codos hacia abajo.","Bájate de forma controlada hasta quedar colgado con los brazos extendidos.","Repite el número de repeticiones deseado."],["Comprueba que la banda esté bien sujeta antes de colgarte.","No tomes impulso con las piernas, deja que trabaje la espalda.","Usa una banda más fina a medida que progreses."]],["scapular-pull-ups","Dominadas Escapulares","Un ejercicio en barra de dominadas con brazos extendidos, que entrena la depresión y retracción de las escápulas.","Espalda","Fuerza","Intermedio","Barra de dominadas",false,["Dorsal ancho","Trapecio"],["Flexores del antebrazo","Romboides"],6.0,"scapular-pull-ups-start.webp","scapular-pull-ups-peak.webp",["Cuélgate de una barra de dominadas con los brazos completamente extendidos.","Mantén los brazos rectos durante todo el movimiento.","Deprime y retrae las escápulas para elevar el pecho.","Haz una breve pausa en la parte superior del movimiento.","Regresa a la posición de cuelgue completo.","Repite el número deseado de repeticiones."],["Piensa en alejar los hombros de las orejas al subir el pecho.","No intentes convertirlo en una dominada; el recorrido es corto.","Controla la vuelta a la posición colgada sin desplomarte."]],["negative-pull-ups","Dominadas Negativas","Una progresión de dominada centrada en la fase excéntrica, en la que se desciende lentamente desde la barra con control.","Espalda","Fuerza","Principiante","Barra de dominadas",false,["Dorsal ancho"],["Bíceps braquial","Flexores del antebrazo","Deltoides posterior","Romboides"],6.0,"negative-pull-ups-start.webp","negative-pull-ups-peak.webp",["Usa un cajón o salta para colocarte en la parte superior de una dominada.","Agarra la barra con las manos a la anchura de los hombros.","Mantén el mentón por encima de la barra un momento.","Bájate lentamente durante 3-5 segundos con control.","Extiende los brazos completamente en la parte inferior.","Vuelve a la posición inicial y repite el número de repeticiones deseado."],["Resiste la bajada durante todo el recorrido, sin dejarte caer al final.","Mantén los hombros activos, lejos de las orejas.","Aprieta el core para no balancearte durante el descenso."]],["close-grip-pull-ups","Dominadas con Agarre Cerrado","Una dominada con agarre prono estrecho que aumenta la activación de los bíceps y la parte interna de la espalda.","Bíceps","Fuerza","Intermedio","Barra de dominadas",false,["Bíceps braquial","Dorsal ancho"],["Romboides"],6.0,"close-grip-pull-ups-start.webp","close-grip-pull-ups-peak.webp",["Cuélgate de la barra de dominadas con las manos a la anchura de los hombros o más juntas, palmas mirando hacia afuera.","Súbete hasta que la barbilla supere la barra.","Baja de forma controlada.","Repite."],["El agarre estrecho aumenta la participación de los bíceps.","Evita los impulsos para el desarrollo de fuerza."]],["wide-grip-pull-ups","Dominadas en Agarre Ancho","Una dominada con agarre prono más ancho que los hombros, que enfatiza el desarrollo de los dorsales.","Espalda","Fuerza","Intermedio","Barra de dominadas",false,["Dorsal ancho"],["Bíceps braquial","Deltoides posterior","Romboides","Trapecio"],6.0,"wide-grip-pull-ups-start.webp","wide-grip-pull-ups-peak.webp",["Agarra la barra de dominadas con un agarre en pronación más ancho que los hombros.","Cuélgate con los brazos completamente extendidos y el core contraído.","Tira del pecho hacia la barra empujando los codos hacia abajo.","Mantén los hombros hacia atrás al subir.","Baja de forma controlada hasta la extensión completa.","Repite el número de repeticiones deseado."],["Cuelga con los brazos extendidos y el core firme.","Lleva el pecho hacia la barra bajando los codos.","Desciende con control hasta la extensión completa."]],["neutral-grip-pull-ups","Dominadas en Agarre Neutro","Una dominada con agarre neutro y palmas enfrentadas que trabaja el dorsal ancho con fuerte participación de los brazos.","Espalda","Fuerza","Intermedio","Barra de dominadas",false,["Dorsal ancho"],["Bíceps braquial","Braquial anterior","Flexores del antebrazo","Romboides"],6.0,"neutral-grip-pull-ups-start.webp","neutral-grip-pull-ups-peak.webp",["Agarra las barras paralelas con las palmas enfrentadas.","Cuelga con los brazos completamente extendidos.","Tírate hacia arriba hasta que el mentón supere la barra.","Aprieta los dorsales en la parte superior del movimiento.","Bájate con control a la posición inicial.","Repite el número de repeticiones deseado."],["Piensa en llevar los codos hacia las costillas al subir.","Evita balancearte; sube en una línea vertical limpia.","Lleva el pecho hacia las barras en la parte alta."]],["chin-ups","Dominadas en Supinación","Una variante de dominadas con agarre supino que activa fuertemente los bíceps junto con el dorsal ancho.","Bíceps","Fuerza","Intermedio","Barra de dominadas",false,["Bíceps braquial","Dorsal ancho"],["Romboides"],6.0,"chin-ups-start.webp","chin-ups-peak.webp",["Cuélgate de una barra con agarre supino a la anchura de los hombros.","Sube hasta que el mentón supere la barra.","Baja de forma controlada.","Repite."],["Mantén el core contraído durante todo el ejercicio.","Evita el balanceo excesivo."]],["drag-curl","Drag Curl","Un curl con barra en el que los codos viajan hacia atrás y la barra se desliza por el torso, eliminando la asistencia del deltoides anterior y enfatizando la cabeza larga del bíceps.","Bíceps","Fuerza","Intermedio","Barra",false,["Bíceps braquial"],["Braquial anterior"],5.0,"drag-curl-start.webp","drag-curl-peak.webp",["Ponte de pie sujetando una barra con agarre supino, con las manos al ancho de los hombros.","Comienza con la barra en los muslos y los codos a los costados.","Sube la barra deslizándola (arrastrándola) hacia arriba a lo largo del cuerpo.","A medida que sube, deja que los codos viajen hacia atrás para que la barra permanezca en contacto con el torso.","Para cuando la barra llegue a la altura del pecho; los bíceps estarán completamente contraídos.","Baja de forma controlada siguiendo el mismo trayecto y repite."],["Usa significativamente menos peso que en un curl estándar — la mecánica modificada lo hace mucho más difícil.","La barra nunca debe separarse del cuerpo."]],["dragon-flag","Dragon Flag","Un exigente ejercicio de core en banco: agarrando detrás de la cabeza, elevas todo el cuerpo en una línea recta y rígida apoyada solo en la parte alta de la espalda.","Core","Fuerza","Avanzado","Sin equipo",true,["Recto abdominal"],["Erectores espinales","Flexores de cadera","Oblicuos","Transverso abdominal"],5.0,"dragon-flag-start.webp","dragon-flag-peak.webp",["Túmbate en un banco y agárralo firmemente detrás de la cabeza.","Eleva el cuerpo de forma que solo la parte superior de la espalda permanezca apoyada en el banco.","Mantén el cuerpo rígido en línea recta.","Baja el cuerpo de forma controlada hasta quedar casi horizontal.","Sube de vuelta y repite."],["Mantén el cuerpo rígido de hombros a pies y muévete solo desde los hombros.","Baja tan despacio como puedas: la fase excéntrica es el ejercicio.","Empieza con progresiones con piernas recogidas o a una pierna antes del dragon flag completo."]],["barbell-front-raise","Elevación Frontal con Barra","Una elevación frontal con barra que aísla el deltoides anterior al subir el peso con los brazos rectos hasta la altura de los hombros.","Hombro","Fuerza","Intermedio","Barra",false,["Deltoides anterior"],["Deltoides lateral","Pectoral mayor","Serrato anterior"],5.0,"barbell-front-raise-start.webp","barbell-front-raise-peak.webp",["Párate sosteniendo una barra con agarre prono a la altura de los muslos.","Mantén los brazos extendidos y el core contraído.","Eleva la barra frente a ti hasta la altura de los hombros.","Haz una breve pausa en la parte superior.","Baja de forma controlada y repite."],["Usa un peso moderado para no balancear el cuerpo.","Evita encoger los hombros mientras subes la barra.","Mantén las muñecas neutras, sin dejar que se doblen hacia atrás."]],["ez-bar-front-raise","Elevación Frontal con Barra Z","Una elevación frontal con ambas manos usando una barra Z. El agarre angulado es más cómodo para las muñecas que una barra recta y permite a ambas manos manejar la misma carga.","Hombro","Fuerza","Principiante","Barra Z",false,["Deltoides anterior"],["Serrato anterior"],5.0,"ez-bar-front-raise-start.webp","ez-bar-front-raise-peak.webp",["Ponte de pie sujetando la barra Z con agarre prono en las curvas internas, con los brazos colgando frente a los muslos.","Mantén los codos ligeramente doblados y fijos durante todo el movimiento.","Sube la barra en un arco suave hasta la altura de los hombros.","Haz una breve pausa en la parte superior y luego baja de forma controlada.","Repite el número de repeticiones recomendado."],["La barra debe desplazarse en línea recta frente al cuerpo.","No balancees el torso; mantén el core contraído y las rodillas ligeramente flexionadas.","Para a la altura de los hombros — subir más desplaza la tensión fuera de los deltoides anteriores."]],["cable-front-raise","Elevación Frontal con Cable","Una elevación frontal en polea que aísla el deltoides anterior con tensión constante durante todo el recorrido.","Hombro","Fuerza","Intermedio","Polea",false,["Deltoides anterior"],["Deltoides lateral","Pectoral mayor"],5.0,"cable-front-raise-start.webp","cable-front-raise-peak.webp",["Colócate de espaldas a una polea baja con un agarre.","Sujeta el agarre con el brazo extendido a la altura del muslo.","Levanta el brazo hacia adelante hasta la altura del hombro manteniéndolo recto.","Pausa en la parte superior.","Baja de forma controlada y repite."],["Evita balancear el torso para ayudarte a subir.","Mantén el codo casi recto, sin bloquearlo.","Baja más despacio de lo que subes para aprovechar la tensión del cable."]],["dumbbell-front-raise","Elevación Frontal con Mancuernas","Un ejercicio de aislamiento que trabaja el deltoides anterior mediante una elevación hacia adelante.","Hombro","Fuerza","Principiante","Mancuernas",false,["Deltoides anterior"],["Deltoides lateral"],5.0,"dumbbell-front-raise-start.webp","dumbbell-front-raise-peak.webp",["Ponte de pie con las mancuernas a los costados, palmas frente a los muslos.","Sube una o ambas mancuernas hacia adelante hasta la altura de los hombros.","Baja de forma controlada.","Repite."],["Evita usar el impulso.","Una ligera flexión de codo reduce el estrés articular."]],["side-lying-lateral-raise","Elevación Lateral Tumbado de Lado","Un ejercicio de aislamiento del deltoides lateral con mancuerna en posición lateral sobre un banco plano, que proporciona tensión constante sin impulso.","Hombro","Fuerza","Principiante","Mancuernas",false,["Deltoides lateral"],["Supraespinoso","Trapecio"],5.0,"side-lying-lateral-raise-start.webp","side-lying-lateral-raise-peak.webp",["Túmbate de lado sobre un banco plano usando el brazo inferior para apoyar la cabeza o sujetar el borde del banco.","Sujeta una mancuerna con la mano superior con el brazo descansando a lo largo del costado.","Con el codo ligeramente flexionado, eleva la mancuerna hasta que el brazo quede perpendicular al suelo.","Pausa brevemente arriba, luego baja la mancuerna despacio hasta el costado.","Completa todas las repeticiones en un lado antes de cambiar."],["Mantén el torso quieto — solo el brazo de trabajo debe moverse.","La posición tumbada elimina el impulso y aísla eficazmente el deltoides lateral.","Usa un peso más ligero que en la elevación lateral de pie — la palanca es más exigente."]],["single-arm-plate-loaded-lateral-raise","Elevación Lateral a Un Brazo en Máquina de Discos","La elevación lateral en máquina de discos trabajando un brazo cada vez, de modo que cada lado levanta su propia carga y ambos pueden entrenarse hasta el mismo nivel.","Hombro","Fuerza","Principiante","Máquina de elevaciones laterales",false,["Deltoides lateral"],["Deltoides anterior","Trapecio"],5.0,"single-arm-plate-loaded-lateral-raise-start.webp","single-arm-plate-loaded-lateral-raise-peak.webp",["Ajusta la altura del asiento para que el eje de la almohadilla quede alineado con tu hombro y carga solo el lado que vas a trabajar.","Siéntate con la espalda apoyada en el respaldo y coloca la cara externa del brazo que trabaja contra su almohadilla.","Sujeta la empuñadura del lado libre o apoya esa mano en el regazo, y mantén el torso alineado con el asiento.","Empuja el brazo que trabaja hacia fuera y hacia arriba contra la almohadilla hasta la altura del hombro, y baja de forma controlada.","Completa todas las repeticiones de ese lado, luego carga y trabaja el otro lado."],["Iguala los lados por el brazo débil, no por el fuerte. Trabajar un lado cada vez solo revela un desequilibrio si dejas que el lado débil fije el número de repeticiones.","No dejes que el torso se incline hacia el lado que trabaja. Con carga en un solo brazo la máquina ya no se equilibra sola, y inclinarse convierte la elevación en una flexión lateral.","Empieza por el brazo débil para que marque el objetivo, y da el mismo descanso a los dos lados."]],["seated-dumbbell-lateral-raise","Elevación Lateral con Mancuerna Sentado","Un ejercicio de aislamiento sentado que levanta las mancuernas hacia los lados, trabajando los deltoides laterales sin impulso de piernas.","Hombro","Fuerza","Principiante","Mancuernas",false,["Deltoides lateral"],["Deltoides anterior","Trapecio"],5.0,"seated-dumbbell-lateral-raise-start.webp","seated-dumbbell-lateral-raise-peak.webp",["Siéntate en un banco con una mancuerna en cada mano a los lados.","Mantén la espalda erguida y el core contraído.","Eleva ambas mancuernas hacia los lados hasta la altura de los hombros.","Mantén una ligera flexión en los codos.","Baja las mancuernas con control.","Repite el número de repeticiones deseado."],["Usa un peso ligero para mantener la elevación estricta.","Lidera con los codos en lugar de con las manos.","Eleva hasta la altura de los hombros y baja con control."]],["lateral-raise","Elevación Lateral con Mancuernas","Un movimiento de aislamiento que trabaja el deltoides lateral para ganar anchura en los hombros.","Hombro","Fuerza","Principiante","Mancuernas",false,["Deltoides lateral"],["Deltoides anterior"],5.0,"lateral-raise-start.webp","lateral-raise-peak.webp",["Párate con mancuernas a los costados.","Eleva las mancuernas hacia los lados hasta que los brazos queden paralelos al suelo.","Baja de forma controlada.","Repite."],["Ligera flexión en los codos.","Guía con los codos, no con las manos."]],["bodyweight-lateral-raise","Elevación Lateral con Peso Corporal","Un movimiento de aislamiento de hombros sin equipamiento para desarrollar el ancho del deltoides lateral.","Hombro","Fuerza","Principiante","Sin equipo",true,["Deltoides lateral"],["Deltoides anterior","Trapecio"],3.5,"bodyweight-lateral-raise-start.webp","bodyweight-lateral-raise-peak.webp",["Párate erguido con los brazos colgando a los lados.","Levanta ambos brazos hacia los lados con un ligero codo doblado hasta la altura de los hombros.","Haz una pausa breve arriba.","Baja lentamente a la posición inicial.","Repite el número de repeticiones deseado."],["Lidera el movimiento con los codos, no con las manos.","Evita encoger los hombros en la parte superior.","Controla el descenso para maximizar el tiempo bajo tensión."]],["plate-loaded-lateral-raise","Elevación Lateral en Máquina de Discos","Una elevación lateral sentado en una máquina de discos, donde unas almohadillas apoyan contra los brazos para que los deltoides laterales levanten la carga sin sujetarla con las manos.","Hombro","Fuerza","Principiante","Máquina de elevaciones laterales",false,["Deltoides lateral"],["Deltoides anterior","Trapecio"],5.0,"plate-loaded-lateral-raise-start.webp","plate-loaded-lateral-raise-peak.webp",["Ajusta la altura del asiento para que el eje de giro de las almohadillas quede alineado con la punta de tus hombros al sentarte.","Carga los soportes de discos por igual en ambos lados y siéntate con la espalda apoyada en el respaldo.","Coloca la cara externa de los brazos contra las almohadillas, con los codos flexionados y los brazos colgando.","Empuja hacia fuera y hacia arriba contra las almohadillas hasta que los brazos queden aproximadamente a la altura de los hombros.","Baja de forma controlada hasta que los brazos vuelvan a los costados y repite el número de repeticiones deseado."],["Ajusta primero el asiento. Si el eje queda por debajo del hombro, las almohadillas llevan el brazo cruzado por delante del cuerpo en lugar de hacia el lado, y el deltoides lateral deja de ser el músculo que trabaja.","Empuja con el brazo, no con la mano. Las empuñaduras solo sirven para que los brazos no resbalen de las almohadillas: apretarlas mete el bíceps y el antebrazo en una elevación que debería ser puro deltoides.","Detente a la altura del hombro. Subir más entrega la última parte de la repetición al trapecio, y la máquina te dejará hacerlo sin protestar."]],["cable-lateral-raise","Elevación Lateral en Polea","Una elevación lateral unilateral en polea, que ofrece tensión constante sobre el deltoides lateral.","Hombro","Fuerza","Intermedio","Polea",false,["Deltoides lateral"],["Deltoides anterior","Trapecio"],5.0,"cable-lateral-raise-start.webp","cable-lateral-raise-peak.webp",["Colócate de lado a una polea baja y agarra el asa con la mano externa.","Mantén una ligera flexión en el codo y el cable por delante de la pierna que trabaja.","Sube el brazo hacia el lado hasta quedar paralelo al suelo.","Baja con control. Repeticiones por lado, luego cambia.","Mantén la tensión — no dejes que el peso descanse abajo."],["Lidera con el codo, no con la mano.","Pausa brevemente arriba, sin balanceo.","Usa menos carga que con mancuerna — la tensión del cable es constante."]],["single-leg-calf-raise","Elevación de Pantorrilla a Una Pierna","Una elevación de pantorrilla unilateral que carga una pantorrilla a la vez y expone desequilibrios laterales.","Pierna","Fuerza","Principiante","Sin equipo",true,["Gemelos"],["Sóleo"],3.5,"single-leg-calf-raise-start.webp","single-leg-calf-raise-peak.webp",["Mantente sobre un pie con la punta sobre una plataforma elevada, talón al aire.","Sujétate a una pared o barandilla con una mano para equilibrio.","Baja el talón por debajo de la plataforma para un estiramiento profundo.","Empuja arriba sobre la punta tan alto como puedas.","Baja con control. Repeticiones por lado, luego cambia."],["Pausa arriba para maximizar la contracción.","Usa una excéntrica lenta para el estiramiento completo.","Sostén una mancuerna del lado que trabaja cuando el peso corporal sea fácil."]],["donkey-calf-raise","Elevación de Pantorrilla a la Burra","Una elevación de pantorrilla inclinada que maximiza el estiramiento al flexionar las caderas.","Pierna","Fuerza","Intermedio","Sin equipo",true,["Gemelos"],["Sóleo"],3.5,"donkey-calf-raise-start.webp","donkey-calf-raise-peak.webp",["Flexiona las caderas y apoya los antebrazos sobre un banco.","Coloca las puntas de los pies en una plataforma elevada, talones al aire.","Baja los talones por debajo de la plataforma para un estiramiento completo.","Empuja arriba sobre las puntas tanto como puedas, contrayendo las pantorrillas.","Baja con control hasta el estiramiento profundo."],["Pausa brevemente arriba para maximizar la contracción.","Usa una excéntrica lenta para el estiramiento completo.","Añade un compañero o peso sobre la zona lumbar para más resistencia."]],["plate-loaded-donkey-calf-raise","Elevación de Pantorrilla a la Burra en Máquina","Una elevación de pantorrilla a la burra en una máquina de discos, con una almohadilla sobre las caderas y el torso inclinado hacia delante para estirar los gemelos en la parte baja de cada repetición.","Pierna","Fuerza","Principiante","Máquina de gemelo tipo burro",false,["Gemelos"],["Sóleo"],5.0,"plate-loaded-donkey-calf-raise-start.webp","plate-loaded-donkey-calf-raise-peak.webp",["Carga los soportes de discos y sube a la plataforma con los metatarsos en el borde y los talones al aire.","Inclínate hacia delante desde las caderas, coloca la almohadilla sobre ellas y apoya los antebrazos en el soporte que tienes delante.","Mantén las rodillas estiradas y la espalda plana, con el torso cerca de la paralela al suelo.","Empuja con los metatarsos y eleva los talones tan alto como puedas, con una pausa breve arriba.","Baja los talones por debajo de la plataforma hasta notar un estiramiento fuerte en los gemelos y repite el número de repeticiones deseado."],["La inclinación hacia delante es el ejercicio. Ponerte erguido lo convierte en una elevación de talones de pie corriente y regala justo el estiramiento extra que venías a buscar.","Mantén las rodillas estiradas todo el tiempo. Flexionarlas traslada el trabajo del gemelo al sóleo, y eso es la elevación sentado, no esta.","Deja que los talones bajen del todo por debajo del borde de la plataforma. La parte baja del recorrido es lo que justifica esta máquina, y recortarla desperdicia todo el montaje."]],["machine-calf-raise","Elevación de Pantorrillas en Máquina","Un ejercicio de aislamiento en máquina de pie que trabaja los gemelos y el sóleo con un recorrido completo del tobillo.","Pierna","Fuerza","Principiante","Máquina de gemelo de pie",false,["Gemelos","Sóleo"],[],5.0,"machine-calf-raise-start.webp","machine-calf-raise-peak.webp",["Párate en la máquina de elevación de pantorrillas con los metatarsos sobre la plataforma.","Coloca los rodillos de hombro firmemente.","Baja los talones por debajo de la plataforma para un estiramiento completo.","Empuja con los metatarsos para elevarte en los dedos de los pies.","Aprieta las pantorrillas en la parte superior.","Baja con control y repite."],["Evita rebotar en la parte baja para no perder tensión.","Mantén las rodillas extendidas pero sin llegar a bloquearlas.","Sube en vertical, sin inclinar los tobillos hacia fuera."]],["lying-leg-raise","Elevación de Piernas Acostado","Un ejercicio de suelo para el abdomen bajo y los flexores de cadera que consiste en elevar las piernas rectas desde posición supina.","Pierna","Fuerza","Principiante","Sin equipo",true,["Flexores de cadera","Recto abdominal"],["Oblicuos","Transverso abdominal"],5.0,"lying-leg-raise-start.webp","lying-leg-raise-peak.webp",["Túmbate boca arriba con las piernas rectas y las manos bajo la zona lumbar o sujetando una superficie estable detrás de la cabeza.","Con las piernas juntas y el core activado, eleva las piernas hasta la vertical.","Pausa brevemente arriba.","Baja las piernas despacio hacia el suelo sin llegar a apoyarlas.","Repite el número de repeticiones deseado."],["Mantén la zona lumbar pegada al suelo durante todo el ejercicio.","Evita el balanceo — controla el descenso para maximizar la tensión.","Dobla ligeramente las rodillas si la flexibilidad de los isquiotibiales lo requiere."]],["hanging-leg-raise","Elevación de Piernas Colgado","Un ejercicio avanzado de core realizado colgado de una barra.","Pierna","Fuerza","Intermedio","Barra de dominadas",false,["Flexores de cadera","Recto abdominal"],["Oblicuos"],5.0,"hanging-leg-raise-start.webp","hanging-leg-raise-peak.webp",["Cuélgate de una barra de dominadas con agarre prono.","Sube las piernas hacia adelante hasta que queden paralelas al suelo.","Mantén brevemente y baja de forma controlada.","Evita balancearte.","Repite."],["Inclina la pelvis hacia atrás al subir las piernas.","Empieza cada repetición desde una posición completamente quieta.","Flexiona las rodillas si con las piernas rectas resulta demasiado difícil."]],["captains-chair-leg-raise","Elevación de Piernas en Silla Romana","Un ejercicio de peso corporal en silla romana para el abdomen bajo con piernas rectas, de mayor dificultad.","Pierna","Fuerza","Intermedio","Sin equipo",true,["Flexores de cadera","Recto abdominal"],["Oblicuos","Transverso abdominal"],5.0,"captains-chair-leg-raise-start.webp","captains-chair-leg-raise-peak.webp",["Colócate en la silla romana con la espalda plana contra el respaldo y los antebrazos en los apoyos.","Deja las piernas colgando rectas hacia abajo.","Con las piernas rectas, súbelas hasta la horizontal o más arriba.","Mantén brevemente arriba, luego baja despacio.","Repite el número de repeticiones deseado."],["Mantén las piernas lo más rectas posible.","Evita el balanceo — controla el movimiento con el core.","Dobla ligeramente las rodillas para reducir la dificultad si es necesario."]],["hanging-knee-raise","Elevación de Rodillas Colgado","Un ejercicio de core colgado de una barra que trabaja el abdomen bajo y los flexores de cadera con rodillas dobladas.","Pierna","Fuerza","Principiante","Barra de dominadas",false,["Flexores de cadera","Recto abdominal"],["Flexores del antebrazo","Oblicuos"],6.0,"hanging-knee-raise-start.webp","hanging-knee-raise-peak.webp",["Cuélgate de una barra con agarre prono y los brazos completamente extendidos.","Activa el core y sube las rodillas hacia el pecho.","Mantén brevemente arriba.","Baja las piernas despacio a la posición inicial.","Repite el número de repeticiones deseado."],["Evita el balanceo — inicia el movimiento desde el core.","Exhala al subir las rodillas.","Progresa a elevaciones de piernas rectas cuando esto resulte fácil."]],["captains-chair-knee-raise","Elevación de Rodillas en Silla Romana","Un ejercicio de peso corporal en silla romana que trabaja el abdomen bajo y los flexores de cadera.","Pierna","Fuerza","Principiante","Sin equipo",true,["Flexores de cadera","Recto abdominal"],["Oblicuos","Transverso abdominal"],5.0,"captains-chair-knee-raise-start.webp","captains-chair-knee-raise-peak.webp",["Colócate en la silla romana con la espalda plana contra el respaldo y los antebrazos en los apoyos.","Deja las piernas colgando rectas hacia abajo.","Activa el core y sube las rodillas hacia el pecho.","Mantén brevemente arriba, luego baja despacio a la posición inicial.","Repite el número de repeticiones deseado."],["Evita balancear las piernas para tomar impulso.","Exhala al subir las rodillas.","Mantén la espalda contra el respaldo durante todo el ejercicio."]],["seated-calf-raise","Elevación de Talones Sentado","Una elevación de talones en máquina realizada sentado para trabajar específicamente el músculo sóleo.","Pierna","Fuerza","Principiante","Máquina de gemelo sentado",false,["Sóleo"],["Gemelos"],5.0,"seated-calf-raise-start.webp","seated-calf-raise-peak.webp",["Siéntate en la máquina de elevación de talones con los pads apoyados en los muslos.","Baja los talones lo más posible.","Elévate sobre las puntas de los pies.","Baja con control.","Repite."],["La posición sentada pre-estira el sóleo.","Utiliza un rango completo de movimiento."]],["barbell-calf-raise","Elevación de Talones con Barra","Una elevación de talones con barra sobre la espalda realizada en una plataforma, que aísla los gemelos con un rango completo.","Pierna","Fuerza","Intermedio","Barra",false,["Gemelos"],["Sóleo"],5.0,"barbell-calf-raise-start.webp","barbell-calf-raise-peak.webp",["Coloca una barra en la parte alta de la espalda como en una sentadilla.","Párate con las puntas de los pies en una plataforma elevada.","Sube sobre los dedos de los pies lo más alto posible.","Haz una pausa y aprieta los gemelos en la parte superior.","Baja los talones por debajo de la plataforma y repite."],["Evita rebotar en la parte baja del movimiento.","Mantén las rodillas extendidas pero sin bloquearlas con fuerza.","Sube y baja en vertical, sin dejar que los tobillos se venzan hacia fuera."]],["dumbbell-calf-raise","Elevación de Talones con Mancuernas","Una elevación de talones con mancuernas sobre una superficie elevada que trabaja gemelos y sóleo en rango completo.","Pierna","Fuerza","Intermedio","Mancuernas",false,["Gemelos","Sóleo"],["Flexores del antebrazo"],5.0,"dumbbell-calf-raise-start.webp","dumbbell-calf-raise-peak.webp",["Ponte de pie sujetando una mancuerna en cada mano a los costados.","Coloca las puntas de los pies sobre una superficie elevada con los talones colgando.","Empuja a través de las puntas de los pies para subir los talones lo más alto posible.","Aprieta los gemelos en la parte superior del movimiento.","Baja los talones por debajo de la plataforma para estirar los gemelos.","Repite el número de repeticiones deseado."],["Evita rebotar abajo y haz una pausa breve en el estiramiento.","Mantén las rodillas extendidas pero sin bloquearlas.","Sube y baja despacio para no perder el equilibrio."]],["bodyweight-calf-raise","Elevación de Talones con Peso Corporal","Una elevación de talones con el propio peso corporal, un ejercicio básico para fortalecer los gemelos.","Pierna","Fuerza","Principiante","Sin equipo",true,["Gemelos"],["Sóleo"],3.5,"bodyweight-calf-raise-start.webp","bodyweight-calf-raise-peak.webp",["Colócate de pie con los pies separados al ancho de las caderas sobre una superficie plana.","Sube de puntillas lo más alto posible.","Aprieta los gemelos en la parte superior.","Baja los talones al suelo de forma controlada.","Repite el número deseado de repeticiones."],["Reparte el peso entre todos los dedos al subir.","Mantén las piernas rectas para centrar el trabajo en el gemelo.","Fija la mirada en un punto para mantener el equilibrio."]],["standing-calf-raise","Elevación de Talones de Pie","Una elevación de talones realizada de pie para desarrollar el gastrocnemio a través de un rango completo de movimiento.","Pierna","Fuerza","Principiante","Máquina de gemelo de pie",false,["Gemelos"],["Sóleo"],5.0,"machine-calf-raise-start.webp","machine-calf-raise-peak.webp",["Párate en el borde de una plataforma o máquina de elevación de talones.","Baja los talones por debajo de la plataforma.","Empuja hacia arriba de puntillas.","Baja lentamente.","Repite."],["Haz una pausa en la parte superior para maximizar la contracción.","Bajar el talón completamente aumenta el rango de movimiento."]],["hack-squat-calf-raise","Elevación de Talones en Máquina Hack Squat","Una elevación de talones en la máquina de sentadilla hack, cargando los gemelos con mucho peso sin tener que equilibrar una barra.","Pierna","Fuerza","Intermedio","Máquina hack squat",false,["Gemelos","Sóleo"],[],5.0,"hack-squat-calf-raise-start.webp","hack-squat-calf-raise-peak.webp",["Colócate en la máquina hack squat con los hombros bajo los apoyos.","Apoya los metatarsos en la plataforma con los talones colgando.","Mantén las piernas rectas con una ligera flexión de rodillas.","Empuja con los metatarsos para elevar los talones.","Baja los talones por debajo de la plataforma para hacer el estiramiento.","Repite el número de repeticiones deseado."],["Sube tan alto como puedas sobre las puntas de los pies.","Haz una pausa en el estiramiento inferior en lugar de rebotar.","Mantén las rodillas rectas pero sin bloquear para conservar la tensión en los gemelos."]],["smith-machine-calf-raise","Elevación de Talón en Máquina Smith","Una elevación de talones en máquina Smith de pie sobre una plataforma, que aísla los gemelos con un estiramiento completo.","Pierna","Fuerza","Principiante","Máquina Smith",false,["Gemelos"],["Sóleo"],5.0,"smith-machine-calf-raise-start.webp","smith-machine-calf-raise-peak.webp",["Coloca la barra de la máquina Smith sobre la parte superior de la espalda y los hombros.","De pie sobre una pequeña plataforma para que los talones puedan bajar por debajo de los dedos.","Desbloquea la barra y elévate sobre las puntas de los pies.","Aprieta las pantorrillas con fuerza en la parte superior.","Baja los talones por debajo de la plataforma para un estiramiento completo.","Repite el número de repeticiones deseado."],["Haz una pausa arriba y otra abajo para eliminar el rebote.","No dobles las rodillas; el movimiento sale solo del tobillo.","Mantén el cuerpo erguido, sin inclinarte hacia delante."]],["straight-bar-cable-front-raise","Elevación frontal en polea con barra recta","Una elevación frontal en la polea baja sujetando una barra recta con ambas manos. A diferencia de la elevación frontal en polea a un brazo, los dos brazos mueven la misma barra y el cable mantiene la tensión sobre el deltoides anterior en todo el recorrido.","Hombro","Fuerza","Intermedio","Polea",false,["Deltoides anterior"],["Deltoides lateral","Pectoral mayor"],5.0,"straight-bar-cable-front-raise-start.webp","straight-bar-cable-front-raise-peak.webp",["Engancha una barra recta a la polea baja y colócate de espaldas a la máquina, con el cable pasando por delante de las piernas.","Sujeta la barra en pronación con las manos a la anchura de los hombros y los brazos colgando estirados delante de los muslos.","Mantén los codos casi extendidos y el core firme para que el torso no se incline hacia atrás.","Eleva la barra hacia delante en un arco suave hasta la altura de los hombros.","Bájala de forma controlada hasta los muslos y repite las repeticiones deseadas."],["Usa poco peso: impulsar la barra con las piernas o inclinarte hacia atrás quita el trabajo al deltoides anterior.","Detente a la altura de los hombros; subir más traslada la carga al trapecio.","Mantén las muñecas neutras en lugar de dejar que se doblen bajo la barra."]],["elliptical-trainer","Elíptica","Un ejercicio de máquina cardiovascular de bajo impacto en el que los pies describen un óvalo continuo sobre las plataformas mientras los manillares móviles se empujan y se tiran, trabajando piernas y tren superior a la vez.","Cuerpo completo","Cardio","Principiante","Elíptica",false,["Glúteo mayor","Cuádriceps"],["Gemelos","Isquiotibiales","Dorsal ancho","Pectoral mayor","Sóleo","Tríceps braquial"],8.0,"elliptical-trainer-main.webp",null,["Súbete a las plataformas de una en una sujetándote al poste central fijo hasta estar estable, y luego toma un manillar móvil con cada mano.","Pon los pedales en marcha hacia delante manteniendo el pie entero apoyado en la plataforma, sin levantar el talón.","Empuja un manillar hacia delante mientras el pie de ese mismo lado avanza, y tira del otro hacia atrás, de modo que brazos y piernas trabajen en oposición.","Mantente erguido con la cadera sobre los pedales y el core activo, en lugar de dejarte caer hacia atrás sobre los manillares.","Ajusta la resistencia y la rampa para sostener una zancada fluida y continúa durante el tiempo o la distancia deseados."],["Mueve tú los manillares en lugar de dejar que las piernas te los empujen — el trabajo de brazos es lo que convierte a la elíptica en una máquina de cuerpo completo.","Mantén los talones apoyados en las plataformas. Ir de puntillas acalambra los gemelos y deja los glúteos fuera de la zancada.","Pedalear hacia atrás durante parte de la sesión desplaza el énfasis hacia isquiotibiales y glúteos y rompe la monotonía de un esfuerzo largo y constante."]],["banded-kneeling-hip-thrust","Empuje de Cadera Arrodillado con Banda","Este ejercicio fortalece los glúteos y los isquiotibiales al impulsar las caderas hacia adelante contra la resistencia de una banda desde una posición arrodillada.","Pierna","Fuerza","Principiante","Banda circular",false,["Glúteo mayor"],["Isquiotibiales"],6.0,"banded-kneeling-hip-thrust-start.webp","banded-kneeling-hip-thrust-peak.webp",["Coloca una banda de bucle justo por encima de tus rodillas. Arrodíllate en el suelo con el torso erguido y las rodillas separadas al ancho de las caderas.","Inclínate ligeramente hacia adelante desde las caderas, manteniendo la espalda recta y el core contraído.","Inicia el movimiento apretando los glúteos, impulsando las caderas hacia adelante hasta que tu torso esté erguido.","Aprieta los glúteos con fuerza en la parte superior, manteniendo la tensión en la banda.","Invierte lentamente el movimiento, controlando la resistencia de la banda mientras regresas a la posición inicial."],["Concéntrate en una fuerte contracción de los glúteos en la parte superior del movimiento.","Mantén el core activado en todo momento para evitar arquear la espalda baja.","Mantén una tensión constante en la banda empujando las rodillas ligeramente hacia afuera."]],["banded-hip-thrust","Empuje de Cadera con Banda","Este ejercicio utiliza una banda de bucle para aumentar la activación de los glúteos durante un empuje de cadera, trabajando eficazmente el glúteo mayor, los isquiotibiales y el glúteo medio para mejorar la fuerza de la parte inferior del cuerpo.","Pierna","Fuerza","Principiante","Banda circular",false,["Glúteo mayor"],["Glúteo medio","Isquiotibiales"],6.0,"banded-hip-thrust-start.webp","banded-hip-thrust-peak.webp",["Coloca una banda de bucle justo por encima de tus rodillas y siéntate en el suelo con la parte superior de tu espalda contra un banco.","Dobla las rodillas, apoya los pies al ancho de las caderas y posiciona la banda para crear tensión.","Impúlsate a través de los talones, extiende las caderas y levanta los glúteos del suelo hasta que tu cuerpo forme una línea recta.","Aprieta los glúteos con fuerza en la parte superior, asegurándote de empujar las rodillas hacia afuera contra la banda.","Baja lentamente las caderas a la posición inicial con control."],["Mantén una tensión constante en la banda durante todo el movimiento.","Concéntrate en una fuerte contracción de los glúteos en el pico del empuje.","Mantén la barbilla metida y la mirada al frente para una columna vertebral neutra.","Asegúrate de que tus espinillas estén verticales en la parte superior del movimiento."]],["kettlebell-hip-thrust","Empuje de Cadera con Kettlebell","Este ejercicio trabaja eficazmente el glúteo mayor y los isquiotibiales, utilizando una kettlebell para añadir resistencia y lograr una potente extensión de cadera y desarrollo de glúteos.","Pierna","Fuerza","Principiante","Kettlebell",false,["Glúteo mayor"],["Isquiotibiales","Cuádriceps"],6.0,"kettlebell-hip-thrust-start.webp","kettlebell-hip-thrust-peak.webp",["Siéntate en el suelo con la parte superior de tu espalda apoyada en un banco, las rodillas flexionadas y los pies planos.","Coloca una kettlebell sobre tus caderas, sujetándola firmemente con ambas manos.","Impúlsate a través de tus talones, levantando tus caderas del suelo hasta que tu cuerpo forme una línea recta desde los hombros hasta las rodillas.","Contrae tus glúteos con fuerza en la parte superior del movimiento.","Baja lentamente tus caderas de vuelta a la posición inicial con control."],["Mantén tu barbilla pegada al pecho para mantener una columna vertebral neutra.","Concéntrate en empujar a través de tus talones para maximizar la activación de los glúteos.","Asegúrate de que tus rodillas sigan la línea de tus dedos de los pies durante todo el movimiento.","Controla la fase excéntrica, resistiendo el peso mientras bajas tus caderas."]],["dumbbell-hip-thrust","Empuje de Cadera con Mancuerna","El Empuje de Cadera con Mancuerna es un ejercicio compuesto muy eficaz para construir glúteos y isquiotibiales fuertes, realizado empujando las caderas hacia arriba con una mancuerna sobre la pelvis.","Pierna","Fuerza","Principiante","Mancuernas",false,["Glúteo mayor"],["Isquiotibiales","Cuádriceps"],6.0,"dumbbell-hip-thrust-start.webp","dumbbell-hip-thrust-peak.webp",["Siéntate en el suelo con la parte superior de la espalda contra un banco, rodillas flexionadas, pies planos y una mancuerna sobre tus caderas.","Contrae tu abdomen y empuja a través de tus talones, levantando las caderas del suelo hasta que tu cuerpo forme una línea recta de hombros a rodillas.","Aprieta tus glúteos con fuerza en la parte superior del movimiento, asegurando una extensión completa de la cadera.","Baja lentamente tus caderas a la posición inicial con control, manteniendo la tensión.","Repite el ejercicio por el número deseado de repeticiones."],["Mantén la barbilla pegada al pecho para mantener una columna vertebral neutra durante todo el movimiento.","Concéntrate en empujar a través de los talones para maximizar la activación de los glúteos.","Controla la fase excéntrica (descenso) para mejorar el crecimiento muscular.","Usa una almohadilla o toalla debajo de la mancuerna para mayor comodidad."]],["plate-loaded-glute-drive","Empuje de Glúteo en Máquina de Discos","Un empuje de cadera en una máquina de glúteo de discos, donde el respaldo y la plataforma integrados fijan la posición para que las caderas extiendan contra la carga sin tener que montar un banco.","Pierna","Fuerza","Principiante","Máquina de hip thrust",false,["Glúteo mayor"],["Glúteo medio","Isquiotibiales","Cuádriceps"],6.0,"plate-loaded-glute-drive-start.webp","plate-loaded-glute-drive-peak.webp",["Carga los soportes de discos por igual y siéntate en la máquina con la parte alta de la espalda contra el respaldo y los pies planos en la plataforma.","Baja la almohadilla o barra sobre tus caderas y ajústala para que apoye en el pliegue de la cadera y no sobre el abdomen.","Coloca los pies de modo que las espinillas queden verticales cuando las caderas estén arriba, y sujeta las empuñaduras.","Empuja las caderas hacia arriba apretando los glúteos hasta que los muslos queden alineados con el torso, y mantén un instante arriba.","Baja de forma controlada hasta justo antes del final del recorrido y repite el número de repeticiones deseado."],["Coloca la almohadilla en el pliegue de la cadera. Dejarla sobre el abdomen es lo único realmente incómodo de esta máquina, y se resuelve moviendo la almohadilla, no añadiendo acolchado.","Termina el movimiento con la cadera, no con la zona lumbar. Si arriba se te abren las costillas es que se acabó la extensión de cadera y has empezado a arquear, que es donde la máquina deja de entrenar el glúteo.","Este es el empuje de cadera al que recurrir cuando el banco y la barra están ocupados: el respaldo y la plataforma forman parte del bastidor, así que no hay montaje que hacer mal."]],["shrug","Encogimiento con Barra","Un movimiento de aislamiento para el trapecio superior.","Espalda","Fuerza","Principiante","Barra",false,["Trapecio"],["Romboides"],5.0,"shrug-start.webp","shrug-peak.webp",["De pie, sostén una barra a lo largo de los brazos con agarre en pronación.","Encoge los hombros directamente hacia las orejas.","Mantén brevemente en la parte superior.","Baja los hombros con control.","Repite."],["Sube los hombros en vertical, sin hacer círculos.","No uses los brazos; los codos quedan extendidos todo el tiempo.","Evita impulsarte con las piernas para subir más peso."]],["behind-the-back-barbell-shrug","Encogimiento de Hombros con Barra Detrás de la Espalda","Un encogimiento de hombros con la barra sujeta por detrás del cuerpo, una variante que concentra el trabajo en el trapecio.","Espalda","Fuerza","Intermedio","Barra",false,["Trapecio"],["Flexores del antebrazo","Romboides"],5.0,"behind-the-back-barbell-shrug-start.webp","behind-the-back-barbell-shrug-peak.webp",["Párate sosteniendo una barra detrás de la espalda con agarre prono.","Mantén los brazos extendidos y el pecho hacia arriba.","Encoge los hombros directamente hacia las orejas.","Haz una pausa y aprieta en la parte superior.","Baja de forma controlada y repite."],["Evita hacer círculos con los hombros al subir.","Mantén la cabeza neutra, sin adelantar la barbilla.","Elige un peso que permita un recorrido completo hacia arriba."]],["ez-bar-shrug","Encogimiento de Hombros con Barra Z","Un encogimiento de hombros con barra Z para un agarre cómodo mientras se carga el trapecio.","Espalda","Fuerza","Principiante","Barra Z",false,["Trapecio"],["Romboides"],5.0,"ez-bar-shrug-start.webp","ez-bar-shrug-peak.webp",["De pie, sujeta la barra Z frente a ti.","Encoge los hombros directamente hacia arriba.","Mantén la posición arriba y luego baja.","Repite."],["Evita girar los hombros en círculos.","Usa un rango completo de movimiento."]],["kettlebell-shrug","Encogimiento de Hombros con Kettlebell","Este ejercicio de aislamiento trabaja los músculos trapecios superiores elevando los hombros, mejorando la estabilidad del hombro y la fuerza del cuello.","Espalda","Fuerza","Principiante","Kettlebell",false,["Trapecio"],["Flexores del antebrazo"],5.0,"kettlebell-shrug-start.webp","kettlebell-shrug-peak.webp",["Ponte de pie con los pies al ancho de las caderas, sosteniendo una kettlebell en cada mano con las palmas hacia tu cuerpo.","Mantén los brazos rectos y los hombros relajados.","Eleva los hombros directamente hacia tus orejas, contrayendo los trapecios en la parte superior.","Mantén la contracción brevemente.","Baja lentamente los hombros a la posición inicial con control.","Repite el movimiento para el número deseado de repeticiones."],["Concéntrate en mover solo los hombros, manteniendo los brazos rectos durante todo el movimiento.","Evita rodar los hombros; muévelos directamente hacia arriba y hacia abajo.","Mantén una columna vertebral neutra y el core activado para prevenir la tensión en la espalda baja.","Usa un peso que permita un rango completo de movimiento y una ejecución controlada."]],["db-shrug","Encogimiento de Hombros con Mancuernas","Un encogimiento de hombros con mancuernas que trabaja el trapecio superior para dar volumen al cuello y la espalda alta.","Espalda","Fuerza","Principiante","Mancuernas",false,["Trapecio"],["Romboides"],5.0,"db-shrug-start.webp","db-shrug-peak.webp",["De pie, sujeta mancuernas a los costados.","Encoge los hombros hacia arriba lo más alto posible.","Mantén brevemente y luego baja.","Repite."],["No hagas círculos con los hombros.","Concéntrate en apretar el trapecio en la posición superior."]],["chest-supported-dumbbell-shrug","Encogimiento de Hombros con Mancuernas y Apoyo en el Pecho","Un encogimiento de hombros boca abajo en un banco inclinado, donde el apoyo del pecho aísla el trapecio y elimina el impulso.","Espalda","Fuerza","Intermedio","Mancuernas",false,["Trapecio"],["Deltoides posterior","Romboides"],5.0,"chest-supported-dumbbell-shrug-start.webp","chest-supported-dumbbell-shrug-peak.webp",["Ajusta un banco inclinado a unos 30 grados.","Túmbate boca abajo en el banco sujetando mancuernas con los brazos extendidos.","Encoge los hombros hacia arriba y hacia atrás en dirección a las orejas.","Aprieta el trapecio superior en la parte superior.","Baja de forma controlada y repite."],["Encoge hacia arriba y atrás hacia las orejas, no solo recto hacia arriba.","Mantén el pecho pegado a la almohadilla para no usar impulso.","Haz una pausa y aprieta arriba antes de bajar con control."]],["smith-machine-shrug","Encogimiento de Hombros en Máquina Smith","Un encogimiento de hombros en máquina Smith que aísla el trapecio sin necesidad de estabilizar la barra.","Espalda","Fuerza","Principiante","Máquina Smith",false,["Trapecio"],["Flexores del antebrazo"],5.0,"smith-machine-shrug-start.webp","smith-machine-shrug-peak.webp",["Párate erguido dentro de una máquina Smith con la barra a la altura de los muslos.","Agarra la barra ligeramente más ancha que el ancho de los hombros con agarre prono.","Desrackea la barra y deja que cuelgue frente a tus muslos.","Encoge los hombros hacia arriba en dirección a las orejas.","Mantén la posición alta un momento, luego baja lentamente.","Repite el número de repeticiones deseado."],["Evita rotar los hombros; súbelos y bájalos en vertical.","No tires con los bíceps; los brazos solo sostienen la barra.","Mantén el cuello relajado y la mirada al frente."]],["plate-loaded-shrug","Encogimiento de Hombros en Máquina de Discos","Un encogimiento de hombros de pie en una máquina de discos, levantando unas empuñaduras que cuelgan a los costados para que el trapecio trabaje sin una barra por delante o por detrás de las piernas.","Espalda","Fuerza","Principiante","Máquina de encogimientos",false,["Trapecio"],["Flexores del antebrazo"],5.0,"plate-loaded-shrug-start.webp","plate-loaded-shrug-peak.webp",["Carga los soportes de discos por igual y súbete a la plataforma de la máquina, de espaldas al bastidor.","Toma una empuñadura con cada mano, con los brazos colgando rectos a los costados y los hombros relajados.","Ponte erguido con el pecho alto, la barbilla nivelada y las rodillas ligeramente flexionadas.","Encoge los hombros en línea recta hacia las orejas todo lo que puedas y mantén un instante arriba.","Baja de forma controlada hasta que los hombros queden completamente abajo y repite el número de repeticiones deseado."],["Encoge en línea recta hacia arriba. Rotar los hombros añade recorrido pero no trabajo extra del trapecio, y lleva la articulación del hombro a describir un círculo bajo carga para nada.","Mantén los brazos rectos y pasivos. Flexionar los codos convierte el movimiento en un remo vertical corto y quita la carga del trapecio.","Las empuñaduras colgando a los costados son la razón de ser de esta máquina: no hay barra que esquivar en los muslos, así que puedes estar erguido y usar todo el recorrido sin acortar la parte alta."]],["bench-leg-pull-in","Encogimiento de Piernas en Banco","Un ejercicio de core en decúbito supino sobre un banco plano que trabaja el recto abdominal llevando las rodillas hacia el pecho.","Core","Fuerza","Principiante","Sin equipo",true,["Recto abdominal"],["Flexores de cadera","Oblicuos"],3.5,"bench-leg-pull-in-start.webp","bench-leg-pull-in-peak.webp",["Túmbate boca arriba sobre un banco plano y agárrate a los lados por encima de la cabeza.","Extiende las piernas rectas con los talones justo por encima de la superficie del banco.","Lleva las rodillas hacia el pecho levantando ligeramente las caderas del banco.","Devuelve las piernas a la posición extendida de forma controlada sin apoyar los talones.","Repite el número de repeticiones indicado."],["Presiona la zona lumbar contra el banco para reducir la participación del psoas.","Controla la fase excéntrica; no dejes que la gravedad baje las piernas sin control.","Contrae el abdomen en el punto más alto de cada repetición."]],["stability-ball-knee-tuck","Encogimiento de Rodillas con Balón de Estabilidad","Un encogimiento de rodillas en posición de plancha con los pies sobre un balón de estabilidad, rodando el balón hacia las caderas para trabajar el abdomen dinámicamente.","Core","Fuerza","Intermedio","Pelota de estabilidad",false,["Recto abdominal"],["Deltoides anterior","Flexores de cadera","Oblicuos","Serrato anterior"],6.0,"stability-ball-knee-tuck-start.webp","stability-ball-knee-tuck-peak.webp",["Comienza en plancha alta con las espinillas o el dorso de los pies sobre un balón de estabilidad.","Las manos están bajo los hombros y el cuerpo en línea recta.","Contrae el core y lleva el balón hacia el pecho encogiendo las rodillas.","Rueda de vuelta hacia afuera extendiendo completamente las piernas a la posición de plancha.","Repite el número de repeticiones recomendado."],["Las caderas no se elevan; mantén el tronco nivelado durante todo el encogimiento.","Los hombros permanecen sobre las muñecas: no dejes que se desplacen hacia adelante."]],["thread-the-needle","Enhebrar la Aguja","Una rotación de rodillas: un brazo se desliza por debajo del cuerpo y el hombro y el lateral de la cabeza descansan en el suelo, rotando la columna torácica de forma pasiva.","Hombro","Estiramiento","Principiante","Sin equipo",true,["Deltoides posterior","Trapecio"],["Erectores espinales","Oblicuos"],5.0,"thread-the-needle-main.webp",null,["Comienza a cuatro apoyos con las manos bajo los hombros y las rodillas bajo las caderas.","Desliza un brazo por debajo del cuerpo con la palma hacia arriba hasta que el hombro y el lateral de la cabeza apoyen en la esterilla.","Mantén las caderas sobre las rodillas y camina la mano de arriba hacia delante o llévala a la espalda.","Mantén la torsión durante el tiempo indicado, respirando hacia la espalda alta.","Presiona la mano de arriba contra el suelo para subir y repite del otro lado."],["Mantén las caderas altas sobre las rodillas; si bajan, la rotación se convierte en una inclinación lateral.","Apoya la cabeza en un bloque si el hombro no llega cómodamente al suelo.","Deja que el hombro se asiente con la respiración en lugar de forzar la torsión."]],["thread-the-needle-flow","Enhebrar la Aguja Dinámico","La versión en movimiento de enhebrar la aguja: desde cuatro apoyos el brazo pasa por debajo del cuerpo y después se abre hacia el techo, rotando la columna torácica por todo su recorrido.","Core","Estiramiento","Principiante","Sin equipo",true,["Oblicuos","Trapecio"],["Erectores espinales","Deltoides posterior"],5.0,"thread-the-needle-flow-start.webp","thread-the-needle-flow-peak.webp",["Comienza a cuatro apoyos con las manos bajo los hombros y las rodillas bajo las caderas.","Desliza un brazo por debajo del cuerpo hasta que el hombro se acerque a la esterilla.","Invierte el movimiento y abre ese brazo hacia el techo, siguiendo la mano con la mirada.","Vuelve por el centro y repite las veces indicadas.","Cambia de lado y repite."],["Mantén las caderas sobre las rodillas para que la rotación se quede en la espalda alta.","Trabaja a un ritmo uniforme en lugar de abrir el brazo de golpe.","Deja que la cabeza siga a la mano en lugar de liderar el movimiento."]],["stair-climber","Escaladora de Escaleras","Un ejercicio de máquina cardiovascular que sube escalón tras escalón por una escalera giratoria, cargando glúteos y cuádriceps de forma continua y sin impacto de aterrizaje.","Pierna","Cardio","Principiante","Escaladora",false,["Glúteo mayor","Cuádriceps"],["Gemelos","Glúteo medio","Isquiotibiales","Sóleo"],8.0,"stair-climber-main.webp",null,["Súbete al escalón inferior con la máquina en su ajuste más lento y sujeta los raíles con suavidad para equilibrarte.","Sube de escalón en escalón apoyando el pie entero en cada uno, no solo la punta.","Mantente erguido con el pecho abierto y la cadera bajo los hombros, sin encorvarte sobre la consola.","Empuja el escalón hacia abajo con el talón del pie adelantado y deja que el glúteo de esa pierna haga el trabajo.","Ajusta el ritmo para poder sostener la postura y sigue subiendo durante el tiempo o el número de pisos deseados."],["No te apoyes en los raíles ni cuelgues los antebrazos sobre ellos — descargar ahí el peso quita trabajo a las piernas y la pantalla deja de significar nada.","Pie entero sobre el escalón, talón incluido. Subir de puntillas traslada toda la sesión a los gemelos y los agota pronto.","Sube escalón a escalón antes de intentar saltártelos; una subida deliberada y erguida vale más que un trote rápido en la parte baja de la escalera."]],["bench-bulgarian-split-stretch","Estiramiento Búlgaro en Banco","Un estiramiento en zancada con el pie trasero en un banco, bajando la cadera para abrir los flexores de cadera y el cuádriceps.","Pierna","Estiramiento","Principiante","Banco plano",false,["Flexores de cadera","Cuádriceps"],["Glúteo mayor"],5.0,"bench-bulgarian-split-stretch-main.webp",null,["Apoya el empeine del pie trasero en un banco detrás de ti.","Coloca el pie delantero plano y flexiona esa rodilla.","Baja la cadera recto hacia abajo.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],["Apóyate en una pared si lo necesitas.","Mantén el torso erguido."]],["bench-couch-stretch","Estiramiento Couch en Banco","Un estiramiento profundo de cuádriceps y flexores de cadera con la espinilla trasera apoyada en el frente del banco.","Pierna","Estiramiento","Principiante","Banco plano",false,["Flexores de cadera","Cuádriceps"],[],5.0,"bench-couch-stretch-main.webp",null,["Arrodíllate con la espinilla trasera contra el frente del banco.","Coloca el pie delantero plano en el suelo.","Lleva el torso erguido hasta que se estire el frente del muslo.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],["Aprieta el glúteo trasero para proteger la zona lumbar.","Acolcha la rodilla trasera con un cojín."]],["banded-figure-4-stretch","Estiramiento Figura 4 con Banda","Un estiramiento de glúteos tumbado en posición de figura 4, usando una banda para acercar ambas piernas al pecho.","Pierna","Estiramiento","Principiante","Banda elástica",false,["Glúteo mayor"],["Glúteo medio"],5.0,"banded-figure-4-stretch-main.webp",null,["Acuéstate boca arriba y cruza un tobillo sobre el muslo opuesto.","Pasa una banda por el muslo de apoyo.","Lleva ambas piernas al pecho con la banda.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],["Mantén la cabeza y los hombros relajados en el suelo.","Deja que la rodilla cruzada caiga hacia afuera."]],["bench-figure-4-glute-stretch","Estiramiento Figura 4 de Glúteos en Banco","Un estiramiento sentado en banco con un tobillo cruzado sobre la rodilla, inclinándose para trabajar el glúteo.","Pierna","Estiramiento","Principiante","Banco plano",false,["Glúteo mayor"],["Glúteo medio"],5.0,"bench-figure-4-glute-stretch-main.webp",null,["Siéntate en el extremo de un banco.","Cruza un tobillo sobre la rodilla opuesta.","Mantén la espalda recta e inclínate sobre la pierna cruzada.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],["Deja que la rodilla cruzada caiga hacia afuera.","Inclínate desde las caderas, manteniendo el pecho abierto."]],["neck-side-stretch","Estiramiento Lateral de Cuello","Un estiramiento suave que alarga el trapecio superior y el lateral del cuello inclinando la oreja hacia el hombro.","Espalda","Estiramiento","Principiante","Sin equipo",true,["Trapecio"],[],5.0,"neck-side-stretch-main.webp",null,["Siéntate o párate erguido con los hombros relajados.","Inclina la cabeza para que una oreja baje hacia ese hombro.","Apoya esa mano sobre la cabeza para un peso suave.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],["Deja que el peso de la mano haga el trabajo, no tires fuerte.","Mantén el hombro opuesto hacia abajo."]],["knee-to-chest-stretch","Estiramiento Rodilla al Pecho","Un estiramiento tumbado que libera los glúteos y la zona lumbar al abrazar una rodilla contra el pecho.","Pierna","Estiramiento","Principiante","Sin equipo",true,["Glúteo mayor"],["Erectores espinales"],5.0,"knee-to-chest-stretch-main.webp",null,["Acuéstate boca arriba con ambas piernas estiradas.","Lleva una rodilla y abrázala al pecho con ambas manos.","Mantén la otra pierna relajada en el suelo.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],["Mantén la cabeza y los hombros relajados en el suelo.","Relájate y sigue respirando todo el tiempo."]],["banded-adductor-stretch","Estiramiento de Aductores con Banda","Un estiramiento tumbado que usa una banda para llevar una pierna estirada hacia el lado y alargar el aductor.","Pierna","Estiramiento","Principiante","Banda elástica",false,["Aductores"],["Isquiotibiales"],5.0,"banded-adductor-stretch-main.webp",null,["Acuéstate boca arriba con una banda en un pie.","Eleva esa pierna y déjala abrir hacia el lado.","Sujeta la banda para controlar cuánto baja la pierna.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],["Mantén las caderas planas y ambos glúteos en el suelo.","Estira hasta una tensión leve, nunca hasta el dolor."]],["bench-adductor-stretch","Estiramiento de Aductores en Banco","Un estiramiento de pie con una pierna estirada apoyada en el banco hacia el lado para alargar el aductor.","Pierna","Estiramiento","Principiante","Banco plano",false,["Aductores"],["Isquiotibiales"],5.0,"bench-adductor-stretch-main.webp",null,["Ponte de lado al banco.","Apoya una pierna estirada sobre el banco hacia el lado.","Mantén el torso erguido y desplázate suavemente hacia el banco.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],["Mantén ambas piernas estiradas.","Mantén el pie de apoyo apuntando al frente."]],["banded-it-band-stretch","Estiramiento de Banda Iliotibial con Banda","Un estiramiento tumbado que usa una banda para cruzar una pierna sobre el cuerpo y trabajar el muslo y la cadera externos.","Pierna","Estiramiento","Principiante","Banda elástica",false,["Abductores"],["Glúteo mayor","Glúteo medio"],5.0,"banded-it-band-stretch-main.webp",null,["Acuéstate boca arriba con una banda en un pie elevado.","Sujeta la banda con la mano contraria.","Lleva la pierna estirada cruzando el cuerpo hacia el suelo.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],["Mantén ambos hombros en el suelo.","Detente al sentir el estiramiento en el muslo externo."]],["standing-quad-stretch","Estiramiento de Cuádriceps de Pie","Un estiramiento de equilibrio de pie que alarga el cuádriceps llevando el talón hacia el glúteo.","Pierna","Estiramiento","Principiante","Sin equipo",true,["Cuádriceps"],["Flexores de cadera"],5.0,"standing-quad-stretch-main.webp",null,["Párate sobre una pierna, apoyándote en una pared si lo necesitas.","Flexiona la otra rodilla y agarra ese tobillo por detrás.","Lleva el talón hacia el glúteo, manteniendo las rodillas juntas.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],["Mete la pelvis hacia adentro para profundizar el estiramiento.","Mantén las rodillas juntas en todo momento."]],["banded-rear-delt-stretch","Estiramiento de Deltoides Posterior con Banda","Un estiramiento de pie para el hombro posterior llevando un brazo cruzado contra la tensión de la banda.","Hombro","Estiramiento","Principiante","Banda elástica",false,["Deltoides posterior"],["Romboides","Trapecio"],5.0,"banded-rear-delt-stretch-main.webp",null,["Pasa una banda por un brazo y sujeta el otro extremo.","Lleva ese brazo en horizontal sobre el pecho.","Usa la banda para profundizar el tirón suavemente.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],["Mantén el hombro que trabaja relajado y abajo.","Relájate y sigue respirando todo el tiempo."]],["banded-lat-stretch","Estiramiento de Dorsales con Banda","Un estiramiento de pie que alarga los dorsales al inclinarse hacia adelante sosteniendo una banda en tensión sobre la cabeza.","Espalda","Estiramiento","Principiante","Banda elástica",false,["Dorsal ancho"],["Deltoides posterior"],5.0,"banded-lat-stretch-main.webp",null,["Sujeta una banda sobre la cabeza con ambas manos en tensión ligera.","Inclínate desde las caderas con los brazos extendidos al frente.","Deja caer el pecho para alargar los lados de la espalda.","Mantén de 20 a 30 segundos, respirando de forma constante."],["Mantén los brazos estirados y los hombros relajados.","Relájate y sigue respirando todo el tiempo."]],["bench-lat-stretch","Estiramiento de Dorsales en Banco","Un estiramiento de rodillas con las manos en el banco, hundiendo el pecho hacia el suelo para alargar los dorsales.","Espalda","Estiramiento","Principiante","Banco plano",false,["Dorsal ancho"],["Deltoides posterior"],5.0,"bench-lat-stretch-main.webp",null,["Arrodíllate en el suelo frente a un banco.","Coloca ambas manos sobre el banco.","Lleva la cadera atrás y deja caer el pecho.","Mantén de 20 a 30 segundos, respirando de forma constante."],["Mantén los brazos estirados y la cabeza entre ellos.","Relájate y sigue respirando todo el tiempo."]],["kneeling-hip-flexor-stretch","Estiramiento de Flexores de Cadera Arrodillado","Un estiramiento en semiarrodillado que abre los flexores de cadera de la pierna trasera empujando la cadera adelante.","Pierna","Estiramiento","Principiante","Sin equipo",true,["Flexores de cadera"],["Aductores","Cuádriceps"],5.0,"kneeling-hip-flexor-stretch-main.webp",null,["Arrodíllate sobre una rodilla con el otro pie plano al frente.","Mantén el torso erguido y el core ligeramente activado.","Empuja la cadera adelante hasta sentir el estiramiento en el frente de la cadera trasera.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],["Aprieta el glúteo de la pierna arrodillada para proteger la zona lumbar.","Evita arquear la zona lumbar."]],["cross-body-shoulder-stretch","Estiramiento de Hombro Cruzado","Un estiramiento de pie para el hombro posterior llevando un brazo en horizontal sobre el pecho.","Hombro","Estiramiento","Principiante","Sin equipo",true,["Deltoides posterior"],["Romboides"],5.0,"cross-body-shoulder-stretch-main.webp",null,["Párate erguido y cruza un brazo estirado sobre el pecho.","Engancha el otro antebrazo por debajo.","Tira suavemente del brazo hacia el pecho.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],["Mantén el hombro estirado abajo, sin encogerlo.","No tires de la articulación del codo en sí."]],["banded-shoulder-stretch","Estiramiento de Hombros con Banda","Un estiramiento de pie que abre los hombros y el pecho sujetando una banda tras la espalda, una mano arriba y otra abajo.","Hombro","Estiramiento","Principiante","Banda elástica",false,["Deltoides anterior"],["Pectoral mayor"],5.0,"banded-shoulder-stretch-main.webp",null,["Sujeta una banda tras la espalda, una mano arriba y otra abajo.","Mantén una tensión ligera en la banda.","Abre el pecho y lleva los hombros suavemente atrás.","Mantén de 20 a 30 segundos, respirando de forma constante."],["Mantén las costillas abajo y evita arquear la espalda.","Separa más las manos para suavizar el estiramiento."]],["banded-hamstring-stretch","Estiramiento de Isquiotibiales con Banda","Un estiramiento tumbado que usa una banda en el pie para acercar la pierna estirada al torso y alargar el isquiotibial.","Pierna","Estiramiento","Principiante","Banda elástica",false,["Isquiotibiales"],["Gemelos"],5.0,"banded-hamstring-stretch-main.webp",null,["Acuéstate boca arriba y pasa una banda por un pie.","Eleva esa pierna recta, sujetando la banda con ambas manos.","Tira suavemente de la banda para acercar la pierna.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],["Mantén la pierna elevada lo más recta posible.","Mantén la otra pierna plana en el suelo."]],["bench-hamstring-stretch","Estiramiento de Isquiotibiales en Banco","Un estiramiento de pie con el talón en un banco, inclinándose sobre la pierna estirada para alargar el isquiotibial.","Pierna","Estiramiento","Principiante","Banco plano",false,["Isquiotibiales"],["Erectores espinales"],5.0,"bench-hamstring-stretch-main.webp",null,["Coloca un talón en el banco con esa pierna estirada.","Mantente erguido sobre la pierna de apoyo.","Inclínate desde las caderas sobre la pierna elevada.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],["Mantén la espalda recta al inclinarte.","Mantén la pierna elevada recta, con los dedos arriba."]],["butterfly-stretch","Estiramiento de Mariposa","Un estiramiento sentado para los aductores, juntando las plantas de los pies con las rodillas caídas hacia afuera.","Pierna","Estiramiento","Principiante","Sin equipo",true,["Aductores"],["Flexores de cadera"],5.0,"butterfly-stretch-main.webp",null,["Siéntate erguido y junta las plantas de los pies.","Deja caer las rodillas hacia el suelo.","Sujeta los pies y mantente erguido.","Mantén de 20 a 30 segundos, respirando de forma constante."],["Presiona suavemente las rodillas con los codos para más estiramiento.","Acerca los talones al cuerpo para aumentar la intensidad."]],["kneeling-wrist-stretch","Estiramiento de Muñecas Arrodillado","Un estiramiento de rodillas para los flexores del antebrazo y las muñecas, con las palmas abajo y los dedos hacia atrás.","Antebrazo","Estiramiento","Principiante","Sin equipo",true,["Flexores del antebrazo"],[],5.0,"kneeling-wrist-stretch-main.webp",null,["Ponte en cuadrupedia y apoya las palmas planas en el suelo.","Gira las manos para que los dedos apunten hacia las rodillas.","Mantén las palmas abajo y desplaza el peso atrás suavemente.","Mantén de 20 a 30 segundos, respirando de forma constante."],["Mantén las palmas planas mientras te inclinas atrás.","Estira hasta una tensión leve, nunca hasta el dolor."]],["banded-calf-stretch","Estiramiento de Pantorrilla con Banda","Un estiramiento tumbado que usa una banda en la planta del pie para flexionar el tobillo y alargar la pantorrilla.","Pierna","Estiramiento","Principiante","Banda elástica",false,["Gemelos"],["Sóleo"],5.0,"banded-calf-stretch-main.webp",null,["Acuéstate boca arriba y pasa una banda por la planta de un pie.","Eleva la pierna y mantenla bastante recta.","Tira de la banda para que los dedos se acerquen a la espinilla.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],["Mantén el tirón constante, sin tirones bruscos.","Mantén la rodilla suavemente estirada."]],["standing-calf-stretch","Estiramiento de Pantorrilla de Pie","Un estiramiento en paso escalonado que alarga la pantorrilla presionando el talón trasero con la pierna estirada.","Pierna","Estiramiento","Principiante","Sin equipo",true,["Gemelos"],["Sóleo"],5.0,"standing-calf-stretch-main.webp",null,["Lleva un pie atrás a un paso escalonado.","Mantén la pierna trasera estirada y el talón presionado al suelo.","Flexiona la rodilla delantera e inclina el peso hacia adelante.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],["Mantén el talón trasero plano y los dedos al frente.","Flexiona un poco la rodilla trasera para trabajar la pantorrilla baja."]],["bench-calf-stretch","Estiramiento de Pantorrilla en Banco","Un estiramiento de pie con la planta del pie en el borde del banco, dejando caer el talón para alargar la pantorrilla.","Pierna","Estiramiento","Principiante","Banco plano",false,["Gemelos"],["Sóleo"],5.0,"bench-calf-stretch-main.webp",null,["Coloca la planta de un pie en el borde del banco.","Mantén esa rodilla estirada.","Deja caer el talón por debajo de los dedos.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],["Sujétate del banco o de una pared para equilibrarte.","Mantén el movimiento lento y controlado."]],["banded-chest-stretch","Estiramiento de Pecho con Banda","Un estiramiento de pie que abre el pecho sujetando una banda tras la espalda y separando los brazos.","Pecho","Estiramiento","Principiante","Banda elástica",false,["Pectoral mayor"],["Deltoides anterior"],5.0,"banded-chest-stretch-main.webp",null,["Sujeta una banda con ambas manos tras la espalda.","Estira los brazos y sepáralos.","Eleva el pecho y junta los omóplatos.","Mantén de 20 a 30 segundos, respirando de forma constante."],["Mantén los hombros abajo, lejos de las orejas.","Estira hasta una tensión leve, nunca hasta el dolor."]],["bench-chest-stretch","Estiramiento de Pecho en Banco","Un estiramiento de rodillas con las manos detrás en el banco, bajando la cadera para abrir el pecho y los hombros.","Pecho","Estiramiento","Principiante","Banco plano",false,["Pectoral mayor"],["Deltoides anterior"],5.0,"bench-chest-stretch-main.webp",null,["Arrodíllate de espaldas al banco.","Coloca ambas manos detrás en el borde del banco.","Baja la cadera para abrir el pecho.","Mantén de 20 a 30 segundos, respirando de forma constante."],["Mantén los hombros abajo, lejos de las orejas.","Estira hasta una tensión leve, nunca hasta el dolor."]],["doorway-chest-stretch","Estiramiento de Pecho en el Marco","Un estiramiento de brazos abiertos que alarga el pecho y los hombros frontales al llevar los brazos atrás.","Pecho","Estiramiento","Principiante","Sin equipo",true,["Pectoral mayor"],["Deltoides anterior"],5.0,"doorway-chest-stretch-main.webp",null,["Párate erguido y sube los brazos en posición de portería.","Flexiona los codos noventa grados, antebrazos verticales.","Lleva los codos atrás y junta los omóplatos.","Mantén de 20 a 30 segundos, respirando de forma constante."],["Mantén las costillas abajo y evita arquear la espalda.","Estira hasta una tensión leve, nunca hasta el dolor."]],["banded-ankle-stretch","Estiramiento de Tobillo con Banda","Un estiramiento sentado que usa una banda en el antepié para flexionar el tobillo y alargar la pantorrilla.","Pierna","Estiramiento","Principiante","Banda elástica",false,["Gemelos"],["Sóleo"],5.0,"banded-ankle-stretch-main.webp",null,["Siéntate con una pierna extendida y una banda en el antepié.","Sujeta la banda con ambas manos.","Tira para que los dedos se acerquen a la espinilla.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],["Mantén la pierna estirada y relajada.","Estira hasta una tensión leve, nunca hasta el dolor."]],["bench-ankle-stretch","Estiramiento de Tobillo en Banco","Un estiramiento de pie con el pie plano en el banco, llevando la rodilla por delante de los dedos para flexionar el tobillo.","Pierna","Estiramiento","Principiante","Banco plano",false,["Gemelos"],["Sóleo"],5.0,"bench-ankle-stretch-main.webp",null,["Coloca un pie entero plano sobre el banco.","Mantén el torso erguido.","Lleva esa rodilla hacia adelante por encima de los dedos.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],["Mantén el talón apoyado en el banco.","Muévete despacio y mantén el pie plano."]],["banded-triceps-stretch","Estiramiento de Tríceps con Banda","Un estiramiento de pie que alarga el tríceps llevando una mano tras la cabeza contra la tensión de la banda.","Tríceps","Estiramiento","Principiante","Banda elástica",false,["Tríceps braquial"],["Dorsal ancho"],5.0,"banded-triceps-stretch-main.webp",null,["Sujeta una banda que baja por la espalda, con la mano de arriba tras la cabeza.","Fija la mano de abajo en la zona lumbar.","Baja la mano de arriba hasta sentir el tríceps estirarse.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],["Mantén la cabeza erguida y las costillas abajo.","Relájate y sigue respirando todo el tiempo."]],["overhead-triceps-stretch","Estiramiento de Tríceps sobre la Cabeza","Un estiramiento de pie que alarga el tríceps y el dorsal llevando la mano por la espalda alta.","Tríceps","Estiramiento","Principiante","Sin equipo",true,["Tríceps braquial"],["Dorsal ancho"],5.0,"overhead-triceps-stretch-main.webp",null,["Sube un brazo sobre la cabeza y flexiona el codo.","Deja caer la mano por detrás de la cabeza.","Con la otra mano empuja el codo flexionado hacia atrás.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],["Mantén la cabeza erguida, no la empujes hacia adelante.","Relájate y sigue respirando todo el tiempo."]],["cobra-stretch","Estiramiento de la Cobra","Una extensión boca abajo que estira los abdominales y la parte frontal del torso al elevar el pecho.","Core","Estiramiento","Principiante","Sin equipo",true,["Recto abdominal"],["Flexores de cadera","Transverso abdominal"],5.0,"cobra-stretch-main.webp",null,["Acuéstate boca abajo con las manos bajo los hombros.","Empuja con las manos para levantar el pecho del suelo.","Mantén caderas y piernas en el suelo, con los hombros relajados.","Mantén de 20 a 30 segundos, respirando de forma constante."],["Mantén los codos algo flexionados, no fuerces la extensión completa.","Baja los hombros alejándolos de las orejas."]],["pigeon-stretch","Estiramiento de la Paloma","Un estiramiento sentado en el suelo para los glúteos y la cadera externa, con la espinilla delantera cruzada al frente.","Pierna","Estiramiento","Principiante","Sin equipo",true,["Glúteo mayor"],["Glúteo medio","Flexores de cadera"],5.0,"pigeon-stretch-main.webp",null,["Desde cuadrupedia, lleva una rodilla adelante y apoya la espinilla cruzada al frente.","Extiende la otra pierna recta hacia atrás, con el empeine en el suelo.","Baja la cadera hacia el suelo y mantenla cuadrada.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],["Coloca un cojín bajo la cadera si no llega al suelo.","Camina las manos hacia adelante para profundizar el estiramiento."]],["cat-stretch","Estiramiento del Gato","Un estiramiento de rodillas que redondea la columna hacia arriba para alargar los músculos de la espalda.","Espalda","Estiramiento","Principiante","Sin equipo",true,["Erectores espinales"],["Romboides","Trapecio"],5.0,"cat-stretch-main.webp",null,["Empieza en cuadrupedia, manos bajo los hombros y rodillas bajo las caderas.","Redondea la columna hacia el techo.","Lleva el mentón hacia el pecho.","Mantén de 20 a 30 segundos, respirando de forma constante."],["Empuja el suelo con las manos para separar los omóplatos.","Relájate y sigue respirando todo el tiempo."]],["lizard-stretch","Estiramiento del Lagarto","Un estiramiento en zancada profunda que abre los flexores de cadera, la ingle y los glúteos con los antebrazos hacia el suelo.","Pierna","Estiramiento","Principiante","Sin equipo",true,["Aductores","Flexores de cadera"],["Glúteo mayor","Isquiotibiales"],5.0,"lizard-stretch-main.webp",null,["Da un paso adelante a una zancada profunda, con el pie bien abierto.","Baja ambos antebrazos hacia el suelo por dentro del pie delantero.","Extiende la pierna trasera y deja que la cadera baje.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],["Apóyate en las manos en vez de los antebrazos para una versión más fácil.","Estira hasta una tensión leve, nunca hasta el dolor."]],["seated-straddle-stretch","Estiramiento en Apertura Sentado","Un estiramiento sentado con piernas abiertas para aductores e isquiotibiales, inclinando el torso entre las piernas.","Pierna","Estiramiento","Principiante","Sin equipo",true,["Aductores","Isquiotibiales"],["Erectores espinales"],5.0,"seated-straddle-stretch-main.webp",null,["Siéntate con las piernas estiradas y bien abiertas en V.","Mantén la espalda larga e inclínate desde las caderas.","Camina las manos hacia adelante por el suelo.","Mantén de 20 a 30 segundos, respirando de forma constante."],["Mantén los dedos de los pies hacia arriba, no girados.","Entra en el estiramiento lentamente, nunca rebotes."]],["banded-terminal-knee-extension","Extensión Terminal de Rodilla con Banda","Un ejercicio de aislamiento que extiende la rodilla contra la banda, usado para el VMO y rehabilitación.","Pierna","Fuerza","Principiante","Banda circular",false,["Cuádriceps"],[],5.0,"banded-terminal-knee-extension-start.webp","banded-terminal-knee-extension-peak.webp",["Ancla una banda elástica a un poste firme a la altura de la rodilla.","Pasa el bucle de modo que la banda quede detrás de una rodilla.","Da un paso atrás para que la banda flexione ligeramente la rodilla.","Extiende la rodilla completamente contra la banda, contrayendo el cuádriceps.","Regresa lentamente. Repeticiones por lado y cambia."],["Contrae fuerte el cuádriceps en la extensión completa.","Mantén el pie plano — no levantes el talón.","Mueve solo la rodilla — la cadera permanece inmóvil."]],["barbell-overhead-extension","Extensión de Barra por Encima de la Cabeza","Este ejercicio de aislamiento trabaja eficazmente el tríceps braquial al extender los codos por encima de la cabeza, promoviendo la hipertrofia y fuerza muscular.","Tríceps","Fuerza","Intermedio","Barra",false,["Tríceps braquial"],[],5.0,"barbell-overhead-extension-start.webp","barbell-overhead-extension-peak.webp",["Carga una barra con el peso adecuado y ponte de pie o siéntate con la columna neutra.","Agarra la barra con un agarre prono, al ancho de los hombros, y presiónala por encima de tu cabeza.","Baja lentamente la barra detrás de tu cabeza flexionando los codos, manteniendo los brazos estables.","Extiende los codos para presionar la barra de vuelta a la posición inicial por encima de la cabeza, contrayendo tus tríceps.","Mantén el control durante todo el movimiento, evitando el impulso."],["Mantén los codos pegados y apuntando hacia adelante para maximizar la activación del tríceps y proteger tus hombros.","Controla la fase excéntrica (descenso) para mejorar la tensión muscular y el crecimiento.","Evita arquear demasiado la espalda baja; contrae tu core para mantener la estabilidad."]],["single-leg-extension","Extensión de Cuádriceps a Una Pierna","Un ejercicio de aislamiento de cuádriceps en una máquina de extensión de piernas, trabajando una pierna a la vez.","Pierna","Fuerza","Intermedio","Máquina de extensión de cuádriceps",false,["Cuádriceps"],[],5.0,"single-leg-extension-start.webp","single-leg-extension-peak.webp",["Siéntate en una máquina de extensión de piernas y coloca un pie bajo la almohadilla.","Deja el otro pie apoyado en el suelo o colgando.","Extiende la pierna de trabajo hasta que quede casi recta.","Contrae el cuádriceps en la parte alta.","Baja la pierna con control.","Completa las repeticiones de un lado y luego cambia."],["Contrae con fuerza el cuádriceps en la parte alta del movimiento.","Baja el peso con control en lugar de dejarlo caer.","Mantén la espalda plana contra el respaldo."]],["back-extension","Extensión de Espalda","Un movimiento de aislamiento que trabaja los erectores espinales de la zona lumbar en un banco de hiperextensión.","Espalda","Fuerza","Principiante","Sin equipo",true,["Erectores espinales"],["Glúteo mayor","Isquiotibiales"],3.5,"back-extension-start.webp","back-extension-peak.webp",["Acuéstate boca abajo en un banco de hiperextensión con las caderas en el borde del pad.","Baja el torso hacia el suelo.","Sube el torso hasta que el cuerpo quede recto.","Repite."],["Mantén los movimientos controlados.","No hiperextiendas más allá de la posición neutra de la columna."]],["machine-back-extension","Extensión de Espalda en Máquina","Un ejercicio de aislamiento sentado para la zona lumbar: con la cadera y las piernas fijas, el torso empuja hacia atrás contra un rodillo acolchado y extiende la columna venciendo la placa de pesas.","Espalda","Fuerza","Principiante","Banco de hiperextensiones",false,["Erectores espinales"],["Glúteo mayor","Isquiotibiales"],5.0,"machine-back-extension-start.webp","machine-back-extension-peak.webp",["Siéntate en la máquina de extensión de espalda con los pies apoyados en la plataforma y ajusta el rodillo para que quede sobre la parte alta de la espalda, justo por debajo de los omóplatos.","Agarra las manijas laterales y deja que el torso venga ligeramente hacia delante: esta es la posición inicial.","Empuja hacia atrás contra el rodillo extendiendo la columna hasta que el torso quede inclinado hacia atrás y la zona lumbar esté totalmente contraída.","Haz una pausa breve en la extensión completa y regresa a la posición inicial de forma controlada, resistiendo el peso durante el recorrido.","Repite el número de repeticiones deseado."],["Coloca el rodillo justo por debajo de los omóplatos: más arriba presiona el cuello y más abajo pierdes recorrido.","Extiende desde la zona lumbar en lugar de lanzar la cabeza y los hombros hacia atrás, y mantén lento el movimiento en ambos sentidos.","Detente con el torso extendido en posición neutra en lugar de forzar la columna más allá, y empieza con poco peso: la zona lumbar responde mejor a repeticiones controladas que a cargas altas."]],["leg-extension","Extensión de Piernas","Un ejercicio de aislamiento para los cuádriceps usando una máquina.","Pierna","Fuerza","Principiante","Máquina de extensión de cuádriceps",false,["Cuádriceps"],[],5.0,"leg-extension-start.webp","leg-extension-peak.webp",["Siéntate en la máquina de extensión de piernas con los tobillos detrás del rodillo.","Extiende las piernas hasta que queden rectas.","Aprieta los cuádriceps en la parte superior.","Baja con control.","Repite."],["Alinea las rodillas con el eje de giro de la máquina.","Sube el peso sin lanzarlo con impulso.","Agárrate a las asas para mantener la cadera estable en el asiento."]],["trx-tricep-extension","Extensión de Tríceps TRX","Este ejercicio trabaja el tríceps braquial utilizando un entrenador de suspensión, enfocándose en la extensión del codo para el desarrollo y la fuerza de la parte superior del brazo.","Tríceps","Fuerza","Intermedio","Entrenador de suspensión (TRX)",false,["Tríceps braquial"],[],5.0,"trx-tricep-extension-start.webp","trx-tricep-extension-peak.webp",["Párate frente al punto de anclaje, sosteniendo las asas del TRX con un agarre por encima, las palmas hacia abajo.","Inclínate hacia adelante, extendiendo tus brazos rectos frente a ti a la altura de los hombros, creando tensión en las correas.","Manteniendo los codos altos y fijos, dóblalos para bajar tu cuerpo, llevando tus manos hacia tus sienes.","Extiende los codos con fuerza para empujar tu cuerpo de vuelta a la posición inicial, contrayendo tus tríceps.","Mantén una posición de plancha rígida durante todo el movimiento, activando tu core y glúteos."],["Ajusta el ángulo de tu cuerpo para aumentar o disminuir la dificultad; cuanto más horizontal, más difícil será el ejercicio.","Mantén los codos apuntando hacia adelante y altos para maximizar el aislamiento del tríceps y minimizar la participación del hombro.","Controla la fase excéntrica (descenso) para una mejor activación y crecimiento muscular."]],["lying-tricep-extension","Extensión de Tríceps Tumbado","Un ejercicio de aislamiento tumbado que baja el peso hacia la frente y extiende los codos para trabajar los tríceps.","Tríceps","Fuerza","Intermedio","Mancuernas",false,["Tríceps braquial"],["Deltoides anterior"],5.0,"lying-tricep-extension-start.webp","lying-tricep-extension-peak.webp",["Túmbate en un banco con una barra o mancuernas sostenidas sobre la cabeza.","Mantén los brazos superiores verticales y los codos apuntando hacia adelante.","Baja el peso hacia la frente doblando los codos.","Extiende los brazos de vuelta a la posición inicial.","Aprieta los tríceps en la parte superior.","Repite el número de repeticiones deseado."],["Mantén los brazos verticales y los codos apuntando hacia delante.","Mueve solo los codos, no los hombros.","Baja el peso con control en lugar de dejarlo caer."]],["ez-bar-lying-tricep-extension","Extensión de Tríceps Tumbado con Barra Z","Una extensión de tríceps tumbado realizada con una barra Z para aislar el tríceps a lo largo de todo el rango de movimiento.","Tríceps","Fuerza","Intermedio","Barra Z",false,["Tríceps braquial"],[],5.0,"ez-bar-lying-tricep-extension-start.webp","ez-bar-lying-tricep-extension-peak.webp",["Túmbate en un banco plano sujetando una barra Z sobre el pecho con un agarre estrecho.","Baja la barra hacia la frente flexionando los codos.","Extiende los brazos de vuelta a la posición inicial.","Repite."],["Mantén los brazos superiores verticales en todo momento para que trabaje el tríceps.","El agarre angulado de la barra Z es más cómodo para las muñecas que una barra recta.","Baja despacio para proteger los codos."]],["one-arm-kettlebell-tricep-kickback","Extensión de Tríceps a Un Brazo con Pesa Rusa","Una extensión de tríceps unilateral con pesa rusa: inclínate, fija el brazo al costado paralelo al suelo y extiende el codo hacia atrás.","Tríceps","Fuerza","Principiante","Kettlebell",false,["Tríceps braquial"],["Deltoides posterior"],5.0,"one-arm-kettlebell-tricep-kickback-start.webp","one-arm-kettlebell-tricep-kickback-peak.webp",["Inclínate hacia delante flexionando las caderas con la espalda recta y las rodillas ligeramente flexionadas.","Sujeta una pesa rusa por el asa con una mano, con la palma hacia el cuerpo.","Fija la parte alta del brazo al costado de modo que quede paralela al suelo; el antebrazo cuelga recto hacia abajo.","Extiende el codo hacia atrás para estirar el brazo del todo por detrás de ti, manteniendo inmóvil la parte alta del brazo.","Aprieta el tríceps en la extensión completa y vuelve de forma controlada a la posición inicial.","Completa todas las repeticiones de un lado y luego cambia de mano."],["La parte alta del brazo no se mueve, solo el antebrazo; balancear el hombro es trampa.","Bloquea la pesa un instante en la extensión completa; tiende a hundirte la muñeca.","Usa una pesa más ligera que en una extensión con mancuerna; la carga descentrada cuesta más de estabilizar."]],["single-arm-tricep-pushdown","Extensión de Tríceps a Un Brazo en Polea","Un ejercicio de aislamiento de tríceps realizado con un brazo a la vez en una máquina de polea con una sola manija.","Tríceps","Fuerza","Intermedio","Polea",false,["Tríceps braquial"],["Extensores del antebrazo"],6.0,"single-arm-tricep-pushdown-start.webp","single-arm-tricep-pushdown-peak.webp",["Coloca una manija individual en una polea alta.","Sujeta la manija con una mano y mantén el codo pegado al costado.","Empuja la manija hacia abajo hasta extender completamente el brazo.","Contrae el tríceps en la parte baja.","Vuelve lentamente a la posición inicial.","Completa las repeticiones de un lado y luego cambia."],["Mantén el codo pegado al costado en todo momento.","Evita inclinarte hacia adelante para generar impulso.","Extiende el brazo por completo en la parte baja para una contracción total."]],["dumbbell-tricep-extension","Extensión de Tríceps con Mancuerna","Una extensión de tríceps en una mano por encima de la cabeza para un desarrollo equilibrado del brazo.","Tríceps","Fuerza","Principiante","Mancuernas",false,["Tríceps braquial"],[],5.0,"dumbbell-tricep-extension-start.webp","dumbbell-tricep-extension-peak.webp",["Ponte de pie sujetando una mancuerna en una mano por encima de la cabeza.","Baja la mancuerna detrás de la cabeza doblando el codo.","Extiende el brazo de vuelta a la posición inicial.","Mantén el codo cerca de la cabeza.","Repite en ambos lados."],["Mantén el codo apuntando al techo durante todo el movimiento.","Baja la mancuerna despacio hasta sentir el estiramiento del tríceps.","Evita arquear la espalda baja manteniendo el abdomen firme."]],["seated-dumbbell-tricep-extension","Extensión de Tríceps con Mancuerna Sentado","Una extensión por encima de la cabeza sentado que baja la mancuerna detrás de la cabeza, estirando y trabajando los tríceps.","Tríceps","Fuerza","Principiante","Mancuernas",false,["Tríceps braquial"],["Deltoides anterior"],5.0,"seated-dumbbell-tricep-extension-start.webp","seated-dumbbell-tricep-extension-peak.webp",["Siéntate en un banco con una mancuerna sostenida sobre la cabeza con ambas manos.","Mantén los brazos superiores verticales junto a las orejas.","Baja la mancuerna detrás de la cabeza flexionando los codos.","Extiende los brazos para empujar la mancuerna de vuelta arriba.","Aprieta los tríceps en la parte superior.","Repite el número de repeticiones deseado."],["Mantén los brazos verticales junto a las orejas.","Mueve solo los antebrazos, manteniendo los codos quietos.","Contrae el core para evitar arquear la zona lumbar."]],["machine-triceps-extension","Extensión de Tríceps en Máquina","Un ejercicio de aislamiento sentado en máquina: los brazos quedan apoyados sobre un rodillo mientras los codos se extienden contra dos manijas, de modo que el tríceps trabaja por un recorrido guiado sin ayuda de los hombros ni del torso.","Tríceps","Fuerza","Principiante","Máquina de extensión de tríceps",false,["Tríceps braquial"],[],5.0,"machine-triceps-extension-start.webp","machine-triceps-extension-peak.webp",["Siéntate en la máquina de extensión de tríceps con la espalda apoyada en el respaldo y los brazos apoyados de plano sobre el rodillo, delante del pecho.","Toma una manija con cada mano, con los codos flexionados y las manos a la altura de los hombros.","Manteniendo los brazos pegados al rodillo, extiende los codos para empujar las manijas hacia abajo y hacia delante hasta estirar los brazos por completo.","Aprieta el tríceps en la extensión completa y flexiona los codos para volver al inicio de forma controlada.","Repite el número de repeticiones deseado."],["Ajusta la altura del asiento para que los brazos queden planos sobre el rodillo y los codos alineados con el eje de giro de la máquina: esa alineación es lo que mantiene el trabajo en el tríceps.","Mantén los brazos pegados al rodillo; si se despegan, el movimiento se convierte en un press y el tríceps deja de trabajar.","Estira los brazos del todo sin bloquear de golpe los codos, y frena la vuelta en lugar de dejar caer las placas."]],["v-bar-tricep-pushdown","Extensión de Tríceps en Polea con Barra en V","Una extensión de tríceps en polea con barra en V que fija las muñecas en posición pronada y ligeramente angulada, cargando la cabeza lateral.","Tríceps","Fuerza","Principiante","Polea",false,["Tríceps braquial"],[],5.0,"v-bar-tricep-pushdown-start.webp","v-bar-tricep-pushdown-peak.webp",["Coloca una barra en V en la polea alta.","Párate frente a la pila y agarra la barra en V con ambas manos, palmas hacia abajo.","Comienza con los codos pegados a los costados y los antebrazos paralelos al suelo.","Empuja el mango hacia abajo hasta que los brazos estén completamente extendidos.","Aprieta los tríceps y vuelve de forma controlada a la posición inicial.","Repite el número de repeticiones recomendado."],["Mantén los codos pegados a los costados durante toda la serie.","No te apoyes en la barra; una pequeña inclinación hacia adelante está bien, pero deja que los tríceps hagan el trabajo."]],["overhead-tricep-extension","Extensión de Tríceps por Encima de la Cabeza","Un ejercicio de aislamiento para el tríceps que enfatiza la cabeza larga.","Tríceps","Fuerza","Principiante","Mancuernas",false,["Tríceps braquial"],[],5.0,"overhead-tricep-extension-start.webp","overhead-tricep-extension-peak.webp",["De pie o sentado, sostén una mancuerna por encima de la cabeza con ambas manos.","Baja la mancuerna detrás de la cabeza doblando los codos.","Extiende los brazos de vuelta a la posición inicial.","Mantén los codos cerca de la cabeza durante todo el ejercicio.","Repite."],["Mueve solo los antebrazos y mantén quieto todo lo demás.","Evita arquear la zona lumbar cuando la mancuerna baje.","Agarra la mancuerna por debajo del disco superior con ambas palmas."]],["ez-bar-overhead-extension","Extensión de Tríceps por Encima de la Cabeza con Barra Z","Extensión de tríceps por encima de la cabeza con barra Z — el agarre angulado es más cómodo para las muñecas que una barra recta y mantiene la cabeza larga bajo un estiramiento profundo.","Tríceps","Fuerza","Intermedio","Barra Z",false,["Tríceps braquial"],[],5.0,"ez-bar-overhead-extension-start.webp","ez-bar-overhead-extension-peak.webp",["Ponte de pie o siéntate sujetando la barra Z por encima de la cabeza con agarre prono en las curvas internas.","Brazos completamente extendidos con la barra sobre la cabeza.","Dobla solo los codos para bajar la barra detrás de la cabeza en un arco.","Mantén los brazos verticales y cerca de la cabeza; solo los antebrazos se mueven.","Extiende los codos para volver la barra a la posición inicial.","Repite el número de repeticiones recomendado."],["Si los codos se abren hacia afuera, baja el peso — significa que los hombros están ayudando.","Cuanto más profundo sea el estiramiento en la parte inferior, mayor será el estímulo de hipertrofia en la cabeza larga.","La versión sentada es más cómoda para la zona lumbar."]],["single-arm-dumbbell-overhead-tricep-extension","Extensión de Tríceps sobre la Cabeza con Mancuerna a Un Brazo","Una extensión de tríceps sobre la cabeza a un brazo que proporciona un estiramiento largo y unilateral de la cabeza larga y entrena la estabilidad del core contra la flexión lateral.","Tríceps","Fuerza","Principiante","Mancuernas",false,["Tríceps braquial"],["Oblicuos"],5.0,"single-arm-dumbbell-overhead-tricep-extension-start.webp","single-arm-dumbbell-overhead-tricep-extension-peak.webp",["De pie o sentado, sostén una mancuerna en una mano sobre la cabeza con el brazo completamente extendido.","La palma mira hacia adelante; la otra mano puede apoyarse en la cadera o en un soporte para mayor estabilidad.","Flexiona el codo para bajar la mancuerna detrás de la cabeza en un arco controlado.","Mantén el brazo superior vertical y cerca de la cabeza durante todo el movimiento.","Extiende el codo para regresar la mancuerna sobre la cabeza.","Completa todas las repeticiones de un lado y luego cambia."],["Solo el antebrazo se mueve — el brazo superior permanece fijo en su lugar.","No dejes que el torso se incline hacia un lado; este también es un ejercicio de core."]],["kettlebell-overhead-tricep-extension","Extensión de tríceps por encima de la cabeza con pesa rusa","Una extensión de tríceps por encima de la cabeza sosteniendo una pesa rusa por las asas con ambas manos. La carga descentrada jala la campana detrás de la cabeza para un estiramiento profundo de la cabeza larga.","Tríceps","Fuerza","Intermedio","Kettlebell",false,["Tríceps braquial"],[],5.0,"kettlebell-overhead-tricep-extension-start.webp","kettlebell-overhead-tricep-extension-peak.webp",["Párate o siéntate sosteniendo una pesa rusa por las asas (boca abajo) con ambas manos por encima de la cabeza.","Brazos completamente extendidos, campana sobre la cabeza.","Flexiona solo los codos para bajar la campana detrás de la cabeza en un arco controlado.","Mantén los brazos verticales y pegados a la cabeza; solo los antebrazos se mueven.","Extiende los codos para devolver la campana por encima de la cabeza.","Repite el número recomendado de repeticiones."],["Agarra las asas firmemente — la campana tiende a rotar en la parte inferior.","Los codos se mantienen pegados; si se abren, reduce la carga.","Una versión sentado en un banco con respaldo es más fácil para la zona lumbar."]],["dumbbell-face-pull","Face Pull con Mancuernas","Un ejercicio para el deltoides posterior y la espalda alta, tirando de mancuernas hacia la cara con los codos muy abiertos.","Hombro","Fuerza","Intermedio","Mancuernas",false,["Deltoides posterior","Romboides"],["Bíceps braquial","Trapecio"],5.0,"dumbbell-face-pull-start.webp","dumbbell-face-pull-peak.webp",["Ponte de pie o siéntate sosteniendo una mancuerna en cada mano con los brazos extendidos hacia adelante.","Flexiona los codos y tira de las mancuernas hacia la cara.","Abre los codos hasta la altura de los hombros.","Contrae el deltoides posterior y la espalda alta en el punto máximo.","Baja las mancuernas con control.","Repite el número de repeticiones deseado."],["Lidera el movimiento con los codos, no con las manos.","Mantén los brazos superiores casi paralelos al suelo.","Usa un peso ligero y prioriza la técnica."]],["trx-face-pull","Face Pull con TRX","El Face Pull con TRX es un ejercicio de tracción compuesto que trabaja los deltoides posteriores y los romboides, utilizando un entrenador de suspensión para mejorar la fuerza de la parte superior de la espalda y la postura.","Hombro","Fuerza","Principiante","Entrenador de suspensión (TRX)",false,["Deltoides posterior","Romboides"],["Trapecio"],6.0,"trx-face-pull-start.webp","trx-face-pull-peak.webp",["Sujeta las asas del TRX con un agarre prono, las palmas hacia abajo.","Inclínate hacia atrás hasta que tus brazos estén completamente extendidos y tu cuerpo forme una línea recta.","Tira de las asas hacia tu cara, llevando los codos altos y abiertos.","Aprieta los omóplatos al máximo de la contracción.","Extiende lentamente los brazos de vuelta a la posición inicial con control."],["Mantén el torso rígido durante todo el movimiento; evita arquear la espalda baja.","Concéntrate en iniciar la tracción con los músculos de la parte superior de la espalda, no solo con los brazos.","Ajusta el ángulo de tu cuerpo para modificar la dificultad: una posición más horizontal es más difícil."]],["ring-face-pull","Face Pull en Anillas","Un face pull en anillas de gimnasia para resistencia ajustable y mejora de la salud del hombro.","Hombro","Fuerza","Intermedio","Anillas",false,["Deltoides posterior","Romboides"],["Trapecio"],6.0,"ring-face-pull-start.webp","ring-face-pull-peak.webp",["Agarra las anillas e inclínate hacia atrás de modo que el cuerpo quede en ángulo.","Jala las anillas hacia la cara, abriendo los codos hacia los lados.","Mantén brevemente y luego regresa.","Repite."],["Ajusta el ángulo del cuerpo para controlar la dificultad.","Rota los brazos externamente en la parte superior."]],["face-pull","Face Pull en Polea","Un ejercicio de cable que trabaja los deltoides posteriores y los rotadores externos.","Hombro","Fuerza","Principiante","Polea",false,["Deltoides posterior","Romboides"],["Trapecio"],6.0,"face-pull-start.webp","face-pull-peak.webp",["Engancha una cuerda en una polea alta.","Tira de la cuerda hacia tu cara, separando los extremos.","Aprieta los deltoides posteriores y los rotadores externos.","Regresa a la posición inicial de forma controlada.","Repite."],["Mantén los codos altos, alineados con los hombros.","Junta las escápulas al final de cada repetición.","Trabaja con peso ligero para no perder la técnica."]],["wide-grip-push-ups","Flexiones con Agarre Ancho","Una variante de flexión con las manos colocadas más separadas para enfatizar el pecho.","Pecho","Fuerza","Intermedio","Sin equipo",true,["Pectoral mayor"],["Deltoides anterior","Serrato anterior","Tríceps braquial"],5.0,"wide-grip-push-ups-start.webp","wide-grip-push-ups-peak.webp",["Comienza en una plancha alta con las manos más separadas que el ancho de hombros.","Mantén el cuerpo en línea recta de la cabeza a los talones.","Baja el pecho hacia el suelo flexionando los codos.","Mantén el core activado y los glúteos contraídos.","Empuja de vuelta hasta extender los brazos.","Repite el número de repeticiones deseado."],["Mantén los codos a unos 45 grados respecto al torso.","Mantén una línea recta de la cabeza a los talones.","Baja hasta que el pecho quede cerca del suelo."]],["close-grip-push-ups","Flexiones con Agarre Cerrado","Una variante de flexión con las manos juntas que enfatiza el tríceps.","Pecho","Fuerza","Intermedio","Sin equipo",true,["Pectoral mayor","Tríceps braquial"],["Deltoides anterior","Serrato anterior"],5.0,"close-grip-push-ups-start.webp","close-grip-push-ups-peak.webp",["Adopta una posición de flexión con las manos directamente bajo los hombros.","Mantén los codos pegados a las costillas.","Baja el pecho hacia el suelo.","Empuja de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],["Lleva los codos hacia atrás, no hacia los lados.","Mantén el cuerpo rígido como una tabla durante todo el movimiento.","Baja despacio para mayor activación del tríceps."]],["clap-push-ups","Flexiones con Palmada","Una flexión pliométrica explosiva que desarrolla la potencia del pecho y las fibras musculares de contracción rápida.","Pecho","Fuerza","Avanzado","Sin equipo",true,["Pectoral mayor"],["Tríceps braquial"],7.0,"clap-push-ups-start.webp","clap-push-ups-peak.webp",["Comienza en la posición estándar de flexión.","Baja el pecho hacia el suelo.","Empuja hacia arriba de forma explosiva para que las manos despeguen del suelo.","Da una palmada y aterriza suavemente, volviendo a la posición inicial.","Repite."],["Aterriza con los codos ligeramente flexionados para absorber el impacto.","Asegúrate de tener suficiente fuerza en la parte superior del cuerpo antes de intentarlo."]],["diamond-push-ups","Flexiones en Diamante","Una flexión con las manos juntas formando un diamante con pulgares e índices, trasladando el énfasis a los tríceps.","Pecho","Fuerza","Intermedio","Sin equipo",true,["Pectoral mayor","Tríceps braquial"],["Deltoides anterior","Serrato anterior"],5.0,"diamond-push-ups-start.webp","diamond-push-ups-peak.webp",["Adopta la posición de flexión con las manos juntas formando un diamante.","Mantén los codos pegados a los costados.","Baja el pecho hacia las manos.","Empuja hacia arriba para extender los brazos.","Repite el número de repeticiones deseado."],["Lleva los codos hacia atrás pegados a los costados, sin abrirlos.","Mantén el cuerpo en una línea recta y rígida de la cabeza a los talones.","Baja con control hasta que el pecho llegue a las manos."]],["deficit-push-ups","Flexiones en Déficit","Una flexión de brazos con las manos sobre soportes elevados, que aumenta el rango de movimiento y el estiramiento del pectoral.","Pecho","Fuerza","Avanzado","Sin equipo",true,["Pectoral mayor"],["Deltoides anterior","Serrato anterior","Tríceps braquial"],5.0,"deficit-push-ups-start.webp","deficit-push-ups-peak.webp",["Coloca las manos en dos superficies elevadas como parallettes o bloques.","Adopta la posición de plancha con las manos bajo los hombros.","Baja el pecho por debajo del nivel de las manos.","Empuja hacia arriba para extender los brazos.","Repite el número de repeticiones deseado."],["Baja solo hasta donde tus hombros toleren el estiramiento.","Mantén el cuerpo en línea recta, sin hundir la cadera.","Progresa desde las flexiones normales antes de añadir déficit."]],["pike-push-ups","Flexiones en Pica","Una flexión realizada con las caderas elevadas en posición de pica, empujando en un ángulo pronunciado para cargar los hombros.","Hombro","Fuerza","Intermedio","Sin equipo",true,["Deltoides anterior","Deltoides lateral"],["Trapecio","Tríceps braquial"],5.0,"pike-push-ups-start.webp","pike-push-ups-peak.webp",["Comienza en posición de perro boca abajo con las caderas altas y las manos a la anchura de los hombros.","Acerca los pies a las manos.","Dobla los codos y baja la cabeza hacia el suelo.","Mantén las caderas altas durante todo el ejercicio.","Empuja hacia arriba hasta que los brazos queden completamente extendidos.","Repite el número de repeticiones deseado."],["Cuanto más altas las caderas, más trabajan los hombros.","Baja la cabeza hacia un punto ligeramente por delante de las manos.","Acerca los pies a las manos para progresar hacia las flexiones en pino."]],["handstand-push-ups","Flexiones en Pino","Un empuje invertido contra la pared, bajando la cabeza hacia el suelo y empujando de vuelta hasta el pino completo.","Hombro","Fuerza","Avanzado","Sin equipo",true,["Deltoides anterior","Tríceps braquial"],["Deltoides lateral","Recto abdominal","Trapecio"],5.0,"handstand-push-ups-start.webp","handstand-push-ups-peak.webp",["Sube a un pino contra la pared con las manos a la anchura de los hombros.","Contrae el core y mantén el cuerpo recto.","Baja la cabeza hacia el suelo flexionando los codos.","Detente justo antes de que la cabeza toque el suelo.","Empuja con las manos para volver al pino completo.","Repite el número de repeticiones deseado."],["Mantén los codos a unos 45 grados en lugar de abrirlos por completo.","Contrae el core para que la espalda no se arquee alejándose de la pared.","Progresa primero con flexiones pike y rangos parciales."]],["decline-push-up","Flexión Declinada","Una flexión con los pies elevados para aumentar la activación del pecho superior y los hombros.","Pecho","Fuerza","Intermedio","Sin equipo",true,["Pectoral mayor"],["Deltoides anterior","Tríceps braquial"],5.0,"decline-push-up-start.webp","decline-push-up-peak.webp",["Coloca los pies en una superficie elevada y las manos en el suelo.","Baja el pecho hacia el suelo de forma controlada.","Vuelve a empujar hasta la posición inicial.","Repite."],["Mantén el cuerpo en línea recta.","Cuanto mayor sea la elevación, más se trabaja el pecho superior."]],["isometric-neck-side","Flexión Lateral Isométrica de Cuello","Un ejercicio estático de cuello que usa la mano como resistencia contra la cabeza, trabajando el esternocleidomastoideo y los escalenos sin equipo.","Espalda","Fuerza","Principiante","Sin equipo",true,["Trapecio"],[],3.5,"isometric-neck-side-main.webp",null,["Siéntate o ponte de pie erguido. Coloca la palma de una mano en el lado de la cabeza, por encima de la oreja.","Empuja la cabeza contra la mano resistiendo por igual con la mano: la cabeza no se mueve.","Mantén la contracción isométrica de 5 a 10 segundos.","Suelta lentamente y repite en el mismo lado durante la serie.","Cambia de lado y repite."],["Ajusta la presión; es un 50 % de esfuerzo, no un pulso.","Mantén la mandíbula relajada y los hombros bajos."]],["dumbbell-side-bend","Flexión Lateral con Mancuerna","Un ejercicio de aislamiento de oblicuos de pie con mancuerna para desarrollar la fuerza lateral del core.","Core","Fuerza","Principiante","Mancuernas",false,["Oblicuos"],["Erectores espinales","Cuadrado lumbar","Transverso abdominal"],5.0,"dumbbell-side-bend-start.webp","dumbbell-side-bend-peak.webp",["Párate erguido sosteniendo una mancuerna a un lado.","Coloca la otra mano en la cadera o detrás de la cabeza.","Inclínate lateralmente hacia el lado de la mancuerna, bajándola por el muslo.","Vuelve a la posición erguida, luego inclínate al lado opuesto con los oblicuos.","Completa todas las repeticiones por lado."],["Evita inclinarte hacia adelante o atrás — muévete estrictamente de lado.","Usa un tempo controlado en ambas direcciones.","Mantén el peso cerca de la pierna durante todo el movimiento."]],["standing-side-bend","Flexión Lateral de Pie","Un estiramiento de pie que alarga los oblicuos y dorsales al estirar los brazos arriba e inclinarse a un lado.","Core","Estiramiento","Principiante","Sin equipo",true,["Oblicuos"],["Dorsal ancho","Cuadrado lumbar"],5.0,"standing-side-bend-main.webp",null,["Párate con los pies al ancho de cadera y sube ambos brazos.","Junta las manos y estírate hacia arriba.","Inclínate suavemente a un lado en una curva larga.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],["Mantén ambos pies fijos y las caderas estables.","Estírate hacia arriba y al lado en vez de solo dejarte caer."]],["standing-side-bend-flow","Flexión Lateral de Pie Alterna","Un flujo lateral de pie: los brazos se estiran por encima de la cabeza y el tronco se inclina de lado a lado con un ritmo controlado, alargando el costado sin sostener ninguna posición final.","Core","Estiramiento","Principiante","Sin equipo",true,["Oblicuos"],["Dorsal ancho","Cuadrado lumbar"],5.0,"standing-side-bend-flow-start.webp","standing-side-bend-flow-peak.webp",["Ponte de pie con los pies a la anchura de las caderas y estira ambos brazos por encima de la cabeza.","Inclina el tronco hacia un lado manteniendo los pies apoyados y las caderas niveladas.","Vuelve por el centro con las costillas alineadas sobre la pelvis.","Inclínate hacia el otro lado del mismo modo.","Sigue alternando las veces indicadas."],["Inclínate solo lateralmente: si el pecho rota, se convierte en un giro.","Mantén ambos talones apoyados para que el movimiento se quede en el tronco.","Muévete con la respiración en lugar de rebotar al final del recorrido."]],["pilates-side-bend","Flexión Lateral de Pilates","Un ejercicio lateral del tronco desde un apoyo de costado: las caderas se elevan y el brazo de arriba se estira por encima de la cabeza, curvando el cuerpo de lado sobre el brazo de apoyo.","Pierna","Fuerza","Intermedio","Sin equipo",true,["Glúteo medio","Oblicuos"],["Deltoides anterior","Transverso abdominal"],5.0,"pilates-side-bend-start.webp","pilates-side-bend-peak.webp",["Siéntate sobre una cadera con las piernas dobladas hacia un lado y la mano de apoyo en el suelo bajo el hombro.","Empuja con la mano y la pierna inferior para elevar las caderas del suelo.","Estira el brazo de arriba por encima de la cabeza para formar un arco largo desde la mano hasta los pies.","Baja las caderas de forma controlada hacia la colchoneta.","Completa las repeticiones y cambia de lado."],["Empuja el suelo para que el hombro de apoyo quede estable y alineado.","Alarga el brazo de arriba en lugar de dejarte caer hacia el lado.","Mantén el movimiento fluido: subir y bajar duran lo mismo."]],["plyo-push-up","Flexión Pliométrica","Una flexión explosiva en la que las manos despegan del suelo al subir, entrena potencia del tren superior.","Pecho","Pliometría","Intermedio","Sin equipo",true,["Pectoral mayor","Tríceps braquial"],["Deltoides anterior"],7.0,"clap-push-ups-start.webp","clap-push-ups-peak.webp",["Colócate en posición de flexión estándar, manos a la anchura de los hombros.","Baja con control hasta que el pecho casi toque el suelo.","Empuja explosivamente para que las manos despeguen del suelo.","Aterriza suave con los codos ligeramente flexionados.","Repite sin pausa el número de repeticiones indicado."],["Mantén el cuerpo en línea recta — sin doblar ni hundir.","Aterriza suave con los codos flexionados.","Apoya las rodillas si no puedes despegar limpiamente."]],["seated-forward-fold","Flexión Sentado hacia Adelante","Un estiramiento sentado para los isquiotibiales y la zona lumbar, inclinando el torso sobre las piernas estiradas.","Pierna","Estiramiento","Principiante","Sin equipo",true,["Isquiotibiales"],["Erectores espinales"],5.0,"seated-forward-fold-main.webp",null,["Siéntate en el suelo con ambas piernas estiradas al frente.","Mantén la espalda larga e inclínate desde las caderas.","Lleva las manos hacia los pies.","Mantén de 20 a 30 segundos, respirando de forma constante."],["Inicia con el pecho, no con la cabeza, para mantener la espalda larga.","Estira hasta una tensión leve, nunca hasta el dolor."]],["wide-legged-forward-fold","Flexión con Piernas Abiertas","Una flexión de pie desde una base amplia con las manos en el suelo, que alarga los isquiotibiales y la cara interna de los muslos mientras la columna cuelga larga.","Pierna","Estiramiento","Principiante","Sin equipo",true,["Aductores","Isquiotibiales"],["Erectores espinales","Gemelos"],5.0,"wide-legged-forward-fold-main.webp",null,["Ponte de pie con los pies muy separados y los bordes externos paralelos.","Apoya las manos en las caderas, eleva el pecho y bascula hacia delante desde las articulaciones de la cadera.","Lleva las manos al suelo bajo los hombros y deja que la cabeza cuelgue.","Mantén la flexión durante el tiempo indicado, desplazando ligeramente el peso hacia las puntas de los pies.","Devuelve las manos a las caderas y sube con la espalda plana."],["Deja una micro flexión en las rodillas para que la flexión venga de las caderas y no de la zona lumbar.","Mantén los pies paralelos; girarlos hacia fuera quita el estiramiento de la cara interna de los muslos.","Apoya las manos en bloques cuando el suelo quede lejos."]],["standing-forward-fold-to-half-lift","Flexión de Pie a Media Elevación","La articulación conocida como media elevación: desde una flexión de pie el pecho sube hasta dejar la espalda plana y la columna larga, y luego vuelve a plegarse. Enseña la diferencia entre una flexión redondeada y una bisagra con la columna larga.","Espalda","Estiramiento","Principiante","Sin equipo",true,["Erectores espinales","Isquiotibiales"],["Glúteo mayor"],5.0,"standing-forward-fold-to-half-lift-start.webp","standing-forward-fold-to-half-lift-peak.webp",["Ponte de pie con los pies a la anchura de las caderas y pliégate hacia delante desde las caderas.","Apoya las manos en las espinillas, en el suelo o en bloques.","Desliza las manos por las espinillas y eleva el pecho hasta dejar la espalda plana y la columna larga.","Vuelve a plegarte dejando que la cabeza y el cuello se relajen.","Sigue alternando entre ambas posiciones las veces indicadas."],["Deja una ligera flexión en las rodillas para que el movimiento venga de las caderas.","Sube a espalda plana en lugar de mirar hacia arriba; el cuello sigue a la columna.","Aleja los hombros de las orejas en la posición elevada."]],["standing-forward-fold","Flexión de Pie hacia Adelante","Un estiramiento de pie que alarga los isquiotibiales y la zona lumbar al inclinar el torso sobre las piernas estiradas.","Pierna","Estiramiento","Principiante","Sin equipo",true,["Isquiotibiales"],["Erectores espinales","Gemelos"],5.0,"standing-forward-fold-main.webp",null,["Párate erguido con los pies al ancho de cadera y las piernas estiradas.","Flexiónate desde las caderas y baja el torso hacia el suelo.","Deja que las manos y la cabeza cuelguen hacia los pies.","Mantén de 20 a 30 segundos, respirando de forma constante."],["Flexiona un poco las rodillas si sientes tensos los isquiotibiales.","Entra en el estiramiento lentamente, nunca rebotes."]],["ring-push-up","Flexión en Anillas","Una flexión sobre anillas de gimnasia, que exige más a los estabilizadores del pecho, hombros y core.","Pecho","Fuerza","Intermedio","Anillas",false,["Pectoral mayor","Tríceps braquial"],["Deltoides anterior","Serrato anterior"],6.0,"ring-push-up-start.webp","ring-push-up-peak.webp",["Coloca las anillas justo por encima del suelo.","Sujeta las anillas y adopta posición de plank con los brazos rectos.","Baja el pecho hacia las anillas, codos pegados al cuerpo.","Empuja arriba hasta extender los brazos.","Repite el número de repeticiones indicado."],["Gira las anillas hacia afuera arriba para activar más el pecho.","Activa el core — las anillas amplifican cualquier oscilación.","Apoya las rodillas para escalar la dificultad."]],["stability-ball-push-up-hands-on-ball","Flexión sobre pelota de estabilidad (manos en la pelota)","Una flexión inclinada realizada con ambas manos sobre una pelota de estabilidad y los pies en el suelo. La superficie inestable exige más al pecho, los hombros y los tríceps, mientras el core mantiene el cuerpo rígido.","Pecho","Fuerza","Intermedio","Pelota de estabilidad",false,["Pectoral mayor"],["Deltoides anterior","Recto abdominal","Serrato anterior","Tríceps braquial"],6.0,"stability-ball-push-up-hands-on-ball-start.webp","stability-ball-push-up-hands-on-ball-peak.webp",["Coloca ambas manos sobre una pelota de estabilidad y camina con los pies hacia atrás hasta una plancha con los brazos extendidos, el cuerpo en línea recta de la cabeza a los talones.","Activa el core y mantén la pelota firme bajo las manos.","Flexiona los codos para bajar el pecho hacia la pelota de forma controlada.","Empuja de nuevo hasta la extensión completa de los brazos sin dejar que la pelota ruede.","Repite las repeticiones deseadas."],["Mantén el cuerpo en una línea recta y rígida: no dejes que las caderas se hundan ni se eleven.","Muévete lento y con control; la inestabilidad de la pelota es lo que hace efectivo el ejercicio, así que resístela en lugar de combatirla con rapidez.","Coloca las manos algo más anchas que los hombros sobre la pelota y mantén los codos a unos 45 grados."]],["flutter-kicks","Flutter Kicks","Un ejercicio de core tumbado boca arriba alternando pequeñas patadas arriba y abajo mientras la zona lumbar permanece pegada al suelo.","Pierna","Fuerza","Intermedio","Sin equipo",true,["Flexores de cadera","Recto abdominal"],["Transverso abdominal"],5.0,"flutter-kicks-start.webp","flutter-kicks-peak.webp",["Túmbate boca arriba con las piernas extendidas.","Coloca las manos bajo los glúteos como apoyo.","Levanta ambas piernas unos centímetros del suelo.","Alterna las piernas arriba y abajo en un rango pequeño.","Mantén el core contraído y la zona lumbar presionada contra el suelo.","Continúa durante el tiempo o las repeticiones deseadas."],["Presiona la zona lumbar contra el suelo durante toda la serie.","Mantén las patadas pequeñas y constantes en lugar de grandes y descontroladas.","Eleva más las piernas si notas que la zona lumbar se arquea."]],["weighted-dips","Fondos Lastrados","Un fondo en paralelas con carga añadida — normalmente un disco colgado de un cinturón de lastre entre las piernas — para mantener el ejercicio en un rango de fuerza cuando los fondos con el propio peso ya resultan fáciles.","Pecho","Fuerza","Avanzado","Paralelas",false,["Pectoral mayor","Tríceps braquial"],["Deltoides anterior"],6.0,"weighted-dips-start.webp","weighted-dips-peak.webp",["Cuelga un disco del cinturón de lastre y ajústalo a la cintura de modo que el peso quede suelto entre las piernas.","Agarra las barras paralelas y súbete hasta la posición inicial con los brazos estirados y los pies separados del suelo.","Inclina ligeramente el torso hacia delante y baja el cuerpo flexionando los codos hasta que los hombros queden por debajo de ellos.","Empuja con las palmas para volver a subir hasta estirar los brazos, evitando que el disco colgante se balancee.","Repite el número de repeticiones deseado."],["Añade peso solo cuando hagas fondos limpios con el propio peso en todo el recorrido: saltos de 2,5 a 5 kg son suficientes, porque la carga se suma a tu propio peso corporal.","Mantén las piernas juntas y el core apretado para que el disco no empiece a balancearse; un peso que oscila estropea la parte baja de la repetición.","Mantén los hombros alejados de las orejas y detén el descenso si notas pinzamiento en la parte delantera del hombro."]],["crab-dips","Fondos de Cangrejo","Un ejercicio de tríceps en el suelo desde la mesa invertida: con las manos detrás de las caderas y el tronco elevado, los codos se flexionan y estiran para subir y bajar el cuerpo.","Tríceps","Fuerza","Intermedio","Sin equipo",true,["Tríceps braquial"],["Deltoides anterior","Glúteo mayor","Pectoral mayor"],5.0,"crab-dips-start.webp","crab-dips-peak.webp",["Siéntate con las rodillas flexionadas, los pies apoyados y las manos en el suelo detrás de ti, con los dedos hacia los talones.","Empuja con manos y pies y eleva las caderas hasta que el tronco quede a la altura de las rodillas.","Flexiona los codos hacia atrás para bajar las caderas hacia el suelo sin sentarte.","Empuja de nuevo hasta estirar los brazos, manteniendo las caderas elevadas.","Repite las veces indicadas y baja las caderas para terminar."],["Mantén los codos apuntando hacia atrás, sin abrirlos hacia los lados.","Sostén las caderas altas toda la serie; dejarlas caer convierte el ejercicio en un descanso.","Aleja más los pies para alargar la palanca y exigir más al tríceps."]],["ring-dips","Fondos en Anillas","Un fondo con el peso corporal desafiante realizado en anillas de gimnasia, que exige mayor estabilización que los fondos en barra.","Pecho","Fuerza","Avanzado","Anillas",false,["Pectoral mayor","Tríceps braquial"],["Deltoides anterior"],6.0,"ring-dips-start.webp","ring-dips-peak.webp",["Apóyate en las anillas con los brazos bloqueados.","Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.","Empuja hacia arriba hasta la posición inicial.","Repite."],["Mantén las anillas cerca del cuerpo.","Gira las anillas hacia afuera en la parte superior para mayor activación del pecho."]],["bench-dips","Fondos en Banco","Un ejercicio de fondos apoyado en un banco que trabaja principalmente el tríceps con el propio peso corporal.","Tríceps","Fuerza","Intermedio","Sin equipo",true,["Tríceps braquial"],["Deltoides anterior","Pectoral mayor"],5.0,"bench-dips-start.webp","bench-dips-peak.webp",["Siéntate en un banco y coloca las manos en el borde junto a las caderas.","Desliza las caderas fuera del banco con las piernas extendidas.","Baja el cuerpo flexionando los codos hasta 90 grados.","Empuja con las palmas para volver a la posición inicial.","Repite el número de repeticiones deseado."],["Mantén la espalda cerca del banco durante todo el recorrido.","No dejes que los hombros se hundan hacia las orejas.","Flexiona las rodillas si necesitas una versión más fácil."]],["straight-bar-dips","Fondos en Barra Recta","Una variante de fondos realizada colgando de una barra recta de dominadas en lugar de barras paralelas de fondos, empujando el cuerpo hacia arriba en un rango de movimiento reducido.","Pecho","Fuerza","Intermedio","Barra de dominadas",false,["Pectoral mayor"],["Tríceps braquial"],6.0,"straight-bar-dips-start.webp","straight-bar-dips-peak.webp",["Agarra una barra recta por encima de la cabeza con ambas manos, colgando con los brazos extendidos y los pies fuera del suelo.","Manteniendo el cuerpo recto, empuja hacia abajo a través de la barra para elevar los hombros y el pecho.","Haz una breve pausa en la parte superior del movimiento.","Baja con control de vuelta a la posición colgante.","Repite el número deseado de repeticiones."],["Mantén el movimiento controlado -- es un rango de movimiento pequeño comparado con los fondos en barras paralelas.","Contrae el core para evitar que el cuerpo se balancee.","Esta posición de muñeca y hombro es más exigente que los fondos estándar -- aumenta el volumen gradualmente."]],["assisted-dips","Fondos en Máquina Asistida","Un ejercicio de fondos en máquina asistida que descarga parte del peso corporal para fortalecer pecho y tríceps.","Pecho","Fuerza","Principiante","Máquina de fondos",false,["Pectoral mayor","Tríceps braquial"],["Deltoides anterior","Romboides"],6.0,"assisted-dips-start.webp","assisted-dips-peak.webp",["Sube a la máquina de fondos asistidos con las rodillas en el pad.","Agarra las barras paralelas y soporta tu peso con los brazos extendidos.","Baja el cuerpo flexionando los codos hasta que los hombros queden por debajo de los codos.","Empuja de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],["Baja de forma controlada, sin rebotar en la parte inferior.","Mantén los hombros alejados de las orejas durante todo el recorrido.","Reduce la asistencia de forma gradual a medida que ganes fuerza."]],["reverse-plank-dips","Fondos en Plancha Invertida","Fondos de tríceps desde una plancha invertida con las piernas estiradas: las piernas permanecen largas y las caderas altas mientras los codos se flexionan y estiran.","Tríceps","Fuerza","Intermedio","Sin equipo",true,["Tríceps braquial"],["Erectores espinales","Glúteo mayor","Deltoides posterior"],5.0,"reverse-plank-dips-start.webp","reverse-plank-dips-peak.webp",["Siéntate con las piernas estiradas y las manos en el suelo detrás de las caderas, con los dedos hacia delante.","Empuja con manos y talones y eleva las caderas a una plancha invertida con las piernas estiradas.","Flexiona los codos hacia atrás y baja un poco las caderas hacia el suelo.","Empuja de nuevo hasta bloquear los brazos, manteniendo las caderas altas.","Repite las veces indicadas."],["Mantén las caderas elevadas abajo; sentarte entre repeticiones quita la carga.","Lleva los codos rectos hacia atrás en lugar de abrirlos hacia fuera.","Flexiona las rodillas si la versión con piernas estiradas exige demasiado a los isquiotibiales."]],["dips","Fondos para Pecho","Un ejercicio compuesto de peso corporal que trabaja el pecho inferior y los tríceps.","Pecho","Fuerza","Intermedio","Paralelas",false,["Pectoral mayor","Tríceps braquial"],["Deltoides anterior"],6.0,"dips-start.webp","dips-peak.webp",["Agarra las barras paralelas y súbete a la posición superior con los brazos extendidos.","Inclina el torso ligeramente hacia adelante.","Baja el cuerpo doblando los codos hasta que los hombros queden por debajo de los codos.","Vuelve a empujar hasta la posición inicial.","Repite."],["Acentúa la inclinación del torso si quieres más trabajo de pecho.","Detén la bajada si notas molestia en el hombro.","Evita encoger los hombros hacia las orejas al empujar."]],["front-lever","Front Lever","Una posición estática avanzada en barra donde el cuerpo se mantiene horizontal con el pecho hacia arriba, requiriendo fuerza de tracción en dorsales y core.","Espalda","Fuerza","Avanzado","Barra de dominadas",false,["Dorsal ancho","Pectoral mayor"],["Deltoides anterior","Bíceps braquial","Erectores espinales","Recto abdominal"],6.0,"front-lever-main.webp",null,["Agarra la barra con agarre prono y cuelga.","Lleva las rodillas al pecho y eleva las caderas hacia arriba, rotando hasta que el pecho mire al techo.","Extiende el cuerpo horizontalmente con brazos rectos y pecho apuntando hacia arriba.","Mantén el cuerpo rígido y paralelo al suelo.","Aguanta el tiempo deseado, luego flexiona y baja de forma controlada."],["Progresa con variantes de rodillas flexionadas y piernas abiertas antes del hold completo.","Aprieta core y glúteos para evitar que las caderas caigan.","Mantén los hombros activamente deprimidos, alejados de las orejas."]],["cat-cow","Gato-Vaca","Un flujo a cuatro apoyos que alterna entre redondear la columna hacia el techo y dejarla descender mientras el pecho se abre, moviendo cada segmento de la espalda por su recorrido.","Espalda","Estiramiento","Principiante","Sin equipo",true,["Erectores espinales","Recto abdominal"],["Transverso abdominal","Trapecio"],5.0,"cat-cow-main.webp",null,["Colócate a cuatro apoyos con las manos bajo los hombros y las rodillas bajo las caderas.","Exhala y redondea la columna hacia el techo, metiendo el coxis y dejando caer la cabeza.","Inhala e inviértelo: deja descender el abdomen, eleva el pecho y el coxis y mira ligeramente al frente.","Alterna entre ambas formas despacio, una respiración por posición.","Termina en columna neutra y siéntate sobre los talones."],["Deja que la respiración marque el ritmo en lugar de correr entre las dos posiciones.","Presiona las manos por igual para que los hombros no se hundan hacia el suelo.","Mueve toda la columna, incluido el cuello, en lugar de doblar solo la zona lumbar."]],["seated-spinal-twist","Giro Espinal Sentado","Una rotación sentada que estira los oblicuos, la espalda media y los glúteos girando hacia una rodilla flexionada.","Espalda","Estiramiento","Principiante","Sin equipo",true,["Erectores espinales","Oblicuos"],["Glúteo mayor"],5.0,"seated-spinal-twist-main.webp",null,["Siéntate con una pierna estirada y cruza el otro pie por encima.","Apoya el codo opuesto contra la parte externa de la rodilla flexionada.","Gira el torso hacia la rodilla flexionada y mira sobre el hombro.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],["Siéntate erguido y alarga la columna antes de girar.","Gira desde la espalda media, no desde la lumbar."]],["supine-spinal-twist","Giro Espinal Tumbado","Un giro tumbado que estira la zona lumbar, los glúteos y los oblicuos al cruzar una rodilla flexionada sobre el cuerpo.","Espalda","Estiramiento","Principiante","Sin equipo",true,["Erectores espinales","Oblicuos"],["Glúteo mayor"],5.0,"supine-spinal-twist-main.webp",null,["Acuéstate boca arriba y lleva una rodilla al pecho.","Guía esa rodilla cruzando el cuerpo hacia el suelo.","Extiende los brazos y gira la cabeza hacia el lado contrario.","Mantén de 20 a 30 segundos, respirando de forma constante.","Cambia de lado y repite."],["Mantén ambos hombros en el suelo.","Relájate y sigue respirando todo el tiempo."]],["russian-twist","Giro Ruso","Un ejercicio de core rotacional que trabaja los oblicuos.","Core","Fuerza","Principiante","Sin equipo",true,["Oblicuos","Recto abdominal"],["Flexores de cadera"],3.5,"russian-twist-start.webp","russian-twist-peak.webp",["Siéntate en el suelo con las rodillas flexionadas e inclínate ligeramente hacia atrás.","Junta las manos o sostén un peso a la altura del pecho.","Rota el torso hacia un lado, luego hacia el otro.","Mantén el core apretado en todo momento.","Repite."],["Gira desde el torso, no solo con los brazos.","Mantén la espalda recta aunque estés ligeramente reclinado.","Hazlo lento y controlado; la velocidad resta trabajo a los oblicuos."]],["kettlebell-russian-twist","Giro ruso con pesa rusa","Un Russian Twist con pesa rusa realizado sentado con los pies en el aire, que entrena los oblicuos mediante rotaciones del torso.","Core","Fuerza","Intermedio","Kettlebell",false,["Oblicuos"],["Flexores de cadera","Recto abdominal"],6.0,"kettlebell-russian-twist-start.webp","kettlebell-russian-twist-peak.webp",["Siéntate en el suelo con las rodillas flexionadas y los pies levantados del suelo.","Sostén una pesa rusa con ambas manos frente al pecho.","Inclínate ligeramente hacia atrás para activar el core.","Rota el torso hacia un lado llevando la pesa rusa junto a la cadera.","Rota hacia el lado opuesto en un movimiento controlado.","Repite el número deseado de repeticiones."],["Gira los hombros, no solo los brazos.","Mantén la espalda recta aunque el torso esté inclinado hacia atrás.","Apoya los pies en el suelo si te cuesta mantener el equilibrio."]],["battle-rope-double-slam","Golpe Doble con Cuerdas de Batalla","Un ejercicio de acondicionamiento en el que ambos extremos de la cuerda suben y se golpean contra el suelo a la vez, generando una gran onda por repetición en lugar de las ondas alternas del ejercicio clásico.","Cuerpo completo","Cardio","Intermedio","Cuerda de batalla",false,["Deltoides anterior","Dorsal ancho"],["Flexores del antebrazo","Glúteo mayor","Oblicuos","Cuádriceps","Recto abdominal","Trapecio"],10.3,"battle-rope-double-slam-start.webp","battle-rope-double-slam-peak.webp",["Toma un extremo de la cuerda en cada mano y colócate frente al anclaje, lo bastante atrás como para que las cuerdas queden algo destensadas.","Separa los pies algo más que la anchura de las caderas y baja a una sentadilla de cuarto, con el pecho alto.","Sube ambos brazos a la vez, dejando que las cuerdas se eleven por delante mientras extiendes la cadera.","Golpea ambos extremos contra el suelo al mismo tiempo, flexionando por la cadera y empujando desde los dorsales.","Aprovecha el rebote para encadenar el siguiente golpe, manteniendo ambos brazos al unísono en lugar de alternarlos.","Sigue golpeando el tiempo o las repeticiones deseadas."],["Los dos brazos se mueven juntos — en cuanto empiezan a alternarse estás haciendo el ejercicio de ondas clásico, que es otro ejercicio distinto.","Impulsa el golpe con la cadera y los dorsales en vez de con los brazos, o los hombros se agotarán mucho antes que los pulmones.","Colócate a la distancia correcta del anclaje: demasiado cerca la cuerda queda floja, demasiado lejos no consigues meterle onda."]],["medicine-ball-slam","Golpe con Balón Medicinal","Un ejercicio explosivo de cuerpo completo donde se levanta un slam ball sobre la cabeza y se lanza contra el suelo con la máxima fuerza.","Core","Fuerza","Principiante","Slam ball",false,["Recto abdominal"],["Glúteo mayor","Dorsal ancho","Oblicuos"],6.0,"medicine-ball-slam-start.webp","medicine-ball-slam-peak.webp",["Párate con los pies a la anchura de los hombros sosteniendo un slam ball frente a las caderas.","Levanta el balón sobre la cabeza extendiendo las caderas y alargándote hacia arriba.","Golpea el balón contra el suelo entre los pies con fuerza, contrayendo el core.","Atrapa el balón en el rebote o recógelo del suelo.","Repite el número de repeticiones recomendado."],["Usa un slam ball de rebote suave, no un balón medicinal tradicional: los balones normales pueden rebotar hacia la cara.","Termina con todo el cuerpo: es un swing completo, no solo un lanzamiento de brazos."]],["warrior-one","Guerrero I","Una postura en paso largo con el pie trasero apoyado en diagonal, la rodilla delantera flexionada y los brazos arriba, con las caderas mirando al frente.","Pierna","Fuerza","Intermedio","Sin equipo",true,["Glúteo mayor","Cuádriceps"],["Deltoides anterior","Erectores espinales"],5.0,"warrior-one-main.webp",null,["Lleva un pie atrás y gíralo unos cuarenta y cinco grados, apoyando toda la planta.","Flexiona la rodilla delantera hasta que quede sobre el tobillo y mantén la pierna trasera estirada.","Lleva ambas caderas hacia el frente de la esterilla y eleva los brazos por encima de la cabeza.","Mantén la posición durante el tiempo indicado, con las costillas cerradas y el pecho alto.","Junta los pies y repite del otro lado."],["Separa los pies lateralmente para que ambas caderas miren al frente sin forzar la rodilla trasera.","Presiona el borde externo del pie trasero para mantener la base estable.","Separa los brazos a la anchura de los hombros si juntar las palmas te arquea la zona lumbar."]],["warrior-two","Guerrero II","Una postura de base amplia con la rodilla delantera flexionada, las caderas abiertas al lado y los brazos extendidos a la altura de los hombros.","Pierna","Fuerza","Intermedio","Sin equipo",true,["Glúteo medio","Cuádriceps"],["Aductores","Deltoides lateral"],5.0,"warrior-two-main.webp",null,["Sepárate en una base amplia con el pie delantero girado noventa grados y el trasero algo hacia dentro.","Flexiona la rodilla delantera hasta que quede sobre el tobillo y apunte hacia los dedos centrales.","Abre las caderas y el pecho hacia el lado y extiende los brazos paralelos al suelo.","Mantén la posición durante el tiempo indicado, con la mirada sobre la mano delantera.","Estira la pierna delantera y repite del otro lado."],["Evita que la rodilla delantera caiga hacia dentro; empújala hacia el lado del dedo meñique.","Alinea los hombros sobre las caderas en lugar de inclinarte hacia la pierna delantera.","Acorta la base si el muslo delantero no puede acercarse a la paralela."]],["warrior-three","Guerrero III","Un equilibrio sobre una pierna con el torso y la pierna elevada paralelos al suelo, formando una línea larga desde las yemas de los dedos hasta el talón elevado.","Pierna","Fuerza","Intermedio","Sin equipo",true,["Glúteo mayor","Isquiotibiales"],["Erectores espinales","Glúteo medio"],5.0,"warrior-three-main.webp",null,["Ponte de pie sobre una pierna con la rodilla blanda y las caderas niveladas.","Bascula hacia delante desde las caderas mientras la otra pierna se eleva por detrás.","Continúa hasta que el torso y la pierna elevada queden aproximadamente paralelos al suelo.","Estira los brazos hacia delante, junto al cuerpo o hacia los lados, y mantén durante el tiempo indicado.","Baja la pierna y repite del otro lado."],["Evita que la cadera elevada se abra hacia arriba; ambas deben mirar al suelo.","Flexiona el pie elevado y empuja el talón hacia atrás para mantener la pierna activa.","Apoya las manos en bloques o en una pared mientras construyes el equilibrio."]],["hack-squat","Hack Squat","Un ejercicio guiado en la máquina hack squat que trabaja principalmente los cuádriceps mediante un patrón de sentadilla controlado sobre el trineo.","Pierna","Fuerza","Intermedio","Máquina hack squat",false,["Glúteo mayor","Cuádriceps"],["Gemelos","Isquiotibiales"],6.0,"hack-squat-start.webp","hack-squat-peak.webp",["Carga la máquina hack squat y colócate con la espalda y los hombros contra los almohadillados.","Sitúa los pies a la anchura de los hombros sobre la plataforma con los pies ligeramente girados hacia fuera.","Suelta los asideros de seguridad y baja el trineo flexionando rodillas y caderas.","Desciende hasta que los muslos estén al menos paralelos a la plataforma.","Empuja con los talones para extender las piernas y devolver el trineo a la posición inicial.","Vuelve a enganchar los asideros de seguridad al terminar la serie."],["Mantén la zona lumbar pegada al almohadillado durante todo el movimiento.","Colocar los pies más arriba en la plataforma desplaza el énfasis hacia glúteos e isquiotibiales.","Controla la bajada; no te impulses desde el punto más bajo."]],["kettlebell-halo","Halo con pesa rusa","Un ejercicio de movilidad de hombros donde se hace girar una pesa rusa alrededor de la cabeza. Calienta el manguito rotador, la columna torácica y la cintura escapular con carga mínima.","Hombro","Fuerza","Principiante","Kettlebell",false,["Deltoides lateral"],["Deltoides posterior","Trapecio"],5.0,"kettlebell-halo-start.webp","kettlebell-halo-peak.webp",["Párate erguido con el core contraído, sosteniendo una pesa rusa ligera por las asas (boca abajo) a la altura del pecho.","Sube la campana a un lado de la cabeza y hazla pasar por detrás en un círculo suave.","Tráela de vuelta a la posición inicial frente a tu cara.","Invierte la dirección cada pocas repeticiones.","Repite el número recomendado de repeticiones o tiempo."],["Solo peso ligero — esto es movilidad, no fuerza.","Mantén la cabeza quieta; la campana gira alrededor, no la cabeza.","Si la campana se aleja, reduce el círculo — órbita ajustada, cerca del cráneo."]],["banded-fire-hydrant","Hidrante de Fuego con Banda","Este ejercicio de aislamiento utiliza una banda de resistencia para fortalecer el glúteo medio y mayor, mejorando la abducción y estabilidad de la cadera.","Pierna","Fuerza","Principiante","Banda circular",false,["Glúteo medio"],["Glúteo mayor"],5.0,"banded-fire-hydrant-start.webp","banded-fire-hydrant-peak.webp",["Coloca una banda de resistencia justo por encima de tus rodillas y ponte en posición de cuadrupedia, manos bajo los hombros y rodillas bajo las caderas.","Mantén tu core activado y la espalda recta, conservando una columna vertebral neutra durante todo el movimiento.","Levanta lentamente una rodilla hacia un lado, manteniendo la rodilla flexionada a 90 grados, hasta que tu muslo esté paralelo al suelo.","Sostén brevemente en la parte superior, contrayendo el glúteo, luego baja la pierna de forma controlada a la posición inicial.","Completa todas las repeticiones de un lado antes de cambiar al otro lado."],["Concéntrate en un movimiento controlado; evita usar el impulso para levantar la pierna.","Mantén tus caderas estables y evita que tu torso rote o se incline.","Asegúrate de que la banda permanezca tensa durante todo el rango de movimiento."]],["smith-machine-hip-thrust","Hip Thrust en Máquina Smith","Un empuje de cadera con la barra en las guías de la máquina Smith, de modo que la carga recorre una línea vertical fija sobre las caderas mientras los hombros quedan apoyados en un banco.","Pierna","Fuerza","Principiante","Máquina Smith",false,["Glúteo mayor","Glúteo medio"],["Isquiotibiales"],6.0,"smith-machine-hip-thrust-start.webp","smith-machine-hip-thrust-peak.webp",["Coloca un banco plano dentro de la máquina Smith, paralelo a la barra y situado de forma que la barra quede sobre el pliegue de tu cadera.","Baja la barra lo suficiente para poder pasar por debajo sentado en el suelo, y apoya la parte alta de la espalda en el banco.","Rueda la barra sobre las caderas, ponle una almohadilla si la necesitas y desengánchala, con los pies planos y a la anchura de las caderas.","Empuja con los talones y extiende las caderas hasta que muslos y torso formen una línea recta, apretando los glúteos arriba.","Baja las caderas de forma controlada hasta quedar justo por encima del suelo y repite el número de repeticiones deseado."],["Alinea el banco antes de cargar la barra. La barra solo sube y baja en vertical, así que si el banco está desplazado la barra acaba sobre el abdomen o los muslos, y a mitad de serie no hay forma de corregirlo.","Pon los topes de seguridad donde queda la barra al final del recorrido. Salir de debajo de una barra Smith cargada estando en el suelo es incómodo, y con los topes deja de ser un problema.","Mira a un punto por delante de ti en lugar de al techo. Mantener la barbilla recogida evita que el movimiento acabe en un arqueo lumbar al bloquear arriba."]],["hip-thrust","Hip thrust con barra","Un ejercicio compuesto para glúteos que utiliza una barra apoyada sobre las caderas.","Pierna","Fuerza","Intermedio","Barra",false,["Glúteo mayor","Glúteo medio"],["Isquiotibiales"],6.0,"hip-thrust-start.webp","hip-thrust-peak.webp",["Siéntate en el suelo con la parte superior de la espalda contra un banco y la barra sobre las caderas.","Empuja las caderas hacia arriba hasta que los muslos queden paralelos al suelo.","Aprieta los glúteos en la parte superior.","Baja las caderas de nuevo con control.","Repite."],["Mantén la barbilla recogida y las costillas abajo.","Empuja a través de los talones, no de las puntas.","Evita arquear la zona lumbar en la parte alta."]],["human-flag","Human Flag","Un sostén isométrico avanzado de calistenia con el cuerpo horizontal sobre un poste vertical, paralelo al suelo.","Espalda","Fuerza","Avanzado","Barra de dominadas",false,["Dorsal ancho","Oblicuos"],["Deltoides anterior","Glúteo mayor","Pectoral mayor","Recto abdominal","Tríceps braquial"],6.0,"human-flag-main.webp",null,["Ponte de pie cerca de un poste vertical resistente.","Agarra el poste arriba con la mano superior (en pronación) y abajo con la mano inferior (en supinación).","Impulsa las piernas hacia arriba y afuera mientras empujas con fuerza el brazo inferior contra el poste.","Extiende el cuerpo en horizontal hasta formar una línea recta paralela al suelo.","Mantén la posición con el cuerpo rígido durante el tiempo objetivo.","Baja de forma controlada."],["Llega a la bandera completa pasando antes por progresiones agrupada y en straddle.","El brazo inferior empuja y el superior tira; juntos equilibran la palanca.","Activa con fuerza dorsales, oblicuos y glúteos para mantenerte rígido."]],["behind-the-neck-lat-pulldown","Jalón al Cuello Detrás de la Cabeza","Un jalón al dorsal con agarre ancho llevado detrás de la cabeza, que trabaja la parte superior del dorsal y los trapecios: requiere movilidad de hombro completa sobre la cabeza.","Espalda","Fuerza","Avanzado","Máquina de jalón al pecho",false,["Dorsal ancho"],["Deltoides posterior","Romboides","Trapecio"],6.0,"behind-the-neck-lat-pulldown-start.webp","behind-the-neck-lat-pulldown-peak.webp",["Siéntate en la máquina de jalón con los muslos asegurados bajo el pad.","Agarra la barra con un agarre ancho prono, más ancho que la anchura de los hombros.","Mantén el torso erguido e inclina la barbilla ligeramente hacia adelante.","Tira de la barra hacia abajo detrás de la cabeza hasta que toque la base del cuello.","Vuelve de forma controlada al estiramiento completo sobre la cabeza.","Repite el número de repeticiones recomendado."],["Solo realiza este ejercicio si tienes movilidad de hombro completa y sin dolor sobre la cabeza.","Usa una carga moderada: no es un levantamiento de fuerza, es un accesorio de hipertrofia."]],["lat-pulldown","Jalón al Pecho","Un ejercicio en máquina de polea que trabaja el dorsal ancho.","Espalda","Fuerza","Principiante","Polea",false,["Dorsal ancho"],["Bíceps braquial","Deltoides posterior","Romboides"],6.0,"lat-pulldown-start.webp","lat-pulldown-peak.webp",["Siéntate en la máquina de jalón con los muslos sujetos bajo los rodillos.","Agarra la barra ancha con un agarre en pronación.","Jala la barra hasta la parte superior del pecho apretando los dorsales.","Regresa la barra lentamente a la posición inicial.","Repite."],["Inicia el tirón bajando los omóplatos, no doblando los codos.","Evita balancear el torso para mover el peso.","Dirige los codos hacia abajo y atrás, no hacia fuera."]],["reverse-grip-lat-pulldown","Jalón al Pecho Agarre Supino","Una variante del jalón al pecho con agarre supino que aumenta la participación del bíceps.","Bíceps","Fuerza","Intermedio","Polea",false,["Bíceps braquial","Dorsal ancho"],["Deltoides posterior","Romboides"],6.0,"reverse-grip-lat-pulldown-start.webp","reverse-grip-lat-pulldown-peak.webp",["Coloca una barra recta en una máquina de jalón al pecho.","Sujeta la barra con agarre supino, al ancho de los hombros.","Siéntate y asegura tus muslos bajo la almohadilla.","Tira de la barra hacia la parte superior del pecho.","Contrae el dorsal y el bíceps en la parte baja.","Vuelve la barra a la posición inicial con control.","Repite el número de repeticiones deseado."],["Mantén el pecho erguido y evita inclinarte demasiado hacia atrás.","Tira con los codos, no solo con las manos.","Contrae el dorsal en la parte baja del movimiento."]],["close-grip-lat-pulldown","Jalón al Pecho con Agarre Cerrado","Una variante del jalón al pecho con agarre cerrado y paralelo que enfatiza la parte baja del dorsal y el bíceps.","Espalda","Fuerza","Intermedio","Polea",false,["Dorsal ancho"],["Bíceps braquial","Braquial anterior","Deltoides posterior","Romboides"],6.0,"close-grip-lat-pulldown-start.webp","close-grip-lat-pulldown-peak.webp",["Siéntate en una máquina de jalón al pecho y asegura tus muslos bajo la almohadilla.","Sujeta el agarre cerrado con las palmas enfrentadas.","Tira de la barra hacia la parte superior del pecho.","Contrae el dorsal en la parte baja.","Vuelve con control y repite."],["Inclínate hacia atrás solo ligeramente, no en exceso.","Evita usar impulso para bajar la barra.","Lleva los codos hacia abajo y atrás, no solo las manos."]],["v-bar-lat-pulldown","Jalón al Pecho con Barra en V","Un jalón con agarre neutro realizado con una barra en V estrecha, maximizando el estiramiento del dorsal y permitiendo una contracción más profunda.","Espalda","Fuerza","Principiante","Máquina de jalón al pecho",false,["Dorsal ancho"],["Bíceps braquial","Romboides","Trapecio"],6.0,"v-bar-lat-pulldown-start.webp","v-bar-lat-pulldown-peak.webp",["Coloca una barra en V (mango doble-D) en el cable de jalón al pecho.","Siéntate con los muslos asegurados bajo el pad y agarra el mango con las palmas enfrentadas.","Comienza con los brazos completamente extendidos por encima de la cabeza.","Tira del mango hacia el esternón empujando los codos hacia abajo y ligeramente hacia atrás.","Aprieta los dorsales en la posición inferior y sube lentamente de forma controlada.","Repite el número de repeticiones recomendado."],["El agarre neutro es más suave con los hombros que los agarres en pronación o supinación.","Imagina que acercas las costillas hacia las caderas: piensa en los dorsales, no en los brazos."]],["one-arm-lat-pulldown","Jalón al Pecho con Un Brazo","Un jalón en cable unilateral con manija individual que trabaja el dorsal ancho permitiendo mayor rango de movimiento y corrección de desequilibrios.","Espalda","Fuerza","Intermedio","Polea",false,["Dorsal ancho"],["Bíceps braquial","Deltoides posterior","Romboides"],6.0,"one-arm-lat-pulldown-start.webp","one-arm-lat-pulldown-peak.webp",["Sujeta una manija individual al jalón de cable y siéntate con los muslos asegurados bajo el soporte.","Agarra la manija con una mano, brazo completamente extendido.","Tira de la manija hacia tu hombro llevando el codo hacia la cadera.","Pausa brevemente en la contracción máxima, luego vuelve con control.","Completa todas las repeticiones en un lado antes de cambiar."],["Inclínate ligeramente alejándote del cable para maximizar el estiramiento del dorsal arriba.","Tira con el codo, no con la mano, para mantener el dorsal activado.","Controla la fase excéntrica para maximizar la tensión en el dorsal durante todo el rango."]],["straight-arm-pulldown","Jalón con Brazos Rectos","Un ejercicio de aislamiento para los dorsales usando cable con los brazos rectos.","Espalda","Fuerza","Intermedio","Polea",false,["Dorsal ancho"],["Deltoides posterior","Tríceps braquial"],5.0,"straight-arm-pulldown-start.webp","straight-arm-pulldown-peak.webp",["Párate frente a una máquina de cable con una barra recta enganchada a la polea alta.","Con los brazos casi rectos, empuja la barra hacia abajo en un arco hacia los muslos.","Aprieta los dorsales en la parte inferior.","Devuelve la barra lentamente a la posición inicial.","Repite."],["Mantén los brazos casi rectos durante todo el movimiento.","Lleva la barra hacia los muslos describiendo un arco.","Aprieta los dorsales en la parte baja del recorrido."]],["tricep-pushdown","Jalón de Tríceps en Cable","Un ejercicio de aislamiento para los tríceps usando una máquina de cable.","Tríceps","Fuerza","Principiante","Polea",false,["Tríceps braquial"],[],5.0,"tricep-pushdown-start.webp","tricep-pushdown-peak.webp",["Párate frente a una máquina de cable con un accesorio de barra recta.","Agarra la barra y pega los codos a los costados.","Empuja la barra hacia abajo hasta que los brazos estén completamente extendidos.","Regresa lentamente a la posición inicial.","Repite."],["Mantén el torso erguido.","Solo deben moverse los antebrazos."]],["kettlebell-sumo-high-pull","Jalón sumo al mentón con pesa rusa","Un jalón con pesa rusa desde el suelo hasta la altura del mentón con postura amplia, combinando una bisagra con un remo en pie para desarrollar el trapecio superior de forma explosiva.","Pierna","Fuerza","Intermedio","Kettlebell",false,["Aductores","Deltoides lateral","Trapecio"],["Glúteo mayor","Isquiotibiales","Deltoides posterior"],6.0,"kettlebell-sumo-high-pull-start.webp","kettlebell-sumo-high-pull-peak.webp",["Párate con los pies más anchos que los hombros, los dedos ligeramente girados hacia afuera y una pesa rusa en el suelo entre los pies.","Bisagra hacia abajo y agarra el asa con ambas manos.","Empuja con los pies y extiende las caderas de forma explosiva para jalar la pesa rusa hacia arriba.","Al subir, lleva los codos hacia arriba y afuera hasta que el asa alcance la altura del mentón.","Baja la pesa rusa de vuelta entre las piernas con control.","Repite el número recomendado de repeticiones."],["Impulsa primero con las caderas; los brazos terminan el movimiento.","Mantén los codos más altos que las manos en la parte superior — piensa: ancho y alto, no estrecho."]],["jefferson-curl","Jefferson curl","Un ejercicio de flexión espinal con carga: de pie y con un peso ligero, redondeas la columna vértebra a vértebra y la vuelves a apilar, desarrollando control segmentario y flexibilidad de isquiotibiales y erectores bajo carga.","Espalda","Fuerza","Intermedio","Mancuernas",false,["Erectores espinales","Isquiotibiales"],["Glúteo mayor"],6.0,"jefferson-curl-start.webp","jefferson-curl-peak.webp",["Ponte de pie sujetando una mancuerna ligera con los brazos estirados, pies aproximadamente al ancho de las caderas.","Mete la barbilla y empieza a redondear la columna desde arriba, vértebra a vértebra.","Baja despacio dejando colgar el peso y manteniendo las piernas casi rectas.","Llega abajo con la espalda totalmente redondeada y un estiramiento en los isquiotibiales.","Invierte el movimiento, reapilando la columna de abajo hacia arriba hasta ponerte de pie."],["Usa un peso muy ligero: es un ejercicio de movilidad controlado, no un levantamiento pesado.","Redondea segmento a segmento; no bisagres desde la cadera como en un peso muerto rígido.","Muévete despacio y nunca rebotes abajo."]],["double-kettlebell-jerk","Jerk con Dos Pesas Rusas","Un levantamiento por encima de la cabeza que utiliza un doble impulso de piernas para elevar dos pesas rusas desde el rack hasta el bloqueo, el movimiento emblema del deporte de pesas rusas.","Hombro","Fuerza","Avanzado","Kettlebell",false,["Deltoides anterior","Cuádriceps"],["Glúteo mayor","Trapecio","Tríceps braquial"],8.0,"double-kettlebell-jerk-start.webp","double-kettlebell-jerk-peak.webp",["Comienza con dos pesas rusas en rack sobre los hombros, con los codos apoyados sobre las caderas.","Realiza una pequeña flexión de rodillas y luego extiende las piernas de forma explosiva para impulsar las pesas hacia arriba.","Cuando suban, realiza una segunda flexión de rodillas por debajo de ellas.","Recibe las pesas rusas por encima de la cabeza con los brazos bloqueados y ponte completamente de pie.","Bájalas de vuelta al rack de forma controlada y repite."],["El jerk tiene dos impulsos, no uno — el segundo impulso es el que te permite bloquear con los brazos relajados.","Respira en cada repetición; el hold es una habilidad aparte."]],["split-jerk","Jerk con Tijera","Un levantamiento por encima de la cabeza que impulsa la barra con una flexión de piernas y la recibe en posición de tijera con los brazos bloqueados.","Cuerpo completo","Halterofilia","Intermedio","Barra",false,["Deltoides anterior","Cuádriceps"],["Glúteo mayor","Trapecio","Tríceps braquial"],8.0,"split-jerk-start.webp","split-jerk-peak.webp",["Sostén la barra en el rack frontal con los codos altos.","Baja recto doblando ligeramente las rodillas.","Impulsa la barra por encima de la cabeza explosivamente con piernas y brazos.","Abre los pies hacia adelante y hacia atrás mientras la barra se bloquea.","Levántate juntando los pies bajo la barra.","Baja la barra y repite."],["Flexiona recto hacia abajo en lugar de inclinar el torso hacia delante.","Separa los pies adelante y atrás mientras la barra se bloquea.","Al recuperarte, lleva primero el pie delantero hacia atrás."]],["push-jerk","Jerk de Empuje","Un levantamiento por encima de la cabeza que usa una flexión y un impulso de piernas para lanzar la barra arriba, recibida en un cuarto de sentadilla.","Cuerpo completo","Halterofilia","Intermedio","Barra",false,["Deltoides anterior","Tríceps braquial"],["Glúteo mayor","Cuádriceps","Trapecio"],8.0,"push-jerk-start.webp","push-jerk-peak.webp",["Sostén la barra en posición de rack frontal sobre los hombros.","Párate con los pies a la anchura de las caderas.","Flexiona ligeramente las rodillas.","Impulsa explosivamente con las piernas y empuja la barra sobre la cabeza.","Baja a una sentadilla de un cuarto debajo de la barra y bloquea los brazos.","Levántate completamente y baja la barra para repetir."],["Mantén el torso erguido durante la flexión.","Impulsa con las piernas antes de empujar con los brazos.","Bloquea los brazos mientras bajas debajo de la barra."]],["l-sit","L-Sit","Un ejercicio isométrico avanzado en el que el cuerpo forma una L con las piernas extendidas, exigente para el core y los flexores de cadera.","Cuerpo completo","Fuerza","Avanzado","Paralelas",false,["Flexores de cadera","Recto abdominal"],["Dorsal ancho","Cuádriceps","Tríceps braquial"],6.0,"l-sit-main.webp",null,["Siéntate en el suelo o empuja hacia arriba en barras paralelas con los brazos rectos.","Bloquea los codos y deprime los hombros.","Eleva las piernas rectas al frente paralelas al suelo.","Forma una L con el cuerpo.","Mantén la posición durante el tiempo indicado.","Baja las piernas con control para salir."],["Mantén las puntas de los pies estiradas hacia delante.","Si no llegas, empieza con las rodillas recogidas.","Respira de forma constante; no aguantes el aire durante el sostén."]],["pilates-saw","La Sierra de Pilates","Un giro con flexión sentado: sentado erguido con las piernas abiertas, el torso rota y después se pliega sobre la pierna contraria para que la mano que alcanza pase junto al dedo meñique como una sierra.","Espalda","Estiramiento","Intermedio","Sin equipo",true,["Erectores espinales","Oblicuos"],["Aductores","Isquiotibiales"],5.0,"pilates-saw-start.webp","pilates-saw-peak.webp",["Siéntate erguido con las piernas estiradas y algo más abiertas que las caderas, los brazos hacia los lados.","Rota el torso hacia un lado manteniendo ambos isquiones en el suelo.","Pliégate hacia delante sobre esa pierna y alcanza con la mano contraria más allá del dedo meñique.","Vuelve a subir a través de la columna y regresa al centro.","Repite hacia el otro lado y sigue alternando."],["Ancla ambos isquiones; si uno se levanta, el giro se convierte en una inclinación.","Primero rota y después pliégate: ese orden es lo que hace funcionar el ejercicio.","Siéntate sobre una manta doblada si la pelvis no puede mantenerse erguida."]],["pilates-leg-pull-back","Leg Pull Back de Pilates","Una plancha invertida con elevaciones alternas de pierna: las caderas se mantienen altas mientras se eleva una pierna cada vez, de modo que glúteos y parte posterior del tronco trabajan ante el apoyo cambiante.","Espalda","Fuerza","Intermedio","Sin equipo",true,["Erectores espinales","Glúteo mayor"],["Isquiotibiales","Deltoides posterior","Tríceps braquial"],5.0,"pilates-leg-pull-back-start.webp","pilates-leg-pull-back-peak.webp",["Siéntate con las piernas estiradas y las manos en el suelo detrás de las caderas, con los dedos hacia delante.","Empuja con manos y talones y eleva las caderas a una plancha invertida.","Con las caderas niveladas y altas, eleva una pierna estirada mientras la pelvis siga quieta.","Baja la pierna de forma controlada y repite con la otra.","Termina la serie y baja las caderas al suelo."],["Detén la elevación donde las caderas empiecen a caer; la altura no es el objetivo.","Mantén el pecho abierto y los hombros lejos de las orejas.","Flexiona un poco las rodillas si la versión con piernas estiradas tira de los isquiotibiales."]],["pilates-leg-pull-front","Leg Pull Front de Pilates","Una plancha alta con elevaciones alternas de pierna: los hombros permanecen sobre las muñecas mientras se eleva una pierna cada vez, lo que añade una demanda antirrotación a la plancha.","Pierna","Fuerza","Intermedio","Sin equipo",true,["Glúteo mayor","Recto abdominal"],["Deltoides anterior","Erectores espinales","Transverso abdominal"],5.0,"pilates-leg-pull-front-start.webp","pilates-leg-pull-front-peak.webp",["Colócate en plancha alta con las manos bajo los hombros y el cuerpo en línea.","Aprieta el tronco y los glúteos para que las caderas no puedan rotar.","Eleva una pierna estirada unos centímetros por encima de la cadera sin que la pelvis se incline.","Bájala de forma controlada y repite con la otra pierna.","Sigue alternando las veces indicadas."],["Eleva la pierna desde el glúteo y no arqueando la zona lumbar.","Reparte el peso entre ambas manos; la tendencia es inclinarse lejos del lado que se eleva.","Reduce la altura hasta que las caderas se mantengan perfectamente niveladas."]],["kettlebell-turkish-get-ups","Levantamiento Turco con Kettlebell","Un ejercicio de cuerpo completo con kettlebell que pasa de estar tumbado a de pie mientras se mantiene el peso bloqueado por encima de la cabeza, trabajando la fuerza, la estabilidad y la movilidad de todo el cuerpo.","Cuerpo completo","Fuerza","Intermedio","Kettlebell",false,["Deltoides anterior","Glúteo mayor","Recto abdominal"],["Oblicuos","Cuádriceps","Tríceps braquial"],6.0,"kettlebell-turkish-get-ups-start.webp","kettlebell-turkish-get-ups-peak.webp",["Túmbate boca arriba sosteniendo una kettlebell por encima de la cabeza con una mano.","Flexiona la rodilla del mismo lado y apoya el pie plano.","Rueda hasta apoyarte en el codo opuesto y luego en la mano.","Empuja las caderas hacia arriba y lleva la pierna estirada hacia atrás a una zancada.","Ponte de pie por completo manteniendo la kettlebell bloqueada por encima de la cabeza.","Invierte la secuencia para volver a la posición inicial."],["Mantén la vista en la kettlebell hasta que estés de pie, luego mira al frente.","Muévete despacio en cada paso: el levantamiento es una secuencia, no un solo movimiento."]],["supine-windshield-wipers","Limpiaparabrisas Tumbado","Un ejercicio de rotación tumbado: con las rodillas flexionadas o las piernas elevadas, ambas piernas oscilan de lado a lado como limpiaparabrisas mientras los hombros permanecen pegados al suelo.","Core","Fuerza","Intermedio","Sin equipo",true,["Oblicuos","Recto abdominal"],["Flexores de cadera","Transverso abdominal"],5.0,"supine-windshield-wipers-start.webp","supine-windshield-wipers-peak.webp",["Túmbate boca arriba con los brazos abiertos a los lados y las rodillas flexionadas sobre las caderas.","Aprieta el tronco para que la zona lumbar no se despegue del suelo.","Baja ambas piernas juntas hacia un lado mientras los hombros sigan apoyados.","Devuélvelas por el centro y bájalas hacia el otro lado.","Sigue alternando las veces indicadas."],["Ambos hombros se quedan en el suelo; son ellos los que definen el recorrido, no las piernas.","Mantén las rodillas juntas para que la pelvis se mueva como una unidad.","Estira las piernas para una versión mucho más difícil cuando tengas el control."]],["hollow-body-hold","Mantenimiento del Cuerpo Hueco","Un mantenimiento isométrico de core de la gimnasia, que entrena la tensión de cuerpo completo con la columna en ligera forma de C.","Core","Fuerza","Intermedio","Sin equipo",true,["Recto abdominal"],["Flexores de cadera","Oblicuos","Transverso abdominal"],5.0,"hollow-body-hold-main.webp",null,["Acuéstate boca arriba con los brazos extendidos sobre la cabeza y las piernas rectas.","Presiona la zona lumbar firmemente contra el suelo.","Levanta ligeramente los hombros, la cabeza y las piernas del suelo.","Mantén la posición con brazos y piernas extendidos, cuerpo en forma de plátano poco profundo.","Sostén durante el tiempo indicado."],["Mantén la zona lumbar pegada al suelo — si se levanta, sube más las piernas.","Mete ligeramente la barbilla para activar los abdominales superiores.","Flexiona las rodillas para escalar si la posición se rompe."]],["heel-to-toe-walk","Marcha en Tándem","Un ejercicio de equilibrio y coordinación caminando sobre una línea imaginaria, colocando el talón de cada paso justo contra los dedos del otro pie para que la base de apoyo se reduzca casi a nada.","Pierna","Fuerza","Principiante","Sin equipo",true,["Glúteo medio","Sóleo"],["Gemelos","Cuádriceps","Transverso abdominal"],2.5,"heel-to-toe-walk-main.webp",null,["Elige una línea recta en el suelo, colócate sobre ella y extiende los brazos a los lados a la altura de los hombros.","Da un paso al frente y coloca el talón justo delante de los dedos del pie de apoyo, en contacto con ellos.","Pasa el peso al pie delantero de forma controlada y haz una pausa breve antes del siguiente paso.","Lleva el pie de atrás hacia delante y colócalo de nuevo talón contra dedos, sin salirte de la línea.","Fija la vista en un punto al frente en lugar de mirarte los pies, y corrige los desequilibrios con los brazos.","Camina el número de pasos deseado, luego date la vuelta y regresa."],["Ve despacio. Si te apresuras acabas caminando normal sobre una línea estrecha y desaparece por completo la exigencia de equilibrio.","Si no consigues mantener la línea, camina junto a una pared y tócala solo cuando lo necesites — eso es una regresión, no un fracaso.","Súbele la dificultad cruzando los brazos sobre el pecho, y todavía más haciéndolo con los ojos cerrados cerca de una pared."]],["reverse-tabletop-hold","Mesa Invertida Isométrica","Una mesa invertida estática: rodillas flexionadas, manos bajo los hombros por detrás del cuerpo, caderas elevadas a la altura de las rodillas y sostenidas, de modo que los glúteos y toda la parte posterior del tronco trabajan de forma isométrica.","Espalda","Fuerza","Principiante","Sin equipo",true,["Erectores espinales","Glúteo mayor"],["Isquiotibiales","Deltoides posterior","Tríceps braquial"],5.0,"reverse-tabletop-hold-main.webp",null,["Siéntate con las rodillas flexionadas, los pies apoyados y las manos en el suelo detrás de ti, con los dedos hacia los talones.","Empuja con manos y pies y eleva las caderas hasta que el tronco quede a la altura de las rodillas.","Abre el pecho, aleja los hombros de las orejas y mira al frente.","Mantén la posición durante el tiempo indicado con las caderas altas.","Baja las caderas de forma controlada para terminar."],["Empuja el suelo en lugar de colgarte de los hombros.","Mantén las rodillas sobre los tobillos y apuntando al frente.","Deja que la cabeza siga la línea de la columna en lugar de dejarla caer hacia atrás."]],["dumbbell-windmill","Molino con Mancuerna","Este ejercicio de cuerpo completo desarrolla estabilidad del core, fuerza de hombros y movilidad de cadera al rotar el torso con una mancuerna sobre la cabeza, trabajando principalmente los oblicuos y deltoides laterales.","Cuerpo completo","Fuerza","Intermedio","Mancuernas",false,["Deltoides lateral","Oblicuos"],["Deltoides anterior","Glúteo medio","Isquiotibiales"],5.0,"dumbbell-windmill-start.webp","dumbbell-windmill-peak.webp",["Ponte de pie con los pies al ancho de los hombros, sosteniendo una mancuerna sobre la cabeza con un brazo extendido.","Gira tus pies ligeramente alejándolos del lado de la mancuerna, manteniendo el brazo recto y la vista en el peso.","Inclínate desde las caderas, empujándolas hacia el lado de la mancuerna, y baja lentamente el torso hacia el suelo.","Mantén la espalda recta y el brazo de la mancuerna vertical mientras alcanzas con tu mano libre el pie o el suelo.","Invierte el movimiento impulsándote con las caderas y los oblicuos para regresar a la posición inicial.","Completa todas las repeticiones por lado, luego cambia y repite para el otro lado."],["Mantén el core contraído durante todo el movimiento para proteger tu columna y mejorar la estabilidad.","Mantén la vista fija en la mancuerna sobre la cabeza para ayudar a mantener el equilibrio y el brazo recto.","Concéntrate en inclinarte desde las caderas, no en redondear la espalda, para activar los isquiotibiales y glúteos.","Comienza con un peso ligero para dominar la forma antes de progresar a cargas más pesadas."]],["kettlebell-windmills","Molino de Viento con Pesa Rusa","Un ejercicio de pesa rusa con el brazo bloqueado por encima de la cabeza, que combina estabilidad de hombro y bisagra lateral de cadera.","Cuerpo completo","Fuerza","Intermedio","Kettlebell",false,["Aductores","Deltoides anterior","Oblicuos"],["Erectores espinales","Glúteo mayor","Isquiotibiales"],5.0,"kettlebell-windmills-start.webp","kettlebell-windmills-peak.webp",["Párate sosteniendo una pesa rusa bloqueada sobre la cabeza con una mano.","Gira los pies unos 45 grados alejándolos del brazo de trabajo.","Con la pesa rusa arriba, inclínate lateralmente desde las caderas.","Lleva la mano opuesta hacia el pie.","Empuja las caderas hacia atrás para volver a la posición erguida.","Completa las repeticiones de un lado y luego cambia."],["No pierdas de vista la pesa durante todo el movimiento.","El brazo de arriba permanece bloqueado y vertical en todo momento.","Empieza sin peso para aprender el patrón del movimiento."]],["mountain-climbers","Mountain Climbers","Un ejercicio dinámico de peso corporal que combina trabajo de core con cardio.","Pierna","Cardio","Principiante","Sin equipo",true,["Flexores de cadera","Recto abdominal"],["Oblicuos","Cuádriceps"],8.0,"mountain-climbers-start.webp","mountain-climbers-peak.webp",["Comienza en posición de plancha alta.","Lleva una rodilla hacia el pecho.","Cambia rápidamente de pierna llevando la otra rodilla hacia adelante.","Continúa alternando a un ritmo brioso.","Repite."],["Mantén los hombros encima de las muñecas todo el tiempo.","No dejes que la cadera se eleve hacia el techo.","Acelera solo mientras puedas mantener la técnica."]],["muscle-snatch","Muscle Snatch","Una variante de la arrancada que tira de la barra por encima de la cabeza sin caer debajo, desarrollando potencia de tirón y fuerza de bloqueo.","Cuerpo completo","Halterofilia","Intermedio","Barra",false,["Deltoides lateral","Trapecio"],["Erectores espinales","Glúteo mayor","Isquiotibiales"],8.0,"muscle-snatch-start.webp","muscle-snatch-peak.webp",["Párate con los pies a la anchura de las caderas y agarra la barra en ancho con agarre de gancho.","Tira de la barra explosivamente desde el suelo manteniéndola cerca del cuerpo.","Encoge los hombros con fuerza y lleva la barra sobre la cabeza sin flexionar las piernas.","Bloquea la barra sobre la cabeza con los brazos rectos.","Baja la barra con control a la posición inicial.","Repite el número de repeticiones deseado."],["Encoge los hombros con fuerza y sigue tirando de la barra hacia arriba.","Mantente erguido; no te metas debajo de la barra para recibirla.","Mantén la barra cerca del cuerpo durante todo el tirón."]],["ring-muscle-up","Muscle-Up en Anillas","Un movimiento avanzado de calistenia que combina dominada y fondo en anillas de gimnasia.","Espalda","Fuerza","Avanzado","Anillas",false,["Dorsal ancho","Pectoral mayor","Tríceps braquial"],["Deltoides anterior","Bíceps braquial","Romboides"],6.0,"ring-muscle-up-start.webp","ring-muscle-up-peak.webp",["Cuelga de las anillas con agarre falso, palmas enfrentadas.","Tira explosivamente, llevando el pecho hacia las anillas.","Pasa los codos por encima de las anillas mientras sube el pecho.","Empuja arriba hasta extender los brazos.","Baja con control pasando por la transición hasta volver al colgado."],["El agarre falso es clave para la transición.","Empuja los codos hacia abajo con fuerza durante la transición.","Construye la fuerza primero con negativas y asistido con banda."]],["muscle-ups","Muscle-Ups","Un movimiento avanzado en barra que combina una dominada explosiva con una transición a fondo para terminar por encima de la barra.","Espalda","Fuerza","Avanzado","Barra de dominadas",false,["Dorsal ancho","Tríceps braquial"],["Deltoides anterior","Bíceps braquial","Pectoral mayor"],6.0,"muscle-ups-start.webp","muscle-ups-peak.webp",["Cuélgate de una barra de dominadas con agarre falso.","Tírate hacia arriba de forma explosiva hacia la barra.","Cuando el pecho llegue a la barra, rota los codos por encima y transiciona a un dip.","Empuja el cuerpo hacia arriba hasta que los brazos queden completamente extendidos sobre la barra.","Baja con control por el mismo recorrido.","Repite el número de repeticiones deseado."],["Usa agarre falso para que las muñecas ya estén sobre la barra en la transición.","Tira explosivamente hacia el esternón, no solo hasta la barbilla.","Practica la transición en anillas bajas o con bandas antes de hacer repeticiones completas."]],["rowing-machine","Máquina de Remo","Un ejercicio cardiovascular de cuerpo completo en la máquina de remo: cada palada empuja con las piernas, lleva el torso hacia atrás y tira de la manija hasta las costillas, trabajando piernas, espalda y brazos en un ciclo continuo.","Cuerpo completo","Cardio","Principiante","Remoergómetro",false,["Dorsal ancho","Cuádriceps"],["Bíceps braquial","Erectores espinales","Glúteo mayor","Isquiotibiales","Romboides","Trapecio"],8.0,"rowing-machine-start.webp","rowing-machine-peak.webp",["Siéntate en la máquina de remo, sujeta los pies con las correas de las plataformas y agarra la manija en pronación.","Deslízate hacia delante hasta la posición de ataque: tibias verticales, torso ligeramente por delante de la cadera y brazos estirados hacia el volante.","Empuja primero con las piernas y desplaza el asiento hacia atrás hasta dejar las rodillas casi estiradas.","Lleva el torso hacia atrás pasando de la vertical y tira entonces de la manija hasta las costillas bajas, con los codos pasando junto a los costados.","Invierte el orden en la recuperación — primero los brazos hacia delante, después el torso y por último flexionar las rodillas — y vuelve a deslizarte hasta la posición de ataque para la siguiente palada.","Continúa durante el tiempo, la distancia o el número de paladas que quieras."],["Respeta el orden: piernas, torso y brazos en el tirón, y brazos, torso y piernas en la recuperación. Flexionar los brazos antes de tiempo desaprovecha la parte más fuerte de la palada.","Rema con la espalda plana y el core activado: redondear la zona lumbar en la posición de ataque es lo que convierte el remo en dolor de espalda en lugar de trabajo cardiovascular.","Lleva la manija en línea recta y horizontal hasta las costillas bajas, y haz la recuperación unas dos veces más lenta que el tirón en lugar de volver de golpe."]],["reverse-nordic-curl","Nordic Curl Inverso","Un ejercicio de cuádriceps con el propio peso corporal, arrodillado, inclinando el torso hacia atrás con control mientras se mantiene la cadera extendida.","Pierna","Fuerza","Intermedio","Sin equipo",true,["Cuádriceps"],["Flexores de cadera","Recto abdominal"],3.5,"reverse-nordic-curl-start.webp","reverse-nordic-curl-peak.webp",["Arrodíllate sobre una almohadilla con los pies planos y el torso erguido.","Mantén la cadera extendida y el core activado.","Inclina el torso lentamente hacia atrás manteniendo el cuerpo en línea recta.","Baja tanto como puedas controlar con el cuádriceps.","Vuelve a subir a la posición inicial.","Repite el número de repeticiones deseado."],["Mantén la cadera extendida en todo momento, sin que se doble.","Baja solo hasta donde puedas controlar el movimiento.","Usa una almohadilla bajo las rodillas para mayor comodidad."]],["double-kettlebell-overhead-carry","Paseo con Dos Kettlebells sobre la Cabeza","Un paseo cargado con una kettlebell bloqueada sobre cada hombro — el más difícil de sostener quieto de todos los paseos, ya que combina la masa descentrada de las bolas con el doble de carga por encima de la cabeza.","Hombro","Fuerza","Avanzado","Kettlebell",false,["Deltoides anterior","Deltoides lateral"],["Erectores espinales","Extensores del antebrazo","Serrato anterior","Transverso abdominal","Trapecio","Tríceps braquial"],5.5,"double-kettlebell-overhead-carry-main.webp",null,["Lleva dos kettlebells al rack y luego pásalas a bloqueo por encima de la cabeza con press o push press.","Estira ambos codos y asienta cada bola por detrás y por encima de su muñeca, con las muñecas rectas.","Lleva las costillas abajo y aprieta fuerte antes del primer paso; con las dos bolas arriba no queda nada con lo que contrapesar.","Camina hacia delante con zancadas cortas y controladas, manteniendo ambas bolas alineadas sobre los hombros.","Sigue mirando al frente y respira de forma constante durante todo el paseo.","Cubre la distancia deseada y baja después ambas bolas al rack y al suelo de forma controlada."],["Gánate este ejercicio. Domina el paseo con una sola kettlebell por ambos lados antes de cargar dos.","Hazlo solo donde puedas soltar ambas bolas con seguridad, y ten claro hacia dónde te apartarás si hace falta.","La distancia debe ser corta y la postura perfecta. En cuanto la espalda se arquee o se doble una muñeca, la serie ha terminado."]],["double-db-overhead-carry","Paseo con Dos Mancuernas sobre la Cabeza","Un paseo cargado con una mancuerna bloqueada sobre cada hombro, que duplica la carga por encima de la cabeza y elimina el brazo libre que de otro modo te ayudaría a equilibrarte.","Hombro","Fuerza","Intermedio","Mancuernas",false,["Deltoides anterior","Deltoides lateral"],["Erectores espinales","Serrato anterior","Transverso abdominal","Trapecio","Tríceps braquial"],5.5,"double-db-overhead-carry-main.webp",null,["Lleva una mancuerna, en cargada o press, hasta el bloqueo sobre cada hombro.","Estira ambos codos del todo y empuja las escápulas hacia los pesos en lugar de encogerte alejándote de ellos.","Aprieta fuerte y mantén las costillas abajo — con los dos brazos arriba la tentación de arquearse es mucho mayor.","Camina hacia delante con zancadas cortas y deliberadas, manteniendo ambas mancuernas alineadas sobre los hombros.","Sigue respirando de forma superficial y constante en vez de aguantar el aire todo el recorrido.","Carga la distancia deseada y baja después ambos pesos de forma controlada."],["Empieza con menos peso por mano que en el paseo a un brazo. Dos brazos por encima de la cabeza no son la mitad de fáciles, son el doble de estabilizar.","Ten pensado cómo abandonar la serie antes de empezar, y carga donde puedas soltar los pesos sin peligro.","Distancias cortas bien hechas superan a las largas hechas torcido. Corta la serie cuando se abran las costillas, no cuando cedan los hombros."]],["kettlebell-overhead-carry","Paseo con Kettlebell sobre la Cabeza","Un paseo cargado con una sola kettlebell bloqueada por encima de la cabeza, donde la bola cuelga por detrás de la muñeca y tira del brazo hacia atrás, lo que la hace más difícil de sostener quieta que una mancuerna.","Hombro","Fuerza","Intermedio","Kettlebell",false,["Deltoides anterior","Deltoides lateral"],["Extensores del antebrazo","Oblicuos","Cuadrado lumbar","Serrato anterior","Trapecio","Tríceps braquial"],5.5,"kettlebell-overhead-carry-main.webp",null,["Lleva una kettlebell en cargada y press hasta el bloqueo, dejando que la bola se asiente sobre el dorso del antebrazo.","Estira el codo del todo y gira el brazo para que la bola quede por detrás y por encima de la muñeca, no desplazada a un lado.","Empaqueta el hombro — empuja el peso hacia arriba y deja que la escápula acompañe, en lugar de hundirla a la fuerza.","Aprieta el tronco y camina hacia delante con zancadas regulares, con la bola alineada sobre hombro y cadera.","Mantén la muñeca recta; dejar que se doble hacia atrás es lo que hace que una kettlebell arriba se sienta inestable.","Carga la distancia deseada, baja de forma controlada y repite por el otro lado."],["Usa menos peso que con mancuerna. La masa descentrada hace que el mismo kilaje cueste bastante más de sostener quieto.","La muñeca doblada es el fallo habitual. Si se te vence una y otra vez, baja el peso en lugar de pelear con él todo el recorrido.","Haz ambos lados la misma distancia — la carga unilateral es el sentido del ejercicio."]],["db-overhead-carry","Paseo con Mancuerna sobre la Cabeza","Un paseo cargado con una sola mancuerna bloqueada por encima del hombro, que exige estabilidad de hombro y un tronco erguido en cada paso.","Hombro","Fuerza","Intermedio","Mancuernas",false,["Deltoides anterior","Deltoides lateral"],["Oblicuos","Cuadrado lumbar","Serrato anterior","Transverso abdominal","Trapecio","Tríceps braquial"],5.5,"db-overhead-carry-main.webp",null,["Lleva una mancuerna, en cargada o press, hasta quedar bloqueada justo encima del hombro.","Estira el brazo del todo, con el codo bloqueado y el bíceps cerca de la oreja.","Lleva las costillas hacia abajo en lugar de arquear la zona lumbar para sostener el peso arriba.","Camina hacia delante con zancadas controladas, manteniendo la mancuerna alineada sobre hombro y cadera.","Mira al frente — echar la cabeza atrás para vigilar el peso arrastra contigo toda la postura.","Carga la distancia deseada, baja de forma controlada y repite con el otro brazo."],["Iguala la distancia con ambos brazos para que la carga asimétrica no se convierta en una adaptación asimétrica.","El codo bloqueado no es opcional. Con el codo blando toda la carga recae en el músculo en lugar del esqueleto y la serie se acaba enseguida.","Si las costillas se abren y la espalda se arquea, el peso excede tu posición actual por encima de la cabeza — corrige la posición antes de añadir carga."]],["kettlebell-farmers-walk","Paseo del Granjero con Pesa Rusa","Un acarreo cargado caminando con un peso pesado en cada mano, que reta el agarre, los trapecios y la estabilidad de todo el cuerpo.","Cuerpo completo","Fuerza","Intermedio","Kettlebell",false,["Flexores del antebrazo","Trapecio"],["Erectores espinales","Glúteo mayor","Cuádriceps","Recto abdominal"],5.5,"kettlebell-farmers-walk-main.webp",null,["Ponte de pie entre dos mancuernas pesadas o asas de granjero.","Flexiona las caderas y agarra las asas con firmeza en agarre neutro.","Ponte erguido con los hombros atrás y el core activado.","Camina hacia delante con pasos cortos y controlados.","Mantén una postura erguida durante todo el recorrido.","Deja los pesos en el suelo al final de la distancia."],["Aprieta las asas con fuerza para que el peso no te resbale de las manos.","Mantén el core firme y no te balancees de lado a lado al caminar.","Da pasos cortos y rápidos; las zancadas largas rompen el equilibrio."]],["suitcase-carry","Paseo del Maletín","Un paseo cargado con el peso en una sola mano, de modo que el tronco tiene que resistir la inclinación lateral durante todo el recorrido — la versión unilateral del paseo del granjero.","Antebrazo","Fuerza","Principiante","Kettlebell",false,["Flexores del antebrazo","Oblicuos","Cuadrado lumbar"],["Erectores espinales","Glúteo medio","Cuádriceps","Trapecio"],5.5,"suitcase-carry-main.webp",null,["Colócate junto a una sola kettlebell o mancuerna, con los pies a la anchura de las caderas.","Flexiona por la cadera, agarra el asa con una mano e incorpórate con el peso colgando a un costado.","Lleva ese hombro abajo y atrás, y aprieta el tronco como si fueran a empujarte de lado.","Camina hacia delante con zancadas normales y regulares, manteniendo el torso erguido y cuadrado en lugar de inclinarte para escapar del peso.","Mantén el brazo libre relajado junto al cuerpo, sin separarlo como contrapeso.","Carga la distancia o el tiempo deseados, deja el peso en el suelo de forma controlada y repite por el otro lado."],["Haz la misma distancia por los dos lados. Todo el valor está en la asimetría, y solo funciona si cargas ambas direcciones por igual.","Si te inclinas hacia el peso o levantas la cadera contraria, el peso es excesivo: esto es ante todo un ejercicio de postura.","El agarre suele fallar antes que el tronco. Es un efecto de entrenamiento legítimo, pero si siempre es el límite, usa correas en las series pesadas."]],["pilates-kneeling-side-kick","Patada Lateral de Rodillas de Pilates","Un ejercicio clásico de suelo: de rodillas con la mano apoyada en el suelo, la pierna de arriba oscila adelante y atrás a la altura de la cadera mientras el tronco permanece inmóvil.","Pierna","Fuerza","Intermedio","Sin equipo",true,["Glúteo medio","Oblicuos"],["Glúteo mayor","Flexores de cadera"],5.0,"pilates-kneeling-side-kick-start.webp","pilates-kneeling-side-kick-peak.webp",["Arrodíllate y apoya en el suelo la mano del mismo lado, con la otra mano detrás de la cabeza.","Extiende la pierna de arriba hacia el lado a la altura de la cadera, con el pie en flexión.","Mantén el tronco completamente quieto y lleva la pierna hacia delante mientras la pelvis siga cuadrada.","Lleva la pierna por detrás de la línea del cuerpo sin arquear la zona lumbar.","Repite las veces indicadas y cambia de lado."],["El tronco es el ejercicio: si se balancea con la pierna, acorta el recorrido.","Mantén el hombro de apoyo alejado de la oreja.","Trabaja a un ritmo controlado en lugar de lanzar la pierna."]],["cable-kickback","Patada Trasera de Glúteos en Cable","Un ejercicio de aislamiento en cable para el glúteo mayor que extiende la cadera hacia atrás contra resistencia constante.","Pierna","Fuerza","Intermedio","Polea",false,["Glúteo mayor"],["Isquiotibiales"],5.0,"cable-kickback-start.webp","cable-kickback-peak.webp",["Coloca una correa de tobillo en la polea baja y sujétala alrededor de un tobillo.","De pie frente a la máquina, agárrate ligeramente al soporte e inclínate un poco desde las caderas.","Lleva la pierna con la correa hacia atrás extendiendo la cadera completamente y manteniendo la rodilla casi recta.","Aprieta el glúteo en la extensión máxima y regresa el pie lentamente a la posición inicial.","Completa todas las repeticiones de un lado antes de cambiar."],["Conduce el movimiento con el talón para maximizar la activación del glúteo.","Mantén las caderas paralelas; evita rotar la pelvis al patear hacia atrás.","El movimiento viene solo de la cadera: mantén la espalda y la pierna de apoyo estables."]],["glute-kickback","Patada de Glúteo","Un ejercicio de aislamiento de glúteos con peso corporal en posición de cuatro puntos para desarrollar el glúteo mayor.","Pierna","Fuerza","Principiante","Sin equipo",true,["Glúteo mayor"],["Erectores espinales","Glúteo medio","Isquiotibiales"],3.5,"glute-kickback-start.webp","glute-kickback-peak.webp",["Comienza a cuatro patas con las manos bajo los hombros y las rodillas bajo las caderas.","Manteniendo la rodilla doblada a 90 grados, empuja el talón hacia el techo.","Aprieta el glúteo en la parte superior del movimiento.","Baja la pierna a la posición inicial con control.","Completa todas las repeticiones y cambia de lado."],["Mantén las caderas paralelas al suelo — evita rotar.","Concéntrate en apretar el glúteo, no solo en levantar la pierna.","Agrega una banda de resistencia o cable para sobrecarga progresiva."]],["glute-kickback-hold","Patada de Glúteo Isométrica","La posición final de la patada de glúteo mantenida en el tiempo: a cuatro apoyos con una pierna extendida hacia atrás a la altura de la cadera, la pelvis nivelada y el glúteo sosteniendo la pierna en el sitio.","Pierna","Fuerza","Principiante","Sin equipo",true,["Glúteo mayor"],["Erectores espinales","Glúteo medio","Isquiotibiales"],3.5,"glute-kickback-hold-main.webp",null,["Colócate a cuatro apoyos con las manos bajo los hombros y las rodillas bajo las caderas.","Aprieta el tronco y mantén la pelvis nivelada; no dejes que el lado que trabaja rote hacia arriba.","Extiende una pierna hacia atrás y arriba hasta que el muslo quede en línea con el torso.","Mantén esa posición durante el tiempo indicado, con el cuello largo y la zona lumbar plana.","Baja la pierna de forma controlada y repite del otro lado."],["Aprieta el glúteo en lugar de subir más; la altura la limita que la pelvis siga cuadrada.","Aleja del oído el hombro que te sostiene para que el tronco no se hunda.","Con la rodilla flexionada la tensión se queda en el glúteo; con la pierna estirada pasa más al isquiotibial."]],["cable-tricep-kickback","Patada de Tríceps con Cable","Una extensión de tríceps en polea baja, realizada con el torso inclinado, que mantiene la tensión en el bloqueo final.","Tríceps","Fuerza","Intermedio","Polea",false,["Tríceps braquial"],["Deltoides posterior"],5.0,"cable-tricep-kickback-start.webp","cable-tricep-kickback-peak.webp",["Engancha un handle a la polea baja e inclínate hacia adelante desde las caderas.","Pega la parte superior del brazo al costado con el codo flexionado a 90 grados.","Extiende el codo para empujar el handle hacia atrás.","Aprieta el tríceps al final del movimiento.","Vuelve de forma controlada. Completa las repeticiones de un lado y luego cambia."],["Evita que el codo caiga o se abra durante la extensión.","Mantén la espalda recta mientras el torso está inclinado.","Usa un peso ligero para no recurrir al impulso."]],["tricep-kickback","Patada de Tríceps con Mancuerna","Un ejercicio de aislamiento para los tríceps realizado en posición inclinada hacia adelante.","Tríceps","Fuerza","Principiante","Mancuernas",false,["Tríceps braquial"],[],5.0,"tricep-kickback-start.webp","tricep-kickback-peak.webp",["Inclínate hacia adelante en las caderas sosteniendo una mancuerna con el codo doblado a 90 grados.","Extiende el brazo recto hacia atrás apretando el tríceps.","Mantén brevemente en la extensión completa.","Baja con control.","Repite en ambos lados."],["Mantén el codo pegado y fijo junto al torso.","Extiende el brazo por completo apretando el tríceps al final.","Trabaja un lado a la vez con control en la bajada."]],["pec-deck","Pec Deck","Una máquina de aislamiento de pecho con almohadillas de codo fijas que trabaja los pectorales mediante aducción horizontal.","Pecho","Fuerza","Principiante","Pec deck",false,["Pectoral mayor"],["Deltoides anterior","Serrato anterior"],5.0,"pec-deck-start.webp","pec-deck-peak.webp",["Siéntate en la máquina pec deck y coloca los antebrazos contra las almohadillas.","Ajusta el asiento para que las almohadillas queden a la altura media del pecho.","Junta las almohadillas frente al pecho apretando.","Mantén la contracción brevemente en el centro.","Regresa con control a la posición inicial.","Repite el número de repeticiones deseado."],["No dejes que los brazos viajen demasiado atrás al abrir.","Mantén la espalda y los hombros pegados al respaldo.","Exhala al juntar las almohadillas e inhala al abrir."]],["downward-dog-pedal","Pedaleo en Perro Boca Abajo","Un calentamiento dentro del perro boca abajo: las rodillas se flexionan alternando, de modo que cada talón presiona hacia el suelo por turnos y la pantorrilla y el tobillo reciben un estiramiento en movimiento en lugar de un mantenimiento estático.","Pierna","Estiramiento","Principiante","Sin equipo",true,["Gemelos","Sóleo"],["Isquiotibiales"],5.0,"downward-dog-pedal-start.webp","downward-dog-pedal-peak.webp",["Colócate en perro boca abajo con las manos a la anchura de los hombros y las caderas altas.","Flexiona una rodilla y deja que ese talón se eleve mientras el talón contrario presiona hacia el suelo.","Cambia de lado con fluidez, como pedaleando, manteniendo las caderas altas todo el tiempo.","Presiona las manos por igual para que los hombros se mantengan estables.","Sigue alternando las veces o el tiempo indicados."],["Mantén las caderas altas; el objetivo son las pantorrillas, no una flexión más profunda.","Presiona toda la mano contra el suelo para que las muñecas no carguen con todo.","Muévete lo bastante despacio como para sentir cada lado en lugar de rebotar."]],["downward-dog","Perro Boca Abajo","Un estiramiento en V invertida que alarga a la vez isquiotibiales, pantorrillas, hombros y espalda.","Cuerpo completo","Estiramiento","Principiante","Sin equipo",true,["Gemelos","Isquiotibiales"],["Erectores espinales","Glúteo mayor","Dorsal ancho"],5.0,"downward-dog-main.webp",null,["Empieza en cuadrupedia con las manos algo por delante de los hombros.","Apoya los dedos de los pies y eleva la cadera hacia arriba y atrás.","Estira las piernas y lleva los talones hacia el suelo.","Mantén de 20 a 30 segundos, respirando de forma constante."],["Flexiona las rodillas si la zona lumbar se redondea.","Empuja el suelo para alargar la columna."]],["downward-dog-to-upward-dog","Perro Boca Abajo a Perro Boca Arriba","La transición del vinyasa: el cuerpo viaja desde el perro boca abajo hacia delante al perro boca arriba y de vuelta, alternando entre una V invertida cargada en los hombros y una extensión con el pecho abierto.","Hombro","Fuerza","Intermedio","Sin equipo",true,["Deltoides anterior","Erectores espinales"],["Pectoral mayor","Serrato anterior","Tríceps braquial"],5.0,"downward-dog-to-upward-dog-start.webp","downward-dog-to-upward-dog-peak.webp",["Empieza en perro boca abajo con las caderas altas y las manos a la anchura de los hombros.","Desplázate hacia delante pasando por la plancha, baja un poco y lleva el pecho al frente hasta el perro boca arriba con los muslos despegados.","Lleva los hombros atrás y abajo y mantén el cuello largo.","Mete los dedos de los pies, empuja el suelo y eleva las caderas de vuelta al perro boca abajo.","Sigue moviéndote entre ambas posiciones las veces indicadas."],["Lo que se mueve son las caderas, no las manos; las palmas siguen plantadas toda la serie.","Presiona el empeine en el perro boca arriba para que los muslos se despeguen de verdad.","Frena en mitad de la transición en lugar de balancearte entre los extremos."]],["downward-dog-to-plank","Perro Boca Abajo a Plancha","Una transición en movimiento entre el perro boca abajo y la plancha alta: las caderas viajan de arriba a la horizontal y de vuelta, de modo que hombros y tronco trabajan en recorrido completo en lugar de sostener una posición.","Hombro","Fuerza","Intermedio","Sin equipo",true,["Deltoides anterior","Recto abdominal"],["Isquiotibiales","Serrato anterior","Trapecio"],5.0,"downward-dog-to-plank-start.webp","downward-dog-to-plank-peak.webp",["Colócate en perro boca abajo con las caderas altas y las manos a la anchura de los hombros.","Desplaza el peso hacia delante y baja las caderas hasta formar una línea recta en plancha alta.","Sostén la plancha un instante con las costillas cerradas y los glúteos activos.","Empuja el suelo y eleva las caderas de vuelta al perro boca abajo.","Sigue alternando las veces indicadas."],["Lo que se mueve son las caderas, no las manos; las palmas se quedan en el mismo sitio toda la serie.","Mantén los hombros alejados de las orejas en ambas posiciones.","Frena la transición si la zona lumbar se hunde al entrar en la plancha."]],["downward-dog-to-low-lunge","Perro Boca Abajo a Zancada Baja","El paso al frente clásico: desde el perro boca abajo un pie viaja entre las manos hasta una zancada baja y regresa. Abre el flexor de la cadera de la pierna trasera y ensaya la transición que aparece en toda práctica de flujo.","Pierna","Estiramiento","Principiante","Sin equipo",true,["Flexores de cadera"],["Glúteo mayor","Cuádriceps"],5.0,"downward-dog-to-low-lunge-start.webp","downward-dog-to-low-lunge-peak.webp",["Empieza en perro boca abajo con las manos a la anchura de los hombros.","Desplaza el peso hacia delante y lleva un pie entre las manos.","Baja la rodilla trasera al suelo y hunde las caderas en una zancada baja.","Empuja con las manos, levanta la rodilla trasera y devuelve el pie delantero al perro boca abajo.","Repite del otro lado y sigue alternando."],["Lleva el pie hasta la altura de las manos en lugar de quedarte corto y arrastrarlo.","Acolcha la rodilla trasera con una esterilla doblada si el suelo es duro.","Mantén la rodilla delantera sobre el tobillo cuando bajen las caderas."]],["upward-dog","Perro Boca Arriba","Una extensión boca abajo sobre los brazos estirados con los muslos despegados del suelo, donde los brazos y los extensores de la espalda mantienen el pecho abierto y la columna larga.","Espalda","Estiramiento","Intermedio","Sin equipo",true,["Erectores espinales","Tríceps braquial"],["Glúteo mayor","Pectoral mayor"],5.0,"upward-dog-main.webp",null,["Túmbate boca abajo con las manos junto a las costillas bajas y el empeine apoyado en el suelo.","Presiona las manos y estira los brazos, elevando primero el pecho y después los muslos de la esterilla.","Lleva los hombros atrás y abajo y mantén el cuello largo.","Mantén la posición durante el tiempo indicado con solo las manos y el empeine en el suelo.","Flexiona los brazos y baja de forma controlada."],["Mantén los hombros sobre las muñecas en lugar de por detrás de ellas.","Presiona el empeine contra el suelo; eso es lo que eleva los muslos.","Si los muslos no pueden despegarse, quédate en la cobra en lugar de forzar la posición."]],["three-legged-dog","Perro de Tres Patas","El perro boca abajo con una pierna elevada: los hombros asumen más carga mientras la pierna elevada se alinea con la columna y las caderas se mantienen cuadradas.","Hombro","Fuerza","Intermedio","Sin equipo",true,["Deltoides anterior","Glúteo mayor"],["Isquiotibiales","Trapecio"],5.0,"three-legged-dog-main.webp",null,["Colócate en perro boca abajo con las manos a la anchura de los hombros y las caderas altas.","Presiona ambas manos por igual contra el suelo y desplaza el peso ligeramente hacia delante.","Eleva una pierna por detrás hasta alinearla con la columna, con ambas caderas niveladas.","Mantén la posición durante el tiempo indicado, con el talón de apoyo bajando hacia el suelo.","Baja la pierna y repite del otro lado."],["Evita que la cadera elevada se abra; una pelvis cuadrada importa más que la altura.","Presiona la base del índice contra el suelo para que las muñecas queden cómodas.","Flexiona ligeramente la rodilla de apoyo si el isquiotibial limita la forma."]],["double-db-kickstand-deadlift","Peso Muerto Kickstand con Doble Mancuerna","Un movimiento de bisagra de cadera en postura escalonada con dos mancuernas que carga principalmente la pierna delantera con el pie trasero como apoyo de equilibrio.","Pierna","Fuerza","Intermedio","Mancuernas",false,["Glúteo mayor","Isquiotibiales"],["Aductores","Erectores espinales"],6.0,"double-db-kickstand-deadlift-start.webp","double-db-kickstand-deadlift-peak.webp",["Coloca un pie detrás de modo que solo los dedos toquen el suelo.","Sostén una mancuerna en cada mano a la altura de la cadera.","Bisagra en la cadera bajando ambas mancuernas hacia la espinilla con la espalda recta.","Mantén la mayor parte del peso en el pie delantero.","Empuja con el talón delantero para volver a posición inicial. Cambia de lado."],["Mantén las mancuernas cerca de las piernas.","Para al notar el estiramiento en el isquiotibial de la pierna delantera.","Completa todas las repeticiones en un lado antes de cambiar."]],["kettlebell-kickstand-deadlift","Peso Muerto Kickstand con Kettlebell","Un movimiento de bisagra de cadera en postura escalonada con una kettlebell que carga la pierna delantera mientras el pie trasero estabiliza.","Pierna","Fuerza","Intermedio","Kettlebell",false,["Glúteo mayor","Isquiotibiales"],["Aductores","Erectores espinales"],6.0,"kettlebell-kickstand-deadlift-start.webp","kettlebell-kickstand-deadlift-peak.webp",["Coloca un pie detrás de modo que solo los dedos toquen el suelo.","Sostén una kettlebell en la mano del lado del pie trasero.","Bisagra en la cadera bajando la kettlebell hacia la espinilla con la espalda recta.","Mantén la mayor parte del peso en el pie delantero.","Empuja con el talón delantero para volver a la posición inicial. Cambia de lado."],["Mantén la kettlebell cerca de la pierna.","Para al sentir el estiramiento en el isquiotibial.","Todas las repeticiones en un lado antes de cambiar."]],["db-kickstand-deadlift","Peso Muerto Kickstand con Mancuerna","Un movimiento de bisagra de cadera en postura escalonada con una mancuerna que carga la pierna delantera mientras el pie trasero ofrece apoyo ligero.","Pierna","Fuerza","Intermedio","Mancuernas",false,["Glúteo mayor","Isquiotibiales"],["Aductores","Erectores espinales"],6.0,"db-kickstand-deadlift-start.webp","db-kickstand-deadlift-peak.webp",["Coloca un pie detrás de modo que solo los dedos rocen el suelo.","Sostén una mancuerna en la mano del lado del pie trasero.","Bisagra en la cadera bajando la mancuerna hacia la espinilla con la espalda recta.","Mantén la mayor parte del peso en el pie delantero.","Empuja con el talón delantero para volver a la posición inicial. Completa todas las repeticiones antes de cambiar de lado."],["Mantén la mancuerna cerca de la pierna durante el descenso.","Para cuando notes el estiramiento en el isquiotibial de la pierna delantera.","Completa todas las repeticiones en un lado antes de cambiar."]],["romanian-deadlift","Peso Muerto Rumano","Un movimiento de bisagra de cadera que enfatiza los isquiotibiales y los glúteos.","Pierna","Fuerza","Intermedio","Barra",false,["Glúteo mayor","Isquiotibiales"],["Erectores espinales"],6.0,"romanian-deadlift-start.webp","romanian-deadlift-peak.webp",["Párate sosteniendo la barra a la altura de las caderas con agarre prono.","Bisagra en las caderas empujándolas hacia atrás mientras mantienes las piernas casi rectas.","Baja la barra a lo largo de las piernas hasta sentir el estiramiento de los isquiotibiales.","Empuja las caderas hacia adelante para volver a la posición de pie.","Repite."],["No redondees la espalda baja; mantén la columna neutra.","Baja solo hasta donde llegues sin perder la postura.","Aprieta los dorsales para mantener la barra cerca del cuerpo."]],["single-leg-romanian-deadlift","Peso Muerto Rumano a Una Pierna","Un peso muerto rumano a una pierna con mancuernas, que trabaja isquiotibiales y glúteos mientras exige equilibrio y estabilidad de cadera.","Pierna","Fuerza","Intermedio","Mancuernas",false,["Glúteo mayor","Isquiotibiales"],["Erectores espinales","Glúteo medio"],6.0,"single-leg-romanian-deadlift-start.webp","single-leg-romanian-deadlift-peak.webp",["Apóyate en una pierna sosteniendo una mancuerna en cada mano frente a los muslos.","Mantén una ligera flexión en la rodilla de apoyo.","Bisagra en la cadera extendiendo la pierna libre detrás.","Baja las mancuernas a lo largo de la pierna de apoyo hasta sentir el estiramiento en los isquiotibiales.","Empuja con el talón para volver a la posición erguida.","Completa las repeticiones de un lado y luego cambia."],["Mantén la cadera cuadrada; no dejes que se abra hacia el lado.","Si pierdes el equilibrio, reduce el rango o usa menos peso.","Mira un punto fijo en el suelo para estabilizarte."]],["one-arm-single-leg-dumbbell-romanian-deadlift","Peso Muerto Rumano a Una Pierna con Mancuerna a Un Brazo","Un peso muerto rumano a una pierna sosteniendo una mancuerna en una sola mano, generalmente la opuesta a la pierna de apoyo (contralateral). Carga los isquiotibiales y glúteos de la pierna de apoyo mientras exige una fuerte contención anti-rotación del core.","Pierna","Fuerza","Avanzado","Mancuernas",false,["Glúteo mayor","Isquiotibiales"],["Erectores espinales","Flexores del antebrazo","Glúteo medio","Oblicuos"],6.0,"one-arm-single-leg-dumbbell-romanian-deadlift-start.webp","one-arm-single-leg-dumbbell-romanian-deadlift-peak.webp",["De pie sobre una pierna, sostén una mancuerna en la mano contraria.","Brazo libre al costado para equilibrarte, pierna libre suspendida justo por encima del suelo.","Bisagra en la cadera de apoyo empujándola hacia atrás mientras la pierna libre se extiende detrás para contrarrestar el peso.","Mantén las caderas cuadradas al suelo; no las abras hacia el lado.","Baja la mancuerna hacia el pie de la pierna de apoyo sintiendo un estiramiento profundo en los isquiotibiales.","Impulsa la cadera hacia adelante para volver a ponerte de pie con control.","Completa todas las repeticiones de un lado y luego cambia."],["Empieza con menos peso del que crees; el equilibrio y la demanda anti-rotación son el factor limitante, no la fuerza de los isquiotibiales.","Si rotas, haz una pausa y reinicia; un recorrido limpio más corto es mejor que uno completo con rotación.","Fijar la vista en un punto fijo en el suelo a un par de metros al frente ayuda con el equilibrio."]],["one-arm-single-leg-kettlebell-romanian-deadlift","Peso Muerto Rumano a Una Pierna con Pesa Rusa a Un Brazo","La versión con pesa rusa del peso muerto rumano a una pierna y un brazo. La masa excéntrica de la pesa rusa y su centro de gravedad más bajo lo convierten en un reto sutilmente diferente al de la mancuerna; excelente para la fuerza de la cadena posterior y el equilibrio bajo carga asimétrica.","Pierna","Fuerza","Avanzado","Kettlebell",false,["Glúteo mayor","Isquiotibiales"],["Erectores espinales","Flexores del antebrazo","Glúteo medio","Oblicuos"],6.0,"one-arm-single-leg-kettlebell-romanian-deadlift-start.webp","one-arm-single-leg-kettlebell-romanian-deadlift-peak.webp",["De pie sobre una pierna, sostén una pesa rusa en la mano contraria por el asa.","Brazo libre al costado para equilibrarte, pierna libre suspendida detrás.","Bisagra en la cadera de apoyo empujándola hacia atrás mientras la pierna libre se extiende para contrarrestar el peso.","Mantén las caderas cuadradas al suelo; la pesa rusa desciende recto por la espinilla.","Siente un estiramiento profundo en los isquiotibiales de la pierna de apoyo en la parte inferior.","Impulsa la cadera hacia adelante para volver a ponerte de pie.","Completa todas las repeticiones de un lado y luego cambia."],["La pesa rusa cuelga más bajo que una mancuerna; acorta ligeramente el recorrido para mantener la espalda plana.","Si la pesa oscila, estás yendo demasiado rápido. Desacelera la fase excéntrica.","Primero domina el peso muerto rumano a una pierna con dos mancuernas antes de progresar a este ejercicio."]],["banded-romanian-deadlift","Peso Muerto Rumano con Banda","Un peso muerto rumano con banda elástica, ideal para calentar y aprender el patrón de hip-hinge.","Pierna","Fuerza","Principiante","Banda circular",false,["Glúteo mayor","Isquiotibiales"],["Erectores espinales"],6.0,"banded-romanian-deadlift-start.webp","banded-romanian-deadlift-peak.webp",["Pisa una banda elástica con ambos pies y agarra el extremo superior.","Coloca los pies a la anchura de las caderas, ligera flexión de rodillas.","Flexiona desde la cadera, deslizando las manos por las piernas.","Baja hasta sentir el estiramiento en los isquiotibiales.","Empuja las caderas adelante para volver a la posición inicial."],["Mantén la banda cerca de las piernas.","Detente en el punto bajo de tu rango limpio — no redondees la espalda.","El movimiento es un hinge, no una sentadilla — las rodillas casi no se flexionan."]],["ez-bar-romanian-deadlift","Peso Muerto Rumano con Barra Z","Un peso muerto rumano con barra Z. El agarre angulado es más cómodo para las muñecas y es ideal para trabajo de bisagra ligero o personas con codos sensibles.","Pierna","Fuerza","Principiante","Barra Z",false,["Glúteo mayor","Isquiotibiales"],["Erectores espinales","Flexores del antebrazo","Trapecio"],6.0,"romanian-deadlift-start.webp","romanian-deadlift-peak.webp",["De pie, sujeta la barra Z a la altura media del muslo con agarre prono en las curvas internas.","Pies a la anchura de las caderas, rodillas ligeramente flexionadas, pecho arriba y dorsales activados.","Empuja las caderas hacia atrás dejando que la barra deslice por la parte delantera de las piernas.","Baja hasta sentir un estiramiento profundo en los isquiotibiales sin redondear la zona lumbar.","Impulsa las caderas hacia adelante para volver a la posición erguida, manteniendo la barra cerca del cuerpo.","Repite el número de repeticiones recomendado."],["El movimiento es una bisagra de cadera, no una sentadilla: las rodillas apenas se doblan.","La barra Z es más corta que una barra recta; agarra las curvas internas para una posición de muñeca casi neutra.","Detente en el límite inferior de tu rango de movimiento limpio: sin estiramiento con la espalda redondeada."]],["dumbbell-romanian-deadlift","Peso Muerto Rumano con Mancuernas","Un peso muerto rumano con mancuernas que enfatiza el estiramiento de los isquiotibiales mediante una bisagra de cadera.","Pierna","Fuerza","Intermedio","Mancuernas",false,["Glúteo mayor","Isquiotibiales"],["Erectores espinales","Flexores del antebrazo"],6.0,"dumbbell-romanian-deadlift-start.webp","dumbbell-romanian-deadlift-peak.webp",["Ponte de pie sujetando mancuernas frente a los muslos con una ligera flexión de rodillas.","Inclínate desde las caderas y empuja los glúteos hacia atrás.","Baja las mancuernas a lo largo de las piernas hasta sentir el estiramiento en los isquiotibiales.","Mantén la espalda recta y los hombros hacia atrás.","Empuja las caderas hacia adelante para volver a la posición de pie.","Repite el número de repeticiones deseado."],["Baja hasta donde tu flexibilidad lo permita, sin forzar.","Mantén la misma flexión suave de rodillas en todo el recorrido.","No conviertas el movimiento en una sentadilla."]],["smith-machine-rdl","Peso Muerto Rumano en Máquina Smith","Un peso muerto rumano realizado en la máquina Smith, que fija la trayectoria de la barra para que puedas concentrarte en la bisagra de cadera y el estiramiento de la cadena posterior.","Pierna","Fuerza","Principiante","Máquina Smith",false,["Isquiotibiales"],["Erectores espinales","Glúteo mayor","Trapecio"],6.0,"smith-machine-rdl-start.webp","smith-machine-rdl-peak.webp",["Ajusta la barra de la máquina Smith a la altura de la mitad del muslo y colócate directamente debajo con los pies al ancho de las caderas.","Desbloquea la barra con agarre en pronación justo por fuera de las caderas.","Empuja las caderas hacia atrás mientras deslizas la barra por la parte delantera de las piernas.","Baja hasta sentir un estiramiento profundo en los isquiotibiales, con la espalda plana y las rodillas ligeramente flexionadas.","Empuja las caderas hacia adelante para volver a la posición de pie, manteniendo la barra cerca del cuerpo.","Repite el número de repeticiones recomendado."],["La barra está guiada en una trayectoria recta — úsala para perfeccionar el patrón de bisagra.","No redondees la zona lumbar al bajar; detente al final del rango de los isquiotibiales."]],["sumo-deadlift","Peso Muerto Sumo","Una variante del peso muerto con postura amplia que desplaza el énfasis hacia glúteos, cuádriceps e interior de los muslos.","Pierna","Fuerza","Intermedio","Barra",false,["Glúteo mayor","Cuádriceps"],["Erectores espinales","Isquiotibiales"],6.0,"sumo-deadlift-start.webp","sumo-deadlift-peak.webp",["Párate con los pies más anchos que el ancho de los hombros, con los pies apuntando hacia afuera.","Agarra la barra entre las piernas.","Contrae el core y empuja a través de los talones para levantarte.","Baja de forma controlada.","Repite."],["Mantén la barra pegada al cuerpo.","Empuja las rodillas hacia afuera en línea con los dedos de los pies."]],["deadlift","Peso Muerto con Barra","Un levantamiento compuesto de cuerpo completo que trabaja principalmente la cadena posterior.","Espalda","Fuerza","Intermedio","Barra",false,["Erectores espinales","Glúteo mayor","Isquiotibiales"],["Cuádriceps","Trapecio"],6.0,"deadlift-start.webp","deadlift-peak.webp",["De pie con los pies a la anchura de las caderas y la barra sobre el medio del pie.","Bisagra en las caderas y agarra la barra.","Contrae el core y levanta extendiendo caderas y rodillas.","Ponte completamente erguido arriba y luego baja de forma controlada.","Repite."],["Mantén la barra cerca del cuerpo.","No redondees la zona lumbar."]],["hex-bar-deadlift","Peso Muerto con Barra Hexagonal","Un peso muerto de pie dentro de una barra hexagonal, manteniendo la carga centrada para un tirón más erguido y amable con la espalda.","Espalda","Fuerza","Intermedio","Barra hexagonal",false,["Erectores espinales","Glúteo mayor","Cuádriceps"],["Flexores del antebrazo","Isquiotibiales","Trapecio"],6.0,"hex-bar-deadlift-start.webp","hex-bar-deadlift-peak.webp",["Colócate dentro de una barra trampa cargada con los pies a la anchura de los hombros.","Flexiona caderas y rodillas para agarrar las asas.","Contrae el core y mantén la espalda plana.","Empuja con los talones y extiende caderas y rodillas para ponerte erguido.","Bloquea en la parte alta con los hombros hacia atrás.","Baja la barra al suelo de forma controlada."],["Mantén el pecho arriba y la espalda plana mientras ajustas el agarre.","Empuja el suelo en lugar de tirar de la barra con la espalda.","Ponte completamente erguido arriba sin inclinarte hacia atrás."]],["dumbbell-deadlift","Peso Muerto con Mancuernas","Un peso muerto con mancuernas que fortalece la cadena posterior mediante un patrón de bisagra de cadera.","Espalda","Fuerza","Intermedio","Mancuernas",false,["Erectores espinales","Glúteo mayor","Isquiotibiales"],["Dorsal ancho","Cuádriceps","Trapecio"],6.0,"dumbbell-deadlift-start.webp","dumbbell-deadlift-peak.webp",["Ponte de pie con las mancuernas frente a los muslos y los pies al ancho de las caderas.","Inclínate desde las caderas y baja las mancuernas a lo largo de las piernas con la espalda recta.","Mantén las mancuernas cerca de las espinillas durante el descenso.","Empuja a través de los talones para volver a la posición de pie.","Extiende completamente las caderas en la parte superior sin hiperlordosis lumbar.","Repite el número de repeticiones deseado."],["Empuja la cadera hacia atrás en lugar de redondear la espalda.","Mira al frente o ligeramente hacia abajo para alinear el cuello.","Levanta con las piernas y la cadera, no con la zona lumbar."]],["pause-deadlift","Peso Muerto con Pausa","Una variante del peso muerto con una pausa deliberada justo por debajo de las rodillas para desarrollar fuerza desde el suelo.","Espalda","Fuerza","Avanzado","Barra",false,["Erectores espinales","Glúteo mayor","Isquiotibiales"],["Cuádriceps","Trapecio"],6.0,"deadlift-start.webp","deadlift-peak.webp",["Colócate en posición de peso muerto convencional.","Levanta la barra del suelo y haz una pausa cuando pase por las rodillas.","Mantén la posición 2-3 segundos y luego completa el levantamiento.","Baja con control.","Repite."],["La pausa elimina el impulso y desarrolla la fuerza de inicio.","Mantén la espalda plana durante la pausa."]],["stiff-leg-deadlift","Peso Muerto con Piernas Rígidas","Una bisagra de cadera con las piernas casi rectas, bajando la barra a lo largo de los muslos para estirar y cargar los isquiotibiales.","Pierna","Fuerza","Intermedio","Barra",false,["Glúteo mayor","Isquiotibiales"],["Erectores espinales","Trapecio"],6.0,"stiff-leg-deadlift-start.webp","stiff-leg-deadlift-peak.webp",["Párate con los pies al ancho de las caderas, sosteniendo una barra frente a los muslos.","Mantén las piernas casi rectas con solo una ligera flexión de rodillas.","Inclínate en las caderas y baja la barra a lo largo de las piernas.","Baja hasta donde la flexibilidad de los isquiotibiales lo permita con la espalda plana.","Empuja a través de los talones para volver a la posición erguida.","Repite el número de repeticiones deseado."],["Lleva las caderas hacia atrás y mantén la barra cerca de las piernas.","Baja solo hasta donde te permita mantener la espalda plana.","Siente la carga en los isquiotibiales al estirar y luego empuja las caderas hacia delante para subir."]],["deficit-deadlift","Peso Muerto en Déficit","Un peso muerto ejecutado sobre una plataforma baja que amplía el recorrido y exige más a isquiotibiales y glúteos.","Espalda","Fuerza","Avanzado","Barra",false,["Erectores espinales","Glúteo mayor","Isquiotibiales"],["Dorsal ancho","Cuádriceps","Trapecio"],6.0,"deficit-deadlift-start.webp","deficit-deadlift-peak.webp",["De pie sobre una plataforma pequeña con una barra cargada sobre el medio del pie.","Bisagra hacia abajo y agarra la barra justo por fuera de las rodillas.","Empuja con las piernas para ponerte erguido manteniendo la barra cerca.","Bloquea caderas y rodillas en la parte superior.","Baja de forma controlada y repite."],["Mantén la columna neutra en todo el recorrido ampliado.","Usa menos peso del que mueves en tu peso muerto habitual.","Domina el peso muerto convencional antes de probar esta variante."]],["kettlebell-single-leg-deadlift","Peso muerto a una pierna con pesa rusa","Un peso muerto a una pierna con pesa rusa que fortalece glúteos e isquiotibiales y pone a prueba el equilibrio.","Pierna","Fuerza","Intermedio","Kettlebell",false,["Glúteo mayor","Isquiotibiales"],["Erectores espinales","Glúteo medio"],6.0,"kettlebell-single-leg-deadlift-start.webp","kettlebell-single-leg-deadlift-peak.webp",["Sostén una pesa rusa en una mano y párate en la pierna contraria.","Bisagra en la cadera y baja la pesa rusa hacia el suelo.","Extiende la pierna libre hacia atrás para mantener el equilibrio.","Baja hasta que el torso quede paralelo al suelo.","Empuja a través del talón de apoyo para volver a ponerte de pie.","Completa las repeticiones en un lado y luego cambia."],["Mantén la cadera cuadrada, sin abrirla hacia el lado libre.","Fija la mirada en un punto del suelo para equilibrarte mejor.","Flexiona ligeramente la rodilla de apoyo durante la bisagra."]],["kettlebell-deadlift","Peso muerto con pesa rusa","Un peso muerto con pesa rusa que fortalece glúteos, isquiotibiales y zona lumbar con un patrón de bisagra de cadera.","Espalda","Fuerza","Intermedio","Kettlebell",false,["Erectores espinales","Glúteo mayor","Isquiotibiales"],["Flexores del antebrazo","Cuádriceps"],6.0,"kettlebell-deadlift-start.webp","kettlebell-deadlift-peak.webp",["Párate con los pies a la anchura de los hombros y la pesa rusa entre los pies.","Bisagra en las caderas y flexiona las rodillas para agarrar el asa.","Contrae el core y mantén la espalda plana.","Empuja a través de los talones para ponerte de pie con la pesa rusa.","Bloquea en la parte superior con los hombros hacia atrás.","Baja la pesa rusa de vuelta al suelo con control."],["Mantén la pesa rusa cerca del cuerpo durante todo el recorrido.","Piensa en empujar el suelo con los talones, no en tirar con la espalda.","Lleva las caderas atrás, no las rodillas adelante, al bajar."]],["kettlebell-sumo-deadlift","Peso muerto sumo con pesa rusa","Un peso muerto con postura amplia usando una sola pesa rusa entre los pies. La postura amplia y la carga cerca del cuerpo hacen de este un patrón dominante de cuádriceps y glúteos que es fácil de aprender.","Pierna","Fuerza","Principiante","Kettlebell",false,["Glúteo mayor","Cuádriceps"],["Aductores","Erectores espinales","Isquiotibiales","Trapecio"],6.0,"kettlebell-sumo-deadlift-start.webp","kettlebell-sumo-deadlift-peak.webp",["Párate con una postura amplia y los pies ligeramente girados hacia afuera, con una pesa rusa en el suelo entre los pies.","Baja con la espalda plana, las rodillas alineadas con los pies, y agarra el asa con ambas manos.","Empuja el suelo y extiende caderas y rodillas juntas para ponerte de pie.","Aprieta los glúteos en la parte superior.","Baja la campana con control de vuelta al suelo empujando las caderas hacia atrás.","Repite el número recomendado de repeticiones."],["Las rodillas se alinean con los pies — no dejes que colapsen hacia adentro.","Los hombros permanecen por encima de las caderas en la parte inferior; si los hombros caen, estrecha la postura.","Mantén la campana cerca del cuerpo durante todo el levantamiento."]],["legs-up-the-wall","Piernas en la Pared","Una posición restaurativa con las caderas cerca de una pared y las piernas apoyadas en vertical, pensada para recuperar y no para esforzarse.","Pierna","Estiramiento","Principiante","Sin equipo",true,["Isquiotibiales"],["Erectores espinales"],1.5,"legs-up-the-wall-main.webp",null,["Siéntate de lado junto a una pared con una cadera en contacto con ella.","Sube las piernas por la pared mientras te tumbas, de modo que las caderas queden cerca de la base.","Deja las piernas apoyadas en la pared, los pies relajados y los brazos abiertos a los lados.","Permanece durante el tiempo indicado, respirando despacio.","Flexiona las rodillas y rueda hacia un lado para salir."],["Aleja las caderas unos centímetros de la pared si notas tirón en los isquiotibiales.","Coloca una manta doblada bajo la pelvis para una versión más suave y sostenida.","Mantén las piernas pasivas; esta posición no debe costar esfuerzo."]],["hanging-pike","Pike Colgado","Una elevación de piernas estricta colgado de la barra hasta tocarla: las piernas se mantienen rectas y los pies suben hasta las manos.","Core","Fuerza","Avanzado","Barra de dominadas",false,["Recto abdominal"],["Flexores del antebrazo","Flexores de cadera","Dorsal ancho"],4.5,"hanging-pike-start.webp","hanging-pike-peak.webp",["Cuélgate de una barra de dominadas con agarre prono a la anchura de los hombros.","Activa los dorsales y contrae el core para crear un cuerpo hueco.","Manteniendo las piernas completamente rectas, súbelas en un arco suave hasta la barra.","Intenta tocar los pies a la barra entre las manos.","Baja las piernas lentamente a la posición de cuelgue y repite."],["Sin balanceo: cada repetición empieza desde un cuelgue muerto con el tronco activado.","Si el rango completo es demasiado difícil, sube solo hasta la horizontal y ve progresando."]],["ball-pike","Pike con Pelota","Un ejercicio avanzado de core en el que las caderas se elevan mientras los pies ruedan una pelota suiza hacia el pecho.","Core","Fuerza","Avanzado","Pelota de estabilidad",false,["Oblicuos","Recto abdominal"],["Deltoides anterior","Flexores de cadera","Serrato anterior"],6.0,"ball-pike-start.webp","ball-pike-peak.webp",["Coloca las espinillas sobre una pelota suiza y las manos en el suelo en plancha alta.","Activa el core y mantén las piernas rectas.","Eleva las caderas, rodando la pelota hacia el pecho hasta formar una V invertida.","Pausa brevemente arriba.","Rueda la pelota de vuelta a la posición inicial de plancha."],["Mantén las piernas rectas todo el tiempo — sin doblar las rodillas.","Mueve desde la cadera, no desde la zona lumbar.","Trabaja primero con flexiones de rodilla si el pike es demasiado difícil."]],["plank","Plancha","Un ejercicio isométrico de core que fortalece toda la zona media.","Core","Fuerza","Principiante","Sin equipo",true,["Recto abdominal","Transverso abdominal"],["Erectores espinales"],3.5,"plank-main.webp",null,["Apoya los antebrazos en el suelo con los codos bajo los hombros.","Extiende las piernas hacia atrás y apóyate sobre los dedos de los pies.","Mantén el cuerpo en línea recta de la cabeza a los talones.","Contrae el core y aprieta los glúteos.","Mantén la posición durante el tiempo deseado.","Baja las rodillas para salir de la posición."],["No dejes que las caderas caigan ni se eleven.","Aprieta los glúteos y los cuádriceps."]],["high-plank","Plancha Alta","Una variación de plancha con los brazos totalmente extendidos en posición de push-up.","Core","Fuerza","Principiante","Sin equipo",true,["Recto abdominal","Transverso abdominal"],["Erectores espinales","Oblicuos"],5.0,"high-plank-main.webp",null,["Empieza en posición de push-up con los brazos totalmente extendidos.","Mantén el cuerpo en línea recta de cabeza a talones.","Contrae el core y mantén la posición.","Respira de forma regular durante el ejercicio."],["Coloca las manos directamente debajo de los hombros.","Aprieta glúteos y abdomen para que la cadera no caiga.","Mira al suelo para mantener el cuello neutro."]],["planche","Plancha Calisténica","Una posición avanzada de calistenia que requiere una fuerza excepcional del tren superior y el core para mantener el cuerpo paralelo al suelo.","Hombro","Fuerza","Avanzado","Sin equipo",true,["Deltoides anterior","Pectoral mayor"],["Serrato anterior","Tríceps braquial"],6.0,"planche-main.webp",null,["Comienza en posición de flexión con las manos giradas hacia afuera.","Inclínate hacia adelante hasta que tu centro de masa quede sobre las manos.","Levanta los pies del suelo manteniendo el cuerpo horizontal.","Mantén la posición.","Regresa al suelo con control."],["Progresa a través de la posición encogida, en estrella y la plancha completa.","Desarrolla la fuerza de muñecas y hombros antes de intentarlo."]],["reverse-plank","Plancha Inversa","Una plancha invertida isométrica con el pecho hacia arriba, que fortalece los glúteos y los erectores de la columna.","Espalda","Fuerza","Intermedio","Sin equipo",true,["Erectores espinales","Glúteo mayor"],["Isquiotibiales","Deltoides posterior","Tríceps braquial"],5.0,"reverse-plank-main.webp",null,["Siéntate en el suelo con las piernas extendidas al frente.","Coloca las manos detrás de ti con los dedos apuntando hacia los pies.","Eleva las caderas del suelo para formar una línea recta de la cabeza a los talones.","Aprieta los glúteos y contrae el core.","Mantén la posición durante el tiempo deseado.","Baja las caderas con control para salir."],["Mantén la cadera alta; si baja, descansa y repite.","No dejes caer la cabeza hacia atrás; alarga el cuello.","Reparte el peso entre talones y manos, con los hombros lejos de las orejas."]],["side-plank","Plancha Lateral","Una variación de plancha lateral que trabaja los oblicuos y el core lateral.","Core","Fuerza","Principiante","Sin equipo",true,["Oblicuos","Transverso abdominal"],["Glúteo medio","Recto abdominal"],3.5,"side-plank-main.webp",null,["Acuéstate de lado con el antebrazo en el suelo y el codo bajo el hombro.","Levanta las caderas del suelo formando una línea recta de la cabeza a los pies.","Mantén la posición con el core apretado.","Respira con regularidad.","Repite de ambos lados."],["No dejes que la cadera se hunda hacia el suelo.","Alinea hombros y cadera en un mismo plano, sin rotar el torso.","Empuja el suelo con el antebrazo para no colgarte del hombro."]],["side-plank-leg-lift","Plancha Lateral con Elevación de Pierna","Una plancha lateral con elevación de la pierna superior, que combina trabajo de core lateral con abducción de cadera.","Pierna","Fuerza","Intermedio","Sin equipo",true,["Glúteo medio","Oblicuos"],["Glúteo mayor","Recto abdominal","Transverso abdominal"],5.0,"side-plank-leg-lift-start.webp","side-plank-leg-lift-peak.webp",["Túmbate de lado con el antebrazo en el suelo y el codo bajo el hombro.","Coloca un pie sobre el otro y eleva las caderas hasta una plancha lateral.","Desde esta plancha lateral estable, sube la pierna de arriba recta hacia el techo.","Baja la pierna de forma controlada sin dejar caer las caderas.","Completa las repeticiones de un lado y luego cambia."],["Mantén las caderas elevadas toda la serie; no dejes que se hundan.","Guía la elevación de la pierna con el talón, no con la punta.","Mantén el cuerpo en una sola línea recta de la cabeza al pie de abajo."]],["side-plank-leg-lift-hold","Plancha Lateral con Elevación de Pierna Isométrica","Una plancha lateral sostenida con la pierna superior elevada: la cadera se mantiene alta y cuadrada mientras la pierna se separa, lo que añade una demanda de glúteo medio al trabajo lateral del tronco.","Pierna","Fuerza","Intermedio","Sin equipo",true,["Glúteo medio","Oblicuos"],["Glúteo mayor","Recto abdominal","Transverso abdominal"],5.0,"side-plank-leg-lift-hold-main.webp",null,["Colócate en plancha lateral sobre el antebrazo, con el codo bajo el hombro y los pies apilados.","Eleva la cadera hasta que el cuerpo forme una línea recta desde los tobillos hasta la cabeza.","Sube la pierna superior aproximadamente a la altura de la cadera, con los dedos del pie al frente.","Mantén la posición durante el tiempo indicado, con la cadera alta y el hombro alineado sobre el codo.","Baja la pierna y la cadera de forma controlada y repite del otro lado."],["Aleja del oído el hombro de apoyo para que el pecho no se venga abajo hacia el suelo.","Termina la serie cuando la cadera empiece a caer, no cuando se canse la pierna.","Apoya la rodilla inferior en el suelo para una versión más sencilla que conserva la elevación de pierna."]],["trx-side-plank","Plancha Lateral en TRX","Una plancha lateral con los pies en el TRX, que trabaja los oblicuos y la estabilidad de la cadera.","Core","Fuerza","Intermedio","Entrenador de suspensión (TRX)",false,["Oblicuos","Transverso abdominal"],["Glúteo medio","Deltoides lateral"],6.0,"trx-side-plank-main.webp",null,["Coloca ambos pies en los soportes del TRX y recuéstate de lado.","Apóyate en el antebrazo inferior con el codo bajo el hombro.","Eleva las caderas de modo que el cuerpo forme una línea recta.","Apila el pie superior sobre el pie inferior.","Mantén la posición respirando de forma constante.","Baja y cambia de lado al terminar la serie."],["Coloca el codo justo debajo del hombro de apoyo.","Eleva la cadera hasta formar una línea recta.","Respira de forma constante y cambia de lado al terminar."]],["trx-plank","Plancha en TRX","Una plancha con los pies suspendidos en el TRX, que aumenta la demanda sobre el core y la estabilidad.","Core","Fuerza","Intermedio","Entrenador de suspensión (TRX)",false,["Recto abdominal","Transverso abdominal"],["Deltoides anterior","Oblicuos"],6.0,"trx-plank-main.webp",null,["Coloca ambos pies en los estribos del TRX.","Adopta una posición de plancha en antebrazos o plancha alta en el suelo.","Mantén el cuerpo en línea recta de la cabeza a los talones.","Contrae el core y aprieta los glúteos.","Mantén la posición el tiempo deseado.","Baja las rodillas para salir de forma segura."],["Mantén el cuerpo en línea recta de la cabeza a los talones.","Aprieta abdomen y glúteos durante toda la retención.","Evita que la cadera se hunda o se eleve."]],["v-sit","Posición en V","Un sostén estático del core en equilibrio sobre los isquiones, con las piernas y el torso elevados formando una V, que exige a los abdominales y los flexores de cadera.","Pierna","Fuerza","Intermedio","Sin equipo",true,["Flexores de cadera","Recto abdominal"],["Oblicuos","Cuádriceps"],5.0,"v-sit-main.webp",null,["Siéntate en el suelo con las piernas extendidas frente a ti.","Inclínate ligeramente hacia atrás y eleva las piernas del suelo.","Extiende los brazos hacia adelante para que el cuerpo forme una V.","Equilíbrate sobre los isquiones con el core firme.","Mantén la posición respirando de forma constante.","Baja las piernas y el torso para salir."],["Mantén el pecho elevado y la columna larga en lugar de redondear la espalda.","Flexiona las rodillas si aún no puedes mantener las piernas estiradas."]],["easy-pose","Postura Fácil","Un sencillo sentado con las piernas cruzadas para respirar y meditar: la pelvis se mantiene erguida, la columna larga y las caderas se asientan sin tensión.","Espalda","Estiramiento","Principiante","Sin equipo",true,["Erectores espinales"],["Aductores","Glúteo medio"],1.5,"easy-pose-main.webp",null,["Siéntate en el suelo y cruza las espinillas con comodidad, cada pie bajo la rodilla contraria.","Elévate sobre una manta doblada o un cojín hasta que las rodillas queden por debajo de las caderas.","Alinea las costillas sobre la pelvis y deja las manos sobre los muslos.","Mantén el sentado durante el tiempo indicado, respirando lenta y regularmente.","Cambia qué espinilla queda delante en la siguiente ronda para repartir el tiempo entre ambos lados."],["Si las rodillas quedan altas, sube la altura del asiento en lugar de forzarlas hacia abajo.","Mantén la barbilla nivelada para que el cuello siga la línea de la columna.","Apoya las rodillas sobre cojines cuando un sentado largo se vuelva incómodo."]],["head-to-knee-pose","Postura de Cabeza a la Rodilla","Una flexión sentada sobre una pierna: una queda estirada y el otro pie se apoya en la cara interna del muslo, de modo que el isquiotibial se alarga de lado en lado.","Espalda","Estiramiento","Principiante","Sin equipo",true,["Erectores espinales","Isquiotibiales"],["Aductores","Glúteo mayor"],5.0,"head-to-knee-pose-main.webp",null,["Siéntate con una pierna estirada al frente y la otra rodilla abierta al lado, con ese pie en la cara interna del muslo.","Gira el pecho hacia la pierna estirada para que el ombligo quede alineado con el muslo.","Bascula desde las caderas y alcanza hacia delante a lo largo de la pierna con la columna larga.","Mantén la flexión durante el tiempo indicado, respirando hacia la parte posterior de la pierna.","Sube con la espalda plana y repite del otro lado."],["Siéntate sobre una manta doblada para que la pelvis pueda bascular en lugar de redondear la espalda.","Mantén los dedos del pie estirado apuntando hacia arriba en lugar de dejarlos caer hacia fuera.","Usa una cinta alrededor del pie cuando las manos no lleguen con comodidad."]],["cow-face-pose","Postura de la Cara de Vaca","Una postura sentada con las rodillas apiladas y los brazos enlazados a la espalda, que estira la cadera externa de un lado y los hombros en direcciones opuestas.","Pierna","Estiramiento","Principiante","Sin equipo",true,["Glúteo mayor","Glúteo medio"],["Deltoides posterior","Tríceps braquial"],5.0,"cow-face-pose-main.webp",null,["Siéntate en el suelo y cruza una rodilla justo encima de la otra para que queden apiladas en la línea media.","Camina los pies hacia las caderas y apoya ambos isquiones por igual.","Sube el brazo del lado de la rodilla superior y flexiónalo por detrás de la cabeza; sube el otro brazo por la espalda hasta engancharlos.","Mantén la posición durante el tiempo indicado, con el pecho abierto y la columna larga.","Suelta y repite con la otra pierna y el otro brazo arriba."],["Siéntate sobre una manta doblada si un isquion se despega del suelo.","Usa una cinta entre las manos cuando los dedos no se toquen; forzar el enganche redondea la espalda.","Mantén el codo de arriba apuntando al techo en lugar de dejarlo abrirse hacia el lado."]],["sphinx-pose","Postura de la Esfinge","Una extensión suave boca abajo sobre los antebrazos: los codos quedan bajo los hombros y el pecho se eleva, de modo que la zona lumbar se extiende sin esfuerzo de los brazos.","Espalda","Estiramiento","Principiante","Sin equipo",true,["Erectores espinales"],["Flexores de cadera","Pectoral mayor"],5.0,"sphinx-pose-main.webp",null,["Túmbate boca abajo y apoya los antebrazos en el suelo con los codos justo bajo los hombros.","Presiona los antebrazos y el empeine contra el suelo y eleva el pecho.","Aleja los hombros de las orejas y alarga la nuca.","Mantén la posición durante el tiempo indicado, respirando hacia la parte frontal del pecho.","Baja el pecho al suelo y descansa."],["Desliza los codos algo hacia delante para una extensión más suave, o hacia atrás para una más profunda.","Mantén los glúteos blandos para que la zona lumbar no se apriete.","Quédate donde se siente estiramiento, no pinzamiento."]],["garland-pose","Postura de la Guirnalda","Una sentadilla profunda sostenida con los talones apoyados y los codos empujando las rodillas hacia fuera, usada para abrir caderas, tobillos y zona lumbar.","Pierna","Estiramiento","Principiante","Sin equipo",true,["Aductores","Glúteo mayor"],["Cuádriceps","Sóleo"],5.0,"garland-pose-main.webp",null,["Ponte de pie con los pies algo más separados que las caderas y las puntas ligeramente hacia fuera.","Baja en cuclillas todo lo que permitan los tobillos, manteniendo los talones en el suelo.","Junta las palmas frente al pecho y presiona los codos contra la cara interna de las rodillas.","Mantén la posición durante el tiempo indicado, con el pecho alto y la columna larga.","Empuja con los pies para volver a ponerte de pie."],["Coloca una toalla enrollada bajo los talones si se levantan; forzarlos redondea la zona lumbar.","Abre más los pies para dejar espacio a la pelvis en lugar de encajarte en una sentadilla estrecha.","Presiona ligeramente rodillas y codos entre sí para que el pecho no se hunda."]],["half-moon-pose","Postura de la Media Luna","Un equilibrio lateral de pie sobre una pierna y una mano, con la pierna de arriba elevada a la altura de la cadera y el pecho abierto hacia el techo.","Pierna","Fuerza","Avanzado","Sin equipo",true,["Glúteo medio","Oblicuos"],["Erectores espinales","Cuádriceps"],5.0,"half-moon-pose-main.webp",null,["Desde una base amplia, flexiona la rodilla delantera y apoya la mano de abajo en el suelo o un bloque por delante de ese pie.","Desplaza el peso hacia delante y eleva la pierna trasera hasta dejarla paralela al suelo.","Estira la pierna de apoyo y apila la cadera de arriba sobre la de abajo, con el brazo superior hacia el techo.","Mantén el equilibrio durante el tiempo indicado, con el pie elevado en flexión.","Baja el pie trasero y repite del otro lado."],["Usa un bloque bajo la mano de abajo; llegar al suelo no es el objetivo de la postura.","Empuja el talón elevado hacia la pared de detrás para mantener la pierna activa.","Mira al suelo en lugar de hacia arriba si el equilibrio se rompe una y otra vez."]],["mountain-pose","Postura de la Montaña","La postura básica de pie: pies enraizados, piernas activas, columna larga y hombros relajados. Es la referencia de alineación con la que se miden las demás posturas de pie.","Cuerpo completo","Estiramiento","Principiante","Sin equipo",true,["Erectores espinales"],["Gemelos","Cuádriceps"],2.0,"mountain-pose-main.webp",null,["Ponte de pie con los pies a la anchura de las caderas y reparte el peso por igual entre ambos.","Activa ligeramente los muslos y deja caer el coxis para que la pelvis quede neutra.","Alinea las costillas sobre la pelvis y la cabeza sobre las costillas, con los brazos relajados a los lados.","Mantén la postura durante el tiempo indicado, respirando con regularidad.","Observa dónde queda el peso y devuélvelo al centro de cada pie."],["Levanta y abre los dedos de los pies una vez y vuelve a apoyarlos; eso reinicia el arco del pie.","Mantén las rodillas blandas en lugar de bloquearlas.","Deja que los hombros roten atrás y abajo sin apretar las escápulas entre sí."]],["pyramid-pose","Postura de la Pirámide","Una flexión de pie sobre la pierna delantera estirada en un paso corto, que aísla el isquiotibial de esa pierna mientras ambas caderas quedan cuadradas.","Pierna","Estiramiento","Intermedio","Sin equipo",true,["Isquiotibiales"],["Erectores espinales","Gemelos"],5.0,"pyramid-pose-main.webp",null,["Lleva un pie atrás cerca del largo de una pierna y gíralo ligeramente hacia fuera.","Cuadra ambas caderas hacia el frente de la esterilla y mantén las dos piernas estiradas.","Bascula desde las caderas y flexiona sobre la pierna delantera, llevando las manos al suelo, a bloques o a la espinilla.","Mantén la flexión durante el tiempo indicado, con la columna larga en lugar de redondeada.","Empuja con los pies para subir y repite del otro lado."],["Acorta el paso hasta que ambas caderas puedan mirar al frente; la longitud vale menos que las caderas cuadradas.","Usa bloques bajo las manos para que el pecho siga acercándose a la espinilla.","Deja una micro flexión en la rodilla delantera si el isquiotibial se agarrota."]],["chair-pose","Postura de la Silla","Un sostén de pie con las caderas hacia atrás y los brazos arriba, donde el cuádriceps y la espalda alta trabajan de forma isométrica contra el peso corporal.","Pierna","Fuerza","Principiante","Sin equipo",true,["Glúteo mayor","Cuádriceps"],["Deltoides anterior","Erectores espinales"],5.0,"chair-pose-main.webp",null,["Ponte de pie con los pies juntos o a la anchura de las caderas y el peso en los talones.","Flexiona las rodillas y lleva las caderas atrás como si fueras a sentarte en una silla.","Eleva los brazos junto a las orejas sin dejar que las costillas se abran.","Mantén la posición durante el tiempo indicado, con el pecho alto y las rodillas siguiendo la línea de los pies.","Empuja con los talones para volver a ponerte de pie."],["Deja suficiente peso en los talones como para poder levantar los dedos de los pies.","Lleva los brazos algo más adelante si subirlos del todo te arquea la zona lumbar.","Baja más para exigir al cuádriceps, pero solo mientras los talones sigan apoyados."]],["revolved-chair-pose","Postura de la Silla Girada","La postura de la silla con una torsión cerrada: las caderas se mantienen bajas y niveladas mientras el pecho rota y un codo se engancha por fuera del muslo contrario.","Core","Fuerza","Intermedio","Sin equipo",true,["Oblicuos","Cuádriceps"],["Erectores espinales","Glúteo mayor"],5.0,"revolved-chair-pose-main.webp",null,["Colócate en la postura de la silla con las rodillas flexionadas, las caderas atrás y las palmas juntas frente al pecho.","Mantén las rodillas a la misma altura para que las caderas no se abran hacia la torsión.","Gira el pecho hacia un lado y engancha el codo contrario por fuera de ese muslo.","Presiona las palmas entre sí y mantén durante el tiempo indicado, alargando la columna en cada inhalación.","Vuelve al centro y repite del otro lado."],["Alinea las rodillas antes de girar; una rodilla que se adelanta finge la mayor parte de la rotación.","Gira desde la zona media de la espalda en lugar de hacer palanca con el brazo contra la pierna.","Mantén el peso en los talones para que la postura siga siendo una sentadilla y no una inclinación."]],["plow-pose","Postura del Arado","Una inversión en la que las piernas pasan por encima de la cabeza hasta que los dedos de los pies llegan al suelo por detrás, alargando toda la parte posterior del cuerpo.","Espalda","Estiramiento","Intermedio","Sin equipo",true,["Erectores espinales","Isquiotibiales"],["Glúteo mayor","Trapecio"],5.0,"plow-pose-main.webp",null,["Túmbate boca arriba con los brazos junto al cuerpo y las palmas hacia abajo.","Eleva ambas piernas por encima de la cabeza y sostén la zona lumbar con las manos.","Baja los dedos de los pies hacia el suelo por detrás de la cabeza, con las piernas tan estiradas como resulte cómodo.","Mantén la posición durante el tiempo indicado, respirando con calma y sin mover la cabeza.","Desciende vértebra a vértebra con las manos sosteniendo la espalda."],["Nunca gires la cabeza dentro de la postura; el cuello está cargado y debe quedar neutro.","Apoya los dedos de los pies en una silla o unos cojines si el suelo queda lejos.","Evita esta postura por completo si tienes molestias cervicales."]],["bow-pose","Postura del Arco","Una extensión en decúbito prono: las manos sujetan los tobillos y las piernas empujan contra ellas, elevando pecho y muslos del suelo y activando toda la cadena posterior.","Espalda","Fuerza","Intermedio","Sin equipo",true,["Erectores espinales","Glúteo mayor"],["Isquiotibiales","Pectoral mayor"],5.0,"bow-pose-main.webp",null,["Túmbate boca abajo con los brazos junto al cuerpo y la frente apoyada en la esterilla.","Flexiona las rodillas y agarra la parte externa de ambos tobillos.","Empuja las espinillas contra las manos para que el pecho y los muslos se despeguen del suelo.","Mantén la posición elevada durante el tiempo indicado, con el cuello largo y la mirada al frente.","Suelta los tobillos y baja de forma controlada."],["La elevación viene de las piernas empujando contra las manos, no de tirar con los brazos.","Mantén las rodillas a la anchura de las caderas en lugar de dejarlas abrirse.","Si notas pinzamiento en los hombros, eleva menos y prioriza mantener el pecho abierto."]],["dancer-pose","Postura del Bailarín","Un equilibrio de pie sobre una pierna en el que el pie libre se sujeta por detrás y empuja hacia atrás, combinando extensión de columna y sostén unipodal.","Pierna","Fuerza","Avanzado","Sin equipo",true,["Glúteo mayor","Cuádriceps"],["Erectores espinales","Flexores de cadera"],5.0,"dancer-pose-main.webp",null,["Ponte de pie y pasa el peso a un pie, con esa rodilla ligeramente flexionada.","Flexiona la otra rodilla y agarra la cara interna de ese tobillo por detrás.","Empuja el pie elevado contra la mano y estira el brazo contrario hacia delante mientras el pecho sube.","Mantén la forma durante el tiempo indicado, con la cadera de apoyo nivelada y la mirada fija.","Suelta el pie y repite del otro lado."],["Fija los ojos en un punto; una mirada que se mueve es lo primero que rompe el equilibrio.","Mantén la rodilla elevada en línea con la cadera en lugar de dejarla abrirse hacia fuera.","Usa una cinta alrededor del pie si el hombro no permite el agarre directo."]],["boat-pose","Postura del Barco","Un equilibrio sentado sobre los isquiones con las piernas elevadas y el pecho alto: la forma de V carga los flexores de la cadera y toda la parte frontal del tronco.","Pierna","Fuerza","Intermedio","Sin equipo",true,["Flexores de cadera","Recto abdominal"],["Erectores espinales","Cuádriceps"],5.0,"boat-pose-main.webp",null,["Siéntate en el suelo con las rodillas flexionadas y los pies apoyados, las manos detrás de los muslos.","Inclínate hacia atrás hasta equilibrarte justo por detrás de los isquiones y eleva el pecho para mantener la columna larga.","Sube las espinillas hasta dejarlas paralelas al suelo y estira las piernas todo lo que la espalda pueda mantenerse plana.","Extiende los brazos hacia delante junto a las piernas y mantén la posición durante el tiempo indicado.","Baja los pies de forma controlada para terminar."],["Mantén el pecho alto; en cuanto la espalda se redondee, vuelve a flexionar las rodillas.","Sujétate por detrás de los muslos si los isquiotibiales te limitan más que el core.","Respira de forma constante en lugar de aguantar el aire."]],["happy-baby","Postura del Bebé Feliz","Una apertura de cadera boca arriba en la que las rodillas se acercan a las axilas y los pies se sujetan por fuera, liberando la cara interna de los muslos y la zona lumbar.","Pierna","Estiramiento","Principiante","Sin equipo",true,["Aductores","Glúteo mayor"],["Erectores espinales","Isquiotibiales"],5.0,"happy-baby-main.webp",null,["Túmbate boca arriba y acerca ambas rodillas al pecho.","Agarra los bordes externos de los pies, o las espinillas si los pies quedan lejos.","Abre las rodillas más allá de las costillas y coloca los tobillos sobre las rodillas, con las plantas hacia arriba.","Empuja suavemente los pies contra las manos y mantén durante el tiempo indicado, con la zona lumbar en el suelo.","Suelta los pies y baja las piernas."],["Mantén el coxis pesado en el suelo en lugar de rodar hacia la espalda alta.","Agarra las espinillas o usa una cinta si el agarre despega los hombros de la esterilla.","Balancéate suavemente de lado a lado si notas tensión en la zona lumbar."]],["puppy-pose","Postura del Cachorro","Una postura de rodillas a medio camino entre la postura del niño y el perro boca abajo: las caderas quedan sobre las rodillas mientras el pecho se acerca al suelo, abriendo hombros y espalda alta.","Espalda","Estiramiento","Principiante","Sin equipo",true,["Dorsal ancho","Deltoides posterior"],["Erectores espinales","Trapecio"],5.0,"puppy-pose-main.webp",null,["Colócate a cuatro apoyos con las caderas sobre las rodillas y las manos bajo los hombros.","Camina las manos hacia delante y baja el pecho hacia el suelo manteniendo las caderas altas.","Apoya la frente o la barbilla en la esterilla y deja que las axilas se ablanden hacia abajo.","Mantén la posición durante el tiempo indicado, respirando hacia la espalda alta.","Camina las manos de vuelta y siéntate sobre los talones para salir."],["Mantén las caderas sobre las rodillas; sentarte atrás convierte esto en la postura del niño.","Presiona las palmas hacia abajo y despega los codos del suelo para que los brazos sigan activos.","Apoya la frente en un bloque si el pecho no baja con comodidad."]],["savasana","Postura del Cadáver","El descanso final de una práctica: tumbado boca arriba con el cuerpo completamente pasivo, dejando que los efectos de la sesión se asienten.","Cuerpo completo","Estiramiento","Principiante","Sin equipo",true,["Erectores espinales"],[],1.3,"savasana-main.webp",null,["Túmbate boca arriba con las piernas cómodamente separadas y los pies cayendo hacia fuera.","Deja los brazos algo separados del cuerpo con las palmas hacia arriba.","Permite que todo el cuerpo se ablande contra el suelo, incluidos la mandíbula, los ojos y las manos.","Permanece durante el tiempo indicado, respirando con naturalidad y sin controlar la respiración.","Flexiona las rodillas y rueda hacia un lado antes de incorporarte despacio."],["Coloca un bolster bajo las rodillas si la zona lumbar no termina de asentarse.","Cúbrete con una manta; el cuerpo se enfría rápido en cuanto deja de moverse.","Esta postura no debe costar ningún esfuerzo: resiste el impulso de reajustarte constantemente."]],["camel-pose","Postura del Camello","Una extensión de rodillas que abre la parte frontal de las caderas, el abdomen y el pecho, con las manos apoyadas en los talones o en la zona lumbar.","Espalda","Estiramiento","Intermedio","Sin equipo",true,["Erectores espinales","Flexores de cadera"],["Pectoral mayor","Cuádriceps"],5.0,"camel-pose-main.webp",null,["Arrodíllate con las rodillas a la anchura de las caderas y las caderas alineadas sobre ellas.","Coloca las manos en la parte posterior de la pelvis con los dedos hacia abajo y eleva el pecho.","Empuja las caderas hacia delante y arquéate hacia atrás, buscando los talones si la posición sigue cómoda.","Mantén la postura durante el tiempo indicado, con el cuello en línea con la columna.","Devuelve las manos a la pelvis y sube liderando con el pecho."],["Mantén las caderas sobre las rodillas; si se van hacia atrás, la postura se derrumba.","Apoya los dedos de los pies y coloca las manos sobre los talones elevados si el alcance completo es demasiado.","Sal despacio: levantar primero la cabeza es lo que suele marear."]],["crow-pose","Postura del Cuervo","Un equilibrio sobre brazos: las rodillas descansan en la parte posterior de los brazos y los pies se elevan, sostenidos por hombros, brazos y tronco.","Hombro","Fuerza","Avanzado","Sin equipo",true,["Deltoides anterior","Tríceps braquial"],["Recto abdominal","Serrato anterior"],5.0,"crow-pose-main.webp",null,["Ponte en cuclillas con los pies juntos y apoya las palmas en el suelo a la anchura de los hombros.","Flexiona los codos hacia atrás y coloca las rodillas altas sobre la parte posterior de los brazos.","Desplaza el peso hacia delante sobre las manos hasta que los pies se despeguen del suelo.","Mantén el equilibrio durante el tiempo indicado, con la espalda alta redondeada y la mirada algo adelante.","Baja los pies de forma controlada."],["Mira al suelo por delante de las manos, no hacia los pies; la mirada dirige el equilibrio.","Coloca un cojín delante mientras aprendes, para caer hacia delante sin riesgo.","Agarra el suelo con las yemas de los dedos para que el peso no se vaya a las muñecas."]],["dolphin-pose","Postura del Delfín","Una V invertida sostenida sobre los antebrazos: las caderas suben hacia el techo mientras los hombros asumen la carga, la preparación estándar para las inversiones sobre antebrazos.","Hombro","Fuerza","Intermedio","Sin equipo",true,["Deltoides anterior","Trapecio"],["Isquiotibiales","Serrato anterior"],5.0,"dolphin-pose-main.webp",null,["Arrodíllate y apoya los antebrazos en el suelo a la anchura de los hombros, con los codos bajo los hombros.","Mete los dedos de los pies y eleva las caderas arriba y atrás hasta formar una V invertida.","Presiona los antebrazos contra el suelo y aleja los hombros de las orejas; los talones pueden quedar altos.","Mantén la posición durante el tiempo indicado, con el cuello relajado entre los brazos.","Baja las rodillas al suelo para salir."],["Evita que los codos se abran; una cinta alrededor de los brazos mantiene la distancia.","Flexiona bien las rodillas para que la columna siga larga en lugar de perseguir piernas rectas.","Acerca un poco los pies a los codos para llevar más peso a los hombros."]],["hero-pose","Postura del Héroe","Un sentado de rodillas en el que las caderas descienden entre los talones, alargando el cuádriceps y la parte frontal de los tobillos mientras la columna se mantiene erguida.","Pierna","Estiramiento","Principiante","Sin equipo",true,["Cuádriceps"],["Erectores espinales","Flexores de cadera"],1.5,"hero-pose-main.webp",null,["Arrodíllate con las rodillas juntas y los pies algo más separados que las caderas, con el empeine apoyado.","Baja las caderas entre los talones, usando un bloque o cojín si el suelo queda lejos.","Alinea las costillas sobre la pelvis y apoya las manos en los muslos.","Mantén el sentado durante el tiempo indicado, con el peso repartido entre ambos isquiones.","Sal apoyándote en las manos y estirando una pierna cada vez."],["Siéntate sobre un bloque en cuanto las rodillas protesten; la altura forma parte normal de la postura.","Coloca una toalla enrollada bajo los tobillos si notas tensión en su parte frontal.","Mantén los pies apuntando hacia atrás en lugar de abrirlos hacia los lados."]],["childs-pose","Postura del Niño","Un estiramiento de descanso de rodillas que alarga los dorsales, la zona lumbar y los hombros con los brazos al frente.","Espalda","Estiramiento","Principiante","Sin equipo",true,["Erectores espinales","Dorsal ancho"],["Trapecio"],5.0,"childs-pose-main.webp",null,["Arrodíllate y lleva la cadera hacia los talones.","Inclina el torso hacia adelante sobre los muslos.","Extiende ambos brazos largos sobre el suelo al frente.","Mantén de 20 a 30 segundos, respirando de forma constante."],["Abre más las rodillas para apoyar el pecho más abajo.","Relájate y sigue respirando todo el tiempo."]],["bench-childs-pose","Postura del Niño en Banco","Un estiramiento de rodillas con los brazos sobre el banco, llevando la cadera atrás para alargar los dorsales y la zona lumbar.","Espalda","Estiramiento","Principiante","Banco plano",false,["Erectores espinales","Dorsal ancho"],[],5.0,"bench-childs-pose-main.webp",null,["Arrodíllate en el suelo frente a un banco.","Extiende ambos brazos al frente y apóyalos en el banco.","Lleva la cadera hacia los talones y deja caer el pecho.","Mantén de 20 a 30 segundos, respirando de forma constante."],["Mantén los brazos estirados y relaja el cuello.","Relájate y sigue respirando todo el tiempo."]],["fish-pose","Postura del Pez","Una extensión boca arriba apoyada en los antebrazos, con el pecho elevado y la cabeza inclinada atrás, que abre la parte frontal del pecho y la garganta.","Espalda","Estiramiento","Intermedio","Sin equipo",true,["Erectores espinales","Pectoral mayor"],["Deltoides anterior","Flexores de cadera"],5.0,"fish-pose-main.webp",null,["Túmbate boca arriba con las piernas estiradas y los brazos junto al cuerpo, las palmas bajo las caderas.","Presiona los antebrazos contra el suelo y eleva el pecho hacia el techo.","Deja que la coronilla apoye ligeramente en el suelo sin cargar peso en el cuello.","Mantén la posición durante el tiempo indicado, respirando hacia la parte alta del pecho.","Levanta la cabeza y baja la espalda al suelo."],["El peso va en los antebrazos, no en la cabeza; el cuello solo guía la posición.","Coloca un bloque a lo largo bajo la espalda alta si la versión en el suelo pincha.","Mantén las piernas activas y los muslos rotando ligeramente hacia dentro."]],["locust-pose","Postura del Saltamontes","Un sostén boca abajo en el que pecho, brazos y piernas se despegan del suelo, de modo que toda la cadena posterior trabaja de forma isométrica sin carga externa.","Espalda","Fuerza","Principiante","Sin equipo",true,["Erectores espinales","Glúteo mayor"],["Isquiotibiales","Deltoides posterior"],5.0,"locust-pose-main.webp",null,["Túmbate boca abajo con los brazos junto al cuerpo y la frente en la esterilla.","Alarga la nuca y estira las yemas de los dedos hacia los pies.","Eleva a la vez el pecho, los brazos y ambas piernas.","Mantén la posición elevada durante el tiempo indicado, con la mirada hacia el suelo.","Baja todo a la vez y descansa."],["Eleva desde el alargamiento de la columna en lugar de tirar de la cabeza hacia arriba.","Mantén las piernas a la anchura de las caderas y las rodillas estiradas.","Empieza elevando solo las piernas y añade el pecho después si la versión completa es demasiado."]],["triangle-pose","Postura del Triángulo","Una postura de base amplia con ambas piernas estiradas y el torso inclinándose lateralmente sobre la pierna delantera, que alarga el isquiotibial y todo el costado.","Pierna","Estiramiento","Intermedio","Sin equipo",true,["Isquiotibiales","Oblicuos"],["Aductores","Glúteo medio"],5.0,"triangle-pose-main.webp",null,["Sepárate en una base amplia con el pie delantero girado hacia fuera y el trasero algo hacia dentro.","Mantén ambas piernas estiradas y estira la mano delantera hacia delante mientras las caderas van atrás.","Inclínate lateralmente y lleva la mano de abajo a la espinilla, un bloque o el suelo, con el brazo de arriba hacia el techo.","Mantén la posición durante el tiempo indicado, girando el pecho hacia el techo.","Empuja con los pies para subir y repite del otro lado."],["Alárgate primero sobre la pierna delantera antes de inclinarte; bajar demasiado pronto derrumba la postura.","Usa un bloque bajo la mano de abajo en lugar de arrastrar el pecho hacia el suelo.","Mantén ambas piernas estiradas y las rótulas activas."]],["eagle-pose","Postura del Águila","Un equilibrio de pie con una pierna enroscada sobre la otra y los brazos entrelazados frente al pecho, sosteniendo una forma estrecha y compacta sobre una pierna flexionada.","Pierna","Fuerza","Intermedio","Sin equipo",true,["Glúteo medio","Cuádriceps"],["Deltoides posterior","Trapecio"],5.0,"eagle-pose-main.webp",null,["Ponte de pie, flexiona ligeramente ambas rodillas y pasa el peso a un pie.","Cruza el otro muslo sobre el muslo de apoyo y engancha el pie por detrás de la pantorrilla si llega.","Cruza el brazo contrario por debajo, enrosca los antebrazos y acerca las palmas.","Baja un poco sobre la pierna de apoyo y mantén durante el tiempo indicado, con los codos elevados.","Desenrosca y repite del otro lado."],["Deja el pie cruzado sobre un bloque o el suelo si engancharlo tras la pantorrilla no es posible.","Sube los codos a la altura de los hombros para que la espalda alta trabaje en lugar de hundirse.","Baja más solo mientras la rodilla de apoyo siga sobre el centro del pie."]],["tree-pose","Postura del Árbol","Un equilibrio de pie sobre una pierna con la planta del pie libre apoyada en la pantorrilla o el muslo interno y las caderas niveladas.","Pierna","Fuerza","Intermedio","Sin equipo",true,["Glúteo medio","Cuádriceps"],["Erectores espinales","Sóleo"],5.0,"tree-pose-main.webp",null,["Ponte de pie y pasa el peso a un pie.","Apoya la planta del otro pie en la cara interna de la pantorrilla o del muslo, evitando la rodilla.","Presiona el pie y la pierna entre sí y nivela las caderas.","Lleva las manos al pecho o por encima de la cabeza y mantén durante el tiempo indicado.","Baja el pie y repite del otro lado."],["No apoyes nunca el pie contra el lateral de la rodilla; solo por encima o por debajo.","Fija la mirada en un punto quieto para estabilizar el equilibrio.","Mantén la pelvis mirando al frente en lugar de dejar que la rodilla elevada la abra."]],["hang-power-clean","Power Clean desde Colgante","Una cargada desde el colgado recibida en una sentadilla parcial, que desarrolla potencia explosiva sin bajar a una sentadilla completa.","Cuerpo completo","Halterofilia","Intermedio","Barra",false,["Glúteo mayor","Cuádriceps","Trapecio"],["Erectores espinales","Isquiotibiales"],8.0,"hang-power-clean-start.webp","hang-power-clean-peak.webp",["De pie con los pies a la anchura de las caderas sujetando la barra a la altura de los muslos.","Realiza una bisagra de cadera para bajar la barra justo por encima de las rodillas.","Extiende caderas y piernas de forma explosiva.","Tira de la barra hacia arriba y recíbela sobre los deltoides frontales en una sentadilla parcial.","Ponte erguido con la barra apoyada en los hombros.","Baja la barra de vuelta a la posición de colgante."],["Impulsa con caderas y piernas antes de que tiren los brazos.","Recibe la barra con los muslos por encima de la paralela.","Mantén la espalda plana al flexionar hacia la posición inicial."]],["leg-press","Prensa de Piernas","Un movimiento compuesto en máquina para cuádriceps y glúteos.","Pierna","Fuerza","Principiante","Prensa de piernas",false,["Glúteo mayor","Cuádriceps"],["Isquiotibiales"],6.0,"leg-press-start.webp","leg-press-peak.webp",["Siéntate en la prensa de piernas con los pies a la anchura de los hombros sobre la plataforma.","Suelta los seguros y baja la plataforma doblando las rodillas.","Empuja la plataforma hacia arriba hasta que las piernas queden casi rectas.","No bloquees las rodillas en la parte superior.","Repite."],["Mantén la zona lumbar pegada al respaldo en todo momento.","Baja solo hasta donde la cadera no se despegue.","Alinea las rodillas con las puntas de los pies."]],["single-leg-press","Prensa de Piernas a Una Pierna","Un ejercicio de tren inferior en una máquina de prensa, empujando la plataforma con una pierna a la vez.","Pierna","Fuerza","Intermedio","Prensa de piernas",false,["Glúteo mayor","Cuádriceps"],["Isquiotibiales"],6.0,"single-leg-press-start.webp","single-leg-press-peak.webp",["Siéntate en la máquina de prensa con un pie sobre la plataforma.","Mantén la otra pierna fuera de la plataforma, apoyada a un lado.","Suelta los seguros y baja la plataforma flexionando la rodilla.","Detente cuando la rodilla forme un ángulo cercano a 90 grados.","Empuja a través del talón para devolver la plataforma.","Completa las repeticiones de un lado y luego cambia."],["Mantén el pie plano y centrado en la plataforma.","Evita que la rodilla se desplace hacia adentro.","No bloquees la rodilla con fuerza en la parte alta."]],["high-foot-leg-press","Prensa de piernas con pies altos","Una prensa de piernas con los pies colocados altos en la plataforma, que desplaza más trabajo hacia la extensión de cadera y el glúteo mayor con la espalda apoyada.","Pierna","Fuerza","Principiante","Prensa de piernas",false,["Glúteo mayor"],["Isquiotibiales","Cuádriceps"],6.0,"high-foot-leg-press-start.webp","high-foot-leg-press-peak.webp",["Ajusta el respaldo para que la zona lumbar permanezca apoyada y la pelvis no se redondee al bajar.","Coloca ambos pies altos y aproximadamente al ancho de los hombros, alineando rodillas y puntas de los pies.","Baja el carro flexionando caderas y rodillas hasta una profundidad cómoda sin despegar la zona lumbar del respaldo.","Empuja con todo el pie y extiende caderas y rodillas sin bloquearlas con fuerza.","Baja el carro bajo control y repite el número deseado de repeticiones."],["Mantén la pelvis pesada contra el respaldo; una posición alta de los pies no justifica redondear la espalda baja.","Mantén los talones y todo el pie apoyados en lugar de empujar solo con los dedos.","Elige una profundidad que conserve la posición de la pelvis."]],["wide-stance-leg-press","Prensa de piernas con postura amplia","Una prensa de piernas con una postura amplia y ligeramente abierta, que aumenta la participación de los aductores junto con la extensión de cadera y rodilla.","Pierna","Fuerza","Principiante","Prensa de piernas",false,["Aductores"],["Glúteo mayor","Isquiotibiales","Cuádriceps"],6.0,"wide-stance-leg-press-start.webp","wide-stance-leg-press-peak.webp",["Ajusta el asiento y el respaldo para que la zona lumbar permanezca apoyada en la parte baja del recorrido.","Coloca los pies separados en la plataforma y gira las puntas hacia fuera solo hasta donde las rodillas puedan seguirlas.","Baja el carro flexionando caderas y rodillas y mantén las rodillas en la misma dirección que los pies.","Empuja con todo el pie y extiende caderas y rodillas sin forzar el bloqueo.","Baja el carro bajo control y repite el número deseado de repeticiones."],["Elige una anchura y un ángulo de los pies que puedas controlar desde la cadera; más ancho no siempre es mejor.","Mantén las rodillas siguiendo a los pies y evita que se hundan hacia dentro.","Detén el descenso antes de que la pelvis se despegue y la espalda pierda contacto con el respaldo."]],["close-stance-leg-press","Prensa de piernas con postura cerrada","Una prensa de piernas con los pies juntos, que aumenta la flexión de rodilla y mantiene el énfasis en los cuádriceps con la espalda apoyada.","Pierna","Fuerza","Principiante","Prensa de piernas",false,["Cuádriceps"],["Glúteo mayor","Isquiotibiales"],6.0,"close-stance-leg-press-start.webp","close-stance-leg-press-peak.webp",["Ajusta el asiento y el respaldo para que la zona lumbar permanezca apoyada durante toda la repetición.","Coloca los pies juntos cerca del centro de la plataforma y alinea rodillas y puntas de los pies.","Baja el carro flexionando rodillas y caderas mientras mantienes ambos pies planos.","Empuja la plataforma con todo el pie y extiende las piernas sin golpear el bloqueo de las rodillas.","Regresa bajo control y repite el número deseado de repeticiones."],["Usa solo la postura más cerrada que permita que las rodillas sigan cómodamente a los pies.","Mantén los talones abajo y evita que las rodillas se junten al descender.","No sacrifiques la posición de la pelvis para conseguir más profundidad."]],["horizontal-leg-press","Prensa de piernas horizontal","Una prensa de piernas en máquina realizada en posición horizontal, que trabaja cuádriceps, glúteos e isquiotibiales.","Pierna","Fuerza","Principiante","Prensa de piernas",false,["Glúteo mayor","Cuádriceps"],["Isquiotibiales"],6.0,"horizontal-leg-press-start.webp","horizontal-leg-press-peak.webp",["Siéntate en la máquina de prensa de piernas horizontal y coloca los pies a la anchura de los hombros.","Desbloquea la máquina y baja la plataforma hacia tu pecho.","Empuja la plataforma de vuelta a la posición inicial.","Repite."],["No dejes que la zona lumbar se separe del asiento.","Evita bloquear completamente las rodillas."]],["arnold-press","Press Arnold","Un press de hombros con mancuernas que rota las palmas durante el ascenso, dirigido al deltoides anterior y lateral.","Hombro","Fuerza","Intermedio","Mancuernas",false,["Deltoides anterior","Deltoides lateral"],["Serrato anterior","Trapecio","Tríceps braquial"],6.0,"arnold-press-start.webp","arnold-press-peak.webp",["Sostén un par de mancuernas a la altura de los hombros con las palmas mirando hacia ti.","Empuja las mancuernas sobre la cabeza mientras rotas las palmas hacia adelante.","Extiende los brazos por completo en la parte superior sin bloquear los codos.","Invierte el movimiento y rota de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],["Evita arquear la zona lumbar al empujar hacia arriba.","Mantén las muñecas firmes y alineadas con los antebrazos.","Controla la bajada en lugar de dejar caer el peso."]],["behind-the-neck-press","Press Detrás del Cuello","Un press vertical con barra realizado por detrás de la nuca, dirigido al deltoides anterior y lateral.","Hombro","Fuerza","Intermedio","Barra",false,["Deltoides anterior","Deltoides lateral"],["Trapecio","Tríceps braquial"],6.0,"behind-the-neck-press-start.webp","behind-the-neck-press-peak.webp",["Siéntate o párate con una barra descansando en la parte alta de los trapecios detrás del cuello.","Agarra la barra más ancho que la anchura de los hombros.","Empuja la barra directamente sobre la cabeza hasta que los brazos estén extendidos.","Baja la barra de vuelta a la posición inicial de forma controlada.","Repite el número de repeticiones deseado."],["Trabaja primero la movilidad de hombros si la posición resulta incómoda.","Baja la barra solo hasta donde tu rango lo permita.","Mantén el core firme para no arquear la zona lumbar."]],["paused-incline-bench-press","Press Inclinado con Pausa","Un press inclinado con barra y pausa sobre la parte alta del pecho, que elimina el rebote y enfatiza pectoral superior y deltoides anterior.","Hombro","Fuerza","Avanzado","Barra",false,["Deltoides anterior","Pectoral mayor"],["Tríceps braquial"],6.0,"paused-incline-bench-press-start.webp","paused-incline-bench-press-peak.webp",["Túmbate en un banco inclinado y agarra la barra ligeramente más abierta que la anchura de los hombros.","Saca la barra del rack y bájala hasta el pecho superior.","Haz una pausa sobre el pecho durante 1-2 segundos.","Empuja la barra hacia arriba hasta que los brazos queden completamente extendidos.","Mantén los omóplatos retraídos durante todo el ejercicio.","Repite el número de repeticiones deseado."],["No acortes la pausa cuando la carga se haga pesada.","Mantén las muñecas firmes sobre los codos durante el recorrido.","Mantén los pies firmes en el suelo durante toda la serie."]],["smith-machine-incline-bench-press","Press Inclinado en Máquina Smith","Un press inclinado en máquina Smith que enfatiza la parte superior del pecho y los deltoides anteriores con una trayectoria guiada.","Hombro","Fuerza","Principiante","Máquina Smith",false,["Deltoides anterior","Pectoral mayor"],["Tríceps braquial"],6.0,"smith-machine-incline-bench-press-start.webp","smith-machine-incline-bench-press-peak.webp",["Ajusta un banco inclinado a 30-45 grados dentro de la máquina Smith.","Recuéstate y agarra la barra ligeramente más ancho que el ancho de hombros.","Desbloquea y baja la barra hasta la parte superior del pecho.","Haz una breve pausa en la parte inferior.","Empuja la barra hacia arriba hasta extender los brazos.","Repite el número de repeticiones deseado."],["Ajusta la posición del banco para que la barra llegue a la parte alta del pecho.","Baja la barra sin rebotarla en el pecho.","Mantén los glúteos en el banco y los pies bien apoyados."]],["landmine-press","Press Landmine","Un press de hombros a dos manos con una barra fijada en un accesorio landmine, cuyo arco natural reduce el estrés en la articulación del hombro.","Hombro","Fuerza","Intermedio","Barra",false,["Deltoides anterior","Pectoral mayor"],["Serrato anterior","Tríceps braquial"],6.0,"landmine-press-start.webp","landmine-press-peak.webp",["Inserta un extremo de la barra en el accesorio landmine y carga el extremo libre con un disco.","Párate en postura escalonada o paralela y sujeta el extremo libre de la barra con ambas manos a la altura del pecho.","Activa el core y empuja la barra hacia adelante y arriba siguiendo su arco natural.","Extiende completamente los brazos sin bloquear los codos, luego baja con control.","Mantén ambas manos en la barra y repite el número de repeticiones deseado."],["Mantén el torso erguido y evita inclinarte excesivamente hacia el press.","La trayectoria angular es más amigable para el hombro que un press estricto sobre la cabeza.","Usa impulso de piernas estilo push press para cargas más pesadas."]],["one-arm-landmine-press","Press Landmine con Un Brazo","Una variante de press sobre la cabeza unilateral con montaje landmine que sigue un arco natural, reduciendo el riesgo de impingement de hombro.","Hombro","Fuerza","Intermedio","Barra",false,["Deltoides anterior","Pectoral mayor"],["Oblicuos","Serrato anterior","Tríceps braquial"],6.0,"one-arm-landmine-press-start.webp","one-arm-landmine-press-peak.webp",["Ancla un extremo de la barra en el accesorio landmine y carga el extremo libre.","Arrodíllate en una rodilla o párate y sujeta el extremo libre a la altura del hombro con una mano.","Empuja la barra hacia arriba y adelante siguiendo su arco hasta extender completamente el brazo.","Baja la barra de regreso a la altura del hombro con control.","Completa todas las repeticiones antes de cambiar de lado."],["Activa el core para evitar que el torso rote hacia el brazo de trabajo.","El movimiento en arco es más amigable para las articulaciones que un press estricto.","Arrodillarse en la rodilla contraria aumenta la demanda antirotacional del core."]],["ohp","Press Militar con Barra","Un movimiento de empuje compuesto por encima de la cabeza que trabaja los hombros y el tríceps.","Hombro","Fuerza","Intermedio","Barra",false,["Deltoides anterior","Deltoides lateral"],["Trapecio","Tríceps braquial"],6.0,"ohp-start.webp","ohp-peak.webp",["De pie con los pies a la anchura de los hombros y la barra a la altura de las clavículas.","Contrae el core y empuja la barra por encima de la cabeza.","Bloquea los codos arriba con la barra sobre el punto medio del pie.","Baja la barra hasta la altura de las clavículas.","Repite."],["No te eches demasiado hacia atrás.","Aprieta los glúteos para mayor estabilidad."]],["cable-pallof-press","Press Pallof en Polea","Un ejercicio de core antirrotación en el que la polea tira de ti hacia un lado mientras empujas el agarre recto desde el pecho y te niegas a dejar que el torso gire.","Core","Fuerza","Intermedio","Polea",false,["Oblicuos","Transverso abdominal"],["Deltoides anterior","Erectores espinales","Glúteo medio","Recto abdominal"],3.5,"cable-pallof-press-start.webp","cable-pallof-press-peak.webp",["Coloca la polea a la altura del pecho y toma el agarre con ambas manos, situado de lado respecto a la máquina.","Sepárate hasta que haya tensión real en el cable, con los pies a la anchura de los hombros y las rodillas ligeramente flexionadas.","Lleva el agarre al centro del pecho y aprieta el tronco y los glúteos.","Empuja el agarre recto hacia delante hasta extender los brazos, resistiendo el tirón que quiere rotarte hacia la máquina.","Mantén un instante la posición extendida y devuelve después el agarre al pecho de forma controlada.","Completa las repeticiones deseadas, luego date la vuelta y repite hacia el otro lado."],["Nada debe rotar. Si los hombros giran hacia la polea al empujar, baja el peso — lo que entrena es la rotación que no llega a ocurrir.","Cuanto más te alejes de la máquina, más largo es el brazo de palanca y más cuesta, así que puedes cambiar la dificultad sin tocar el stack.","Mantén los brazos a la altura del pecho y los hombros abajo; dejar que el agarre suba lo convierte en una elevación frontal."]],["spoto-press","Press Spoto","Un press de banca con barra que incluye una pausa con la barra suspendida sobre el pecho, eliminando el rebote.","Pecho","Fuerza","Intermedio","Barra",false,["Pectoral mayor"],["Deltoides anterior","Tríceps braquial"],6.0,"spoto-press-start.webp","spoto-press-peak.webp",["Túmbate en un banco plano y agarra la barra ligeramente más ancha que los hombros.","Desrackea la barra y sostenla sobre el pecho con los brazos extendidos.","Baja la barra hasta que quede a un centímetro por encima del pecho.","Mantén esa posición un segundo completo sin tocar el pecho.","Empuja la barra hacia arriba hasta que los brazos estén extendidos.","Repite el número de repeticiones deseado."],["Detén la barra a un par de centímetros del pecho.","Mantén la pausa un segundo completo sin tocar el pecho.","Conserva los omóplatos retraídos durante todo el recorrido."]],["one-arm-kettlebell-bottoms-up-press","Press Strict con Pesa Rusa Invertida a Un Brazo","Un press estricto por encima de la cabeza con la pesa rusa boca abajo: la bola arriba y el asa en la palma. La carga invertida exige un agarre fuerte, estabilidad perfecta de hombro y una trayectoria impecable.","Hombro","Fuerza","Avanzado","Kettlebell",false,["Deltoides anterior"],["Flexores del antebrazo","Deltoides lateral","Serrato anterior","Tríceps braquial"],6.0,"one-arm-kettlebell-bottoms-up-press-start.webp","one-arm-kettlebell-bottoms-up-press-peak.webp",["Limpia una pesa rusa ligera a la posición de rack y luego inclínala para que la bola apunte hacia arriba y el asa quede en la palma.","Agarra el asa con fuerza; la muñeca absolutamente recta y vertical.","Contrae el core y empuja la bola recto hacia arriba sin dejarla caer.","Bloquea el codo arriba con la bola todavía perfectamente vertical.","Baja lentamente a la posición de rack manteniendo la pesa vertical durante todo el descenso.","Completa todas las repeticiones de un lado y luego cambia."],["Si la bola se inclina, la serie termina; no luches para bajarla.","Empieza con muy poco peso; es un ejercicio de habilidad y estabilidad, no un press pesado.","Aprieta fuerte durante todo el recorrido; cualquier relajación y la pesa cae."]],["svend-press","Press Svend","Un press con apretón de disco que carga los pectorales a través de la aducción isométrica mientras se extiende el peso alejándolo del pecho.","Pecho","Fuerza","Principiante","Discos",false,["Pectoral mayor"],["Deltoides anterior","Tríceps braquial"],5.0,"svend-press-start.webp","svend-press-peak.webp",["Párate erguido sosteniendo un disco de pesas (o dos apretados juntos) entre las palmas a la altura del pecho.","Aprieta fuerte los discos para generar tensión en los pectorales.","Empuja los discos recto hacia adelante hasta que los brazos estén completamente extendidos.","Haz una breve pausa manteniendo el apretón, luego devuelve los discos al pecho.","Repite el número de repeticiones recomendado."],["Cuanto más fuerte aprietes los discos, mayor activación del pecho obtendrás.","Mantén los discos a la altura del esternón durante todo el ejercicio: no dejes que caigan hacia las caderas."]],["kettlebell-svend-press","Press Svend con Kettlebells","Un ejercicio de pecho de pie presionando dos kettlebells unidas por las bolas, aísla el pecho interno.","Pecho","Fuerza","Principiante","Kettlebell",false,["Pectoral mayor"],["Deltoides anterior","Tríceps braquial"],5.0,"kettlebell-svend-press-start.webp","kettlebell-svend-press-peak.webp",["De pie, junta dos kettlebells por las bolas a la altura del pecho.","Mantén las kettlebells horizontales — bolas tocándose, asas hacia afuera.","Empuja las kettlebells al frente hasta extender los brazos.","Tíralas de regreso al pecho con control.","Repite el número de repeticiones indicado."],["La presión entre las bolas hace el ejercicio.","Usa kettlebells muy ligeras — el agarre incómodo dicta la carga.","Mantén los codos ligeramente flexionados en el lockout."]],["db-svend-press","Press Svend con Mancuernas","Un ejercicio de pecho de pie presionando dos mancuernas entre sí frente al cuerpo, aísla el pecho interno.","Pecho","Fuerza","Principiante","Mancuernas",false,["Pectoral mayor"],["Deltoides anterior","Tríceps braquial"],5.0,"db-svend-press-start.webp","db-svend-press-peak.webp",["De pie, junta dos mancuernas horizontalmente a la altura del pecho.","Mantén la presión hacia adentro sobre las mancuernas todo el tiempo.","Empuja las mancuernas al frente hasta extender los brazos.","Tíralas de regreso al pecho con control.","Repite el número de repeticiones indicado."],["La presión entre las mancuernas hace el ejercicio — no dejes que se separen.","Usa carga ligera — el objetivo es activar el pecho, no levantar mucho.","Mantén los codos ligeramente flexionados en el lockout."]],["single-db-svend-press","Press Svend con una Mancuerna","Un press de pecho de pie sosteniendo una sola mancuerna en vertical entre las palmas, donde lo que trabaja los pectorales es la presión hacia adentro y no la carga.","Pecho","Fuerza","Principiante","Mancuernas",false,["Pectoral mayor"],["Deltoides anterior","Tríceps braquial"],5.0,"single-db-svend-press-start.webp","single-db-svend-press-peak.webp",["De pie y erguido, sostén una sola mancuerna en vertical frente al esternón, con el mango entre las palmas planas.","Aprieta con fuerza las palmas contra la mancuerna para que la tensión vaya al pecho y el peso no resbale.","Empuja la mancuerna recto hacia adelante hasta extender por completo los brazos, manteniéndola a la altura del pecho todo el recorrido.","Haz una breve pausa sin soltar la presión y devuelve la mancuerna al pecho con control.","Repite el número de repeticiones recomendado."],["La presión sobre la mancuerna hace el ejercicio. Si agarras el mango en lugar de aplastar el peso entre las palmas planas, el pecho no trabaja.","Usa una mancuerna ligera. Las palmas la sostienen solo por fricción, así que el agarre marca el límite mucho antes que el pecho.","Mantén los codos ligeramente flexionados en el lockout y la mancuerna a la altura del esternón; si baja hacia las caderas, los pectorales dejan de trabajar."]],["incline-db-press","Press con mancuernas en banco inclinado","Un movimiento de press en banco inclinado que enfatiza la parte superior del pecho.","Pecho","Fuerza","Intermedio","Mancuernas",false,["Pectoral mayor"],["Deltoides anterior","Tríceps braquial"],6.0,"incline-db-press-start.webp","incline-db-press-peak.webp",["Ajusta el banco a 30 grados de inclinación y siéntate con las mancuernas a la altura de los hombros.","Empuja las mancuernas hacia arriba y juntas hasta que los brazos estén completamente extendidos.","Baja las mancuernas de vuelta a la altura de los hombros con control.","Repite."],["Mantén los pies firmes en el suelo y las escápulas retraídas.","Evita chocar las mancuernas en la parte alta.","Baja hasta sentir un estiramiento suave en el pecho."]],["decline-bench-press","Press de Banca Declinado","Un press de pecho compuesto en banco declinado que trabaja el pectoral inferior.","Pecho","Fuerza","Intermedio","Mancuernas",false,["Pectoral mayor"],["Deltoides anterior","Tríceps braquial"],6.0,"decline-bench-press-start.webp","decline-bench-press-peak.webp",["Ajusta el banco en declinación. Túmbate y asegura los pies.","Descuelga la barra y bájala hasta el pecho inferior.","Vuelve a empujar hasta la posición inicial.","Repite."],["Mantén la espalda plana sobre el banco.","Usa un ayudante cuando trabajes con cargas más pesadas."]],["decline-bench-press-barbell","Press de Banca Declinado con Barra","Un press compuesto con barra en banco declinado que enfatiza el pecho inferior.","Pecho","Fuerza","Intermedio","Barra",false,["Pectoral mayor"],["Deltoides anterior","Tríceps braquial"],6.0,"decline-bench-press-barbell-start.webp","decline-bench-press-barbell-peak.webp",["Ajusta el banco en declinación. Túmbate y asegura los pies.","Agarra la barra ligeramente más ancha que la anchura de los hombros.","Baja la barra hasta el pecho inferior y luego empuja hacia arriba.","Repite."],["Controla el descenso.","Mantén los codos a unos 45 grados respecto al torso."]],["decline-bench-press-ez-bar","Press de Banca Declinado con Barra Z","Un press declinado con barra Z y agarre cómodo para las muñecas que trabaja el pecho inferior.","Pecho","Fuerza","Intermedio","Barra Z",false,["Pectoral mayor"],["Deltoides anterior","Tríceps braquial"],6.0,"decline-bench-press-ez-bar-start.webp","decline-bench-press-ez-bar-peak.webp",["Ajusta el banco en declinación. Asegura los pies y agarra la barra Z.","Baja la barra hasta el pecho inferior.","Empuja hacia arriba de forma explosiva.","Repite."],["El agarre angulado reduce la tensión en las muñecas.","Mantén el core contraído."]],["smith-machine-decline-bench-press","Press de Banca Declinado en Máquina Smith","Un press de banca en banco declinado bajo la máquina Smith, donde el ángulo con la cabeza abajo y la trayectoria guiada llevan el trabajo al pectoral inferior.","Pecho","Fuerza","Principiante","Máquina Smith",false,["Pectoral mayor"],["Deltoides anterior","Tríceps braquial"],6.0,"smith-machine-decline-bench-press-start.webp","smith-machine-decline-bench-press-peak.webp",["Coloca un banco declinado en la máquina de modo que la barra quede alineada con tu pecho inferior al tumbarte, y engancha las piernas bajo los rodillos.","Túmbate con la cabeza en el extremo bajo, toma un agarre prono algo más ancho que los hombros y desengancha la barra.","Baja la barra de forma controlada hasta que toque el pecho inferior, manteniendo los codos a unos cuarenta y cinco grados del torso.","Empuja la barra hacia arriba hasta extender los brazos, sin bloquear los codos con fuerza.","Repite el número de repeticiones deseado y vuelve a enganchar la barra antes de soltar las piernas."],["Alinea el banco antes de cargarlo. La barra solo se mueve en un plano, así que si el banco está unos centímetros desviado la barra te llegará a la garganta o al estómago en lugar del pecho inferior.","Asegura primero las piernas bajo los rodillos. Con la cabeza abajo y sin sujeción, te deslizarás hacia el extremo bajo del banco en la primera repetición dura.","Incorpórate despacio entre series. Las series largas con la cabeza por debajo del corazón marean a mucha gente, y esta es la variante donde ocurre."]],["close-grip-incline-bench","Press de Banca Inclinado con Agarre Cerrado","Un press de banca inclinado con agarre cerrado que trabaja los tríceps y el pecho superior.","Tríceps","Fuerza","Intermedio","Barra",false,["Tríceps braquial"],["Deltoides anterior","Pectoral mayor"],6.0,"close-grip-incline-bench-start.webp","close-grip-incline-bench-peak.webp",["Ajusta el banco en inclinación. Agarra la barra con las manos a la anchura de los hombros o más juntas.","Baja la barra hasta el pecho superior.","Empuja hacia arriba.","Repite."],["La inclinación aumenta el estiramiento de la cabeza larga de los tríceps.","Mantén los codos pegados para mantener el foco en los tríceps."]],["close-grip-bench-press","Press de Banca con Agarre Cerrado","Una variación del press de banca con agarre estrecho que desplaza el énfasis hacia los tríceps.","Tríceps","Fuerza","Intermedio","Barra",false,["Tríceps braquial"],["Deltoides anterior","Pectoral mayor"],6.0,"close-grip-bench-press-start.webp","close-grip-bench-press-peak.webp",["Túmbate en un banco plano y agarra la barra con las manos a la anchura de los hombros.","Baja la barra hasta el pecho inferior manteniendo los codos cerca de los costados.","Vuelve a empujar hasta la extensión completa.","Repite."],["Mantén los codos pegados para maximizar la activación de los tríceps.","Evita un agarre demasiado estrecho para prevenir tensión en las muñecas."]],["bench-press","Press de Banca con Barra","Un movimiento compuesto de empuje que trabaja el pecho, los hombros y los tríceps.","Pecho","Fuerza","Intermedio","Barra",false,["Pectoral mayor"],["Deltoides anterior","Tríceps braquial"],6.0,"bench-press-start.webp","bench-press-peak.webp",["Acuéstate en el banco con los ojos bajo la barra.","Agarra la barra ligeramente más ancho que la anchura de los hombros.","Saca la barra del rack y bájala hasta el centro del pecho.","Empuja la barra de vuelta hasta la extensión completa de los brazos.","Repite el número de repeticiones deseado."],["Mantén los pies planos en el suelo.","Conserva una ligera curvatura en la zona lumbar.","Impulsa con las piernas para dar estabilidad."]],["ez-bar-bench-press","Press de Banca con Barra Z","Un press de pecho en banco plano realizado con una barra Z, cuyos agarres angulados son más cómodos para las muñecas mientras trabajan el pectoral, los deltoides anteriores y los tríceps.","Pecho","Fuerza","Intermedio","Barra Z",false,["Pectoral mayor"],["Deltoides anterior","Tríceps braquial"],6.0,"ez-bar-bench-press-start.webp","ez-bar-bench-press-peak.webp",["Túmbate en un banco plano con los pies apoyados en el suelo y agarra las curvas anguladas de la barra Z sobre el pecho.","Desengancha la barra y sostenla sobre la parte baja del pecho con los brazos extendidos.","Baja la barra de forma controlada hacia la parte baja del pecho.","Empuja la barra de nuevo hacia arriba hasta extender completamente los brazos.","Repite durante el número de repeticiones deseado."],["Mantén los pies apoyados en el suelo y un ligero arco en la zona lumbar para una base estable.","El agarre angulado de la barra Z es más cómodo para las muñecas que una barra recta.","Baja la barra hacia la parte baja del pecho y mantén los codos a unos 45 grados para proteger los hombros."]],["close-grip-ez-bar-bench-press","Press de Banca con Barra Z y Agarre Cerrado","Un press enfocado en los tríceps con barra Z y agarre estrecho para mayor comodidad en las muñecas.","Tríceps","Fuerza","Intermedio","Barra Z",false,["Tríceps braquial"],["Deltoides anterior","Pectoral mayor"],6.0,"close-grip-ez-bar-bench-press-start.webp","close-grip-ez-bar-bench-press-peak.webp",["Túmbate en un banco plano y agarra las curvas internas de la barra Z.","Baja la barra hasta el pecho con los codos pegados.","Empuja hacia arriba hasta la extensión completa.","Repite."],["La barra Z reduce la incomodidad en las muñecas.","Mantén el movimiento controlado."]],["db-bench-press","Press de Banca con Mancuernas","Un ejercicio compuesto de pecho con mancuernas que permite mayor rango de movimiento que el press de banca con barra.","Pecho","Fuerza","Intermedio","Mancuernas",false,["Pectoral mayor"],["Deltoides anterior","Tríceps braquial"],6.0,"db-bench-press-start.webp","db-bench-press-peak.webp",["Túmbate en un banco plano sosteniendo una mancuerna en cada mano a la altura del pecho.","Empuja las mancuernas hacia arriba hasta extender completamente los brazos.","Bájalas lentamente hasta la posición inicial.","Repite."],["Mantén las muñecas neutras durante todo el ejercicio.","Aprieta el pecho en la parte superior del movimiento."]],["close-grip-db-bench-press","Press de Banca con Mancuernas y Agarre Cerrado","Un press de banca con mancuernas sostenidas juntas para aumentar la participación de los tríceps.","Tríceps","Fuerza","Intermedio","Mancuernas",false,["Tríceps braquial"],["Deltoides anterior","Pectoral mayor"],6.0,"close-grip-db-bench-press-start.webp","close-grip-db-bench-press-peak.webp",["Túmbate en un banco plano y sostén dos mancuernas juntas sobre el pecho.","Bájalas hasta el pecho manteniendo los codos cerca.","Empuja hacia arriba.","Repite."],["Mantén las mancuernas presionadas entre sí durante todo el movimiento.","Mantén los codos pegados."]],["paused-bench-press","Press de Banca con Pausa","Un press de banca con barra en el que la pausa sobre el pecho elimina el rebote y endurece la fase inicial del empuje.","Pecho","Fuerza","Avanzado","Barra",false,["Pectoral mayor"],["Deltoides anterior","Tríceps braquial"],6.0,"paused-bench-press-start.webp","paused-bench-press-peak.webp",["Túmbate en un banco plano y agarra la barra ligeramente más abierta que la anchura de los hombros.","Saca la barra del rack y bájala hasta el pecho.","Haz una pausa sobre el pecho durante 1-2 segundos.","Empuja la barra hacia arriba hasta que los brazos queden completamente extendidos.","Controla el descenso en cada repetición.","Repite el número de repeticiones deseado."],["No dejes que la barra se hunda en el pecho durante la pausa.","Mantén los omóplatos retraídos y pegados al banco.","Pide que alguien te asista cuando muevas cargas altas."]],["wide-grip-bench-press","Press de Banca en Agarre Ancho","Una variante del press de banca con un agarre más ancho que los hombros para maximizar la activación del pectoral.","Pecho","Fuerza","Intermedio","Barra",false,["Pectoral mayor"],["Deltoides anterior","Tríceps braquial"],6.0,"wide-grip-bench-press-start.webp","wide-grip-bench-press-peak.webp",["Túmbate en un banco plano. Agarra la barra más ancha que los hombros.","Baja la barra hasta la mitad del pecho.","Empuja de vuelta a la extensión completa.","Repite."],["Un agarre más ancho reduce la participación de los tríceps.","Evita doblar las muñecas en exceso."]],["smith-machine-bench-press","Press de Banca en Máquina Smith","Un press de banca en máquina Smith cuyo recorrido guiado permite entrenar el pecho con menos demanda de estabilización.","Pecho","Fuerza","Principiante","Máquina Smith",false,["Pectoral mayor"],["Deltoides anterior","Tríceps braquial"],6.0,"smith-machine-bench-press-start.webp","smith-machine-bench-press-peak.webp",["Acuéstate en un banco plano dentro de la máquina Smith.","Agarra la barra ligeramente más ancho que el ancho de hombros y desbloquéala.","Baja la barra con control hasta el centro del pecho.","Haz una breve pausa sin rebotar.","Empuja la barra hacia arriba hasta extender completamente los brazos.","Repite el número de repeticiones deseado."],["Alinea el banco para que la barra baje a la mitad del pecho.","Mantén los pies firmes en el suelo durante toda la serie.","Aprende el giro de muñeca para enganchar la barra antes de cargar peso."]],["seated-barbell-overhead-press","Press de Barra sobre la Cabeza Sentado","Un press de barra sobre la cabeza estricto en posición sentada, que elimina el impulso de caderas y aísla los deltoides y los tríceps.","Hombro","Fuerza","Intermedio","Barra",false,["Deltoides anterior"],["Deltoides lateral","Trapecio","Tríceps braquial"],6.0,"seated-barbell-overhead-press-start.webp","seated-barbell-overhead-press-peak.webp",["Ajusta un banco vertical dentro del rack con los pines a la altura aproximada de los hombros cuando estés sentado.","Siéntate con la espalda plana contra el pad y desrackea la barra en la parte frontal de los hombros.","Empuja la barra sobre la cabeza hasta extender completamente los brazos, pasando la cabeza por delante en la parte superior.","Baja la barra de vuelta a las clavículas con control.","Repite el número de repeticiones recomendado."],["Mantén las costillas abajo y los glúteos apretados; no te inclines hacia atrás como en un press de banca.","Empuja la barra recto hacia arriba, no hacia adelante."]],["push-press","Press de Empuje","Un press de barra sobre la cabeza que usa el impulso de las piernas para empujar cargas más pesadas.","Hombro","Fuerza","Intermedio","Barra",false,["Deltoides anterior","Deltoides lateral"],["Cuádriceps","Tríceps braquial"],6.0,"push-press-start.webp","push-press-peak.webp",["Párate con la barra apoyada en los deltoides frontales.","Flexiona ligeramente las rodillas.","Impulsa con las piernas y empuja la barra sobre la cabeza.","Bloquea completamente.","Baja al inicio.","Repite."],["Usa el impulso de las piernas solo para iniciar — termina con los hombros.","Mantén el core apretado en todo momento."]],["dumbbell-push-press","Press de Empuje con Mancuernas","Un press de hombros compuesto que usa el impulso de las piernas para desarrollar potencia en hombros y tríceps.","Hombro","Fuerza","Intermedio","Mancuernas",false,["Deltoides anterior","Tríceps braquial"],["Glúteo mayor","Deltoides lateral","Cuádriceps","Trapecio"],6.0,"dumbbell-push-press-start.webp","dumbbell-push-press-peak.webp",["Párate sosteniendo mancuernas a la altura de los hombros, palmas hacia adelante.","Dobla ligeramente las rodillas en una cuarta sentadilla.","Empuja con las piernas para generar impulso y presiona las mancuernas hacia arriba.","Extiende los brazos completamente arriba.","Baja las mancuernas con control a la altura de los hombros."],["Usa un descenso poco profundo — no es una sentadilla completa.","Empuja los talones contra el suelo para iniciar el press.","Mantén el core activado para proteger la zona lumbar."]],["seated-db-press","Press de Hombro con Mancuernas Sentado","Un movimiento de press sentado para los hombros usando mancuernas.","Hombro","Fuerza","Intermedio","Mancuernas",false,["Deltoides anterior","Deltoides lateral"],["Trapecio","Tríceps braquial"],6.0,"seated-db-press-start.webp","seated-db-press-peak.webp",["Siéntate en un banco con respaldo sosteniendo mancuernas a la altura de los hombros.","Empuja las mancuernas sobre la cabeza hasta extender completamente los brazos.","Baja las mancuernas de vuelta a la altura de los hombros.","Repite."],["No arquees la espalda baja; mantén el contacto con el respaldo.","Sube las mancuernas en línea recta, sin chocarlas arriba.","Exhala al empujar y mantén el core firme."]],["one-arm-kettlebell-shoulder-press","Press de Hombro con Pesa Rusa a Un Brazo","Un press de hombro estricto a un brazo con pesa rusa, que exige estabilidad del core para evitar la inclinación lateral.","Hombro","Fuerza","Intermedio","Kettlebell",false,["Deltoides anterior","Deltoides lateral"],["Oblicuos","Trapecio","Tríceps braquial"],6.0,"one-arm-kettlebell-shoulder-press-start.webp","one-arm-kettlebell-shoulder-press-peak.webp",["Sostén una pesa rusa en posición de rack en un hombro.","De pie con los pies a la anchura de las caderas.","Empuja la pesa rusa recto hacia arriba hasta bloquear el codo.","Mantén el core apretado durante todo el ejercicio.","Baja la pesa rusa a la posición de rack con control.","Completa las repeticiones de un lado y luego cambia."],["No te inclines hacia el lado contrario al empujar.","Mantén el antebrazo vertical bajo la pesa durante el recorrido.","Exhala al empujar y evita encoger el hombro hacia la oreja."]],["dumbbell-shoulder-press","Press de Hombros con Mancuernas","Un press vertical con mancuernas, sentado o de pie, que desarrolla las porciones anterior y lateral del deltoides.","Hombro","Fuerza","Intermedio","Mancuernas",false,["Deltoides anterior","Deltoides lateral"],["Trapecio","Tríceps braquial"],6.0,"dumbbell-shoulder-press-start.webp","dumbbell-shoulder-press-peak.webp",["Siéntate o ponte de pie sujetando mancuernas a la altura de los hombros con las palmas mirando hacia adelante.","Empuja ambas mancuernas por encima de la cabeza hasta que los brazos queden completamente extendidos.","Mantén el core contraído y evita arquear la zona lumbar.","Baja las mancuernas de forma controlada hasta la altura de los hombros.","No dejes que las mancuernas se desplacen detrás de la cabeza.","Repite el número de repeticiones deseado."],["Sube las mancuernas en línea recta, sin chocarlas arriba.","Mantén las muñecas firmes, alineadas con los antebrazos.","Si tu zona lumbar se arquea, reduce el peso."]],["machine-shoulder-press","Press de Hombros en Máquina","Un movimiento de press por encima de la cabeza en máquina para los hombros.","Hombro","Fuerza","Principiante","Máquina de press de hombro",false,["Deltoides anterior","Deltoides lateral"],["Trapecio","Tríceps braquial"],6.0,"machine-shoulder-press-start.webp","machine-shoulder-press-peak.webp",["Siéntate en la máquina con la espalda contra el rodillo.","Agarra las manijas a la altura de los hombros.","Presiona las manijas sobre la cabeza hasta que los brazos queden completamente extendidos.","Baja con control a la posición inicial.","Repite."],["No arquees la zona lumbar al empujar hacia arriba.","Evita bloquear los codos de golpe en la parte alta.","Mantén las muñecas firmes y alineadas con los antebrazos."]],["smith-machine-shoulder-press","Press de Hombros en Máquina Smith","Un press vertical para deltoides en máquina Smith realizado sentado en un banco, con la barra estabilizada por los raíles.","Hombro","Fuerza","Principiante","Máquina Smith",false,["Deltoides anterior","Deltoides lateral"],["Trapecio","Tríceps braquial"],6.0,"smith-machine-shoulder-press-start.webp","smith-machine-shoulder-press-peak.webp",["Siéntate en un banco colocado dentro de una máquina Smith.","Agarra la barra ligeramente más ancha que el ancho de los hombros a la altura de los hombros.","Desrackea la barra y empújala por encima de la cabeza hasta que los brazos estén extendidos.","Baja la barra de vuelta a la altura de los hombros de forma controlada.","Mantén el core contraído durante todo el ejercicio.","Repite el número de repeticiones deseado."],["Sitúate de forma que la barra no roce la cabeza al subir.","Evita arquear la zona lumbar al empujar.","Suelta el aire en la subida de cada repetición."]],["seated-smith-machine-shoulder-press","Press de Hombros en Máquina Smith Sentado","Un press de hombros sentado en máquina Smith, cuyo recorrido guiado facilita el aprendizaje del empuje vertical.","Hombro","Fuerza","Principiante","Máquina Smith",false,["Deltoides anterior","Deltoides lateral"],["Trapecio","Tríceps braquial"],6.0,"seated-smith-machine-shoulder-press-start.webp","seated-smith-machine-shoulder-press-peak.webp",["Coloca un banco dentro de la máquina Smith.","Siéntate mirando hacia adelante con la barra a la altura de los hombros.","Agarra la barra ligeramente más ancho que el ancho de hombros.","Desbloquea la barra y empuja hacia arriba hasta extender los brazos.","Baja la barra de vuelta a la altura de los hombros con control.","Repite el número de repeticiones deseado."],["Coloca el banco de modo que la barra baje justo delante de la cara.","No bloquees los codos con brusquedad en la parte alta.","Mantén el torso erguido y el core activo durante toda la serie."]],["cable-chest-press","Press de Pecho con Cable","Un press de pecho de pie en polea que ofrece tensión constante sobre el pectoral durante todo el recorrido.","Pecho","Fuerza","Intermedio","Polea",false,["Pectoral mayor"],["Deltoides anterior","Serrato anterior","Tríceps braquial"],6.0,"cable-chest-press-start.webp","cable-chest-press-peak.webp",["Ajusta los cables a la altura del pecho y colócate de espaldas a la máquina.","Sujeta un agarre en cada mano y da un paso adelante adoptando una postura escalonada.","Empuja los agarres hacia adelante hasta extender los brazos completamente.","Aprieta el pecho en la parte superior.","Vuelve de forma controlada y repite."],["Evita que los hombros se adelanten al extender los brazos.","Mantén el core activo para no perder el equilibrio.","Mantén las muñecas rectas durante la fase de empuje."]],["trx-chest-press","Press de Pecho con TRX","Un ejercicio compuesto de empuje que utiliza un entrenador de suspensión para desarrollar fuerza y estabilidad en el pecho.","Pecho","Fuerza","Principiante","Entrenador de suspensión (TRX)",false,["Pectoral mayor"],["Deltoides anterior","Recto abdominal","Tríceps braquial"],6.0,"trx-chest-press-start.webp","trx-chest-press-peak.webp",["Ajusta las asas del entrenador de suspensión a la altura de la mitad de la pantorrilla.","Ponte de espaldas al punto de anclaje, sosteniendo un asa en cada mano, con los brazos extendidos.","Inclínate hacia adelante en una posición de plancha, manteniendo tu cuerpo recto de la cabeza a los talones.","Baja tu pecho hacia tus manos doblando los codos, manteniendo la tensión en las correas.","Empuja hacia arriba a la posición inicial, extendiendo completamente los brazos y contrayendo el pecho."],["Mantén tu core activado durante todo el movimiento para mantener una plancha rígida.","Controla la fase excéntrica (descenso) para una mejor activación muscular.","Ajusta la posición de tus pies para modificar la dificultad: más cerca del anclaje para más fácil, más lejos para más difícil.","Asegúrate de que tus codos se muevan ligeramente hacia afuera y hacia atrás, sin abrirlos demasiado."]],["chest-press-machine","Press de Pecho en Máquina","Un movimiento de empuje para el pecho en máquina, ideal para principiantes.","Pecho","Fuerza","Principiante","Máquina de press de pecho",false,["Pectoral mayor"],["Deltoides anterior","Tríceps braquial"],6.0,"chest-press-machine-start.webp","chest-press-machine-peak.webp",["Siéntate en la máquina con la espalda plana contra el respaldo.","Agarra los mangos a la altura del pecho.","Empuja los mangos hacia adelante hasta extender los brazos completamente.","Vuelve lentamente a la posición inicial.","Repite."],["Ajusta el asiento para que las manijas queden a la altura del pecho.","Empuja sin bloquear los codos de golpe.","Vuelve atrás con control, sin soltar el peso de golpe."]],["kettlebell-close-grip-floor-press","Press de Suelo con Agarre Cerrado con Pesa Rusa","Un press de suelo con una sola pesa rusa agarrada con ambas manos juntas, que desplaza el énfasis del pecho a los tríceps.","Tríceps","Fuerza","Intermedio","Kettlebell",false,["Tríceps braquial"],["Deltoides anterior","Pectoral mayor"],6.0,"kettlebell-close-grip-floor-press-start.webp","kettlebell-close-grip-floor-press-peak.webp",["Túmbate boca arriba en el suelo con las rodillas flexionadas y los pies apoyados.","Sujeta una única pesa rusa por el asa con ambas manos juntas, con la pesa apoyada en el pecho y los codos bien pegados a las costillas.","Activa el core y empuja la pesa rusa recto hacia arriba hasta estirar del todo los brazos.","Baja de forma controlada hasta que la parte alta de los brazos toque el suelo y haz una breve pausa.","Vuelve a empujar hacia arriba hasta la extensión completa.","Repite el número de repeticiones recomendado."],["Mantén los codos pegados a unos 30–45 grados del torso; abrirlos lo convierte en press de pecho.","La breve pausa al tocar el suelo con los codos elimina el rebote y fuerza un empuje limpio.","Elige una pesa que puedas controlar con dos manos; el agarre estrecho no perdona si se ladea."]],["dumbbell-floor-press","Press de Suelo con Mancuernas","Un press con mancuernas realizado tumbado en el suelo, que limita el rango de movimiento para un press más amigable con las articulaciones.","Pecho","Fuerza","Intermedio","Mancuernas",false,["Pectoral mayor"],["Deltoides anterior","Tríceps braquial"],6.0,"dumbbell-floor-press-start.webp","dumbbell-floor-press-peak.webp",["Túmbate en el suelo con una mancuerna en cada mano a la altura del pecho.","Empuja las mancuernas hacia arriba hasta que los brazos queden extendidos.","Baja de forma controlada hasta que los codos toquen el suelo.","Repite."],["El suelo limita la tensión en el hombro en la posición inferior.","Mantén las muñecas alineadas sobre los codos."]],["single-arm-machine-shoulder-press","Press de hombros unilateral en máquina","Un press de hombros unilateral sentado en máquina que permite empujar cada brazo por separado mientras la espalda permanece apoyada y la máquina guía la resistencia.","Hombro","Fuerza","Principiante","Máquina de press de hombro",false,["Deltoides anterior","Deltoides lateral"],["Trapecio","Tríceps braquial"],6.0,"single-arm-machine-shoulder-press-start.webp","single-arm-machine-shoulder-press-peak.webp",["Ajusta el asiento para que el agarre de trabajo comience cerca del hombro y apoya firmemente la espalda en el respaldo.","Sujeta un agarre con la muñeca recta y deja la mano libre sobre el soporte.","Empuja el agarre hacia arriba sin separarte del respaldo ni girar el torso.","Baja el agarre bajo control hasta que el codo quede justo por debajo de la posición inicial.","Completa las repeticiones de un lado y después entrena el otro lado."],["Comienza con el brazo más débil y deja que marque el peso y las repeticiones de ambos lados.","Mantén las costillas abajo y la espalda contra el respaldo en lugar de inclinarte hacia un lado.","Detén el movimiento ante una posición dolorosa del hombro; el recorrido de la máquina debe sentirse controlado."]],["kettlebell-floor-press","Press de suelo con pesas rusas","Un press de pecho con dos brazos realizado tumbado en el suelo con una pesa rusa en cada mano. El suelo limita el rango de movimiento (los tríceps tocan el suelo antes del estiramiento completo), haciéndolo amigable para los hombros y una excelente opción en casa.","Pecho","Fuerza","Intermedio","Kettlebell",false,["Pectoral mayor"],["Deltoides anterior","Tríceps braquial"],6.0,"kettlebell-floor-press-start.webp","kettlebell-floor-press-peak.webp",["Acuéstate boca arriba en el suelo con las rodillas flexionadas y los pies apoyados.","Sostén una pesa rusa en cada mano a la altura del pecho, con las campanas apoyadas en el antebrazo externo.","Empuja ambas pesas rusas hacia arriba hasta que los brazos estén completamente extendidos.","Baja con control hasta que los tríceps toquen el suelo — no rebotes.","Repite el número recomendado de repeticiones."],["Los codos se mantienen a unos 45 grados del torso; no los abras.","El agarre importa: mantén las campanas estables contra el exterior de los antebrazos.","El suelo limita el rango de movimiento por diseño — esta es la ventaja, no el problema."]],["one-arm-kettlebell-floor-glute-bridge-press","Press en Puente de Glúteos en Suelo con Pesa Rusa a Un Brazo","Un ejercicio combinado en el suelo que une un puente de glúteos con un press de pesa rusa a un brazo.","Pierna","Fuerza","Intermedio","Kettlebell",false,["Glúteo mayor","Pectoral mayor"],["Deltoides anterior","Isquiotibiales","Tríceps braquial"],6.0,"one-arm-kettlebell-floor-glute-bridge-press-start.webp","one-arm-kettlebell-floor-glute-bridge-press-peak.webp",["Túmbate boca arriba con las rodillas dobladas y los pies planos en el suelo.","Sostén una pesa rusa en una mano a la altura del hombro.","Eleva las caderas en un puente de glúteos.","Empuja la pesa rusa recto hacia el techo.","Baja la pesa rusa y las caderas con control.","Completa las repeticiones de un lado y luego cambia."],["Mantén las caderas elevadas y firmes mientras haces el press.","Sujeta la pesa con la muñeca recta y firme.","Evita que la cadera rote hacia el lado cargado."]],["floor-press","Press en Suelo","Un movimiento de press con barra realizado en el suelo, limitando el rango de movimiento y eliminando la participación del tren inferior.","Pecho","Fuerza","Intermedio","Barra",false,["Pectoral mayor"],["Deltoides anterior","Tríceps braquial"],6.0,"floor-press-start.webp","floor-press-peak.webp",["Túmbate en el suelo y colócate bajo una barra en el rack.","Baja la barra hasta el pecho hasta que los codos toquen el suelo.","Empuja de vuelta hasta el bloqueo.","Repite."],["El contacto de los codos con el suelo proporciona un punto de parada natural.","Útil para trabajar la debilidad en la fase final de extensión."]],["floor-ez-bar-press","Press en Suelo con Barra Z","Una variación del press en suelo con barra Z para una posición más cómoda de muñecas y codos.","Pecho","Fuerza","Intermedio","Barra Z",false,["Pectoral mayor"],["Deltoides anterior","Tríceps braquial"],6.0,"floor-ez-bar-press-start.webp","floor-ez-bar-press-peak.webp",["Túmbate en el suelo sujetando una barra Z sobre el pecho.","Baja la barra hasta que los codos toquen el suelo.","Empuja de vuelta hasta la extensión completa.","Repite."],["La barra Z reduce la tensión en las muñecas en comparación con una barra recta.","Mantén los pies planos sobre el suelo."]],["one-arm-kettlebell-floor-press","Press en Suelo con Pesa Rusa a Un Brazo","Un press de pecho unilateral con pesa rusa ejecutado tumbado en el suelo, que acorta el recorrido y trabaja pectoral y tríceps.","Pecho","Fuerza","Intermedio","Kettlebell",false,["Pectoral mayor"],["Deltoides anterior","Tríceps braquial"],6.0,"one-arm-kettlebell-floor-press-start.webp","one-arm-kettlebell-floor-press-peak.webp",["Túmbate boca arriba en el suelo con las rodillas dobladas.","Sostén una pesa rusa en un hombro con una mano.","Empuja la pesa rusa recto hacia arriba hasta que el brazo quede completamente extendido.","Baja la pesa rusa hasta que la parte superior del brazo toque el suelo.","Mantén el core contraído durante todo el ejercicio.","Completa las repeticiones de un lado y luego cambia."],["Apoya el brazo en el suelo con suavidad, sin rebotar.","Sujeta la pesa con la muñeca firme, sin dejar que se doble.","Evita abrir el codo en exceso hacia el lado."]],["incline-bench-press","Press en banco inclinado con barra","Un movimiento de press con barra en banco inclinado que trabaja la parte superior del pecho.","Pecho","Fuerza","Intermedio","Barra",false,["Pectoral mayor"],["Deltoides anterior","Tríceps braquial"],6.0,"incline-bench-press-start.webp","incline-bench-press-peak.webp",["Acuéstate en un banco inclinado a 30-45 grados.","Agarra la barra ligeramente más ancha que los hombros y desrackea.","Baja la barra hasta la parte superior del pecho.","Empuja la barra de vuelta hasta la extensión completa.","Repite."],["Retrae las escápulas y mantenlas pegadas al banco.","Evita rebotar la barra en el pecho.","Pide asistencia cuando trabajes con cargas pesadas."]],["incline-bench-ez-bar-press","Press en banco inclinado con barra Z","Un press en banco inclinado con barra Z que trabaja la parte superior del pecho con un agarre cómodo para las articulaciones.","Pecho","Fuerza","Intermedio","Barra Z",false,["Pectoral mayor"],["Deltoides anterior","Tríceps braquial"],6.0,"incline-bench-ez-bar-press-start.webp","incline-bench-ez-bar-press-peak.webp",["Ajusta el banco a 30–45 grados. Agarra la barra Z con las manos en las secciones anguladas.","Baja la barra hasta la parte superior del pecho.","Empuja de vuelta hasta la extensión completa.","Repite."],["La inclinación desplaza el énfasis hacia la parte superior del pectoral.","Controla el descenso para evitar tensión en los hombros."]],["paused-ohp","Press militar con pausa","Una variante del press militar que hace una pausa con la barra a la altura de los hombros, eliminando el impulso para desarrollar fuerza de empuje estricta y estabilidad por encima de la cabeza.","Hombro","Fuerza","Avanzado","Barra",false,["Deltoides anterior","Deltoides lateral"],["Trapecio","Tríceps braquial"],6.0,"ohp-start.webp","ohp-peak.webp",["Colócate con la barra a la altura de los hombros, pies al ancho de los hombros y el core firme.","Empuja la barra recta por encima de la cabeza hasta bloquear los codos.","Baja la barra de forma controlada hasta el frente de los hombros.","Mantén una pausa completa de un segundo en los hombros, conservando la tensión y evitando cualquier rebote.","Vuelve a empujar desde la posición estática sin usar impulso de piernas."],["Mantén la pausa estricta: sin rebotar la barra en los hombros.","Aprieta el core y mantén la trayectoria de la barra vertical sobre el medio del pie.","Usa un peso que puedas controlar desde el arranque estático."]],["double-kettlebell-overhead-press","Press por Encima de la Cabeza con Dos Pesas Rusas","Un press vertical con dos pesas rusas desde la posición de rack que desarrolla hombros y tríceps con gran exigencia del core.","Hombro","Fuerza","Intermedio","Kettlebell",false,["Deltoides anterior","Tríceps braquial"],["Recto abdominal","Serrato anterior","Trapecio"],6.0,"double-kettlebell-overhead-press-start.webp","double-kettlebell-overhead-press-peak.webp",["Lleva dos pesas rusas al rack sobre los hombros.","Ponte de pie con los pies separados al ancho de las caderas.","Empuja ambas pesas rusas directamente hacia arriba.","Bloquea los brazos en la parte superior.","Baja de vuelta a la posición de rack y repite."],["Aprieta el abdomen para evitar arquear la zona lumbar.","Adelanta ligeramente la cabeza cuando las pesas pasen la frente.","Baja al rack con control entre repeticiones."]],["bodyweight-overhead-press","Press por Encima de la Cabeza con Peso Corporal","Un press vertical de peso corporal en posición de pica que imita el patrón del press de hombros sin material.","Hombro","Fuerza","Principiante","Sin equipo",true,["Deltoides anterior","Tríceps braquial"],["Serrato anterior","Trapecio"],5.0,"bodyweight-overhead-press-start.webp","bodyweight-overhead-press-peak.webp",["Colócate de pie frente a una pared en posición de pica con las manos en el suelo.","Acerca los pies a la pared para lograr una línea corporal más vertical.","Baja la cabeza hacia el suelo flexionando los codos.","Presiona con las manos para extender los brazos.","Repite el número deseado de repeticiones."],["Da pasos cortos con los pies para ajustar la dificultad.","Mantén el cuello neutro, con la mirada entre las manos.","Reparte el peso por toda la palma para aliviar las muñecas."]],["thoracic-bridge","Puente Torácico","Un sostén de movilidad que eleva las caderas desde una posición de mesa y abre el pecho, extendiendo la columna torácica mientras los glúteos y los hombros sostienen el puente.","Espalda","Fuerza","Intermedio","Sin equipo",true,["Erectores espinales","Glúteo mayor"],["Deltoides posterior","Tríceps braquial"],5.0,"thoracic-bridge-main.webp",null,["Siéntate en el suelo con las rodillas flexionadas y las manos detrás, los dedos apuntando hacia atrás.","Empuja con las manos y los pies para elevar las caderas del suelo.","Sigue empujando hasta que el pecho se abra y los brazos queden extendidos.","Deja caer la cabeza hacia atrás y mantén la posición.","Respira de forma constante mientras mantienes el puente.","Baja de nuevo de forma controlada."],["Eleva bien las caderas y aprieta los glúteos para proteger la zona lumbar.","Mantén los pies planos y el peso repartido entre manos y pies."]],["stability-ball-hip-bridge","Puente de Cadera con Balón de Estabilidad","Un puente de glúteos con los pies sobre un balón de estabilidad, que añade demanda antirotación y de equilibrio al patrón básico del puente.","Pierna","Fuerza","Principiante","Pelota de estabilidad",false,["Glúteo mayor"],["Isquiotibiales","Recto abdominal"],5.0,"stability-ball-hip-bridge-start.webp","stability-ball-hip-bridge-peak.webp",["Túmbate boca arriba en el suelo y coloca ambos pies sobre un balón de estabilidad.","Los brazos descansan a los lados en el suelo para equilibrarte.","Aprieta los glúteos y presiona los talones contra el balón para elevar las caderas.","Termina con una línea recta desde los hombros hasta las rodillas.","Baja las caderas de forma controlada sin que el balón ruede.","Repite el número de repeticiones recomendado."],["El balón intentará desplazarse: mantén los pies presionados directamente hacia abajo.","Sin hiperextensión en la parte superior; detente cuando el cuerpo esté en línea."]],["single-leg-glute-bridge","Puente de Glúteo a Una Pierna","Un puente de glúteo unilateral que carga un glúteo a la vez y ayuda a corregir desequilibrios laterales.","Pierna","Fuerza","Intermedio","Sin equipo",true,["Glúteo mayor"],["Erectores espinales","Isquiotibiales"],5.0,"single-leg-glute-bridge-start.webp","single-leg-glute-bridge-peak.webp",["Acuéstate boca arriba con una rodilla flexionada y el pie plano, la otra pierna extendida recta.","Activa el core y contrae el glúteo del lado que trabaja.","Empuja las caderas arriba presionando con el talón de trabajo.","Pausa arriba con el cuerpo en línea recta de hombros a rodilla.","Baja con control. Repeticiones por lado, luego cambia."],["Mantén la pierna extendida en línea con el muslo de trabajo.","Contrae el glúteo arriba — no empujes desde la zona lumbar.","Ralentiza la fase de bajada para más estímulo."]],["single-leg-glute-bridge-hold","Puente de Glúteo a Una Pierna Isométrico","La parte alta del puente de glúteo a una pierna mantenida en el tiempo: la cadera queda extendida y nivelada mientras una pierna permanece elevada, de modo que un solo glúteo sostiene toda la posición.","Pierna","Fuerza","Intermedio","Sin equipo",true,["Glúteo mayor"],["Erectores espinales","Isquiotibiales"],5.0,"single-leg-glute-bridge-hold-main.webp",null,["Túmbate boca arriba con una rodilla flexionada y ese pie apoyado, y eleva la otra pierna hasta que el muslo quede casi vertical.","Empuja con el talón del pie apoyado y eleva la cadera hasta que el cuerpo quede recto desde la rodilla hasta los hombros.","Nivela la pelvis para que el lado elevado no caiga y lleva las costillas hacia abajo.","Mantén la posición alta durante el tiempo indicado, con la rodilla elevada quieta.","Baja la cadera de forma controlada y repite del otro lado."],["Fíjate en la pelvis más que en la altura: una cadera nivelada un poco más abajo vale más que una alta y girada.","Mantén el talón apoyado cerca del glúteo para que el isquiotibial no se acalambre.","Estira del todo la pierna libre si la posición te resulta fácil, pero solo mientras la pelvis siga nivelada."]],["glute-bridge","Puente de Glúteos","Un ejercicio de activación de glúteos con el peso corporal realizado tumbado en el suelo.","Pierna","Fuerza","Principiante","Sin equipo",true,["Glúteo mayor"],["Isquiotibiales"],3.5,"glute-bridge-start.webp","glute-bridge-peak.webp",["Túmbate boca arriba con las rodillas flexionadas y los pies planos en el suelo.","Eleva las caderas apretando los glúteos.","Mantén brevemente en la parte alta con las caderas totalmente extendidas.","Baja las caderas de forma controlada.","Repite."],["Empuja con los talones para activar mejor los glúteos.","Evita arquear la zona lumbar al extender las caderas.","Mantén las rodillas alineadas con los pies durante todo el recorrido."]],["glute-bridge-hold","Puente de Glúteos Isométrico","La parte alta del puente de glúteos mantenida en el tiempo: la cadera queda completamente extendida con hombros, caderas y rodillas en línea, de modo que los glúteos permanecen bajo tensión en lugar de encadenar repeticiones.","Pierna","Fuerza","Principiante","Sin equipo",true,["Glúteo mayor"],["Isquiotibiales"],3.5,"glute-bridge-hold-main.webp",null,["Túmbate boca arriba con las rodillas flexionadas y los pies apoyados, separados a la anchura de las caderas y lo bastante cerca como para rozar los talones con los dedos.","Empuja con los talones y eleva la cadera hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros.","Aprieta los glúteos y lleva las costillas hacia abajo para que la zona lumbar no tome el mando.","Mantén la posición alta durante el tiempo indicado, con el peso en los talones.","Baja la cadera de forma controlada para terminar la serie."],["Empuja ligeramente las rodillas hacia fuera durante el mantenimiento para que los glúteos sigan activos.","Deja de subir cuando la cadera quede a la altura de las rodillas; más arriba suele significar arquear la espalda.","Para añadir carga, apoya una mancuerna o un disco sobre la cadera antes de elevarla."]],["banded-glute-bridge","Puente de Glúteos con Banda","Un puente de glúteos con una banda circular por encima de las rodillas que suma tensión de abducción al empuje de cadera.","Pierna","Fuerza","Principiante","Banda circular",false,["Glúteo mayor"],["Glúteo medio","Isquiotibiales"],6.0,"banded-glute-bridge-start.webp","banded-glute-bridge-peak.webp",["Túmbate boca arriba con las rodillas flexionadas y los pies apoyados en el suelo a la anchura de los hombros.","Coloca una banda circular alrededor de ambas piernas justo por encima de las rodillas.","Presiona la zona lumbar contra el suelo y activa el core.","Empuja con los talones y aprieta los glúteos para elevar las caderas en puente, manteniendo la tensión de la banda al empujar las rodillas hacia afuera.","Arriba, el cuerpo forma una línea recta de los hombros a las rodillas. Haz una breve pausa.","Baja de forma controlada hasta la posición inicial y repite el número de repeticiones recomendado."],["Las rodillas tienden a irse hacia dentro; empújalas hacia afuera contra la banda.","Detén la subida cuando las caderas queden a la altura de hombros y rodillas; no hiperextiendas la lumbar.","Aprieta fuerte arriba; un puente rápido a medio recorrido se siente fácil porque lo es."]],["barbell-glute-bridge","Puente de Glúteos con Barra","Un puente de glúteos con carga usando una barra para mayor resistencia.","Pierna","Fuerza","Intermedio","Barra",false,["Glúteo mayor"],["Isquiotibiales"],6.0,"barbell-glute-bridge-start.webp","barbell-glute-bridge-peak.webp",["Acuéstate en el suelo con una barra sobre las caderas y las rodillas flexionadas.","Eleva las caderas apretando los glúteos.","Aguanta en la parte superior con las caderas completamente extendidas.","Baja con control.","Repite."],["Evita arquear la zona lumbar al extender la cadera.","Empuja con los talones, no con las puntas de los pies.","Mete la barbilla y mantén la parte alta de la espalda apoyada."]],["barbell-pullover","Pullover con Barra","Un movimiento compuesto que estira y trabaja el dorsal y el pectoral a través de un arco amplio.","Espalda","Fuerza","Intermedio","Barra",false,["Dorsal ancho","Pectoral mayor"],["Tríceps braquial"],6.0,"barbell-pullover-start.webp","barbell-pullover-peak.webp",["Acuéstate en un banco con una barra sostenida sobre el pecho.","Baja la barra hacia atrás sobre tu cabeza en un arco.","Tírala de vuelta al inicio sobre el pecho.","Repite."],["Mantén una ligera flexión en los codos.","Activa el dorsal para impulsar la barra de vuelta."]],["ez-bar-pullover","Pullover con Barra EZ","Este ejercicio compuesto trabaja los dorsales y pectorales extendiendo los brazos por encima de la cabeza con una barra EZ, promoviendo la fuerza y la hipertrofia del tren superior.","Espalda","Fuerza","Intermedio","Barra Z",false,["Dorsal ancho","Pectoral mayor"],["Serrato anterior","Tríceps braquial"],6.0,"ez-bar-pullover-start.webp","ez-bar-pullover-peak.webp",["Acuéstate boca arriba en un banco plano con la cabeza ligeramente fuera del extremo, sosteniendo una barra EZ con agarre pronado.","Extiende la barra directamente sobre tu pecho, manteniendo una ligera flexión en los codos.","Baja lentamente la barra en un arco detrás de tu cabeza, sintiendo un estiramiento en tus dorsales y pecho.","Jala la barra de regreso a la posición inicial usando tus dorsales y pectorales.","Mantén el control durante todo el movimiento, evitando el impulso."],["Mantén tu core contraído para evitar arquear excesivamente la espalda baja.","Concéntrate en un estiramiento profundo en la parte inferior del movimiento.","Usa un compañero para cargas más pesadas y asegurar la seguridad.","Controla la fase excéntrica (descenso) para una máxima activación muscular."]],["bent-arm-ez-bar-pullover","Pullover con Barra Z y Brazos Flexionados","Un pullover con brazos flexionados en un banco plano usando una barra Z, más amigable para las muñecas que la versión con barra recta, manteniendo el estiramiento profundo del dorsal y el pectoral.","Espalda","Fuerza","Intermedio","Barra Z",false,["Dorsal ancho","Pectoral mayor"],["Deltoides posterior","Serrato anterior","Tríceps braquial"],6.0,"bent-arm-ez-bar-pullover-start.webp","bent-arm-ez-bar-pullover-peak.webp",["Acuéstate en un banco plano sosteniendo una barra Z con un agarre prono estrecho en las curvas internas.","Comienza con la barra sobre el pecho, codos flexionados a aproximadamente 90 grados.","Mantén el ángulo de los codos fijo y baja la barra en un arco sobre la cabeza hasta sentir un estiramiento profundo en el dorsal y el pectoral.","Tira de la barra de vuelta sobre el pecho por el mismo arco, sin extender los codos.","Repite el número de repeticiones recomendado."],["El ángulo de los codos permanece fijo: solo se mueve el hombro.","Carga menor que en un pullover con brazos extendidos: el rango es mayor y el brazo de palanca es menor.","Si la zona lumbar se arquea, planta los pies con más firmeza y aprieta el abdomen."]],["bent-arm-barbell-pullover","Pullover con Barra y Brazos Flexionados","Un pullover con barra y codos flexionados que lleva el peso por detrás de la cabeza para trabajar dorsales y pectoral.","Espalda","Fuerza","Intermedio","Barra",false,["Dorsal ancho","Pectoral mayor"],["Serrato anterior","Tríceps braquial"],5.0,"bent-arm-barbell-pullover-start.webp","bent-arm-barbell-pullover-peak.webp",["Acuéstate en un banco sosteniendo una barra sobre el pecho con los codos flexionados.","Mantén los codos flexionados durante todo el movimiento.","Baja la barra detrás de la cabeza en un arco.","Tira de la barra de vuelta sobre el pecho usando el dorsal.","Repite el número de repeticiones deseado."],["Mantén la cadera y la zona lumbar en contacto con el banco.","Baja solo hasta donde notes un estiramiento cómodo.","Empieza con un peso ligero hasta dominar la trayectoria."]],["plate-pullover","Pullover con Disco","Un pullover sosteniendo un disco, que trabaja dorsales, pecho y serrato.","Espalda","Fuerza","Principiante","Discos",false,["Dorsal ancho","Pectoral mayor"],["Serrato anterior","Tríceps braquial"],6.0,"plate-pullover-start.webp","plate-pullover-peak.webp",["Acuéstate plano en un banco sujetando un disco con ambas manos.","Empuja el disco sobre el pecho con los brazos casi rectos.","Baja el disco en arco por detrás de la cabeza hasta sentir el estiramiento.","Tira del disco de regreso sobre el pecho por el mismo arco.","Repite el número de repeticiones indicado."],["Mantén los codos suaves pero con el mismo ángulo.","Detente al final de tu rango limpio — sin estiramiento excesivo del hombro.","Apoya bien los pies para mantener la estabilidad."]],["db-pullover","Pullover con Mancuerna","Un movimiento compuesto que trabaja los dorsales y el pecho con un movimiento de estiramiento.","Espalda","Fuerza","Intermedio","Mancuernas",false,["Dorsal ancho","Pectoral mayor"],["Tríceps braquial"],6.0,"db-pullover-start.webp","db-pullover-peak.webp",["Túmbate en un banco plano con una mancuerna sobre el pecho y los brazos extendidos.","Baja la mancuerna detrás de la cabeza en arco, manteniendo una ligera flexión de codos.","Estira hasta sentir tensión en los dorsales y el pecho.","Tira de la mancuerna de vuelta a la posición inicial.","Repite."],["Baja la mancuerna solo hasta donde el hombro lo permita.","Evita arquear la zona lumbar en la fase de estiramiento.","Mantén la flexión de los codos constante durante todo el arco."]],["floor-kettlebell-pullover","Pullover con Pesa Rusa en Suelo","Un pullover realizado tumbado en el suelo con una pesa rusa sujetada por el asa o por las asas laterales. El suelo limita el rango de movimiento en comparación con la versión en banco, lo que reduce la tensión en los hombros y lo convierte en una buena opción para entrenar en casa o como ejercicio de prehabilitación.","Espalda","Fuerza","Principiante","Kettlebell",false,["Dorsal ancho","Pectoral mayor"],["Serrato anterior","Tríceps braquial"],6.0,"floor-kettlebell-pullover-start.webp","floor-kettlebell-pullover-peak.webp",["Túmbate boca arriba en el suelo con las rodillas flexionadas y los pies planos.","Sujeta una pesa rusa por el asa con ambas manos sobre el pecho, brazos casi extendidos (ligera flexión de codos).","Manteniendo el ángulo de los codos fijo, baja la pesa hacia atrás en arco hasta que los brazos toquen el suelo.","Tira de la pesa de vuelta sobre el pecho siguiendo el mismo arco.","Repite el número de repeticiones recomendado."],["El suelo limita el rango de movimiento; si te parece demasiado corto, usa la versión en banco.","Agarra el asa con firmeza y aprieta los dorsales en la parte alta.","Mantén la zona lumbar pegada al suelo durante todo el ejercicio."]],["kettlebell-pullover","Pullover con pesa rusa","Un pullover en banco plano con una pesa rusa sostenida por las asas. El profundo estiramiento por encima de la cabeza trabaja los dorsales, el tríceps (cabeza larga) y el serrato.","Espalda","Fuerza","Intermedio","Kettlebell",false,["Dorsal ancho","Pectoral mayor"],["Serrato anterior","Tríceps braquial"],6.0,"kettlebell-pullover-start.webp","kettlebell-pullover-peak.webp",["Acuéstate en un banco plano sosteniendo una pesa rusa por las asas con ambas manos sobre el pecho, brazos casi rectos (ligera flexión de codos).","Con el ángulo de los codos fijo, baja la campana por encima de la cabeza en arco hasta que los brazos estén en línea con el torso.","Tira de la campana de vuelta sobre el pecho siguiendo el mismo arco.","Repite el número recomendado de repeticiones."],["Mantén la zona lumbar presionada contra el banco — no arquees para ganar recorrido.","Agarra las asas con fuerza; la campana intentará voltearse en la parte inferior.","Baja solo hasta donde tu movilidad de hombros lo permita sin dolor."]],["reverse-tabletop-hip-pulses","Pulsos de Cadera en Mesa Invertida","Pulsos de glúteo desde la mesa invertida: los brazos permanecen estirados y solo las caderas bajan y suben, de modo que el trabajo se queda en el glúteo y no en el tríceps.","Pierna","Fuerza","Intermedio","Sin equipo",true,["Glúteo mayor"],["Erectores espinales","Isquiotibiales"],5.0,"reverse-tabletop-hip-pulses-start.webp","reverse-tabletop-hip-pulses-peak.webp",["Siéntate con las rodillas flexionadas, los pies apoyados y las manos en el suelo detrás de ti.","Empuja con manos y pies y eleva las caderas hasta que el tronco quede a la altura de las rodillas.","Con los codos estirados, baja las caderas unos centímetros.","Aprieta los glúteos para volver a subirlas al nivel.","Pulsa las veces indicadas y baja."],["Mantén los brazos bloqueados: flexionar los codos convierte esto en un fondo.","Impulsa desde los talones y los glúteos, no desde la zona lumbar.","Mantén el pecho abierto y los hombros lejos de las orejas."]],["double-kettlebell-push-press","Push Press con Dos Pesas Rusas","Un push press con dos pesas rusas en rack. El impulso de piernas (un solo descenso) permite lanzar más carga por encima de la cabeza que en un press estricto — el nivel intermedio entre el press militar estricto y el jerk.","Hombro","Fuerza","Intermedio","Kettlebell",false,["Deltoides anterior"],["Glúteo mayor","Deltoides lateral","Cuádriceps","Tríceps braquial"],6.0,"double-kettlebell-push-press-start.webp","double-kettlebell-push-press-peak.webp",["Ponte de pie con dos pesas rusas en rack sobre los hombros, codos hacia abajo y pegados.","Pies al ancho de los hombros, core contraído.","Flexiona ligeramente las rodillas manteniendo el torso vertical.","Extiende las piernas de forma explosiva y empuja ambas pesas por encima de la cabeza en un solo movimiento.","Bloquea los brazos con las pesas sobre el punto medio del pie.","Baja de vuelta al rack de forma controlada.","Repite el número de repeticiones recomendado."],["Solo UN descenso — si vuelves a doblar las rodillas bajo las pesas, eso es un jerk.","El impulso viene de las piernas; los brazos terminan el movimiento.","El torso permanece vertical en todo momento; sin inclinación."]],["one-arm-dumbbell-push-press","Push Press con Mancuerna a Un Brazo","Un push press unilateral con una sola mancuerna. El impulso de piernas te permite lanzar cargas más pesadas por encima de la cabeza que un press estricto a un brazo, y la carga asimétrica exige una fuerte contención anti-flexión lateral.","Hombro","Fuerza","Intermedio","Mancuernas",false,["Deltoides anterior"],["Glúteo mayor","Deltoides lateral","Oblicuos","Cuádriceps","Tríceps braquial"],6.0,"one-arm-dumbbell-push-press-start.webp","one-arm-dumbbell-push-press-peak.webp",["De pie con la mancuerna en un hombro, palma hacia adentro (neutro).","Pies a la anchura de los hombros, core contraído, brazo libre al costado para equilibrio.","Flexiona ligeramente las rodillas manteniendo el torso vertical.","Extiende las piernas de forma explosiva y empuja la mancuerna por encima de la cabeza en un solo movimiento.","Bloquea el codo arriba y baja la mancuerna al hombro con control.","Completa todas las repeticiones de un lado y luego cambia."],["El impulso viene de las piernas; el brazo termina el movimiento, no lo inicia.","El torso debe mantenerse erguido y cuadrado; no te inclines hacia el lado contrario a la carga.","Menos peso y mejor impulso de piernas superan a más peso con el torso inclinado."]],["one-arm-kettlebell-push-press","Push Press con Pesa Rusa a Un Brazo","Un press unilateral con pesa rusa que usa un impulso de piernas para llevar el peso por encima de la cabeza.","Hombro","Fuerza","Intermedio","Kettlebell",false,["Deltoides anterior"],["Glúteo mayor","Cuádriceps","Trapecio","Tríceps braquial"],6.0,"one-arm-kettlebell-push-press-start.webp","one-arm-kettlebell-push-press-peak.webp",["Sostén una pesa rusa en posición de rack en un hombro.","De pie con los pies a la anchura de los hombros.","Flexiona ligeramente las rodillas.","Extiende las piernas de forma explosiva y empuja la pesa rusa por encima de la cabeza.","Bloquea el codo en la parte superior.","Baja la pesa rusa al hombro con control.","Completa las repeticiones de un lado y luego cambia."],["Haz la flexión de piernas corta y rápida, sin inclinar el torso.","Sincroniza el empuje de piernas con la extensión del brazo.","Aprieta el core al recibir la pesa de vuelta en el hombro."]],["push-up","Push-Up","Un ejercicio fundamental con el peso corporal para el pecho, los hombros y los tríceps.","Pecho","Fuerza","Principiante","Sin equipo",true,["Pectoral mayor","Tríceps braquial"],["Deltoides anterior"],5.0,"push-up-start.webp","push-up-peak.webp",["Comienza en posición de plancha alta con las manos a la anchura de los hombros.","Baja el cuerpo hasta que el pecho casi toque el suelo.","Empuja hacia arriba hasta la posición inicial.","Mantén el cuerpo en línea recta en todo momento.","Repite."],["Aprieta el abdomen y los glúteos para evitar que la cadera caiga.","No abras los codos en exceso; mantenlos cerca del torso.","Mantén el cuello neutro mirando al suelo."]],["stability-ball-push-up","Push-Up con Balón de Estabilidad","Un push-up realizado con los pies sobre un balón de estabilidad, que añade una fuerte demanda antirotación al push-up estándar.","Pecho","Fuerza","Intermedio","Pelota de estabilidad",false,["Pectoral mayor"],["Deltoides anterior","Recto abdominal","Serrato anterior","Tríceps braquial"],6.0,"stability-ball-push-up-start.webp","stability-ball-push-up-peak.webp",["Arrodíllate frente a un balón de estabilidad y coloca las espinillas o los pies encima.","Apoya las manos en el suelo bajo los hombros en posición de plancha alta.","Contrae fuerte el core: el balón querrá rodar hacia los lados.","Baja el pecho al suelo doblando los codos.","Vuelve a empujar hasta la posición inicial sin dejar que el balón se tambalee.","Repite el número de repeticiones recomendado."],["Comienza con las espinillas sobre el balón; solo con los pies es mucho más difícil.","Si el balón se desplaza de lado a lado, falta contracción del core: reduce la velocidad."]],["knee-push-ups","Push-Up en Rodillas","Una variante de flexión apta para principiantes, con las rodillas apoyadas en el suelo para reducir la carga sobre el tren superior.","Pecho","Fuerza","Principiante","Sin equipo",true,["Pectoral mayor"],["Deltoides anterior","Recto abdominal","Tríceps braquial"],5.0,"knee-push-ups-start.webp","knee-push-ups-peak.webp",["Comienza en posición de push-up con las rodillas en el suelo.","Coloca las manos a la anchura de los hombros en el suelo.","Mantén el cuerpo en línea recta desde las rodillas hasta los hombros.","Baja el pecho hacia el suelo doblando los codos.","Empuja con las manos para volver a la posición inicial.","Repite el número de repeticiones deseado."],["No abras los codos en exceso hacia los lados.","Aprieta los glúteos y el abdomen durante todo el movimiento.","Mira al suelo para mantener el cuello neutro."]],["archer-push-ups","Push-Ups Arquero","Una flexión ancha bajando hacia una mano mientras el brazo contrario permanece estirado, cargando un lado cada vez.","Pecho","Fuerza","Avanzado","Sin equipo",true,["Pectoral mayor"],["Deltoides anterior","Recto abdominal","Serrato anterior","Tríceps braquial"],5.0,"archer-push-ups-start.webp","archer-push-ups-peak.webp",["Colócate en posición de push-up amplia con los brazos extendidos.","Bájate hacia una mano mientras mantienes el otro brazo extendido.","Mantén el core apretado y el cuerpo en línea recta.","Empuja de vuelta a la posición inicial.","Alterna lados en cada repetición el número de veces deseado."],["Mantén las caderas paralelas al suelo mientras te desplazas hacia el lado.","Deja que el brazo estirado ayude lo menos posible.","Empieza con flexiones anchas y desplázate un poco más en cada sesión."]],["pseudo-planche-push-ups","Push-Ups de Pseudo Plancha","Una flexión con las manos giradas hacia atrás y los hombros inclinados muy por delante de las muñecas, imitando la carga de la plancha.","Hombro","Fuerza","Avanzado","Sin equipo",true,["Deltoides anterior","Pectoral mayor"],["Serrato anterior","Tríceps braquial"],5.0,"pseudo-planche-push-ups-start.webp","pseudo-planche-push-ups-peak.webp",["Comienza en posición de push-up con las manos giradas de modo que los dedos apunten hacia atrás.","Inclina los hombros hacia adelante por delante de las muñecas.","Baja el pecho hacia el suelo flexionando los codos.","Mantén el cuerpo en línea recta.","Empuja hacia arriba manteniendo la inclinación hacia adelante.","Repite el número deseado de repeticiones."],["Cuanto más te inclines hacia delante, más difícil será cada repetición.","Mantén los codos pegados al cuerpo al bajar.","Mantén las escápulas protraídas y el cuerpo rígido."]],["wall-push-ups","Push-Ups en Pared","Una flexión de pie contra la pared apta para principiantes, que trabaja el pecho con carga reducida.","Pecho","Fuerza","Principiante","Sin equipo",true,["Pectoral mayor"],["Deltoides anterior","Tríceps braquial"],5.0,"wall-push-ups-start.webp","wall-push-ups-peak.webp",["Párate frente a una pared y coloca las palmas sobre ella a la altura de los hombros.","Retrocede con los pies hasta que los brazos estén completamente extendidos.","Flexiona los codos para acercar el pecho a la pared.","Mantén el cuerpo en línea recta durante todo el movimiento.","Empuja de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],["Apoya las palmas a la altura de los hombros.","Mantén el cuerpo en línea recta de la cabeza a los pies.","Acerca el pecho a la pared flexionando los codos."]],["incline-push-ups","Push-up inclinado","Una variación del push-up apta para principiantes con las manos elevadas sobre un banco o escalón.","Pecho","Fuerza","Principiante","Sin equipo",true,["Pectoral mayor"],["Deltoides anterior","Tríceps braquial"],5.0,"incline-push-ups-start.webp","incline-push-ups-peak.webp",["Coloca las manos sobre un banco o superficie elevada, a la anchura de los hombros.","Extiende las piernas hacia atrás en posición de plancha.","Baja el pecho hacia el banco flexionando los codos.","Empuja de vuelta a la posición inicial.","Repite."],["Aprieta el abdomen para que la cadera no se hunda.","Cuanto más alta la superficie, más fácil el ejercicio.","Asegúrate de que el banco no se mueva antes de empezar."]],["dumbbell-reverse-fly","Pájaro Invertido con Mancuernas","Un ejercicio de aislamiento inclinado que levanta las mancuernas hacia los lados, trabajando los deltoides posteriores y la espalda alta.","Hombro","Fuerza","Intermedio","Mancuernas",false,["Deltoides posterior"],["Romboides","Trapecio"],5.0,"dumbbell-reverse-fly-start.webp","dumbbell-reverse-fly-peak.webp",["Inclínate hacia adelante desde las caderas sujetando mancuernas con los brazos colgando.","Mantén la espalda recta y las rodillas ligeramente dobladas.","Sube las mancuernas hacia los lados hasta la altura de los hombros.","Aprieta los omóplatos en la parte superior.","Baja las mancuernas de forma controlada.","Repite el número de repeticiones deseado."],["Usa un peso ligero para que trabajen los deltoides posteriores, no el impulso.","Aprieta los omóplatos juntos arriba.","Mantén una flexión suave y fija en los codos en todo momento."]],["rack-pull","Rack Pull","Una variación de peso muerto en rango parcial desde pines a la altura de las rodillas, que enfatiza la parte superior de la espalda, el trapecio y la fuerza de bloqueo con cargas superiores al peso muerto completo.","Espalda","Fuerza","Intermedio","Barra",false,["Erectores espinales","Glúteo mayor","Isquiotibiales","Trapecio"],["Flexores del antebrazo","Antebrazos","Dorsal ancho"],6.0,"rack-pull-start.webp","rack-pull-peak.webp",["Coloca los pines de seguridad en un rack a la altura de las rodillas y apoya una barra cargada sobre ellos.","Párate con los pies al ancho de caderas y agarra la barra justo fuera de las piernas.","Activa el core, retrae las escápulas y empuja con las piernas para levantar la barra.","Extiende completamente caderas y rodillas en la parte superior.","Baja la barra a los pines con control y reposiciónate antes de la siguiente repetición."],["Usa una bisagra de cadera — mantén la barra cerca del cuerpo en todo momento.","Los rack pulls permiten cargas superiores a tu máximo de peso muerto para sobrecargar el bloqueo.","Enfócate en la tensión de la parte superior de la espalda para evitar el redondeo con cargas pesadas."]],["smith-machine-reverse-grip-bent-over-row","Remo Inclinado con Agarre Inverso en Máquina Smith","Un remo inclinado con agarre supino en máquina Smith, que dirige el trabajo a los dorsales y bíceps.","Bíceps","Fuerza","Principiante","Máquina Smith",false,["Bíceps braquial","Dorsal ancho"],["Erectores espinales","Romboides","Trapecio"],6.0,"smith-machine-reverse-grip-bent-over-row-start.webp","smith-machine-reverse-grip-bent-over-row-peak.webp",["De pie dentro de la máquina Smith y agarra la barra con agarre en supinación.","Bisagra hacia adelante en las caderas hasta que el torso esté aproximadamente a 45 grados.","Mantén la espalda plana y el core contraído.","Tira de la barra hacia el abdomen inferior.","Aprieta los dorsales y los omóplatos en la parte superior.","Baja la barra con control y repite."],["Mantén las muñecas rectas; el agarre supino las carga más.","No conviertas el remo en un curl; tira con la espalda.","Evita incorporarte al tirar; el torso mantiene su inclinación."]],["reverse-grip-bent-over-row","Remo Inclinado con Agarre Invertido","Un remo con barra y agarre supino que trabaja dorsales y romboides, con participación de los bíceps.","Espalda","Fuerza","Intermedio","Barra",false,["Dorsal ancho","Romboides"],["Bíceps braquial","Erectores espinales","Trapecio"],6.0,"reverse-grip-bent-over-row-start.webp","reverse-grip-bent-over-row-peak.webp",["Párate con los pies a la anchura de los hombros y agarra la barra con agarre supinado.","Inclínate hacia adelante desde las caderas con una ligera flexión de rodillas.","Deja que la barra cuelgue con los brazos extendidos.","Jala la barra hacia el abdomen inferior llevando los codos hacia atrás.","Aprieta la espalda en la parte superior.","Baja la barra con control.","Repite el número deseado de repeticiones."],["Mantén la espalda neutra y el core firme durante todo el recorrido.","No uses impulso con el torso; el cuerpo queda inclinado y estable.","Mantén las muñecas rectas para proteger los codos con este agarre."]],["cable-bent-over-row","Remo Inclinado con Cable","Una variante de remo con cable que proporciona tensión constante durante todo el movimiento.","Espalda","Fuerza","Intermedio","Polea",false,["Dorsal ancho","Romboides"],["Bíceps braquial","Deltoides posterior"],6.0,"cable-bent-over-row-start.webp","cable-bent-over-row-peak.webp",["Engancha una barra recta o un agarre en V a la polea baja.","Inclínate hacia adelante desde las caderas con las rodillas ligeramente flexionadas.","Tira del agarre hacia la parte inferior del pecho.","Aprieta los omóplatos en la parte superior.","Baja de forma controlada y repite."],["Mantén la espalda recta y el torso estable durante toda la serie.","Piensa en llevar los codos hacia atrás, no en tirar con las manos.","No dejes que el peso te arrastre hacia delante al bajar."]],["smith-machine-bent-over-row","Remo Inclinado en Máquina Smith","Un remo inclinado en máquina Smith que trabaja dorsales y romboides con una trayectoria de barra fija.","Espalda","Fuerza","Principiante","Máquina Smith",false,["Dorsal ancho","Romboides"],["Bíceps braquial","Erectores espinales","Trapecio"],6.0,"smith-machine-bent-over-row-start.webp","smith-machine-bent-over-row-peak.webp",["De pie dentro de la máquina Smith con los pies al ancho de los hombros.","Agarra la barra en pronación ligeramente más ancho que los hombros.","Bisagra en las caderas hasta que el torso esté aproximadamente a 45 grados.","Tira de la barra hacia el pecho inferior llevando los codos hacia atrás.","Aprieta los omóplatos en la parte superior.","Baja la barra con control y repite."],["Mantén la espalda recta y el core firme en la inclinación.","No te incorpores al tirar; el ángulo del torso no cambia.","Evita encoger los hombros hacia las orejas durante el remo."]],["rings-inverted-row","Remo Invertido en Anillas","Un remo horizontal con peso corporal en anillas cerca del suelo, más difícil que el remo de pie en anillas.","Espalda","Fuerza","Intermedio","Anillas",false,["Dorsal ancho","Romboides","Trapecio"],["Bíceps braquial","Flexores del antebrazo","Deltoides posterior","Recto abdominal"],6.0,"rings-inverted-row-start.webp","rings-inverted-row-peak.webp",["Coloca las anillas justo por encima de la cadera.","Acuéstate bajo las anillas y agárralas con las palmas enfrentadas.","Camina con los pies adelante hasta que el cuerpo forme una línea recta.","Tira del pecho hacia las anillas, juntando los omóplatos.","Baja con control hasta extender los brazos."],["Mantén el cuerpo en línea recta — de los talones a la cabeza.","Activa glúteos y core para no hundirte.","Eleva los pies en un cajón para una versión más difícil."]],["pendlay-row","Remo Pendlay","Un remo estricto con barra realizado desde una parada muerta en el suelo entre repeticiones con el torso paralelo al suelo. Popularizado por el entrenador Glenn Pendlay.","Espalda","Fuerza","Intermedio","Barra",false,["Dorsal ancho","Romboides","Trapecio"],["Bíceps braquial","Erectores espinales","Deltoides posterior"],6.0,"pendlay-row-start.webp","pendlay-row-peak.webp",["Carga una barra y colócala en el suelo.","Bisagra en las caderas hasta que el torso quede paralelo al suelo con las rodillas ligeramente dobladas.","Agarra la barra ligeramente más abierta que la anchura de los hombros con un agarre en pronación.","Jala la barra de forma explosiva hacia el pecho inferior.","Baja la barra al suelo con control y haz una pausa antes de la siguiente repetición.","Repite."],["Cada repetición debe comenzar desde el suelo sin rebote.","Mantén el torso fijo a aproximadamente 90 grados; no uses el impulso del cuerpo.","Lleva los codos hacia arriba y atrás, no hacia los lados."]],["seated-cable-row","Remo Sentado en Polea","Un ejercicio de espalda en una máquina de remo con polea, tirando de una manija hacia el torso estando sentado.","Espalda","Fuerza","Intermedio","Polea",false,["Dorsal ancho","Romboides"],["Bíceps braquial","Erectores espinales","Deltoides posterior"],6.0,"seated-cable-row-start.webp","seated-cable-row-peak.webp",["Siéntate en la estación de remo y coloca los pies en los apoyos.","Sujeta la manija y siéntate erguido con una ligera inclinación hacia adelante.","Lleva los codos hacia atrás y tira de la manija hacia la parte baja del abdomen.","Contrae los omóplatos al final del tirón.","Extiende los brazos con control de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],["Mantén el torso erguido con un balanceo mínimo.","Lleva los codos directamente hacia atrás, no hacia los lados.","Contrae los omóplatos al final del tirón."]],["trx-row","Remo TRX","Este ejercicio de tracción con peso corporal utiliza un entrenador de suspensión para trabajar toda tu espalda, desarrollando fuerza en los dorsales, romboides y bíceps.","Espalda","Fuerza","Principiante","Entrenador de suspensión (TRX)",false,["Dorsal ancho","Romboides"],["Bíceps braquial","Deltoides posterior","Trapecio"],6.0,"trx-row-start.webp","trx-row-peak.webp",["Sujeta las asas de un entrenador de suspensión con un agarre prono, las palmas de las manos enfrentadas.","Inclínate hacia atrás, extendiendo completamente los brazos y manteniendo el cuerpo recto de la cabeza a los talones.","Activa tu core y tira del pecho hacia las manos, juntando los omóplatos.","Haz una breve pausa en la parte superior, luego baja lentamente a la posición inicial con control.","Mantén el cuerpo rígido durante todo el movimiento, evitando que las caderas se caigan."],["Ajusta la posición de tus pies: cuanto más cerca estén tus pies del punto de anclaje, más difícil será el ejercicio.","Mantén los codos cerca del cuerpo para enfatizar los dorsales, o ábrelos ligeramente para trabajar más la parte superior de la espalda.","Concéntrate en iniciar la tracción con los músculos de la espalda, no solo con los brazos.","Controla la fase excéntrica (de descenso) para maximizar el compromiso muscular."]],["upright-row","Remo al Mentón con Barra","Un movimiento de tirón compuesto para los deltoides laterales y el trapecio superior.","Hombro","Fuerza","Intermedio","Barra",false,["Deltoides lateral","Trapecio"],["Deltoides anterior","Bíceps braquial"],6.0,"upright-row-start.webp","upright-row-peak.webp",["Párate sosteniendo una barra con un agarre en pronación a la anchura de los hombros.","Tira de la barra hacia arriba a lo largo del cuerpo en dirección al mentón.","Lidera con los codos, manteniéndolos por encima de las manos.","Baja la barra de forma controlada.","Repite."],["Sube la barra pegada al cuerpo hacia la barbilla.","Guía el movimiento con los codos por encima de las manos.","Baja la barra de forma controlada en cada repetición."]],["ez-bar-upright-row","Remo al Mentón con Barra Z","Una variación del remo vertical con barra Z para una posición de muñecas más cómoda.","Hombro","Fuerza","Intermedio","Barra Z",false,["Deltoides lateral","Trapecio"],["Deltoides anterior","Bíceps braquial"],6.0,"ez-bar-upright-row-start.webp","ez-bar-upright-row-peak.webp",["De pie, sujeta la barra Z con agarre a la anchura de los hombros en las partes anguladas.","Tira de la barra hacia arriba a lo largo del cuerpo hasta la altura del mentón.","Lidera el movimiento con los codos, manteniéndolos por encima de las manos.","Baja de forma controlada.","Repite."],["Mantén las muñecas relajadas, sin doblarlas hacia arriba.","Evita balancear el torso para subir la barra.","Si notas molestias en los hombros, reduce el rango o la carga."]],["cable-upright-row","Remo al Mentón con Cable","Un remo al mentón con cable para tensión constante en los deltoides laterales y el trapecio.","Hombro","Fuerza","Intermedio","Polea",false,["Deltoides lateral","Trapecio"],["Deltoides anterior","Bíceps braquial"],6.0,"cable-upright-row-start.webp","cable-upright-row-peak.webp",["Colócate frente a la máquina de cable y agarra una barra recta o cuerda a la altura de los muslos.","Tira de la barra hacia el mentón llevando los codos por delante.","Baja de forma controlada.","Repite."],["Mantén los codos más altos que las muñecas.","Evita encoger los hombros en exceso."]],["dumbbell-upright-row","Remo al Mentón con Mancuernas","Un movimiento de tirón compuesto con mancuernas que trabaja los deltoides laterales y el trapecio superior.","Hombro","Fuerza","Intermedio","Mancuernas",false,["Deltoides lateral","Trapecio"],["Deltoides anterior","Bíceps braquial","Romboides"],6.0,"dumbbell-upright-row-start.webp","dumbbell-upright-row-peak.webp",["Párate sosteniendo dos mancuernas frente a los muslos, palmas hacia el cuerpo.","Tira de las mancuernas recto hacia arriba a lo largo del cuerpo, liderando con los codos.","Sube hasta la altura del mentón con los codos por encima de las muñecas.","Pausa brevemente, luego baja con control.","Repite el número de repeticiones deseado."],["Mantén las mancuernas cerca del cuerpo durante todo el movimiento.","Lidera con los codos, no con las manos.","Evita un agarre muy estrecho para reducir el riesgo de impingement de hombro."]],["smith-machine-upright-row","Remo al Mentón en Máquina Smith","Un remo al mentón en máquina Smith, tirando de la barra guiada por delante del torso con los codos al frente, para trabajar los deltoides laterales y el trapecio superior.","Hombro","Fuerza","Principiante","Máquina Smith",false,["Deltoides lateral","Trapecio"],["Deltoides anterior","Bíceps braquial"],6.0,"smith-machine-upright-row-start.webp","smith-machine-upright-row-peak.webp",["Coloca la barra a la altura de las caderas, toma un agarre prono algo más ancho que los hombros y sitúate cerca de ella con los brazos estirados.","Desengancha la barra y ponte erguido con los hombros atrás y el core activado.","Tira de la barra en línea recta por delante del cuerpo, guiando con los codos y manteniendo la barra cerca.","Detente cuando la barra llegue al pecho inferior y los codos queden a la altura de los hombros, y haz una pausa breve.","Baja la barra de forma controlada hasta estirar los brazos de nuevo y repite las repeticiones deseadas."],["Detente a la altura del pecho. Tirar de la barra hasta la clavícula rota el hombro hacia la posición que provoca el pinzamiento por el que este ejercicio es conocido.","Guía con los codos, no con las manos. Si las muñecas suben primero, toman el relevo los bíceps y los deltoides laterales apenas trabajan.","Abre el agarre si el movimiento pincha. Un agarre estrecho fuerza más rotación interna, y la trayectoria fija de la barra no te deja ninguna alternativa."]],["chest-supported-smith-machine-row","Remo con Apoyo en el Pecho en Máquina Smith","Un remo contra un respaldo inclinado dentro de la máquina Smith, donde el apoyo del pecho saca la zona lumbar del movimiento y la barra guiada mantiene el tirón en una sola línea.","Espalda","Fuerza","Principiante","Máquina Smith",false,["Dorsal ancho","Romboides"],["Bíceps braquial","Deltoides posterior"],6.0,"chest-supported-smith-machine-row-start.webp","chest-supported-smith-machine-row-peak.webp",["Coloca un banco inclinado dentro de la máquina Smith mirando hacia la barra, y baja la barra lo suficiente para que tus brazos cuelguen rectos al apoyarte en el respaldo.","Ponte de pie a horcajadas del banco con los pies firmes y el pecho apoyado en la parte alta del respaldo.","Toma un agarre prono algo más ancho que los hombros y desengancha la barra con los brazos extendidos.","Tira de la barra hacia la parte baja del pecho, guiando con los codos y juntando las escápulas arriba.","Baja la barra de forma controlada hasta estirar los brazos de nuevo y repite el número de repeticiones deseado."],["Mantén el pecho en el respaldo en cada repetición. En cuanto te separas de él para mover el peso lo has convertido otra vez en un remo inclinado y has perdido la razón del montaje.","Guía con los codos y detente cuando pasen del torso. Tirar más solo adelanta los hombros, y la trayectoria fija de la barra no les deja escapatoria.","Como aquí la zona lumbar no hace nada, este es el remo para los días en que un remo inclinado no es opción: ajusta el peso a lo que tu espalda puede tirar, no a lo que tus piernas podrían aguantar."]],["ez-bar-reverse-grip-row","Remo con Barra EZ y Agarre Supino","Este ejercicio compuesto de tracción trabaja el dorsal ancho y el bíceps, desarrollando eficazmente el grosor de la espalda y la fuerza de los brazos con un agarre supinado.","Bíceps","Fuerza","Intermedio","Barra Z",false,["Bíceps braquial","Dorsal ancho"],["Deltoides posterior","Romboides","Trapecio"],6.0,"ez-bar-reverse-grip-row-start.webp","ez-bar-reverse-grip-row-peak.webp",["Ponte de pie con los pies al ancho de los hombros, sujetando una barra EZ con un agarre supino al ancho de los hombros.","Inclínate desde las caderas, manteniendo una ligera flexión de rodillas y la espalda recta, hasta que tu torso esté casi paralelo al suelo.","Deja que la barra cuelgue directamente debajo de tus hombros con los brazos completamente extendidos.","Tira de la barra hacia tu abdomen inferior, apretando los omóplatos y llevando los codos hacia arriba.","Controla la fase excéntrica, bajando lentamente la barra a la posición inicial con los brazos completamente extendidos."],["Mantén una columna vertebral neutra durante todo el movimiento para proteger tu espalda baja.","Concéntrate en iniciar la tracción con los dorsales, no solo con los bíceps.","Evita encogerte de hombros; manténlos deprimidos y retraídos.","Utiliza un rango completo de movimiento, extendiendo los brazos por completo en la parte inferior."]],["barbell-row","Remo con Barra Inclinado","Un movimiento de jalón compuesto que trabaja la parte superior e intermedia de la espalda.","Espalda","Fuerza","Intermedio","Barra",false,["Dorsal ancho","Romboides"],["Bíceps braquial","Deltoides posterior"],6.0,"barbell-row-start.webp","barbell-row-peak.webp",["Inclínate en las caderas con una ligera flexión de rodillas.","Agarra la barra ligeramente más ancho que la anchura de los hombros.","Tira de la barra hacia el pecho inferior apretando los omóplatos.","Baja la barra de forma controlada.","Repite."],["Mantén el torso a aproximadamente 45 grados.","No uses el impulso para balancear el peso."]],["bent-over-ez-bar-row","Remo con Barra Z Inclinado","Un movimiento de jalón horizontal con barra Z para un ejercicio de remo de espalda amigable con las muñecas.","Espalda","Fuerza","Intermedio","Barra Z",false,["Dorsal ancho","Romboides"],["Bíceps braquial","Deltoides posterior"],6.0,"bent-over-ez-bar-row-start.webp","bent-over-ez-bar-row-peak.webp",["Sostén una barra Z con agarre prono e inclínate en las caderas a 45 grados.","Tira de la barra hacia la parte inferior de las costillas.","Baja de forma controlada.","Repite."],["Mantén la espalda plana durante todo el movimiento.","Inicia el movimiento con los codos, no con las manos."]],["barbell-rear-delt-row","Remo con Barra para Deltoides Posterior","Un remo con barra inclinado con los codos abiertos que traslada el énfasis de los dorsales a los deltoides posteriores y la parte alta de la espalda.","Hombro","Fuerza","Intermedio","Barra",false,["Deltoides posterior"],["Dorsal ancho","Romboides","Trapecio"],6.0,"barbell-rear-delt-row-start.webp","barbell-rear-delt-row-peak.webp",["Inclínate en las caderas con la espalda plana hasta que el torso quede casi paralelo al suelo.","Sostén una barra con agarre prono, más ancho que la anchura de los hombros, brazos colgando.","Rema la barra hacia el pecho superior con los codos abiertos hacia los lados.","Haz una pausa y aprieta los deltoides posteriores y la parte alta de la espalda en la cima.","Baja la barra de forma controlada y repite."],["Jala con los codos, no con las manos: piensa en impulsarlos hacia arriba y hacia afuera.","Usa una carga menor que en un remo estándar; el agarre ancho reduce el brazo de palanca."]],["double-kettlebell-row","Remo con Dos Pesas Rusas","Un remo inclinado con dos pesas rusas que desarrolla dorsales y romboides con fuerte trabajo postural.","Espalda","Fuerza","Intermedio","Kettlebell",false,["Dorsal ancho","Romboides"],["Bíceps braquial","Erectores espinales","Trapecio"],6.0,"double-kettlebell-row-start.webp","double-kettlebell-row-peak.webp",["Sujeta una pesa rusa en cada mano e inclínate hacia adelante desde las caderas.","Deja los brazos colgando rectos desde los hombros.","Rema ambas pesas rusas hacia las caderas llevando los codos hacia atrás.","Aprieta los omóplatos en la parte superior.","Baja de forma controlada y repite."],["No redondees la zona lumbar al mantener la inclinación.","Evita los tirones y rema con un movimiento fluido.","Si la fatiga rompe tu postura, termina la serie."]],["double-kettlebell-rear-delt-row","Remo con Dos Pesas Rusas para Deltoides Posterior","Un remo inclinado con una pesa rusa en cada mano y los codos abiertos hacia fuera, lejos del torso, que traslada el trabajo de los dorsales a los deltoides posteriores y la parte alta de la espalda.","Hombro","Fuerza","Intermedio","Kettlebell",false,["Deltoides posterior","Romboides"],["Bíceps braquial","Erectores espinales","Dorsal ancho","Trapecio"],6.0,"double-kettlebell-rear-delt-row-start.webp","double-kettlebell-rear-delt-row-peak.webp",["Coloca una pesa rusa justo por fuera de cada pie, con los pies separados a la anchura de las caderas.","Inclínate desde las caderas con la espalda plana hasta que el torso quede casi paralelo al suelo, con las rodillas ligeramente flexionadas.","Sujeta ambas asas con agarre prono y deja los brazos colgando rectos desde los hombros.","Rema ambas pesas llevando los codos hacia los lados, alejándolos de las costillas en lugar de deslizarlos hacia atrás junto a ellas.","Detente cuando los brazos queden más o menos en línea con los hombros y aprieta los omóplatos.","Baja las pesas de forma controlada hasta que los brazos vuelvan a colgar rectos y repite las repeticiones deseadas."],["El codo abierto es toda la clave. Si se pega a las costillas estarás haciendo un remo con dos pesas rusas normal y trabajando los dorsales en lugar de los deltoides posteriores.","Usa menos carga que en un remo convencional. El codo abierto es una palanca larga y el deltoides posterior es un motor mucho más pequeño que el dorsal.","Mantén constante el ángulo de la inclinación. Enderezarte al tirar traslada el trabajo al trapecio y a la zona lumbar y acorta justo el rango en el que trabaja el deltoides posterior."]],["chest-supported-kettlebell-row","Remo con Kettlebell Apoyado en el Pecho","Este ejercicio trabaja los músculos de tu espalda, principalmente el dorsal ancho y los romboides, al tirar de una kettlebell hacia tu pecho mientras tu torso está apoyado.","Espalda","Fuerza","Principiante","Kettlebell",false,["Dorsal ancho","Romboides"],["Bíceps braquial","Deltoides posterior","Trapecio"],6.0,"chest-supported-kettlebell-row-start.webp","chest-supported-kettlebell-row-peak.webp",["Acuéstate boca abajo en un banco inclinado, dejando que tus brazos cuelguen libremente con una kettlebell en cada mano.","Contrae tu abdomen y retrae tus escápulas.","Tira de las kettlebells hacia tus caderas, apretando tus escápulas.","Haz una breve pausa en la parte superior, sintiendo la contracción en tu espalda.","Baja lentamente las kettlebells a la posición inicial con control."],["Mantén el torso estable durante todo el movimiento; evita balancearte.","Concéntrate en iniciar el tirón con los músculos de la espalda, no solo con los brazos.","Mantén los codos cerca de tu cuerpo para enfatizar el dorsal ancho."]],["single-arm-db-row","Remo con Mancuerna a Un Brazo","Un ejercicio de espalda unilateral con mancuerna para un desarrollo equilibrado.","Espalda","Fuerza","Intermedio","Mancuernas",false,["Dorsal ancho","Romboides"],["Bíceps braquial","Deltoides posterior"],6.0,"single-arm-db-row-start.webp","single-arm-db-row-peak.webp",["Coloca una rodilla y una mano en un banco como apoyo.","Sostén una mancuerna en la otra mano con el brazo extendido.","Tira de la mancuerna hacia la cadera apretando el omóplato.","Baja la mancuerna con control.","Repite de ambos lados."],["No gires el torso al tirar; mantén la cadera estable.","Evita encoger el hombro hacia la oreja al iniciar el tirón.","Haz las mismas repeticiones con cada brazo."]],["single-arm-chest-supported-dumbbell-row","Remo con Mancuerna a Una Mano con Pecho Apoyado","Un remo unilateral realizado con un brazo a la vez sobre un banco inclinado con apoyo para el pecho, que aísla cada lado de la espalda y reduce el impulso.","Espalda","Fuerza","Intermedio","Mancuernas",false,["Dorsal ancho","Romboides"],["Bíceps braquial","Deltoides posterior"],6.0,"single-arm-chest-supported-dumbbell-row-start.webp","single-arm-chest-supported-dumbbell-row-peak.webp",["Túmbate boca abajo en un banco inclinado sujetando una mancuerna con una mano, con el brazo colgando recto hacia abajo.","Rema la mancuerna hacia tu costado, llevando el codo más allá del torso.","Aprieta el omóplato en la parte superior y luego baja de forma controlada.","Completa todas las repeticiones de un lado antes de cambiar de brazo."],["Trabajar un lado a la vez te permite concentrarte en una contracción completa sin que el otro brazo compense.","Mantén el pecho presionado contra el banco durante todo el movimiento para evitar usar impulso.","Iguala el número de repeticiones en ambos lados para evitar desequilibrios."]],["bent-over-db-row","Remo con Mancuernas Inclinado","Un remo inclinado a dos brazos con una mancuerna en cada mano, que trabaja la espalda y exige estabilidad.","Espalda","Fuerza","Intermedio","Mancuernas",false,["Dorsal ancho","Romboides"],["Bíceps braquial","Deltoides posterior","Trapecio"],6.0,"bent-over-db-row-start.webp","bent-over-db-row-peak.webp",["Ponte de pie con los pies a la anchura de las caderas, sujetando una mancuerna en cada mano a los lados, con las palmas hacia dentro.","Flexiona las caderas con la espalda recta hasta que el torso quede a unos 30–45 grados de la horizontal, con las mancuernas colgando justo debajo de los hombros.","Activa el core y tira de ambas mancuernas hacia arriba y ligeramente atrás, llevando los codos por detrás de las costillas.","Aprieta la parte alta de la espalda arriba, manteniendo los codos pegados.","Baja de forma controlada hasta la posición inicial con los brazos completamente estirados.","Repite el número de repeticiones recomendado."],["El ángulo del torso se mantiene fijo todo el rato; no te incorpores para ayudar al peso.","Tira hacia las costillas bajas o el abdomen, no hacia el pecho; así mantienes el dorsal cargado.","Si la lumbar se redondea, flexiona menos y recoloca antes de la siguiente serie."]],["chest-supported-db-row","Remo con Mancuernas con Apoyo en el Pecho","Un remo con mancuernas con apoyo en el pecho para eliminar la tensión en la zona lumbar y aislar los músculos de la espalda.","Espalda","Fuerza","Intermedio","Mancuernas",false,["Dorsal ancho","Romboides"],["Bíceps braquial","Deltoides posterior"],6.0,"chest-supported-db-row-start.webp","chest-supported-db-row-peak.webp",["Túmbate boca abajo en un banco inclinado con las mancuernas colgando por debajo.","Rema las mancuernas hacia los lados.","Aprieta en la parte superior y baja.","Repite."],["El apoyo en el pecho elimina la fatiga de la espalda.","Concéntrate en juntar los omóplatos."]],["one-arm-kettlebell-row","Remo con Pesa Rusa a Un Brazo","Un remo unilateral con pesa rusa y apoyo en banco, que fortalece el dorsal ancho y los romboides de cada lado.","Espalda","Fuerza","Intermedio","Kettlebell",false,["Dorsal ancho","Romboides"],["Bíceps braquial","Deltoides posterior","Trapecio"],6.0,"one-arm-kettlebell-row-start.webp","one-arm-kettlebell-row-peak.webp",["Apoya una mano y una rodilla sobre un banco para sujetarte.","Sostén una pesa rusa en la mano contraria con el brazo extendido.","Jala la pesa rusa hacia la cadera llevando el codo hacia atrás.","Aprieta la espalda en la parte superior del movimiento.","Baja la pesa rusa con control.","Completa las repeticiones de un lado y luego cambia."],["Mantén la espalda plana y paralela al suelo.","Evita rotar el torso al subir la pesa.","Tira con la espalda, no solo con el bíceps."]],["sled-row","Remo con Trineo","Un remo con carga: agarras el trineo y lo tiras hacia ti mientras caminas hacia atrás, trabajando la espalda con un arrastre continuo en lugar de repeticiones sueltas.","Espalda","Fuerza","Intermedio","Trineo",false,["Dorsal ancho"],["Bíceps braquial","Glúteo mayor","Deltoides posterior","Romboides","Trapecio"],6.0,"sled-row-start.webp","sled-row-peak.webp",["Carga el trineo y agarra sus postes con ambas manos, una en cada poste.","Ponte de pie frente al trineo con los brazos estirados y el torso ligeramente inclinado hacia atrás contra la carga.","Tira del trineo hacia ti llevando los codos atrás y da un paso corto hacia atrás al mismo tiempo.","Estira los brazos de nuevo, da otro paso atrás y repite el tirón.","Continúa por distancia o por tiempo, manteniendo un ritmo constante de tirón y paso."],["Pecho arriba y espalda recta: deja que las piernas te lleven hacia atrás en vez de encorvarte sobre el trineo.","Usa una carga que puedas mover de forma continua; la idea es un arrastre constante, no un tirón máximo.","Si tu gimnasio tiene asas o una cuerda para el trineo, funcionan igual."]],["ring-row","Remo en Anillas","Un remo con peso corporal en anillas de gimnasia, realizado en ángulo para trabajar espalda y bíceps.","Espalda","Fuerza","Principiante","Anillas",false,["Dorsal ancho","Romboides"],["Bíceps braquial","Deltoides posterior","Trapecio"],6.0,"ring-row-start.webp","ring-row-peak.webp",["Coloca las anillas a la altura de la cadera o el pecho.","Sujeta las anillas con las palmas enfrentadas, inclínate atrás con los brazos rectos.","Activa el core y tira del pecho hacia las anillas.","Junta los omóplatos arriba.","Baja con control hasta extender los brazos."],["Cuanto más bajo el ángulo del cuerpo, más difícil el remo.","Mantén el cuerpo recto — no dejes caer las caderas.","Tira con los codos atrás, no abiertos, para más implicación dorsal."]],["bench-pull","Remo en Banco","Un remo tumbado boca abajo sobre un banco elevado que centra el trabajo en la espalda al apoyar el torso.","Espalda","Fuerza","Intermedio","Barra",false,["Dorsal ancho","Romboides"],["Bíceps braquial","Deltoides posterior","Trapecio"],6.0,"bench-pull-start.webp","bench-pull-peak.webp",["Acuéstate boca abajo en un banco elevado con los brazos colgando rectos hacia abajo.","Agarra una barra o mancuernas debajo de ti.","Rema el peso hasta la parte inferior del banco.","Aprieta los omóplatos en la parte superior.","Baja de forma controlada y repite."],["Mantén el pecho pegado al banco durante toda la serie.","Tira con los codos en lugar de con las manos.","Evita los tirones bruscos al iniciar cada repetición."]],["dumbbell-bench-pull","Remo en Banco con Mancuernas","Un movimiento de remo boca abajo sobre un banco para trabajar la parte superior de la espalda de forma estricta.","Espalda","Fuerza","Intermedio","Mancuernas",false,["Dorsal ancho","Romboides"],["Bíceps braquial","Deltoides posterior"],6.0,"dumbbell-bench-pull-start.webp","dumbbell-bench-pull-peak.webp",["Túmbate boca abajo en un banco inclinado sujetando mancuernas.","Deja los brazos colgando rectos hacia abajo.","Tira de las mancuernas hacia el pecho apretando los omóplatos.","Baja de forma controlada.","Repite."],["Mantén el pecho pegado al banco en todo momento.","Inicia el tirón con la espalda, no con los bíceps.","Controla la bajada hasta estirar por completo los brazos."]],["kneeling-cable-row","Remo en Polea Arrodillado","Un remo en polea ejecutado desde una posición de rodillas erguida, eliminando el impulso de cadera y manteniendo la tensión en la parte superior de la espalda durante todo el movimiento.","Espalda","Fuerza","Principiante","Polea",false,["Dorsal ancho"],["Bíceps braquial","Deltoides posterior","Romboides","Trapecio"],6.0,"kneeling-cable-row-start.webp","kneeling-cable-row-peak.webp",["Ajusta la polea a la altura del pecho y conecta una cuerda o un mango doble en D.","Arrodíllate erguido frente a la máquina lo suficientemente lejos para que el peso no llegue al tope.","Agarra el mango con ambas manos y sostenlo extendido frente a ti a la altura del pecho.","Lleva el mango hacia el esternón llevando los codos hacia atrás y apretando los omóplatos.","Regresa de forma controlada a la posición inicial con estiramiento.","Repite el número de repeticiones recomendado."],["Mantente erguido: no te inclines hacia atrás para terminar la repetición.","La postura de rodillas erguidas obliga al core a resistir la rotación en cada tirón."]],["wide-grip-seated-cable-row","Remo en Polea Sentado en Agarre Ancho","Una variante del remo sentado con agarre ancho que hace énfasis en la parte superior de la espalda.","Espalda","Fuerza","Intermedio","Polea",false,["Dorsal ancho","Romboides"],["Bíceps braquial","Deltoides posterior"],6.0,"wide-grip-seated-cable-row-start.webp","wide-grip-seated-cable-row-peak.webp",["Siéntate en la estación de remo con los pies en la plataforma.","Agarra la barra ancha con un agarre en pronación.","Tira de la barra hacia el abdomen superior apretando los omóplatos.","Extiende los brazos de vuelta a la posición inicial de forma controlada.","Repite."],["Sujeta la barra ancha con agarre prono.","Lleva la barra hacia el abdomen alto juntando los omóplatos.","Extiende los brazos al frente de forma controlada."]],["t-bar-row","Remo en T","Un remo compuesto con barra en T y torso inclinado, que desarrolla dorsales y romboides con cargas elevadas.","Espalda","Fuerza","Intermedio","Barra",false,["Dorsal ancho","Romboides"],["Bíceps braquial","Erectores espinales","Trapecio"],6.0,"t-bar-row-start.webp","t-bar-row-peak.webp",["Colócate a horcajadas sobre la barra en T con los pies al ancho de los hombros.","Inclínate en las caderas hasta que el torso quede a unos 45 grados.","Agarra los mangos y mantén la espalda plana.","Tira de la barra hacia el pecho llevando los codos hacia atrás.","Aprieta los omóplatos en la parte superior.","Baja la barra de forma controlada y repite."],["Inclina el torso unos 45 grados manteniendo la espalda plana.","Tira llevando los codos hacia atrás, no solo con los brazos.","Junta los omóplatos en la parte alta del tirón."]],["inverted-row","Remo invertido","Un ejercicio de jalón horizontal con el peso corporal realizado bajo una barra fija, tirando del pecho hacia la barra mientras se mantiene el cuerpo rígido.","Espalda","Fuerza","Intermedio","Barra",false,["Dorsal ancho","Romboides","Trapecio"],["Bíceps braquial","Deltoides posterior","Recto abdominal"],6.0,"inverted-row-start.webp","inverted-row-peak.webp",["Coloca una barra en un rack a la altura de la cintura aproximadamente.","Acuéstate debajo y agarra la barra ligeramente más ancha que los hombros con agarre prono.","Cuélgate con los brazos extendidos, los talones en el suelo y el cuerpo recto de la cabeza a los tobillos.","Tira del pecho hacia la barra, apretando los omóplatos.","Bájate con control hasta que los brazos estén completamente extendidos.","Repite."],["Mantén el core contraído — sin que las caderas se hundan.","Para hacerlo más difícil, eleva los pies; para hacerlo más fácil, camina los pies hacia la barra.","Haz una breve pausa en la parte superior con el pecho contra la barra."]],["chin-tuck-hold","Retracción de Mentón Sostenida","Un ejercicio estático de cuello que retrae la cabeza hacia atrás para fortalecer los flexores profundos del cuello y contrarrestar la postura de cabeza adelantada.","Cuerpo completo","Fuerza","Intermedio","Sin equipo",true,["Trapecio"],["Romboides"],5.0,"chin-tuck-hold-main.webp",null,["Ponte de pie o siéntate erguido con los hombros relajados.","Lleva el mentón recto hacia atrás, creando una papada.","Mantén la cabeza nivelada sin inclinarla.","Mantén la posición durante el tiempo deseado.","Suelta y repite durante varias series."],["Imagina deslizar la cabeza hacia atrás sobre la columna, no asentir hacia abajo.","Mantén la mirada nivelada y la respiración relajada."]],["downward-dog-to-knee-drive","Rodilla al Codo desde Perro de Tres Patas","Desde el perro de tres patas, la pierna elevada se pliega hacia delante para llevar la rodilla hacia el codo o la nariz y vuelve a extenderse. Los hombros sostienen la posición y el tronco hace el plegado, un lado cada vez.","Pierna","Fuerza","Intermedio","Sin equipo",true,["Flexores de cadera","Recto abdominal"],["Deltoides anterior","Glúteo mayor","Serrato anterior"],5.0,"downward-dog-to-knee-drive-start.webp","downward-dog-to-knee-drive-peak.webp",["Colócate en perro boca abajo y eleva una pierna por detrás a perro de tres patas.","Presiona ambas manos contra el suelo y desplaza el peso ligeramente hacia delante.","Redondea la espalda alta y lleva esa rodilla hacia el codo o la nariz.","Extiende la pierna de vuelta arriba de forma controlada.","Termina las repeticiones de ese lado y cambia."],["Deja que la espalda alta se redondee al entrar la rodilla; con la espalda plana la rodilla se queda corta.","Mantén los hombros sobre las muñecas al desplazarte en lugar de pasarte por delante.","Eleva la pierna solo hasta donde las caderas sigan niveladas al salir."]],["downward-dog-knee-tuck","Rodilla al Pecho en Perro Boca Abajo","Un ejercicio dinámico de core sostenido en perro boca abajo: las caderas se mantienen altas mientras una rodilla se lleva bajo el pecho y vuelve al inicio, alternando lados. Los hombros sostienen toda la serie, de modo que el tronco trabaja sin la posición baja de cadera de una plancha.","Pierna","Fuerza","Intermedio","Sin equipo",true,["Flexores de cadera","Recto abdominal"],["Deltoides anterior","Serrato anterior","Transverso abdominal"],5.0,"downward-dog-knee-tuck-start.webp","downward-dog-knee-tuck-peak.webp",["Colócate en perro boca abajo con las manos a la anchura de los hombros y las caderas altas.","Empuja el suelo y aprieta el tronco para que la zona lumbar siga larga.","Lleva una rodilla hacia el pecho, redondeando ligeramente la espalda alta al entrar.","Extiende la pierna de vuelta a la posición inicial de forma controlada.","Repite con la otra pierna y sigue alternando las veces indicadas."],["Mantén las caderas altas; si caen, esto se convierte en un escalador.","Lleva la rodilla con el abdomen en lugar de impulsarte con el pie de apoyo.","Aleja los hombros de las orejas para que el tronco no se hunda entre los brazos."]],["high-knees","Rodillas Altas","Un ejercicio cardio con peso corporal en el que las rodillas suben a la altura de la cadera en alternancia rápida.","Cuerpo completo","Cardio","Principiante","Sin equipo",true,["Flexores de cadera","Cuádriceps"],["Gemelos","Recto abdominal"],8.0,"high-knees-main.webp",null,["Mantente erguido con los pies a la anchura de las caderas.","Lleva una rodilla arriba hacia el pecho bombeando el brazo opuesto.","Cambia de pierna rápidamente, espejando la acción del brazo.","Continúa alternando a ritmo rápido.","Continúa durante el intervalo de trabajo indicado."],["Sube las rodillas al menos a la altura de la cadera.","Mantente ligero sobre las puntas de los pies.","Mantén el torso erguido — no te eches atrás."]],["wrist-roller","Rodillo de Muñeca","Un ejercicio para el antebrazo que consiste en enrollar un peso con la cuerda mediante el giro de las muñecas.","Antebrazo","Fuerza","Intermedio","Rodillo de muñeca",false,["Extensores del antebrazo","Flexores del antebrazo"],["Deltoides anterior"],6.0,"wrist-roller-start.webp","wrist-roller-peak.webp",["Agarra el mango del rodillo con los brazos extendidos al frente a la altura de los hombros.","Deja que el peso cuelgue del cordón.","Enrolla el mango hacia adelante con movimientos alternos de muñeca para subir el peso.","Mantén los brazos rectos durante todo el movimiento.","Una vez enrollado por completo, invierte la rotación para bajar el peso.","Repite el número de repeticiones deseado."],["Mantén los brazos extendidos al frente a la altura de los hombros.","Enrolla la cuerda con giros alternos de las muñecas.","Invierte la rotación para bajar el peso de forma controlada."]],["pilates-roll-down","Roll Down de Pilates","Una articulación de la columna de pie: la cabeza guía un descenso vértebra a vértebra hacia el suelo y de vuelta, movilizando toda la espalda mientras las piernas se mantienen estables.","Espalda","Estiramiento","Principiante","Sin equipo",true,["Erectores espinales"],["Isquiotibiales","Recto abdominal"],5.0,"pilates-roll-down-start.webp","pilates-roll-down-peak.webp",["Ponte de pie con los pies a la anchura de las caderas y los brazos colgando a los lados.","Lleva la barbilla al pecho y empieza a rodar hacia abajo vértebra a vértebra.","Deja los brazos y la cabeza colgando pesados cuando la columna esté completamente descendida.","Sube por el mismo camino, apilando las vértebras una a una, la cabeza al final.","Repite las veces indicadas."],["Mantén las rodillas blandas para que el movimiento venga de la columna y no de los isquiotibiales.","Ve lo bastante despacio como para sentir cada segmento; la velocidad arruina el ejercicio.","Mantén el peso en el centro de los pies mientras bajas."]],["pilates-roll-over","Roll Over de Pilates","Una inversión controlada desde la colchoneta: con los brazos presionando el suelo, las piernas estiradas viajan por encima de la cabeza hasta que los pies apuntan al suelo, y después la columna vuelve a bajar segmento a segmento.","Core","Fuerza","Avanzado","Sin equipo",true,["Recto abdominal","Transverso abdominal"],["Erectores espinales","Flexores de cadera"],5.0,"pilates-roll-over-start.webp","pilates-roll-over-peak.webp",["Túmbate boca arriba con las piernas estiradas y los brazos presionando la colchoneta a los lados.","Eleva ambas piernas a la vertical sin dejar que la zona lumbar se arquee.","Presiona los brazos hacia abajo y lleva las piernas por encima de la cabeza hasta dejarlas paralelas al suelo por detrás.","Abre un poco las piernas, flexiona los pies y baja la columna vértebra a vértebra.","Devuelve las piernas a la vertical y repite las veces indicadas."],["Impulsa el movimiento con el abdomen, no lanzando las piernas.","Mantén el peso fuera del cuello: el descenso se detiene en las escápulas.","Evita este ejercicio si tienes molestias cervicales y constrúyelo antes con curls más pequeños."]],["cable-external-rotation","Rotación Externa con Cable","Un ejercicio de rotación externa en polea, con el codo pegado al costado, que fortalece el deltoides posterior y la parte alta de la espalda.","Hombro","Fuerza","Intermedio","Polea",false,["Deltoides posterior"],["Romboides","Trapecio"],6.0,"cable-external-rotation-start.webp","cable-external-rotation-peak.webp",["Ajusta la polea a la altura del codo y agarra el handle.","Colócate de lado a la máquina con el codo de trabajo flexionado a 90 grados.","Mantén el codo pegado al costado y rota el antebrazo hacia afuera.","Pausa al final del movimiento.","Vuelve de forma controlada. Completa las repeticiones de un lado y luego cambia."],["Evita encoger los hombros mientras giras el brazo.","Trabaja con poco peso y de forma lenta y controlada.","Mantén la muñeca firme, alineada con el antebrazo."]],["ab-wheel-rollout","Rueda Abdominal","Un ejercicio de core haciendo rodar una rueda adelante y atrás, que entrena la antiextensión de la columna.","Core","Fuerza","Intermedio","Rueda abdominal",false,["Recto abdominal","Transverso abdominal"],["Deltoides anterior","Dorsal ancho","Oblicuos","Serrato anterior"],6.0,"ab-wheel-rollout-start.webp","ab-wheel-rollout-peak.webp",["Arrodíllate en el suelo y agarra las asas de la rueda a la anchura de los hombros.","Activa fuertemente el core para que la zona lumbar quede neutra.","Rueda la rueda lentamente hacia adelante, extendiendo el cuerpo lo más lejos que puedas controlar.","Detente antes de que las caderas se hundan o la espalda se arquee.","Tira de la rueda de regreso hacia las rodillas contrayendo los abdominales."],["Activa el core antes de cada repetición — no dejes que la lumbar se arquee.","Aumenta el rango progresivamente, parando antes de que las caderas se hundan.","Usa un tope contra la pared si no puedes controlar la posición baja."]],["barbell-ab-rollout","Rueda Abdominal con Barra","Una rueda abdominal de rodillas usando una barra cargada con discos, que ofrece un rodamiento más suave y carga ajustable en comparación con la rueda abdominal.","Core","Fuerza","Intermedio","Barra",false,["Recto abdominal"],["Dorsal ancho","Oblicuos","Transverso abdominal"],6.0,"barbell-ab-rollout-start.webp","barbell-ab-rollout-peak.webp",["Carga discos del mismo tamaño en ambos extremos de la barra y colócala en el suelo.","Arrodíllate detrás de la barra y agárrala a la anchura de los hombros con los brazos extendidos.","Contrae el core con fuerza, luego rueda la barra hacia adelante alejándola del cuerpo.","Avanza hasta donde puedas mantener la columna neutra: detente antes de que las caderas se hundan.","Tira de la barra de vuelta a la posición inicial contrayendo los abdominales y el dorsal.","Repite el número de repeticiones recomendado."],["Empieza con discos pequeños para un rango limitado; pasa a los de 20 kg para rodamientos completos.","En el momento en que la zona lumbar se arquee o caiga, detente: has superado tu rango."]],["jump-rope","Saltar la Cuerda","Un ejercicio cardio clásico que trabaja gemelos, tobillos y ritmo con una cuerda y saltos rítmicos.","Cuerpo completo","Cardio","Principiante","Cuerda de saltar",false,["Gemelos","Sóleo"],["Flexores del antebrazo","Cuádriceps"],11.8,"jump-rope-main.webp",null,["Sujeta el mango de la cuerda en cada mano con la cuerda detrás de ti.","Balancea la cuerda sobre la cabeza y al frente en un arco fluido.","Salta justo lo suficiente para que la cuerda pase bajo los pies.","Aterriza suave sobre las puntas, rodillas ligeramente flexionadas.","Mantén un ritmo constante durante el intervalo indicado."],["Gira la cuerda con las muñecas, no con los hombros.","Salta bajo — apenas dos o tres centímetros del suelo.","Mantente erguido con los codos cerca del cuerpo."]],["box-jump","Salto al Cajón","Un salto pliométrico desde media sentadilla a un cajón estable, que entrena la potencia del tren inferior.","Pierna","Pliometría","Intermedio","Cajón pliométrico",false,["Glúteo mayor","Cuádriceps"],["Gemelos","Isquiotibiales","Sóleo"],7.0,"box-jump-start.webp","box-jump-peak.webp",["Mantente a unos 30 cm frente a un cajón firme con los pies a la anchura de los hombros.","Baja a una media sentadilla y balancea los brazos atrás.","Lanza los brazos arriba y salta explosivamente al cajón.","Aterriza suave con los pies planos y rodillas flexionadas.","Baja caminando — no saltando — y reinicia."],["Baja siempre caminando — los saltos hacia abajo repetidos sobrecargan el Aquiles.","Aterriza suave con todo el pie, rodillas alineadas con los dedos.","Elige una altura que puedas superar sin doblar la cadera."]],["jumping-jacks","Saltos de Tijera","Este clásico ejercicio dinámico de cuerpo completo eleva la frecuencia cardíaca y trabaja pantorrillas, hombros, cuádriceps y glúteos, siendo excelente para calentar o acondicionar.","Cuerpo completo","Cardio","Principiante","Sin equipo",true,["Gemelos","Glúteo medio","Deltoides lateral"],["Abductores","Cuádriceps","Sóleo"],8.0,"jumping-jacks-start.webp","jumping-jacks-peak.webp",["Ponte de pie con los pies juntos y los brazos a los lados.","Simultáneamente, salta abriendo las piernas y levantando los brazos por encima de la cabeza.","Asegúrate de que tus brazos se junten o casi se junten por encima de tu cabeza.","Salta juntando los pies de nuevo mientras bajas los brazos a los lados.","Mantén un movimiento continuo y rítmico."],["Aterriza suavemente sobre las puntas de los pies para absorber el impacto.","Mantén tu core activado durante todo el movimiento.","Controla tu respiración; inhala al saltar hacia afuera, exhala al saltar hacia adentro.","Aumenta la velocidad para un mayor desafío cardiovascular."]],["bulgarian-split-squat","Sentadilla Búlgara","Una variante de sentadilla unilateral con el pie trasero elevado.","Pierna","Fuerza","Intermedio","Mancuernas",false,["Glúteo mayor","Cuádriceps"],["Isquiotibiales"],6.0,"bulgarian-split-squat-start.webp","bulgarian-split-squat-peak.webp",["Colócate de pie frente a un banco y apoya un pie detrás sobre el banco.","Sujeta mancuernas a los lados.","Baja el cuerpo hasta que el muslo delantero quede paralelo al suelo.","Empuja con el talón delantero para volver a la posición de pie.","Repite en ambos lados."],["Mantén casi todo el peso sobre la pierna adelantada.","Ajusta la distancia al banco hasta que la zancada sea estable.","Completa todas las repeticiones con una pierna antes de cambiar."]],["kettlebell-bulgarian-split-squat","Sentadilla Búlgara con Kettlebell","Esta variación unilateral de sentadilla desarrolla fuerza, músculo y estabilidad en la parte inferior del cuerpo al elevar el pie trasero y sostener una kettlebell, apuntando principalmente a los cuádriceps y glúteos.","Pierna","Fuerza","Intermedio","Kettlebell",false,["Glúteo mayor","Cuádriceps"],["Glúteo medio","Isquiotibiales"],6.0,"kettlebell-bulgarian-split-squat-start.webp","kettlebell-bulgarian-split-squat-peak.webp",["Párate de espaldas a un banco, colocando un pie sobre él detrás de ti, con los cordones hacia abajo. Sostén una kettlebell en la mano opuesta.","Mantén el torso erguido y activa tu core.","Baja tu cuerpo doblando ambas rodillas, permitiendo que tu rodilla delantera se alinee con tus dedos del pie.","Desciende hasta que tu muslo delantero esté paralelo al suelo o ligeramente por debajo, manteniendo tu rodilla trasera cerca del suelo.","Impúlsate a través del talón delantero para regresar a la posición inicial, extendiendo tus caderas y rodillas.","Completa todas las repeticiones por lado antes de cambiar."],["Asegúrate de que tu pie delantero esté lo suficientemente lejos del banco para permitir un rango completo de movimiento sin molestias.","Mantén tu torso erguido durante todo el movimiento para maximizar la activación de glúteos y cuádriceps.","Controla la fase excéntrica (descenso) para desarrollar fuerza y estabilidad.","Experimenta sosteniendo la kettlebell en la misma mano que la pierna que trabaja (ipsilateral) o en la mano opuesta (contralateral) para diferentes desafíos."]],["smith-machine-bulgarian-split","Sentadilla Búlgara en Máquina Smith","Una sentadilla búlgara realizada en la máquina Smith para mayor estabilidad y control de la carga.","Pierna","Fuerza","Intermedio","Máquina Smith",false,["Glúteo mayor","Cuádriceps"],["Isquiotibiales"],6.0,"smith-machine-bulgarian-split-start.webp","smith-machine-bulgarian-split-peak.webp",["Coloca un banco detrás de la máquina Smith. Apoya la barra sobre los trapecios.","Coloca el pie trasero en el banco y el pie delantero hacia adelante.","Baja la rodilla trasera hacia el suelo.","Empuja con el talón delantero para volver.","Repite de ambos lados."],["La máquina Smith guía la trayectoria de la barra.","Concéntrate en mantener la rodilla delantera alineada sobre los dedos del pie."]],["front-squat","Sentadilla Frontal","Una sentadilla con barra sostenida al frente sobre los deltoides, enfatizando cuádriceps y core.","Pierna","Fuerza","Intermedio","Barra",false,["Glúteo mayor","Cuádriceps"],["Erectores espinales","Isquiotibiales"],6.0,"front-squat-start.webp","front-squat-peak.webp",["Limpia o coloca la barra en los deltoides frontales con los codos altos.","Baja en sentadilla manteniendo el torso erguido hasta que los muslos estén paralelos al suelo.","Vuelve a subir.","Repite."],["Mantén los codos altos para estabilizar la barra.","Un torso más vertical aumenta la activación de los cuádriceps."]],["dumbbell-front-squat","Sentadilla Frontal con Mancuernas","Una sentadilla sosteniendo mancuernas apoyadas en los hombros, manteniendo el torso erguido y enfatizando los cuádriceps.","Pierna","Fuerza","Intermedio","Mancuernas",false,["Glúteo mayor","Cuádriceps"],["Erectores espinales","Isquiotibiales","Recto abdominal"],6.0,"dumbbell-front-squat-start.webp","dumbbell-front-squat-peak.webp",["Sujeta una mancuerna en cada mano apoyadas sobre los hombros.","Mantén los codos en alto y el torso erguido.","Baja las caderas flexionando las rodillas hasta que los muslos queden paralelos al suelo.","Empuja a través de los talones para ponerte de pie.","Mantén la columna en posición neutra durante todo el movimiento.","Repite el número de repeticiones deseado."],["Mantén los codos altos para que las mancuernas queden apoyadas en los hombros.","Siéntate entre las caderas en lugar de plegarte hacia delante.","Empuja con todo el pie y mantén los talones en el suelo."]],["one-arm-kettlebell-front-squat","Sentadilla Frontal con Pesa Rusa a Un Brazo","Una sentadilla frontal con una pesa rusa apoyada en un solo hombro, que obliga al core a resistir la inclinación lateral.","Pierna","Fuerza","Intermedio","Kettlebell",false,["Glúteo mayor","Cuádriceps"],["Erectores espinales","Isquiotibiales","Oblicuos"],6.0,"one-arm-kettlebell-front-squat-start.webp","one-arm-kettlebell-front-squat-peak.webp",["Sostén una pesa rusa en posición de rack en un hombro.","De pie con los pies a la anchura de los hombros.","Baja en sentadilla flexionando las rodillas y las caderas.","Mantén el pecho alto y el torso erguido durante todo el ejercicio.","Impulsa a través de los talones para volver a ponerte de pie.","Completa las repeticiones de un lado y luego cambia."],["Resiste la tendencia a inclinarte hacia el lado de la pesa.","Empuja las rodillas hacia afuera en la parte baja.","Mantén el codo pegado al cuerpo bajo la pesa."]],["smith-machine-front-squat","Sentadilla Frontal en Máquina Smith","Una sentadilla en máquina Smith con la barra apoyada al frente sobre los hombros, donde la trayectoria fija y el torso erguido mantienen el trabajo en los cuádriceps.","Pierna","Fuerza","Principiante","Máquina Smith",false,["Glúteo mayor","Cuádriceps"],["Erectores espinales","Glúteo medio","Isquiotibiales"],6.0,"smith-machine-front-squat-start.webp","smith-machine-front-squat-peak.webp",["Coloca la barra a la altura del pecho alto y métete debajo para que se apoye al frente de los hombros, contra las clavículas.","Cruza los brazos sobre la barra o toma un agarre frontal abierto, y sube los codos hasta que los brazos queden casi paralelos al suelo.","Desengancha la barra y separa los pies aproximadamente al ancho de los hombros, ligeramente por delante de ella.","Baja en línea recta manteniendo los codos altos y el torso erguido, hasta que los muslos queden al menos paralelos al suelo.","Empuja desde el medio de los pies para volver a subir y repite el número de repeticiones deseado."],["Los codos altos son toda la ejercicio. En cuanto bajan, la barra rueda de los hombros hacia las manos y la posición frontal se desmorona.","Ajusta los topes de seguridad justo por debajo de tu posición más profunda antes de desenganchar nada: en una sentadilla frontal, soltar la barra es la salida más rápida de una repetición fallida.","Colocarte ligeramente por delante de la barra te permite mantener el torso vertical. Con una trayectoria fija, situarte justo debajo de la barra te obliga a inclinarte y empuja la barra fuera del apoyo frontal."]],["goblet-squat","Sentadilla Goblet","Una sentadilla apta para principiantes con una pesa rusa sujetada a la altura del pecho que mejora la postura y la profundidad.","Pierna","Fuerza","Principiante","Kettlebell",false,["Glúteo mayor","Cuádriceps"],["Isquiotibiales"],6.0,"goblet-squat-start.webp","goblet-squat-peak.webp",["Sujeta una pesa rusa a la altura del pecho con ambas manos.","Baja en sentadilla manteniendo el peso cerca del pecho.","Vuelve a subir.","Repite."],["La posición goblet favorece de forma natural un torso erguido.","Empuja las rodillas hacia afuera en la parte baja."]],["dumbbell-pistol-squat","Sentadilla Pistola con Mancuerna","La Sentadilla Pistola con Mancuerna es una variación avanzada de sentadilla a una pierna que desarrolla fuerza significativa en la parte inferior del cuerpo, equilibrio y movilidad, apuntando principalmente a los cuádriceps y glúteos.","Pierna","Fuerza","Avanzado","Mancuernas",false,["Glúteo mayor","Cuádriceps"],["Glúteo medio","Isquiotibiales"],6.0,"dumbbell-pistol-squat-start.webp","dumbbell-pistol-squat-peak.webp",["Ponte de pie, sosteniendo una mancuerna en cada mano con los brazos colgando a los lados.","Levanta una pierna recta hacia adelante, manteniéndola extendida durante todo el movimiento.","Baja tu cuerpo doblando la rodilla de tu pierna de apoyo, manteniendo el pecho erguido y la espalda recta.","Desciende hasta que tus glúteos estén cerca de tu talón o tu muslo esté paralelo al suelo, manteniendo el equilibrio.","Empuja a través de tu talón para volver a la posición inicial, extendiendo completamente tu pierna de apoyo.","Completa todas las repeticiones de un lado, luego cambia de pierna y repite para el otro lado por serie."],["Empieza con sentadillas pistola sin peso para dominar el patrón de movimiento antes de añadir mancuernas.","Deja que las mancuernas cuelguen rectas a los lados y mantén el pecho erguido para conservar el equilibrio sobre el pie que trabaja.","Concéntrate en controlar la fase excéntrica (de descenso) para mejorar la estabilidad y la fuerza.","Eleva ligeramente el talón sobre un disco pequeño si la movilidad del tobillo es un factor limitante."]],["trx-pistol-squat","Sentadilla Pistola con TRX","Un desafiante ejercicio unilateral de pierna que utiliza un entrenador de suspensión para asistir el equilibrio y la profundidad, trabajando principalmente los cuádriceps y glúteos.","Pierna","Fuerza","Intermedio","Entrenador de suspensión (TRX)",false,["Glúteo mayor","Cuádriceps"],["Glúteo medio","Isquiotibiales"],6.0,"trx-pistol-squat-start.webp","trx-pistol-squat-peak.webp",["Ancla el entrenador de suspensión y sujeta las asas con ambas manos, con los brazos extendidos.","Ponte de pie, levanta una pierna recta hacia adelante, manteniéndola separada del suelo.","Inicia la sentadilla empujando las caderas hacia atrás y doblando la rodilla de la pierna de apoyo, bajando el cuerpo lo más profundo posible.","Mantén el pecho erguido, la espalda recta y usa el TRX para el equilibrio y soporte según sea necesario.","Impúlsate a través del talón para volver a la posición inicial, extendiendo completamente la pierna de apoyo.","Completa todas las repeticiones por lado antes de cambiar de pierna."],["Mantén la tensión en las correas del TRX durante todo el movimiento para mayor estabilidad.","Concéntrate en un descenso controlado y un ascenso potente.","Mantén la pierna que no trabaja extendida y elevada para activar los flexores de la cadera.","Ajusta tu agarre en el TRX para modificar el nivel de asistencia."]],["db-somersault-squat","Sentadilla Somersault con Mancuerna","Una sentadilla unilateral con alcance y mancuerna, que añade rotación y movilidad de hombro al patrón de sentadilla.","Pierna","Fuerza","Intermedio","Mancuernas",false,["Glúteo mayor","Cuádriceps"],["Isquiotibiales","Oblicuos"],6.0,"db-somersault-squat-start.webp","db-somersault-squat-peak.webp",["Pies a la anchura de los hombros, sostén una mancuerna en una mano a la altura del hombro.","Baja en sentadilla mientras llevas la mancuerna al frente y cruzando el cuerpo.","Alcanza el punto bajo con la mancuerna extendida pasando la rodilla opuesta.","Empuja con los talones para subir, regresando la mancuerna al hombro.","Repeticiones por lado, luego cambia."],["Mueve lento durante la rotación para mantener la columna controlada.","Usa una mancuerna ligera — la palanca larga exige al hombro.","Empuja las rodillas afuera para mantener la trayectoria estable."]],["sumo-squat","Sentadilla Sumo","Una sentadilla con barra y postura amplia con las puntas hacia afuera, que enfatiza glúteos y cara interna de los muslos.","Pierna","Fuerza","Intermedio","Barra",false,["Glúteo mayor","Cuádriceps"],["Erectores espinales","Glúteo medio","Isquiotibiales"],6.0,"sumo-squat-start.webp","sumo-squat-peak.webp",["Párate con los pies más anchos que el ancho de los hombros y los pies apuntando hacia afuera.","Sostén una barra sobre la parte superior de la espalda.","Contrae el core y mantén el pecho arriba.","Dobla caderas y rodillas para bajar a una sentadilla profunda.","Empuja a través de los talones para volver a la posición de pie.","Repite el número de repeticiones deseado."],["Abre las puntas de los pies y empuja las rodillas hacia afuera.","Mantén el pecho alto y el core firme.","Baja en profundidad flexionando caderas y rodillas a la vez."]],["db-sumo-squat","Sentadilla Sumo con Mancuernas","Una sentadilla de pies anchos con mancuernas sujetadas a los lados, que enfatiza la cara interna de los muslos y los glúteos.","Pierna","Fuerza","Principiante","Mancuernas",false,["Glúteo mayor","Cuádriceps"],["Aductores","Glúteo medio","Isquiotibiales"],6.0,"db-sumo-squat-start.webp","db-sumo-squat-peak.webp",["Ponte de pie con los pies más anchos que los hombros y las puntas giradas hacia afuera unos 30 grados.","Sujeta una mancuerna en cada mano a los lados.","Activa el core y mantén el pecho alto.","Flexiona caderas y rodillas para bajar recto en una sentadilla profunda.","Empuja con los talones para volver a ponerte de pie.","Repite el número de repeticiones deseado."],["Alinea las rodillas con las puntas de los pies; no dejes que se vayan hacia dentro.","Mantén el torso tan erguido como te permita la movilidad de cadera.","Elige mancuernas más ligeras que en una sentadilla normal; el agarre es el límite."]],["trx-squat","Sentadilla TRX","Este ejercicio compuesto de peso corporal utiliza un entrenador de suspensión para asistir en la realización de una sentadilla, trabajando eficazmente cuádriceps, glúteos e isquiotibiales.","Pierna","Fuerza","Principiante","Entrenador de suspensión (TRX)",false,["Glúteo mayor","Cuádriceps"],["Isquiotibiales"],6.0,"trx-squat-start.webp","trx-squat-peak.webp",["Párate mirando hacia el punto de anclaje, sosteniendo las asas con las palmas enfrentadas y los brazos extendidos.","Inclínate ligeramente hacia atrás, manteniendo tu cuerpo recto y el core activado, con los pies al ancho de los hombros.","Inicia la sentadilla empujando las caderas hacia atrás y doblando las rodillas, bajando tu cuerpo como si te sentaras en una silla.","Desciende hasta que tus muslos estén paralelos al suelo o tan profundo como te sea cómodo, manteniendo la tensión en las correas.","Impúlsate a través de los talones para volver a la posición inicial, extendiendo completamente las caderas y las rodillas."],["Mantén el pecho erguido y la mirada al frente durante todo el movimiento para mantener una columna vertebral neutra.","Usa el entrenador de suspensión para ayudarte a controlar el descenso y el ascenso, especialmente si eres nuevo en las sentadillas.","Concéntrate en empujar las rodillas ligeramente hacia afuera para activar los glúteos de manera más efectiva."]],["squat","Sentadilla Trasera con Barra","Un movimiento compuesto de tren inferior que trabaja cuádriceps, glúteos e isquiotibiales.","Pierna","Fuerza","Intermedio","Barra",false,["Glúteo mayor","Cuádriceps"],["Erectores espinales","Isquiotibiales"],6.0,"squat-start.webp","squat-peak.webp",["Coloca la barra sobre tus trapecios superiores.","Desrackea y da un paso atrás, con los pies al ancho de los hombros.","Contrae el core y haz la sentadilla hasta que los muslos queden paralelos.","Empuja a través de los talones para volver a la posición de pie.","Repite."],["Mantén el pecho arriba durante todo el movimiento.","Empuja las rodillas hacia afuera en línea con los dedos de los pies."]],["pistol-squat","Sentadilla a una Pierna (Pistol)","Una sentadilla a una pierna con la pierna libre extendida adelante, que exige fuerza y equilibrio.","Pierna","Fuerza","Avanzado","Sin equipo",true,["Glúteo mayor","Cuádriceps"],["Glúteo medio","Isquiotibiales","Flexores de cadera"],6.0,"pistol-squat-start.webp","pistol-squat-peak.webp",["Mantente sobre una pierna, la otra extendida al frente, brazos al lado para equilibrio.","Flexiona la cadera y la rodilla de apoyo, manteniendo el pecho arriba.","Baja lentamente hasta que la parte posterior del muslo toque la pantorrilla.","Empuja con el talón de apoyo para volver a subir.","Repeticiones por lado, luego cambia de pierna."],["Sostén un contrapeso ligero al pecho si te cuesta el equilibrio.","Construye la fuerza primero con pistol asistido sobre cajón.","Mantén el talón de trabajo plano en el suelo."]],["banded-squat","Sentadilla con Banda","Una sentadilla con peso corporal y banda sobre las rodillas para enseñar a sacar las rodillas afuera.","Pierna","Fuerza","Principiante","Banda circular",false,["Glúteo mayor","Cuádriceps"],["Glúteo medio","Isquiotibiales"],6.0,"banded-squat-start.webp","banded-squat-peak.webp",["Coloca una banda elástica justo sobre las rodillas.","Pies a la anchura de los hombros, puntas ligeramente afuera.","Empuja las rodillas hacia afuera contra la banda al bajar.","Desciende hasta que los muslos queden paralelos o más abajo.","Empuja con los talones para volver a subir."],["Empuja las rodillas contra la banda durante toda la repetición.","Pecho arriba y espalda recta.","No dejes que las rodillas se vayan hacia adentro."]],["overhead-squat","Sentadilla con Barra en Alto","Una sentadilla con la barra bloqueada por encima de la cabeza con agarre ancho de arrancada, que exige movilidad, estabilidad y un core fuerte.","Pierna","Fuerza","Intermedio","Barra",false,["Glúteo mayor","Cuádriceps"],["Erectores espinales","Deltoides lateral","Trapecio"],6.0,"overhead-squat-start.webp","overhead-squat-peak.webp",["Sostén una barra por encima de la cabeza con un agarre ancho de arrancada y los codos bloqueados.","De pie con los pies ligeramente más abiertos que la anchura de los hombros.","Baja en sentadilla empujando las caderas hacia atrás y doblando las rodillas.","Mantén la barra directamente sobre el punto medio de los pies.","Impulsa a través de los talones para volver a ponerte de pie.","Repite el número de repeticiones deseado."],["Gira las axilas hacia delante para fijar la barra en su sitio.","Mantén la barra sobre el mediopié, con el torso más erguido que en una sentadilla trasera.","Trabaja la movilidad de hombros y tobillos antes de añadir peso."]],["kettlebell-squat","Sentadilla con Kettlebell","Una variante de sentadilla sosteniendo una kettlebell con ambas manos colgando baja entre las piernas, añadiendo carga a un patrón de sentadilla estándar.","Pierna","Fuerza","Principiante","Kettlebell",false,["Cuádriceps"],["Glúteo mayor"],6.0,"kettlebell-squat-start.webp","kettlebell-squat-peak.webp",["Ponte de pie con los pies separados al ancho de los hombros, sosteniendo una kettlebell con ambas manos frente a ti.","Deja que la kettlebell cuelgue naturalmente entre tus piernas mientras contraes el core.","Flexiona las caderas y las rodillas para bajar en sentadilla, manteniendo la kettlebell cerca del cuerpo.","Empuja con los pies para volver a la posición inicial.","Repite el número deseado de repeticiones."],["Mantén el pecho arriba y la espalda recta durante todo el movimiento.","Usa la kettlebell como contrapeso para ayudarte a bajar más profundo en la sentadilla.","Empuja las rodillas hacia afuera, en línea con los dedos de los pies, al descender."]],["db-squat","Sentadilla con Mancuernas","Un patrón de sentadilla cargado con una mancuerna en cada mano, accesible sin barra.","Pierna","Fuerza","Principiante","Mancuernas",false,["Glúteo mayor","Cuádriceps"],["Isquiotibiales"],6.0,"db-squat-start.webp","db-squat-peak.webp",["Pies a la anchura de los hombros, una mancuerna en cada mano a los lados.","Activa el core y mantén el pecho arriba.","Baja en sentadilla flexionando caderas y rodillas.","Desciende hasta que los muslos queden paralelos o más abajo.","Empuja con los talones para volver a subir."],["Mantén el pecho arriba y la espalda recta.","Empuja las rodillas en línea con los dedos del pie.","Usa straps si el agarre se convierte en el factor limitante."]],["pause-squat","Sentadilla con Pausa","Una sentadilla con barra que incluye una pausa de varios segundos en la posición baja para eliminar el rebote y reforzar la salida del fondo.","Pierna","Fuerza","Intermedio","Barra",false,["Glúteo mayor","Cuádriceps"],["Erectores espinales","Glúteo medio","Isquiotibiales"],6.0,"pause-squat-start.webp","pause-squat-peak.webp",["Saca la barra del rack y apóyala sobre la parte superior de la espalda.","De pie con los pies a la anchura de los hombros.","Baja en sentadilla hasta que los muslos queden paralelos al suelo.","Mantén la posición inferior durante 2-3 segundos.","Impulsa a través de los talones para volver a ponerte de pie.","Repite el número de repeticiones deseado."],["Mantén la tensión en la pausa; no te relajes en el fondo.","Coge aire arriba y mantén el abdomen firme toda la repetición.","Mantén el pecho alto para que la barra no te venza hacia delante."]],["bodyweight-squat","Sentadilla con Peso Corporal","Una sentadilla con el propio peso corporal, apta para principiantes, que desarrolla los glúteos y los cuádriceps.","Pierna","Fuerza","Principiante","Sin equipo",true,["Glúteo mayor","Cuádriceps"],["Erectores espinales","Glúteo medio","Isquiotibiales"],6.0,"bodyweight-squat-start.webp","bodyweight-squat-peak.webp",["Colócate de pie con los pies separados al ancho de los hombros y los brazos extendidos al frente.","Siéntate hacia atrás y hacia abajo flexionando caderas y rodillas.","Baja hasta que los muslos queden paralelos al suelo.","Empuja con los talones para volver a la posición de pie.","Repite el número deseado de repeticiones."],["Empuja las rodillas hacia afuera en línea con los pies.","Mantén el pecho erguido y la mirada al frente.","Evita que los talones se despeguen del suelo al bajar."]],["jump-squat","Sentadilla con Salto","Una sentadilla pliométrica con peso corporal donde explotas hacia arriba en un salto vertical.","Pierna","Pliometría","Principiante","Sin equipo",true,["Glúteo mayor","Cuádriceps"],["Gemelos","Isquiotibiales"],7.0,"jump-squat-start.webp","jump-squat-peak.webp",["Mantente con los pies a la anchura de los hombros.","Baja a una media sentadilla con los brazos atrás.","Explota hacia arriba, balanceando los brazos y saltando lo más alto posible.","Aterriza suave en media sentadilla para absorber el impacto.","Repite sin pausa el número de repeticiones indicado."],["Aterriza suave con las rodillas flexionadas.","Lanza los brazos arriba para ganar altura en el salto.","Mantén el pecho arriba — no dejes que el torso colapse."]],["heel-elevated-squat","Sentadilla con Talones Elevados","Una variante de sentadilla con los talones elevados sobre discos para enfatizar los cuádriceps y mejorar la profundidad.","Pierna","Fuerza","Intermedio","Barra",false,["Glúteo mayor","Cuádriceps"],["Aductores","Erectores espinales","Isquiotibiales"],6.0,"heel-elevated-squat-start.webp","heel-elevated-squat-peak.webp",["Coloca discos de peso o una cuña bajo los talones, pies al ancho de los hombros.","Sostén una barra en la parte superior de la espalda o mancuernas a los lados.","Activa el core y baja en sentadilla manteniendo el torso erguido.","Baja hasta que los muslos estén paralelos al suelo o más abajo.","Empuja a través de los pies para volver a la posición inicial."],["Los talones elevados permiten un torso más erguido y mayor recorrido de rodilla.","Mantén las rodillas alineadas con los dedos del pie durante todo el movimiento.","Comienza con una elevación pequeña y auméntala a medida que mejore la movilidad."]],["cossack-squat","Sentadilla cosaca","Una sentadilla lateral de base amplia que hunde el cuerpo profundamente sobre una pierna flexionada mientras la otra permanece recta, entrenando fuerza unilateral, movilidad de cadera y flexibilidad de aductores.","Pierna","Fuerza","Intermedio","Sin equipo",true,["Glúteo mayor","Cuádriceps"],["Aductores","Isquiotibiales"],6.0,"cossack-squat-start.webp","cossack-squat-peak.webp",["Ponte en una postura amplia con las puntas de los pies ligeramente hacia afuera.","Desplaza el peso hacia un lado, flexiona esa rodilla y húndete en una sentadilla profunda.","Mantén la pierna contraria recta, con el talón en el suelo y los dedos hacia arriba.","Baja tanto como te permita tu movilidad, manteniendo el pecho erguido.","Empuja con la pierna flexionada para volver al centro y repite hacia el otro lado."],["Mantén el talón de la pierna que trabaja apoyado: no ruedes hacia las puntas.","Apunta con los dedos de la pierna recta hacia arriba para mantener tensión en los aductores.","Sujeta un peso ligero frente al pecho como contrapeso si lo necesitas."]],["box-squat","Sentadilla en Caja","Una sentadilla realizada hasta una caja o banco, que fija la profundidad y enseña a sentarse hacia atrás en las caderas.","Pierna","Fuerza","Intermedio","Sin equipo",true,["Glúteo mayor","Cuádriceps"],["Erectores espinales","Glúteo medio","Isquiotibiales"],6.0,"box-squat-start.webp","box-squat-peak.webp",["Ponte de pie frente a una caja o banco, con los pies al ancho de los hombros y los brazos extendidos hacia adelante para el equilibrio.","Empuja las caderas hacia atrás y flexiona las rodillas, sentándote hacia la caja en lugar de bajar en línea recta.","Toca la caja ligeramente con los glúteos sin dejarte caer sobre ella.","Empuja con los pies para volver a ponerte de pie, apretando los glúteos arriba.","Repite las repeticiones deseadas."],["Usa una altura de caja que permita que los muslos queden aproximadamente paralelos al suelo, y bájala a medida que mejore tu movilidad.","Mantén el peso en el centro de los pies — no te inclines hacia los dedos.","No te sientes por completo en la caja: relajar todo el peso sobre ella te hace perder tensión en el core y sobrecarga la columna."]],["smith-machine-squat","Sentadilla en Máquina Smith","Una sentadilla guiada en máquina Smith con la barra sobre los trapecios, que trabaja cuádriceps y glúteos con trayectoria fija.","Pierna","Fuerza","Principiante","Máquina Smith",false,["Glúteo mayor","Cuádriceps"],["Erectores espinales","Glúteo medio","Isquiotibiales"],6.0,"smith-machine-squat-start.webp","smith-machine-squat-peak.webp",["Ajusta la barra de la máquina Smith a la altura de los hombros y colócate debajo de ella.","Apoya la barra sobre tus trapecios superiores y desrackéala.","Párate con los pies al ancho de los hombros, ligeramente por delante de la barra.","Desciende hasta que los muslos queden paralelos al suelo.","Empuja a través de los talones para volver a la posición de pie.","Repite el número de repeticiones deseado."],["Coloca los pies ligeramente por delante de la barra.","Baja hasta que los muslos queden paralelos al suelo.","Empuja con los talones para volver a subir."]],["wall-sit","Sentadilla en Pared","Un ejercicio isométrico estático que consiste en mantener la posición de sentadilla contra una pared para desarrollar la resistencia de los cuádriceps.","Pierna","Fuerza","Principiante","Sin equipo",true,["Glúteo mayor","Cuádriceps"],["Isquiotibiales"],5.0,"wall-sit-main.webp",null,["Párate con la espalda contra una pared.","Deslízate hacia abajo hasta que los muslos estén paralelos al suelo.","Mantén la posición.","Vuelve a ponerte de pie cuando termines."],["Mantén las rodillas a 90 grados.","Presiona la espalda plana contra la pared."]],["stability-ball-wall-squat","Sentadilla en Pared con Pelota","Una sentadilla con peso corporal apoyando una pelota suiza entre la zona lumbar y la pared, que guía la columna.","Pierna","Fuerza","Principiante","Pelota de estabilidad",false,["Glúteo mayor","Cuádriceps"],["Isquiotibiales"],6.0,"stability-ball-wall-squat-start.webp","stability-ball-wall-squat-peak.webp",["Coloca una pelota suiza entre tu zona lumbar y una pared.","Adelanta los pies unos 30 cm, un poco más anchos que los hombros.","Baja en sentadilla mientras la pelota rueda por la espalda.","Detente cuando los muslos queden paralelos al suelo.","Empuja con los talones para volver a subir."],["Carga el peso en talones y medio del pie.","No dejes que las rodillas pasen las puntas de los pies.","La pelota debe rodar suavemente — no te separes de ella."]],["dumbbell-split-squat","Sentadilla en Postura Dividida con Mancuernas","Una sentadilla en posición de tijera sosteniendo mancuernas a los lados, que trabaja los cuádriceps y glúteos una pierna a la vez.","Pierna","Fuerza","Intermedio","Mancuernas",false,["Glúteo mayor","Cuádriceps"],["Glúteo medio","Isquiotibiales"],6.0,"dumbbell-split-squat-start.webp","dumbbell-split-squat-peak.webp",["Ponte en postura dividida sujetando mancuernas a los costados.","Mantén el torso erguido y el core contraído.","Baja la rodilla trasera hacia el suelo doblando ambas rodillas.","Para cuando el muslo delantero quede paralelo al suelo.","Empuja a través del talón delantero para volver a la posición de pie.","Completa las repeticiones de un lado y luego cambia."],["Mantén la mayor parte del peso en la pierna delantera.","Baja la rodilla trasera recta hacia el suelo.","Lleva la rodilla delantera sobre los dedos sin dejar que se hunda hacia dentro."]],["split-squat","Sentadilla en Tijera","Una zancada estática bajando en línea recta con las piernas en tijera, desarrollando fuerza unilateral sin dar el paso.","Pierna","Fuerza","Intermedio","Sin equipo",true,["Glúteo mayor","Cuádriceps"],["Glúteo medio","Isquiotibiales"],6.0,"split-squat-start.webp","split-squat-peak.webp",["Párate en posición de tijera con un pie adelante y otro atrás.","Mantén el torso erguido y el core contraído.","Baja las caderas rectas hacia abajo doblando ambas rodillas.","Detente cuando la rodilla trasera esté justo por encima del suelo.","Empuja a través del talón delantero para volver al inicio.","Completa las repeticiones de un lado y luego cambia."],["Baja en línea recta en lugar de lanzarte hacia delante.","Mantén la mayor parte del peso sobre el pie delantero.","Mantén el talón delantero apoyado durante toda la repetición."]],["smith-machine-split-squat","Sentadilla en Tijera en Máquina Smith","Una sentadilla en tijera estática bajo la barra de la máquina Smith, con el pie trasero apoyado en el suelo en lugar de un banco, de modo que la trayectoria guiada quita el equilibrio de un movimiento unilateral.","Pierna","Fuerza","Intermedio","Máquina Smith",false,["Glúteo mayor","Cuádriceps"],["Isquiotibiales"],6.0,"smith-machine-split-squat-start.webp","smith-machine-split-squat-peak.webp",["Coloca la barra lo bastante baja para que siga librando tus hombros en el punto más bajo de la repetición, métete debajo y apóyala sobre los trapecios altos.","Desengancha la barra y da una zancada larga hacia delante con un pie, dejando el pie trasero apoyado en el suelo con el talón elevado.","Comprueba que la tibia delantera quedará vertical al bajar; ajusta la longitud de la zancada antes de empezar a cargarla.","Baja en línea recta flexionando ambas rodillas hasta que la rodilla trasera quede justo por encima del suelo y el muslo delantero cerca de la paralela.","Empuja con el talón delantero para volver al inicio sin mover los pies, y repite las repeticiones deseadas antes de cambiar de lado."],["Fija primero la longitud de la zancada sin carga. Una vez que la barra está sobre tu espalda, la trayectoria fija no te dejará avanzar para corregir una posición demasiado corta.","Baja recto, no hacia delante. La barra solo puede desplazarse en vertical, así que empujar la cadera hacia delante únicamente adelanta la rodilla más allá de los dedos.","Haz el mismo número de repeticiones por lado y empieza por la pierna más débil, ya que una sentadilla en tijera guiada oculta una diferencia entre lados que una barra libre dejaría en evidencia."]],["kettlebell-pistol-squat","Sentadilla pistola con pesa rusa","Una sentadilla a una pierna con la pesa rusa al pecho que exige fuerza y equilibrio avanzados.","Pierna","Fuerza","Avanzado","Kettlebell",false,["Glúteo mayor","Cuádriceps"],["Glúteo medio","Isquiotibiales","Recto abdominal"],6.0,"kettlebell-pistol-squat-start.webp","kettlebell-pistol-squat-peak.webp",["Sostén una pesa rusa a la altura del pecho con ambas manos.","Párate en una pierna con la otra extendida hacia adelante.","Baja las caderas en una sentadilla a una sola pierna.","Mantén la pierna elevada fuera del suelo durante todo el movimiento.","Empuja a través del talón de apoyo para volver a ponerte de pie.","Completa las repeticiones en un lado y luego cambia."],["Mantén la pesa rusa cerca del pecho como contrapeso.","Baja despacio para no desplomarte en la parte final.","El talón de apoyo no se despega del suelo."]],["band-pull-apart","Separación de Banda Elástica","Un ejercicio de alto volumen para el deltoides posterior y los retractores escapulares que se realiza separando una banda elástica a la altura de los hombros.","Hombro","Fuerza","Principiante","Banda elástica",false,["Deltoides posterior"],["Romboides","Trapecio"],5.0,"band-pull-apart-start.webp","band-pull-apart-peak.webp",["Párate sosteniendo una banda elástica ligera con ambas manos, brazos extendidos al frente a la altura de los hombros.","Las manos comienzan a la anchura de los hombros, palmas mirando hacia abajo.","Manteniendo los brazos extendidos, separa la banda llevando las manos hacia los lados.","Termina con la banda tocando el pecho y los omóplatos juntos.","Vuelve lentamente a la posición inicial y repite."],["Lidera el movimiento con los meñiques: esto rota externamente los hombros.","Usa una banda lo suficientemente ligera para hacer 15-30 repeticiones limpias; es un ejercicio preventivo de alto número de repeticiones."]],["skull-crusher","Skull Crusher","Una extensión de tríceps tumbado con barra que aísla los tríceps a través de un rango de movimiento completo.","Tríceps","Fuerza","Intermedio","Barra",false,["Tríceps braquial"],[],5.0,"skull-crusher-start.webp","skull-crusher-peak.webp",["Acuéstate en un banco plano sosteniendo una barra sobre el pecho con agarre estrecho.","Baja la barra hacia la frente flexionando los codos.","Extiende los brazos de vuelta a la posición inicial.","Repite."],["Mantén los brazos superiores verticales durante todo el ejercicio.","Baja lentamente para proteger los codos."]],["db-skull-crusher","Skull Crusher con Mancuernas","Una extensión de tríceps tumbado con mancuernas que permite el movimiento independiente de cada brazo.","Tríceps","Fuerza","Intermedio","Mancuernas",false,["Tríceps braquial"],[],5.0,"db-skull-crusher-start.webp","db-skull-crusher-peak.webp",["Túmbate en un banco plano sosteniendo mancuernas sobre el pecho.","Baja las mancuernas hacia los lados de la cabeza.","Extiende los brazos hacia arriba.","Repite."],["Mantén los codos apuntando hacia el techo.","Usa un tempo controlado."]],["kettlebell-skull-crusher","Skull crusher con pesa rusa","Un skull crusher tumbado en un banco plano, sosteniendo una pesa rusa por las asas con ambas manos. La masa descentrada cuelga por debajo de las muñecas, añadiendo un reto de agarre y control.","Tríceps","Fuerza","Intermedio","Kettlebell",false,["Tríceps braquial"],[],5.0,"kettlebell-skull-crusher-start.webp","kettlebell-skull-crusher-peak.webp",["Acuéstate en un banco plano sosteniendo una pesa rusa por las asas con ambas manos, brazos extendidos sobre el pecho.","Flexiona solo los codos para bajar la campana hacia la frente en un arco controlado.","Mantén los brazos verticales; solo los antebrazos se mueven.","Extiende los codos para empujar la campana de vuelta arriba.","Repite el número recomendado de repeticiones."],["Agarra las asas firmemente — la campana tiende a rotar hacia adelante en la parte inferior.","Los codos se mantienen pegados — si se abren, la carga es demasiado pesada.","Inclina los brazos ligeramente hacia atrás en dirección a la cabeza para mantener tensión en los tríceps al bloquear."]],["dumbbell-snatch","Snatch con Mancuerna","Un levantamiento explosivo a un brazo que impulsa la mancuerna desde el suelo hasta encima de la cabeza en un movimiento fluido.","Cuerpo completo","Halterofilia","Intermedio","Mancuernas",false,["Deltoides anterior","Glúteo mayor","Trapecio"],["Erectores espinales","Isquiotibiales","Cuádriceps"],8.0,"dumbbell-snatch-start.webp","dumbbell-snatch-peak.webp",["Ponte de pie con los pies al ancho de los hombros y la mancuerna en el suelo entre tus pies.","Inclínate y agarra la mancuerna con una mano.","Extiende caderas, rodillas y tobillos de forma explosiva para tirar de la mancuerna hacia arriba.","Empuja la mancuerna por encima de la cabeza en un movimiento fluido.","Bloquea el brazo y estabiliza en la parte superior.","Completa las repeticiones de un lado y luego cambia."],["Extiende completamente caderas y rodillas antes de tirar con el brazo.","Empuja la mancuerna hacia arriba hasta un bloqueo estable sobre la cabeza.","Mantén la mancuerna cerca del cuerpo mientras sube."]],["ez-bar-spider-curl","Spider Curl con Barra Z","Un curl con el pecho apoyado sobre un banco inclinado usando barra Z, aislando el bíceps con técnica estricta.","Bíceps","Fuerza","Intermedio","Barra Z",false,["Bíceps braquial"],["Braquial anterior","Braquiorradial"],5.0,"ez-bar-spider-curl-start.webp","ez-bar-spider-curl-peak.webp",["Túmbate boca abajo en un banco inclinado sujetando una barra Z con agarre supino.","Deja que tus brazos cuelguen rectos desde los hombros.","Sube la barra hacia tus hombros.","Aprieta los bíceps en la parte alta del movimiento.","Baja la barra de forma controlada.","Repite el número de repeticiones deseado."],["Deja los brazos colgando verticales y mantén fijos los brazos superiores.","Haz el curl solo con el bíceps: el banco elimina cualquier excusa para balancearte.","Baja hasta el estiramiento completo antes de empezar la siguiente repetición."]],["pilates-spine-stretch-forward","Spine Stretch Forward de Pilates","Una articulación sentada: sentado erguido con las piernas abiertas, la columna se enrolla hacia delante segmento a segmento sobre las piernas y después vuelve a apilarse vértebra a vértebra.","Espalda","Estiramiento","Intermedio","Sin equipo",true,["Erectores espinales","Recto abdominal"],["Isquiotibiales","Transverso abdominal"],5.0,"pilates-spine-stretch-forward-start.webp","pilates-spine-stretch-forward-peak.webp",["Siéntate erguido con las piernas estiradas y algo más abiertas que las caderas, los pies en flexión.","Estira los brazos hacia delante a la altura de los hombros.","Baja la barbilla y enrolla la columna hacia delante vértebra a vértebra, alcanzando más allá de los pies.","Vuelve a apilar la columna desde la base hasta quedar sentado erguido.","Repite las veces indicadas."],["Mantén la pelvis erguida: la curva viene de la columna, no de bascular la cadera.","Empuja los talones hacia fuera todo el tiempo para que las piernas sigan activas.","Siéntate sobre una manta doblada si ya sentarte erguido te redondea la zona lumbar."]],["pilates-spine-twist","Spine Twist de Pilates","Una rotación sentada con las piernas juntas y los brazos abiertos: el tronco gira a cada lado de forma controlada mientras la pelvis y las piernas permanecen completamente quietas.","Core","Estiramiento","Intermedio","Sin equipo",true,["Oblicuos"],["Erectores espinales","Transverso abdominal"],5.0,"pilates-spine-twist-start.webp","pilates-spine-twist-peak.webp",["Siéntate erguido con las piernas estiradas y juntas, los pies en flexión y los brazos abiertos a la altura de los hombros.","Crece a través de la columna y presiona ambos isquiones contra el suelo.","Rota el tronco hacia un lado mientras las caderas sigan cuadradas y vuelve al centro.","Rota hacia el otro lado del mismo modo.","Sigue alternando las veces indicadas."],["Las piernas son el ancla: si un pie se adelanta, la pelvis se ha movido.","Alárgate hacia arriba antes de cada rotación en lugar de hundirte en ella.","Gira la cabeza con el tronco en lugar de que ella lidere."]],["double-kettlebell-split-jerk","Split Jerk con Dos Pesas Rusas","Un jerk con dos pesas rusas que combina un impulso de piernas con una recepción en tijera bajo la carga.","Cuerpo completo","Halterofilia","Intermedio","Kettlebell",false,["Deltoides anterior","Cuádriceps"],["Glúteo mayor","Trapecio","Tríceps braquial"],8.0,"double-kettlebell-split-jerk-start.webp","double-kettlebell-split-jerk-peak.webp",["Lleva dos pesas rusas al rack sobre los hombros.","Flexiona ligeramente las rodillas.","Impulsa las pesas rusas por encima de la cabeza de forma explosiva.","Separa las piernas para recibirlas con los brazos bloqueados.","Recupera la posición juntando los pies."],["Haz el dip corto y vertical, sin inclinar el torso.","Genera el empuje con las piernas, no con los hombros.","Bloquea los codos antes de juntar los pies."]],["standing-split","Split de Pie","Una flexión de pie con una pierna elevada por detrás: el torso se pliega sobre la pierna de apoyo mientras la pierna libre se eleva hacia el techo.","Pierna","Estiramiento","Avanzado","Sin equipo",true,["Glúteo mayor","Isquiotibiales"],["Erectores espinales","Cuádriceps"],5.0,"standing-split-main.webp",null,["Desde una flexión hacia delante, apoya ambas manos en el suelo o en bloques junto al pie de apoyo.","Pasa el peso a una pierna y eleva la otra por detrás.","Mantén la pierna de apoyo estirada y las caderas tan niveladas como permita la elevación.","Mantén la posición durante el tiempo indicado, acercando el pecho a la espinilla de apoyo.","Baja el pie elevado y repite del otro lado."],["Nivela primero las caderas y acepta menos altura; abrir la cadera convierte esto en otra postura.","Usa bloques bajo las manos para que la columna pueda mantenerse larga.","Agarra el tobillo de apoyo con una mano solo cuando el equilibrio ya sea estable."]],["step-ups","Step Ups","Una subida a un cajón o banco con una pierna que entrena cuádriceps y glúteos de forma funcional.","Pierna","Fuerza","Intermedio","Sin equipo",true,["Glúteo mayor","Cuádriceps"],["Gemelos","Glúteo medio","Isquiotibiales"],5.0,"step-ups-start.webp","step-ups-peak.webp",["Párate frente a una caja o banco resistente.","Coloca un pie completamente sobre la superficie de la caja.","Empuja a través de ese talón para subir el cuerpo a la caja.","Sube el pie de atrás para quedar completamente sobre la caja.","Baja con el mismo pie que subió primero.","Alterna piernas o completa todas las repeticiones de un lado antes de cambiar."],["Apoya todo el pie sobre la superficie del cajón.","Impulsa con el talón de la pierna que sube, no con la de atrás.","Controla el descenso en lugar de dejarte caer."]],["superman","Superman","Un ejercicio de peso corporal para la zona lumbar realizado en prono, levantando brazos y piernas simultáneamente.","Espalda","Fuerza","Principiante","Sin equipo",true,["Erectores espinales","Glúteo mayor"],["Isquiotibiales"],3.5,"superman-start.webp","superman-peak.webp",["Túmbate boca abajo con los brazos extendidos por encima de la cabeza.","Levanta simultáneamente los brazos, el pecho y las piernas del suelo.","Mantén brevemente la posición superior.","Baja de forma controlada.","Repite."],["Aprieta los glúteos al levantar.","Evita los movimientos bruscos."]],["double-kettlebell-swing-snatch","Swing Snatch con Dos Pesas Rusas","Un snatch con dos pesas rusas iniciado con un swing entre las piernas y finalizado con ambas pesas bloqueadas arriba.","Cuerpo completo","Halterofilia","Intermedio","Kettlebell",false,["Glúteo mayor","Isquiotibiales"],["Deltoides anterior","Erectores espinales","Flexores del antebrazo","Trapecio"],8.0,"double-kettlebell-swing-snatch-start.webp","double-kettlebell-swing-snatch-peak.webp",["Ponte de pie con los pies al ancho de los hombros sujetando dos pesas rusas.","Inclínate desde las caderas para balancear las pesas entre las piernas.","Extiende las caderas de forma explosiva para balancear las pesas hacia arriba.","Empuja hacia arriba para recibir ambas pesas rusas por encima de la cabeza con los brazos bloqueados.","Baja de forma controlada y repite."],["Genera la potencia con un golpe seco de cadera.","Mantén la espalda plana cuando las pesas pasan entre las piernas.","Suaviza la recepción arriba para que las pesas no golpeen tus antebrazos."]],["one-arm-dumbbell-swing","Swing con Mancuerna a un Brazo","Este ejercicio dinámico desarrolla potencia explosiva en glúteos e isquiotibiales mediante una potente bisagra de cadera, involucrando el core y los hombros para un entrenamiento de cuerpo completo.","Cuerpo completo","Fuerza","Intermedio","Mancuernas",false,["Glúteo mayor","Isquiotibiales"],["Erectores espinales","Flexores del antebrazo","Deltoides lateral"],8.0,"one-arm-dumbbell-swing-start.webp","one-arm-dumbbell-swing-peak.webp",["Párate con los pies al ancho de los hombros, una mancuerna en el suelo ligeramente delante de ti.","Haz una bisagra de cadera, manteniendo la espalda recta, y agarra la mancuerna con una mano.","Lleva la mancuerna hacia atrás entre tus piernas, luego impulsa explosivamente tus caderas hacia adelante.","Balancea la mancuerna hasta la altura del pecho, manteniendo tu brazo relajado y estirado.","Permite que la mancuerna baje, haciendo una bisagra de cadera mientras desciende.","Repite las repeticiones deseadas por lado, manteniendo el control."],["Concéntrate en impulsar con tus caderas, no en tirar con tu brazo.","Mantén tu core contraído durante todo el movimiento para mayor estabilidad.","Mantén una columna vertebral neutra; evita redondear tu espalda.","Controla la fase excéntrica mientras la mancuerna baja."]],["one-arm-kettlebell-swing","Swing con Pesa Rusa a Un Brazo","Un swing de pesa rusa a un brazo, un movimiento balístico de bisagra de cadera que desarrolla potencia en glúteos e isquiotibiales.","Cuerpo completo","Fuerza","Intermedio","Kettlebell",false,["Glúteo mayor","Isquiotibiales"],["Deltoides anterior","Erectores espinales","Oblicuos"],8.0,"one-arm-kettlebell-swing-start.webp","one-arm-kettlebell-swing-peak.webp",["De pie con los pies a la anchura de los hombros y la pesa rusa en el suelo frente a ti.","Bisagra en las caderas y agarra la pesa rusa con una mano.","Lleva la pesa rusa hacia atrás entre las piernas.","Impulsa las caderas hacia adelante para lanzar la pesa rusa hasta la altura del pecho.","Deja que la gravedad lleve la pesa rusa de vuelta entre las piernas.","Completa las repeticiones de un lado y luego cambia."],["Genera la potencia con la cadera, no con el brazo.","Mantén la espalda recta cuando la pesa pase entre las piernas.","No dejes que la pesa tire del hombro hacia delante."]],["kettlebell-swing","Swing con pesa rusa","Un movimiento explosivo de bisagra de cadera con pesa rusa para potencia y acondicionamiento físico.","Pierna","Fuerza","Intermedio","Kettlebell",false,["Glúteo mayor","Isquiotibiales"],["Erectores espinales","Cuádriceps"],8.0,"kettlebell-swing-start.webp","kettlebell-swing-peak.webp",["Párate con los pies a la anchura de los hombros y la pesa rusa en el suelo por delante.","Bisagra en las caderas, agarra la pesa rusa y llévala hacia atrás entre las piernas.","Extiende las caderas de forma explosiva para balancear la pesa rusa hasta la altura del pecho.","Deja que la pesa rusa vuelva a balancearse entre las piernas.","Repite en un movimiento fluido."],["La fuerza nace de la cadera, no de los brazos.","Aprieta glúteos y abdomen en la parte alta del swing.","Es una bisagra de cadera, no una sentadilla."]],["kettlebell-swing-clean","Swing y cargada con pesa rusa","Un clean con pesa rusa iniciado desde el swing, que lleva el peso hasta la posición de rack en el hombro.","Cuerpo completo","Halterofilia","Intermedio","Kettlebell",false,["Glúteo mayor","Isquiotibiales"],["Deltoides anterior","Erectores espinales","Trapecio"],8.0,"kettlebell-swing-clean-start.webp","kettlebell-swing-clean-peak.webp",["Párate con los pies a la anchura de los hombros y la pesa rusa entre los pies.","Bisagra en las caderas y agarra el asa con una mano.","Balancea la pesa rusa hacia atrás entre las piernas.","Extiende las caderas hacia adelante para jalar la pesa rusa hasta el hombro.","Recibe la pesa rusa en la posición de rack sobre el hombro.","Completa las repeticiones en un lado y luego cambia."],["Mantén la pesa cerca del cuerpo en la subida.","Recibe la pesa con suavidad, sin golpearte el antebrazo.","Genera la potencia con la cadera, no tirando con el brazo."]],["trx-y-fly","TRX Y-Fly","Este ejercicio con el entrenador de suspensión fortalece los deltoides posteriores y el trapecio, mejorando la salud del hombro y la postura al fortalecer la parte superior de la espalda.","Hombro","Fuerza","Intermedio","Entrenador de suspensión (TRX)",false,["Deltoides posterior","Trapecio"],["Deltoides lateral","Romboides"],5.0,"trx-y-fly-start.webp","trx-y-fly-peak.webp",["Párate frente al punto de anclaje, sujetando las asas con un agarre por encima, las palmas de las manos enfrentadas.","Inclínate hacia atrás, extendiendo los brazos rectos hacia adelante, manteniendo tu cuerpo en posición de plancha.","Inicia el movimiento juntando y bajando tus omóplatos, formando una \"Y\" con tu cuerpo.","Mantén los brazos rectos y los codos ligeramente flexionados, apretando los omóplatos en la parte superior.","Controla lentamente el descenso de vuelta a la posición inicial, resistiendo la tracción de las correas."],["Ajusta el ángulo de tu cuerpo para modificar la dificultad: inclinarte más hacia atrás aumenta el desafío.","Concéntrate en la retracción y depresión de tus omóplatos durante todo el movimiento.","Mantén un core rígido y una línea corporal recta para evitar que las caderas se caigan."]],["thruster","Thruster","Un movimiento de cuerpo completo con barra que combina una sentadilla frontal con un press por encima de la cabeza en un solo impulso fluido.","Hombro","Fuerza","Intermedio","Barra",false,["Deltoides anterior","Cuádriceps"],["Glúteo mayor","Trapecio","Tríceps braquial"],6.0,"thruster-start.webp","thruster-peak.webp",["Sostén una barra en posición de rack frontal con los codos altos.","Párate con los pies al ancho de los hombros.","Baja en sentadilla hasta paralelo manteniendo el torso erguido.","Impúlsate saliendo de la sentadilla y empuja la barra por encima de la cabeza en un solo movimiento.","Bloquea los brazos en la parte superior con la barra sobre la cabeza.","Baja la barra al rack frontal y repite."],["Aprovecha el impulso de la sentadilla para lanzar el press.","Mantén los codos altos para que la barra descanse en los hombros, no en las muñecas.","Termina cada repetición con la barra bloqueada sobre las orejas."]],["scissor-kicks","Tijeras","Un ejercicio de core realizado boca arriba, cruzando alternadamente las piernas rectas para trabajar el abdomen bajo y los flexores de cadera.","Pierna","Fuerza","Intermedio","Sin equipo",true,["Flexores de cadera","Recto abdominal"],["Oblicuos","Transverso abdominal"],5.0,"scissor-kicks-start.webp","scissor-kicks-peak.webp",["Recuéstate boca arriba con las manos bajo los glúteos.","Eleva ambas piernas unos centímetros del suelo.","Cruza alternadamente una pierna sobre la otra en un movimiento de tijera.","Mantén la zona lumbar presionada contra el suelo.","Mantén un ritmo constante durante todo el ejercicio.","Repite el número de repeticiones deseado."],["Presiona la zona lumbar contra el suelo en todo momento.","Mantén las piernas rectas y cerca del suelo.","Muévete con control, no con velocidad."]],["toes-to-bar","Toes to Bar","Un ejercicio avanzado de core colgado de una barra que requiere fuerza de flexión de cadera y activación del dorsal para llevar los pies hasta la barra.","Pierna","Fuerza","Intermedio","Barra de dominadas",false,["Flexores de cadera","Recto abdominal"],["Flexores del antebrazo","Dorsal ancho","Oblicuos"],6.0,"toes-to-bar-start.webp","toes-to-bar-peak.webp",["Cuélgate de una barra con agarre prono y los brazos completamente extendidos, cuerpo quieto.","Activa los dorsales y el core para evitar balanceos.","Eleva las piernas con rodillas rectas llevando los pies hacia la barra.","Toca la barra con los pies, luego baja las piernas con control.","Repite el número de repeticiones deseado."],["Inicia el movimiento desde el core, no con impulso de patada.","Exhala con fuerza al elevar las piernas para aumentar la presión intraabdominal.","Si no puedes alcanzar la barra, practica las elevaciones de piernas colgado como progresión."]],["rope-climb","Trepa de Cuerda","Un ejercicio de jalón para todo el cuerpo que trepa una cuerda vertical mano a mano, cargando el dorsal ancho, el bíceps, el agarre y el core de forma isométrica.","Espalda","Fuerza","Avanzado","Cuerda de escalada",false,["Dorsal ancho"],["Bíceps braquial","Flexores del antebrazo","Recto abdominal"],6.0,"rope-climb-main.webp",null,["Agarra la cuerda lo más arriba posible con ambas manos.","Envuelve la cuerda alrededor de un pie (gancho en S o en J) o apriétala entre ambos pies.","Súbete mientras los pies aprietan para soportar el peso corporal y sueltan la cuerda.","Alcanza más arriba con una mano, luego con la otra, y vuelve a sujetar con los pies.","Repite hasta llegar a la cima de la cuerda.","Baja mano bajo mano con los pies controlando la velocidad — nunca te deslices."],["Aprende el bloqueo de pies antes de intentar trepar más alto; duplica tu capacidad de trabajo.","Nunca te dejes caer desde la cima; el descenso controlado es parte del ejercicio."]],["v-ups","V-Ups","Un ejercicio dinámico de core que eleva las piernas y el torso juntos formando una V, trabajando los abdominales y los flexores de la cadera.","Pierna","Fuerza","Intermedio","Sin equipo",true,["Flexores de cadera","Recto abdominal"],["Oblicuos","Transverso abdominal"],5.0,"v-ups-start.webp","v-ups-peak.webp",["Túmbate boca arriba con los brazos extendidos por encima de la cabeza y las piernas rectas.","Levanta simultáneamente las piernas y la parte superior del cuerpo hacia el centro.","Alcanza las manos hacia los pies en la parte superior, formando una V.","Mantén las piernas rectas durante todo el movimiento.","Baja ambos extremos de forma controlada hasta el suelo.","Repite el número de repeticiones deseado."],["Mantén las piernas estiradas mientras las elevas.","Lleva las manos hacia los pies en la parte alta.","Baja ambos extremos con control en lugar de dejarte caer plano."]],["supported-shoulderstand","Vela con Apoyo","Una inversión apoyada en los hombros y los brazos, con las manos sosteniendo la espalda y el cuerpo alineado en vertical sobre los hombros.","Espalda","Fuerza","Intermedio","Sin equipo",true,["Erectores espinales","Recto abdominal"],["Glúteo mayor","Trapecio"],5.0,"supported-shoulderstand-main.webp",null,["Túmbate boca arriba, idealmente con una manta doblada bajo los hombros y la cabeza fuera de ella.","Eleva las piernas por encima de la cabeza y sostén la zona lumbar con ambas manos, los codos a la anchura de los hombros.","Camina las manos por la espalda y alinea las caderas sobre los hombros hasta que el cuerpo quede vertical.","Mantén la posición durante el tiempo indicado, con la cabeza y el cuello completamente quietos.","Baja las piernas por encima de la cabeza y desciende despacio con las manos sosteniendo la espalda."],["El peso va en los hombros y los brazos, nunca en el cuello.","No gires la cabeza mientras estás invertido.","Construye la postura con piernas en la pared y el arado antes de sostenerla mucho tiempo."]],["lunge","Zancada","Una zancada hacia delante con el peso corporal, entrenando cuádriceps, glúteos y equilibrio una pierna a la vez.","Pierna","Fuerza","Intermedio","Sin equipo",true,["Glúteo mayor","Cuádriceps"],["Erectores espinales","Glúteo medio","Isquiotibiales"],5.0,"lunge-start.webp","lunge-peak.webp",["Párate erguido con los pies a la anchura de las caderas.","Da un paso adelante largo con una pierna.","Baja la rodilla trasera hacia el suelo hasta que ambas rodillas formen ángulos de 90 grados.","Empuja con el talón delantero para volver a la posición de pie.","Completa las repeticiones de un lado y luego cambia."],["Da una zancada lo bastante larga para que ambas rodillas lleguen a unos 90 grados.","Mantén el torso erguido y la mirada al frente.","Empuja con el talón delantero para volver en un solo movimiento potente."]],["crescent-lunge","Zancada Alta","Un sostén en paso largo con el talón trasero elevado y los brazos arriba, que carga la pierna delantera mientras la cadera trasera se mantiene larga.","Pierna","Fuerza","Intermedio","Sin equipo",true,["Glúteo mayor","Cuádriceps"],["Erectores espinales","Flexores de cadera"],5.0,"crescent-lunge-main.webp",null,["Adelanta un pie a un paso largo con el talón trasero elevado y los dedos apuntando al frente.","Flexiona la rodilla delantera unos noventa grados para que quede sobre el tobillo.","Lleva la cadera trasera hacia delante hasta que ambas apunten al frente de la esterilla y eleva los brazos.","Mantén la posición durante el tiempo indicado, con las costillas cerradas y la pierna trasera estirada.","Junta los pies y repite del otro lado."],["Separa un poco los pies lateralmente si el equilibrio es lo que te limita.","Empuja el talón trasero hacia la pared de detrás para mantener activa la pierna de atrás.","Baja los brazos a las caderas si estirarlos arriba te arquea la zona lumbar."]],["revolved-crescent-lunge","Zancada Alta Girada","Una zancada alta con torsión cerrada: el talón trasero sigue elevado, las caderas miran al frente y el pecho rota sobre el muslo delantero.","Core","Fuerza","Intermedio","Sin equipo",true,["Oblicuos","Cuádriceps"],["Erectores espinales","Flexores de cadera"],5.0,"revolved-crescent-lunge-main.webp",null,["Colócate en zancada alta con la rodilla delantera sobre el tobillo y el talón trasero elevado.","Junta las palmas frente al pecho y cuadra ambas caderas hacia el frente de la esterilla.","Gira el pecho hacia la pierna delantera y engancha el codo contrario por fuera del muslo.","Mantén la torsión durante el tiempo indicado, empujando el talón trasero hacia la pared de detrás.","Deshaz la torsión y repite del otro lado."],["Mantén la pierna trasera estirada y larga; es lo que impide que la torsión se hunda en las caderas.","Baja la rodilla trasera al suelo para una versión más sencilla con la misma rotación.","Alarga primero la columna y gira después: torcer una espalda redondeada no lleva a ningún sitio."]],["low-lunge","Zancada Baja","Un estiramiento en paso largo con la rodilla trasera apoyada: las caderas se hunden hacia delante y alargan el flexor de la cadera de la pierna de atrás.","Pierna","Estiramiento","Principiante","Sin equipo",true,["Flexores de cadera","Cuádriceps"],["Erectores espinales","Glúteo mayor"],5.0,"low-lunge-main.webp",null,["Desde la posición de rodillas, adelanta un pie para que la rodilla quede sobre el tobillo.","Apoya la rodilla trasera en el suelo y deja el empeine estirado.","Mete ligeramente el coxis y empuja las caderas hacia delante hasta notar el alargamiento en la parte frontal del muslo trasero.","Eleva el pecho, sube los brazos si te resulta agradable y mantén durante el tiempo indicado.","Vuelve atrás y repite del otro lado."],["Acolcha la rodilla trasera con una esterilla doblada si el suelo es duro.","Aprieta el glúteo de atrás para profundizar el estiramiento sin arquear la zona lumbar.","Mantén la rodilla delantera sobre el tobillo en lugar de dejarla deslizarse hacia delante."]],["low-lunge-to-half-split","Zancada Baja a Medio Split","Una secuencia en movimiento para isquiotibiales y flexores de cadera: desde una zancada baja las caderas retroceden sobre la rodilla trasera y la pierna delantera se estira en medio split, y después las caderas vuelven a deslizarse hacia delante.","Pierna","Estiramiento","Principiante","Sin equipo",true,["Isquiotibiales"],["Gemelos","Flexores de cadera"],5.0,"low-lunge-to-half-split-start.webp","low-lunge-to-half-split-peak.webp",["Empieza en zancada baja con la rodilla trasera en el suelo y la delantera sobre el tobillo.","Apoya las manos en el suelo o en bloques a ambos lados del pie delantero.","Lleva las caderas atrás sobre la rodilla trasera y estira la pierna delantera con el pie en flexión.","Sostén el medio split un instante y desliza las caderas hacia delante otra vez a la zancada.","Repite las veces indicadas y cambia de lado."],["Mantén larga la parte posterior de la pierna delantera: flexiona un poco la rodilla en lugar de redondear la columna para llegar.","Se mueven las caderas, no el pie delantero; el pie se queda donde estaba.","Acolcha la rodilla trasera y usa bloques bajo las manos si el suelo queda lejos."]],["walking-lunge","Zancada Caminando","Una zancada en movimiento que avanza pierna tras pierna, trabajando los cuádriceps y glúteos con un desafío de equilibrio adicional.","Pierna","Fuerza","Intermedio","Sin equipo",true,["Glúteo mayor","Cuádriceps"],["Glúteo medio","Isquiotibiales"],5.0,"walking-lunge-start.webp","walking-lunge-peak.webp",["Párate erguido con los pies separados al ancho de las caderas y las manos en las caderas.","Da un paso adelante largo con un pie en zancada.","Baja hasta que ambas rodillas estén en torno a 90 grados.","Empuja con el talón delantero y lleva el pie trasero hacia adelante.","Continúa alternando piernas al avanzar.","Repite el número de repeticiones deseado."],["Baja hasta que ambas rodillas formen unos 90 grados.","Mantén el torso erguido al dar el paso.","Impulsa con el talón delantero para avanzar con fluidez."]],["kettlebell-goblet-lunge","Zancada Goblet con Kettlebell","Este ejercicio compuesto unilateral fortalece los cuádriceps, glúteos e isquiotibiales al realizar una zancada con una kettlebell en posición de copa, mejorando la fuerza y estabilidad del tren inferior.","Pierna","Fuerza","Principiante","Kettlebell",false,["Glúteo mayor","Cuádriceps"],["Glúteo medio","Isquiotibiales"],6.0,"kettlebell-goblet-lunge-start.webp","kettlebell-goblet-lunge-peak.webp",["Ponte de pie sosteniendo una kettlebell por sus cuernos a la altura del pecho, con los codos pegados al cuerpo, en la posición de copa.","Da un paso controlado hacia adelante con una pierna, bajando las caderas hasta que ambas rodillas estén flexionadas aproximadamente a 90 grados.","Asegúrate de que tu rodilla delantera esté alineada sobre tu tobillo y tu rodilla trasera flote justo por encima del suelo.","Impúlsate a través del talón de tu pie delantero para volver a la posición inicial, manteniendo el equilibrio y la tensión del core.","Completa todas las repeticiones por lado antes de cambiar, o alterna las piernas por serie."],["Mantén el pecho erguido y el core contraído durante todo el movimiento para proteger tu columna y mantener la estabilidad.","Concéntrate en un descenso controlado y un impulso potente hacia arriba, activando tus glúteos y cuádriceps.","Evita que tu rodilla delantera se colapse hacia adentro; mantenla alineada con tus dedos del pie."]],["reverse-lunge","Zancada Inversa","Una variación de la zancada que da un paso hacia atrás para mayor estabilidad de rodilla.","Pierna","Fuerza","Intermedio","Mancuernas",false,["Glúteo mayor","Cuádriceps"],["Isquiotibiales"],6.0,"reverse-lunge-start.webp","reverse-lunge-peak.webp",["Párate sosteniendo mancuernas a los costados.","Da un paso hacia atrás con una pierna y baja la rodilla hacia el suelo.","Baja hasta que el muslo delantero quede paralelo al suelo.","Empuja con el talón delantero para volver a la posición de pie.","Repite en ambos lados."],["Da el paso atrás lo bastante largo para que la rodilla delantera no pase del pie.","Mantén el torso erguido y las mancuernas pegadas al cuerpo.","Completa el mismo número de repeticiones con cada pierna."]],["barbell-reverse-lunge","Zancada Inversa con Barra","Una zancada con barra dando el paso hacia atrás en lugar de hacia delante, manteniendo la tibia delantera vertical mientras carga cuádriceps y glúteos.","Pierna","Fuerza","Intermedio","Barra",false,["Glúteo mayor","Cuádriceps"],["Erectores espinales","Glúteo medio","Isquiotibiales"],6.0,"barbell-reverse-lunge-start.webp","barbell-reverse-lunge-peak.webp",["Coloca una barra en la parte alta de la espalda y párate erguido.","Da un paso hacia atrás con un pie en una zancada larga.","Baja la rodilla trasera hacia el suelo de forma controlada.","Impulsa a través del talón delantero para volver a la posición inicial.","Completa las repeticiones de un lado, luego cambia."],["Da el paso atrás lo bastante largo para que la tibia delantera quede casi vertical.","Baja la rodilla trasera en línea recta en lugar de inclinarte hacia delante.","Mantén el pecho erguido y las caderas alineadas."]],["kettlebell-reverse-lunge","Zancada Inversa con Kettlebell","Este ejercicio compuesto unilateral desarrolla fuerza y estabilidad en la parte inferior del cuerpo, trabajando principalmente glúteos y cuádriceps, e involucrando isquiotibiales, glúteo medio y oblicuos.","Pierna","Fuerza","Principiante","Kettlebell",false,["Glúteo mayor","Cuádriceps"],["Glúteo medio","Isquiotibiales","Oblicuos"],6.0,"kettlebell-reverse-lunge-start.webp","kettlebell-reverse-lunge-peak.webp",["Ponte de pie con una kettlebell en una mano, el brazo extendido hacia abajo, en el mismo lado de la pierna que retrocederá.","Da un paso hacia atrás con una pierna, bajando las caderas hasta que ambas rodillas estén flexionadas aproximadamente a 90 grados.","Mantén la espinilla delantera vertical y el pecho erguido, asegurándote de que la rodilla trasera flote justo por encima del suelo.","Impúlsate a través del talón delantero para volver a la posición inicial.","Completa todas las repeticiones por lado antes de cambiar al otro lado."],["Mantén un core estable durante todo el movimiento para proteger tu columna vertebral.","Concéntrate en un descenso controlado y un ascenso potente.","Mantén el pie delantero plano y distribuye el peso uniformemente entre el talón y la parte media del pie.","Evita que la rodilla delantera se colapse hacia adentro; mantenla alineada con los dedos del pie."]],["bodyweight-reverse-lunge","Zancada Inversa con Peso Corporal","Una variante de zancada usando solo el peso corporal, dando un paso hacia atrás para mayor estabilidad de rodilla que una zancada hacia adelante.","Pierna","Fuerza","Principiante","Sin equipo",true,["Glúteo mayor","Cuádriceps"],["Isquiotibiales"],5.0,"bodyweight-reverse-lunge-start.webp","bodyweight-reverse-lunge-peak.webp",["Ponte de pie con los pies separados a la altura de las caderas.","Da un paso hacia atrás con una pierna y baja la rodilla hacia el suelo.","Baja hasta que tu muslo delantero quede paralelo al suelo.","Empuja a través del talón delantero para volver a la posición de pie.","Repite con ambas piernas."],["No necesitas peso -- concéntrate en el equilibrio y un descenso controlado.","Mantén el torso erguido en lugar de inclinarte hacia adelante.","Da un paso lo suficientemente atrás para que tu rodilla delantera quede detrás de los dedos del pie."]],["smith-machine-reverse-lunge","Zancada Inversa en Máquina Smith","Una zancada inversa bajo la barra de la máquina Smith, dando un paso atrás con un pie y devolviéndolo a la posición de pie en cada repetición mientras la barra guiada mantiene la carga estable.","Pierna","Fuerza","Intermedio","Máquina Smith",false,["Glúteo mayor","Cuádriceps"],["Glúteo medio","Isquiotibiales"],6.0,"smith-machine-reverse-lunge-start.webp","smith-machine-reverse-lunge-peak.webp",["Coloca la barra de modo que descanse sobre los trapecios altos al estar de pie y desengánchala con los pies bajo las caderas.","Da un paso recto hacia atrás con un pie y baja la rodilla trasera hacia el suelo, manteniendo la tibia delantera vertical y la mayor parte del peso en el pie delantero.","Detente cuando la rodilla trasera esté a punto de tocar el suelo y el muslo delantero quede aproximadamente paralelo a él.","Empuja con el talón delantero y devuelve el pie trasero a la posición de pie bajo la barra.","Completa todas las repeticiones de un lado, o alterna piernas, y luego cambia."],["Da un paso atrás lo bastante largo. Un paso corto lleva la rodilla delantera muy por delante de los dedos, y la trayectoria fija de la barra no te dejará corregirlo una vez cargado.","El pie que se desplaza hace todo el recorrido; el pie delantero no se mueve en absoluto. Si cambia de sitio entre repeticiones, tu paso es demasiado largo o demasiado corto.","La máquina te quita el equilibrio, no la carga: mantén el tronco firme y levántate desde abajo en lugar de recostarte contra la barra."]],["side-lunge","Zancada Lateral","Una zancada lateral que da un paso amplio hacia un lado, trabajando los cuádriceps, glúteos y la cara interna de los muslos en un patrón lateral.","Pierna","Fuerza","Intermedio","Sin equipo",true,["Glúteo mayor","Cuádriceps"],["Glúteo medio","Isquiotibiales","Flexores de cadera"],5.0,"side-lunge-start.webp","side-lunge-peak.webp",["De pie con los pies al ancho de las caderas y las manos en el pecho.","Da un paso amplio hacia un lado con una pierna, manteniendo la otra recta.","Flexiona la rodilla de la pierna que dio el paso y empuja las caderas hacia atrás en una sentadilla lateral.","Mantén el pecho erguido y el talón de trabajo apoyado.","Empuja con la pierna flexionada para volver a la posición de pie.","Completa las repeticiones de un lado y luego cambia."],["Empuja las caderas hacia atrás mientras flexionas la rodilla del paso.","Mantén la pierna contraria estirada y ambos talones apoyados.","Mantén el pecho erguido en lugar de redondear hacia delante."]],["plyo-lunge","Zancada Pliométrica","Un salto explosivo en posición de zancada que cambia las piernas en el aire, alternando cada repetición.","Pierna","Pliometría","Intermedio","Sin equipo",true,["Glúteo mayor","Cuádriceps"],["Glúteo medio","Isquiotibiales"],7.0,"plyo-lunge-start.webp","plyo-lunge-peak.webp",["Comienza en una zancada con un pie adelantado.","Baja a una zancada profunda con la rodilla trasera casi tocando el suelo.","Despega ambos pies y cambia las piernas en el aire.","Aterriza suave en zancada con la pierna opuesta adelante.","Continúa alternando sin pausa."],["Aterriza suave con las rodillas flexionadas.","Cambia la posición de las piernas por completo — no solo saltes en el sitio.","Mantén el torso erguido — no te inclines adelante."]],["trx-lunge","Zancada TRX","Un ejercicio unilateral de tren inferior apto para principiantes que utiliza un entrenador de suspensión para trabajar los cuádriceps y glúteos, mientras involucra los isquiotibiales y el glúteo medio para la estabilidad.","Pierna","Fuerza","Principiante","Entrenador de suspensión (TRX)",false,["Glúteo mayor","Cuádriceps"],["Glúteo medio","Isquiotibiales"],6.0,"trx-lunge-start.webp","trx-lunge-peak.webp",["Ponte de espaldas al punto de anclaje, sosteniendo las asas del entrenador de suspensión frente a ti.","Coloca un pie en ambos estribos, extendiendo la pierna hacia atrás.","Contrae tu abdomen y baja tu cuerpo doblando la rodilla delantera, manteniendo el torso erguido.","Desciende hasta que tu muslo delantero esté paralelo al suelo o ligeramente por debajo, manteniendo la tensión en el entrenador de suspensión.","Impúlsate a través del talón delantero para volver a la posición inicial, extendiendo la pierna delantera.","Completa todas las repeticiones en un lado, luego cambia de pierna y repite por lado."],["Mantén tu rodilla delantera alineada con tus dedos del pie, evitando que colapse hacia adentro.","Conserva una columna vertebral neutra durante todo el movimiento, previniendo un arqueo o redondeo excesivo.","Controla la fase excéntrica (de descenso) para maximizar el compromiso muscular.","Ajusta tu distancia del punto de anclaje para modificar la dificultad."]],["barbell-lunge","Zancada con Barra","Una zancada hacia delante con la barra sobre la parte alta de la espalda, entrenando cuádriceps y glúteos una pierna a la vez.","Pierna","Fuerza","Intermedio","Barra",false,["Glúteo mayor","Cuádriceps"],["Erectores espinales","Glúteo medio","Isquiotibiales"],6.0,"barbell-reverse-lunge-start.webp","barbell-reverse-lunge-peak.webp",["Coloca una barra en la parte alta de la espalda y párate erguido.","Da un paso adelante con una pierna en una zancada larga.","Baja la rodilla trasera hacia el suelo hasta que el muslo delantero quede paralelo.","Impulsa a través del talón delantero para volver a la posición inicial.","Completa las repeticiones de un lado, luego cambia."],["Da una zancada lo bastante larga para que la rodilla delantera quede sobre el tobillo.","Mantén el torso erguido y el core contraído bajo la barra.","Empuja el suelo con el talón delantero, no con los dedos."]],["db-lunge","Zancada con Mancuernas","Un ejercicio unilateral de tren inferior con mancuernas que trabaja los cuádriceps y los glúteos mediante un paso adelante.","Pierna","Fuerza","Intermedio","Mancuernas",false,["Glúteo mayor","Cuádriceps"],["Isquiotibiales"],6.0,"db-lunge-start.webp","db-lunge-peak.webp",["De pie, sujeta mancuernas a los costados.","Da un paso adelante con un pie y baja la rodilla trasera hacia el suelo.","Empuja con el pie delantero para volver.","Alterna las piernas.","Repite."],["Mantén el torso erguido.","La rodilla delantera debe seguir la dirección de los pies."]],["kettlebell-lunge-press","Zancada con press de pesa rusa","Un ejercicio de cuerpo completo que combina una zancada con un press de pesa rusa a un brazo.","Cuerpo completo","Fuerza","Intermedio","Kettlebell",false,["Deltoides anterior","Glúteo mayor","Cuádriceps"],["Isquiotibiales","Recto abdominal","Tríceps braquial"],6.0,"kettlebell-lunge-press-start.webp","kettlebell-lunge-press-peak.webp",["Sostén una pesa rusa a la altura del hombro con un brazo.","Da un paso adelante en zancada con la pierna contraria.","Mientras haces la zancada, empuja la pesa rusa por encima de la cabeza.","Bloquea el brazo en la parte superior del press.","Da un paso atrás de vuelta a la posición de pie mientras bajas la pesa rusa.","Completa las repeticiones en un lado y luego cambia."],["Mantén el abdomen firme para no inclinarte hacia el lado cargado.","La rodilla delantera debe apuntar en la dirección del pie.","Empieza con poco peso hasta dominar la coordinación del movimiento."]],["kettlebell-offset-reverse-lunge-and-press","Zancada inversa con press desequilibrado de pesa rusa","Una zancada inversa combinada con un press de pesa rusa a un brazo, con carga descompensada que exige estabilidad del core.","Cuerpo completo","Fuerza","Intermedio","Kettlebell",false,["Deltoides anterior","Glúteo mayor","Cuádriceps"],["Isquiotibiales","Oblicuos","Tríceps braquial"],6.0,"kettlebell-offset-reverse-lunge-and-press-start.webp","kettlebell-offset-reverse-lunge-and-press-peak.webp",["Sostén una pesa rusa a la altura del hombro en un lado.","Da un paso hacia atrás en zancada inversa con la pierna contraria.","Al llegar a la parte inferior de la zancada, empuja la pesa rusa por encima de la cabeza.","Empuja con el talón delantero para volver a ponerte de pie.","Baja la pesa rusa de vuelta a la altura del hombro.","Completa las repeticiones en un lado y luego cambia."],["Mantén el torso erguido frente a la carga descompensada.","Bloquea el codo arriba con la muñeca firme y recta.","Si pierdes el equilibrio, acorta un poco el paso atrás."]],["kettlebell-rotational-lunge","Zancada rotacional con pesa rusa","Una zancada lateral con pesa rusa y rotación del torso que trabaja piernas, glúteos y oblicuos en varios planos.","Pierna","Fuerza","Intermedio","Kettlebell",false,["Glúteo mayor","Cuádriceps"],["Glúteo medio","Isquiotibiales","Oblicuos"],6.0,"kettlebell-rotational-lunge-start.webp","kettlebell-rotational-lunge-peak.webp",["Sostén una pesa rusa con ambas manos a la altura del pecho.","Da un paso hacia un lado en una zancada lateral.","Rota el torso hacia la pierna que hace la zancada.","Lleva la pesa rusa hacia la rodilla flexionada.","Empuja con la pierna de la zancada para volver al centro.","Completa las repeticiones en un lado y luego cambia."],["Gira desde el torso, no desde las rodillas.","Mantén la espalda larga al bajar la pesa hacia la rodilla.","Controla la rotación, sin movimientos bruscos."]],["extended-side-angle","Ángulo Lateral Extendido","Una postura de pie con base amplia, la rodilla delantera flexionada y el torso extendido sobre ese muslo, formando una línea larga desde el talón trasero hasta la mano de arriba.","Core","Fuerza","Intermedio","Sin equipo",true,["Oblicuos","Cuádriceps"],["Aductores","Glúteo medio"],5.0,"extended-side-angle-main.webp",null,["Sepárate en una base amplia con el pie delantero girado hacia fuera y el trasero algo hacia dentro.","Flexiona la rodilla delantera hasta que quede sobre el tobillo y mantén la pierna trasera estirada.","Apoya el antebrazo delantero sobre el muslo, o la mano en el suelo o un bloque, y estira el brazo de arriba por encima de la oreja.","Mantén la posición durante el tiempo indicado, girando el pecho hacia el techo.","Estira la pierna delantera para subir y repite del otro lado."],["Presiona el borde externo del pie trasero; la postura pierde su base en cuanto ese talón se levanta.","Mantén la rodilla delantera apuntando a los dedos centrales en lugar de dejarla caer hacia dentro.","Apoya el antebrazo en el muslo en lugar de la mano en el suelo para conservar el pecho abierto."]]]$j$::jsonb) e
on conflict (id) do nothing;